def _arg_value(name: str, default: str | None = None) -> str | None:
    prefix = name + "="
    for index, arg in enumerate(sys.argv):
        if arg == name and index + 1 < len(sys.argv):
            return sys.argv[index + 1]
        if arg.startswith(prefix):
            return arg.split("=", 1)[1]
    return default


def _normalize_level_id(value: str | None) -> str:
    raw = str(value or "enceladus").strip().lower().replace(" ", "_").replace("-", "_")
    aliases = {
        "enceladus": "enceladus",
        "enceladus_ice": "enceladus",
        "ice": "enceladus",
        "mimas": "mimas",
        "mimas_snowfield": "mimas",
        "mimas_snow": "mimas",
        "snowfield": "mimas",
        "iapetus": "iapetus",
        "iapetus_ridge": "iapetus",
        "ridge": "iapetus",
        "cassini_regio": "iapetus",
        "titan": "titan",
        "titan_methane": "titan",
        "methane_coast": "titan",
        "hydrocarbon": "titan",
        "pluto": "pluto",
        "pluto_ice": "pluto",
        "sputnik_planitia": "pluto",
        "kuiper": "pluto",
        "mars": "mars",
        "mars_snow_caps": "mars",
        "mars_snowcap": "mars",
        "snow_caps": "mars",
        "europa": "europa",
        "europa_depths": "europa",
        "jovian_ice": "europa",
        "ice_iron_canyon": "europa",
        "triton": "triton",
        "triton_valleys": "triton",
        "neptunian_valleys": "triton",
        "nitrogen_frost": "triton",
    }
    return aliases.get(raw, "enceladus")


