def panda_path(path: Path) -> Filename:
    return Filename.fromOsSpecific(str(path.resolve()))


def configure_prc() -> None:
    apply_panda_window_config(loadPrcFileData, APP_TITLE, sys.argv)
    headless = "--smoke-test" in sys.argv or "--offscreen" in sys.argv or "--test-shot" in sys.argv or "--boot-shot" in sys.argv
    apply_prc_optimization(loadPrcFileData, ROOT.parent, sys.argv, headless=headless)
    if headless or "--no-audio" in sys.argv:
        loadPrcFileData("", "audio-library-name null")
    else:
        loadPrcFileData("", "audio-library-name p3openal_audio")
    loadPrcFileData("", "texture-minfilter linear-mipmap-linear")
    loadPrcFileData("", "texture-magfilter linear")
    if "--xvfb" not in sys.argv:
        if "--smoke-test" in sys.argv:
            loadPrcFileData("", "window-type offscreen")
            loadPrcFileData("", "load-display p3tinydisplay")
        elif "--offscreen" in sys.argv or "--test-shot" in sys.argv or "--boot-shot" in sys.argv:
            loadPrcFileData("", "window-type offscreen")
            loadPrcFileData("", "load-display p3tinydisplay")


configure_prc()


def clamp(value: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, value))


@dataclass
class Hole:
    x: float
    y: float
    radius: float


class TextureFactory:
    def __init__(self, folder: Path) -> None:
        self.folder = folder
        self.folder.mkdir(parents=True, exist_ok=True)
        self.texture_folder = self.folder.parent / "textures"
        self.texture_folder.mkdir(parents=True, exist_ok=True)
        self.version_file = self.folder / f".{MOON_LEVEL_ID}_texture_version"
        self.texture_prefix = str(MOON_THEME["texture_prefix"])
        self.hole_mask_size = 1024
        self.hole_mask_path = self.folder / f"{self.texture_prefix}_hole_mask.png"
        self.hole_overlay_path = self.folder / f"{self.texture_prefix}_surface_sheet.png"
        self._surface_base_path = self.folder / f"{self.texture_prefix}_surface_base.png"
        self._surface_detail_path = self.folder / f"{self.texture_prefix}_surface_detail.png"
        self.hole_mask_image: Image.Image | None = None

    def _find_custom_loading_planet_wrap(self) -> Path | None:
        """Optional user-replaceable wrap slot for the boot/loading Enceladus moon.

        Put a 2:1 equirectangular texture at assets/textures/loading_planet_wrap.png
        to replace the generated fallback. JPG/JPEG/WEBP variants are also accepted.
        """
        candidates = [
            "loading_planet_wrap.png",
            "loading_planet_wrap.jpg",
            "loading_planet_wrap.jpeg",
            "loading_planet_wrap.webp",
            "enceladus_boot_wrap.png",
            "enceladus_boot_wrap.jpg",
            "enceladus_boot_wrap.jpeg",
            "enceladus_boot_wrap.webp",
            "mimas_boot_wrap.png",
            "mimas_boot_wrap.jpg",
            "mimas_boot_wrap.jpeg",
            "mimas_boot_wrap.webp",
        ]
        for name in candidates:
            candidate = self.texture_folder / name
            if candidate.exists() and candidate.is_file():
                return candidate
        return None

    def ensure_all(self, holes: list[Hole] | None = None) -> dict[str, Path]:
        prefix = self.texture_prefix
        self._surface_base_path = self.folder / f"{prefix}_surface_base.png"
        self._surface_detail_path = self.folder / f"{prefix}_surface_detail.png"
        textures = {
            "ice_base": self._surface_base_path,
            "mountain_base": self.folder / f"{prefix}_subsurface_base.png",
            "ice_detail": self._surface_detail_path,
            "water": self.folder / f"{prefix}_water_deep.png",
            "seafloor": self.folder / f"{prefix}_seafloor.png",
            "stars": self.folder / "enceladus_space_stars.png",
            "jupiter": self.folder / "europa_jupiter_generated.png",
            "neptune": self.folder / "triton_neptune_generated.png",
            "jupiter_shadow": self.folder / "europa_jupiter_shadow_mask.png",
            **{f"jupiter_storm_frame_{idx}": self.folder / f"europa_jupiter_storm_frame_{idx:02d}.png" for idx in range(8)},
            **{f"jupiter_wrap_frame_{idx}": self.folder / f"europa_jupiter_wrapped_frame_{idx:02d}.png" for idx in range(8)},
            "saturn_body": self.folder / "saturn_body_wrapped.png",
            "sun": self.folder / "sun_glow.png",
            "moon": self.folder / f"{prefix}_neighbor_moon.png",
            "sky_mist": self.folder / f"{prefix}_sky_mist.png",
            "vapor_cloud": self.folder / f"{prefix}_vapor_cloud.png",
            "ground_haze": self.folder / f"{prefix}_ground_haze.png",
            "underwater_blur": self.folder / f"{prefix}_underwater_blur_soft.png",
            "hole_mask": self.hole_mask_path,
            "ice_overlay": self.hole_overlay_path,
            "hole_ring": self.folder / f"{prefix}_hole_ring.png",
            "hole_wall": self.folder / f"{prefix}_hole_wall.png",
            "holo_tech": self.folder / "enceladus_holo_tech.png",
            "sheet_metal": self.folder / "enceladus_sheet_metal_panel.png",
            "solar_panel": self.folder / "enceladus_solar_panel.png",
        }
        force = True
        if self.version_file.exists():
            try:
                force = self.version_file.read_text(encoding="utf-8").strip() != TEXTURE_VERSION
            except Exception:
                force = True
        force = force or ("--regen-textures" in sys.argv)
        required_keys = ["ice_base", "mountain_base", "ice_detail", "water", "seafloor", "stars", "saturn_body", "sun", "moon", "sky_mist", "vapor_cloud", "ground_haze", "hole_ring", "hole_wall", "holo_tech", "sheet_metal", "solar_panel"]
        if IS_EUROPA_LEVEL:
            required_keys.extend([
                "jupiter",
                "jupiter_shadow",
                *[f"jupiter_storm_frame_{idx}" for idx in range(8)],
                *[f"jupiter_wrap_frame_{idx}" for idx in range(8)],
            ])
        if IS_TRITON_LEVEL:
            required_keys.append("neptune")
        if IS_TITAN_LEVEL:
            required_keys.append("underwater_blur")
        required = [textures[k] for k in required_keys]
        if force or not all(path.exists() for path in required):
            if force or not textures["ice_base"].exists():
                self._make_ice_base(textures["ice_base"])
            if force or not textures["mountain_base"].exists():
                self._make_mountain_base(textures["mountain_base"])
            if force or not textures["ice_detail"].exists():
                self._make_ice_detail(textures["ice_detail"])
            if force or not textures["water"].exists():
                self._make_water_texture(textures["water"])
            if force or not textures["seafloor"].exists():
                self._make_seafloor_texture(textures["seafloor"])
            if force or not textures["stars"].exists():
                self._make_star_texture(textures["stars"])
            if IS_EUROPA_LEVEL:
                if force or not textures["jupiter"].exists():
                    self._make_jupiter_texture(textures["jupiter"])
                if force or not textures["jupiter_shadow"].exists():
                    self._make_jupiter_shadow_texture(textures["jupiter_shadow"])
                storm_paths = [textures[f"jupiter_storm_frame_{idx}"] for idx in range(8)]
                if force or not all(path.exists() for path in storm_paths):
                    self._make_jupiter_storm_shell_frames(storm_paths)
                wrapped_paths = [textures[f"jupiter_wrap_frame_{idx}"] for idx in range(8)]
                if force or not all(path.exists() for path in wrapped_paths):
                    self._make_jupiter_wrapped_fx_frames(
                        textures["jupiter"],
                        textures["jupiter_shadow"],
                        storm_paths,
                        wrapped_paths,
                    )
            if IS_TRITON_LEVEL and (force or not textures["neptune"].exists()):
                self._make_neptune_texture(textures["neptune"])
            if force or not textures["saturn_body"].exists():
                self._make_saturn_body_texture(textures["saturn_body"])
            if force or not textures["sun"].exists():
                self._make_sun_texture(textures["sun"])
            if force or not textures["moon"].exists():
                self._make_moon_texture(textures["moon"])
            if force or not textures["sky_mist"].exists():
                self._make_sky_mist_texture(textures["sky_mist"])
            if force or not textures["vapor_cloud"].exists():
                self._make_vapor_cloud_texture(textures["vapor_cloud"])
            if force or not textures["ground_haze"].exists():
                self._make_ground_haze_texture(textures["ground_haze"])
            if IS_TITAN_LEVEL and (force or not textures["underwater_blur"].exists()):
                self._make_underwater_blur_texture(textures["underwater_blur"])
            if force or not textures["hole_ring"].exists():
                self._make_hole_ring_texture(textures["hole_ring"])
            if force or not textures["hole_wall"].exists():
                self._make_hole_wall_texture(textures["hole_wall"])
            if force or not textures["holo_tech"].exists():
                self._make_holo_tech_texture(textures["holo_tech"])
            if force or not textures["sheet_metal"].exists():
                self._make_sheet_metal_texture(textures["sheet_metal"])
            if force or not textures["solar_panel"].exists():
                self._make_solar_panel_texture(textures["solar_panel"])
            self.version_file.write_text(TEXTURE_VERSION, encoding="utf-8")
        self.reset_hole_mask(holes or [])
        return textures

    def ensure_loading_screen_assets(self) -> dict[str, Path]:
        """Create lightweight boot-screen art without touching the Pass 62 terrain textures."""
        prefix = str(MOON_THEME["texture_prefix"])
        view_path = self.folder / f"{prefix}_boot_view.png"
        shadow_path = self.folder / f"{prefix}_boot_shadow.png"
        stamp_path = self.folder / ".loading_texture_version"
        custom_wrap_path = self._find_custom_loading_planet_wrap()
        if custom_wrap_path is not None:
            try:
                stat = custom_wrap_path.stat()
                signature = f"{LOADING_TEXTURE_VERSION}|wrap={custom_wrap_path.name}|{stat.st_size}|{stat.st_mtime_ns}"
            except Exception:
                signature = f"{LOADING_TEXTURE_VERSION}|wrap={custom_wrap_path.name}"
        else:
            signature = f"{LOADING_TEXTURE_VERSION}|wrap=procedural"
        # Pass69: approved cinematic loading screens are now treated as source assets.
        # Do not overwrite them just because an older procedural loading version changed.
        force = "--regen-loading-screen" in sys.argv
        if force or not view_path.exists():
            self._make_loading_enceladus_view(view_path, wrap_path=custom_wrap_path)
        if force or not shadow_path.exists():
            self._make_loading_shadow_mask(shadow_path)
        stamp_path.write_text(signature, encoding="utf-8")
        return {"view": view_path, "shadow": shadow_path}

    def _make_titan_loading_view(self, path: Path, width: int = 1920, height: int = 1080) -> None:
        rng = random.Random(320132)
        img = Image.new("RGBA", (width, height), (78, 32, 8, 255))
        px = img.load()
        for y in range(height):
            ny = y / max(height - 1, 1)
            for x in range(width):
                nx = x / max(width - 1, 1)
                haze = clamp(1.0 - abs(ny - 0.38) * 1.25, 0.0, 1.0)
                sun_warm = clamp(1.0 - (((nx - 0.78) ** 2 + (ny - 0.28) ** 2) ** 0.5) * 2.6, 0.0, 1.0)
                r = int(clamp(96 + (1.0 - ny) * 86 + haze * 54 + sun_warm * 58, 0, 255))
                g = int(clamp(42 + (1.0 - ny) * 36 + haze * 38 + sun_warm * 44, 0, 255))
                b = int(clamp(10 + (1.0 - ny) * 10 + haze * 9, 0, 255))
                px[x, y] = (r, g, b, 255)
        draw = ImageDraw.Draw(img, "RGBA")
        # Faint Saturn through Titan haze: visible, but not the wrong clear white moon.
        scx, scy, sr = int(width * 0.58), int(height * 0.38), int(height * 0.26)
        for ring in range(72, 0, -4):
            alpha = int(2 + (72 - ring) * 0.20)
            draw.ellipse((scx - sr - ring, scy - sr - ring, scx + sr + ring, scy + sr + ring), outline=(255, 188, 84, alpha), width=3)
        draw.ellipse((scx - sr, scy - sr, scx + sr, scy + sr), fill=(230, 170, 78, 28), outline=(255, 212, 132, 32), width=2)
        draw.arc((scx - sr * 2.0, scy - sr * 0.35, scx + sr * 2.0, scy + sr * 0.35), 188, 350, fill=(255, 184, 80, 36), width=5)
        # Sun glare diffused by haze.
        sx, sy = int(width * 0.82), int(height * 0.25)
        for r in range(130, 5, -6):
            alpha = int(max(0, 22 - r * 0.12))
            draw.ellipse((sx - r, sy - r, sx + r, sy + r), fill=(255, 210, 92, alpha))
        draw.ellipse((sx - 16, sy - 16, sx + 16, sy + 16), fill=(255, 238, 154, 170))
        # Distant tholin dunes and methane seas.
        horizon = int(height * 0.57)
        pts = [(0, horizon)]
        for i in range(0, width + 96, 96):
            pts.append((i, horizon - int(18 * math.sin(i * 0.010) + rng.randrange(-8, 9))))
        pts += [(width, height), (0, height)]
        draw.polygon(pts, fill=(74, 34, 12, 210))
        for i in range(22):
            yy = int(height * (0.62 + i * 0.017))
            amp = 12 + i * 8
            color = (122 + i * 3, 58 + i, 16, max(18, 76 - i * 2))
            line_pts = []
            for x in range(-80, width + 80, 80):
                line_pts.append((x, yy + int(math.sin(x * 0.006 + i) * amp)))
            draw.line(line_pts, fill=color, width=max(2, 5 - i // 7))
        water = Image.new("RGBA", (width, height), (0, 0, 0, 0))
        wd = ImageDraw.Draw(water, "RGBA")
        shore_y = int(height * 0.66)
        lake_poly = [(0, height), (0, shore_y + 70)]
        for x in range(0, width + 80, 80):
            lake_poly.append((x, shore_y + int(math.sin(x * 0.007) * 32 + math.sin(x * 0.021) * 14)))
        lake_poly += [(width, height)]
        wd.polygon(lake_poly, fill=(34, 19, 8, 205))
        for i in range(18):
            yy = shore_y + 28 + i * 20
            wd.line([(0, yy + int(math.sin(i) * 8)), (width, yy + int(math.sin(i + 1.1) * 10))], fill=(220, 128, 28, 28), width=2)
        img.alpha_composite(water.filter(ImageFilter.GaussianBlur(radius=0.6)))
        img = img.filter(ImageFilter.GaussianBlur(radius=0.25))
        img.save(path)

    def _make_pluto_loading_view(self, path: Path, width: int = 1920, height: int = 1080) -> None:
        """Generate Pluto boot/loading art as a cinematic surface view.

        Pass66 replaces the flat circular placeholder with a world-entry view:
        dark Kuiper Belt star field, Charon, distant perimeter ice walls,
        translucent shard silhouettes, and rust-cracked nitrogen terrain.
        """
        rng = random.Random(66066)
        img = Image.new("RGBA", (width, height), (0, 1, 5, 255))
        px = img.load()
        for y in range(height):
            ny = y / max(height - 1, 1)
            horizon_fade = clamp(1.0 - abs(ny - 0.56) * 2.4, 0.0, 1.0)
            upper = clamp(1.0 - ny, 0.0, 1.0)
            for x in range(width):
                nx = x / max(width - 1, 1)
                faint_haze = horizon_fade * 0.08 + upper * 0.018
                px[x, y] = (int(0 + faint_haze * 28), int(1 + faint_haze * 36), int(5 + faint_haze * 62), 255)
        draw = ImageDraw.Draw(img, "RGBA")
        # Dense distant star field; small stars only, no cartoon planet disc.
        for _ in range(980):
            sx = rng.randrange(width)
            sy = rng.randrange(0, int(height * 0.72))
            tone = rng.randrange(128, 255)
            alpha = rng.randrange(32, 116)
            radius = 1 if rng.random() < 0.96 else 2
            draw.ellipse((sx-radius, sy-radius, sx+radius, sy+radius), fill=(tone, min(255, tone+8), 255, alpha))
        # Charon, smaller and shaded, above the horizon.
        ccx, ccy, cr = int(width * 0.18), int(height * 0.23), int(height * 0.072)
        for yy in range(ccy - cr, ccy + cr + 1):
            for xx in range(ccx - cr, ccx + cr + 1):
                dx = (xx - ccx) / max(cr, 1)
                dy = (yy - ccy) / max(cr, 1)
                rr = dx*dx + dy*dy
                if rr <= 1.0:
                    nz = math.sqrt(max(0.0, 1.0 - rr))
                    light = clamp(0.32 + 0.68 * max(0.0, -dx*0.42 - dy*0.24 + nz*0.86), 0.0, 1.0)
                    tone = int(76 + light * 126)
                    img.putpixel((xx, yy), (tone, tone + 5, min(255, tone + 18), 220))
        draw.ellipse((ccx-cr, ccy-cr, ccx+cr, ccy+cr), outline=(210, 228, 255, 52), width=2)
        # Perimeter mountains across horizon.
        horizon = int(height * 0.58)
        ridge = [(0, horizon)]
        for x in range(0, width + 50, 50):
            high = 72 + int(48 * math.sin(x * 0.006 + 1.1) + 28 * math.sin(x * 0.017)) + rng.randrange(-22, 24)
            ridge.append((x, horizon - max(22, high)))
        ridge += [(width, height), (0, height)]
        draw.polygon(ridge, fill=(56, 54, 68, 220))
        # Tall translucent shard silhouettes beyond the landing basin.
        for i in range(70):
            x = rng.randrange(-80, width + 80)
            base_y = rng.randrange(int(height * 0.52), int(height * 0.83))
            h = rng.randrange(80, 330)
            w = rng.randrange(8, 32)
            alpha = rng.randrange(34, 78)
            draw.polygon([(x-w, base_y), (x+w, base_y+rng.randrange(-12, 18)), (x+rng.randrange(-8, 9), base_y-h)], fill=(180, 210, 245, alpha), outline=(215, 235, 255, max(18, alpha//2)))
        # Foreground terrain with long wave forms and broad rust spray/cracks.
        terrain = [(0, height), (0, int(height * 0.68))]
        for x in range(0, width + 50, 50):
            y = int(height * 0.67 + math.sin(x * 0.005) * 22 + math.sin(x * 0.017 + 0.5) * 12)
            terrain.append((x, y))
        terrain += [(width, height)]
        draw.polygon(terrain, fill=(96, 88, 96, 238))
        for i in range(26):
            y0 = int(height * (0.66 + i * 0.016))
            pts = []
            for x in range(-120, width + 121, 80):
                pts.append((x, y0 + int(math.sin(x * 0.006 + i*0.55) * (12 + i * 1.7))))
            draw.line(pts, fill=(175, 168, 178, max(12, 68 - i*2)), width=max(1, 4 - i//8))
        # Huge sprayed rust patches, not smooth ellipses: many ragged blobs and speckles.
        for i in range(42):
            cx = rng.randrange(-120, width + 120)
            cy = rng.randrange(int(height * 0.58), height + 60)
            rw = rng.randrange(120, 360)
            rh = rng.randrange(28, 95)
            color = rng.choice([(142, 54, 34, 56), (166, 70, 42, 48), (104, 42, 34, 44)])
            for j in range(rng.randrange(4, 10)):
                ox = rng.randrange(-rw//2, rw//2)
                oy = rng.randrange(-rh//2, rh//2)
                draw.ellipse((cx+ox-rw//3, cy+oy-rh//3, cx+ox+rw//3, cy+oy+rh//3), fill=color)
        for i in range(34):
            x0 = rng.randrange(-80, width)
            y0 = rng.randrange(int(height * 0.58), height)
            pts = []
            for j in range(9):
                pts.append((x0 + j*rng.randrange(45, 105), y0 + int(math.sin(j*1.3+i)*36) + rng.randrange(-12, 13)))
            draw.line(pts, fill=(40, 20, 18, 120), width=rng.randrange(1, 4))
            draw.line([(x+2, y+1) for x, y in pts], fill=(164, 67, 40, 60), width=1)
        img = img.filter(ImageFilter.GaussianBlur(radius=0.18))
        img.save(path)

    def _make_loading_enceladus_view(self, path: Path, width: int = 1920, height: int = 1080, wrap_path: Path | None = None) -> None:
        """Generate the boot/loading Enceladus view.

        If assets/textures/loading_planet_wrap.* exists, it is sampled once as an
        equirectangular wrap over the 3D moon. Otherwise the built-in procedural
        Enceladus surface is used. Either path avoids repeated/tiled screen-space
        texture cards.
        """
        if IS_TITAN_LEVEL and wrap_path is None:
            self._make_titan_loading_view(path, width, height)
            return
        if IS_PLUTO_LEVEL and wrap_path is None:
            self._make_pluto_loading_view(path, width, height)
            return
        rng = random.Random(7308)
        img = Image.new("RGBA", (width, height), (1, 2, 7, 255))
        bg = Image.new("RGBA", (width, height), (1, 2, 7, 255))
        bpx = bg.load()
        for y in range(height):
            ny = y / max(height - 1, 1)
            for x in range(width):
                nx = x / max(width - 1, 1)
                haze = clamp(1.0 - (((nx - 0.70) ** 2 + (ny - 0.50) ** 2) ** 0.5) * 2.3, 0.0, 1.0)
                bpx[x, y] = (int(1 + haze * 3), int(2 + haze * 8), int(7 + haze * 24), 255)
        img = bg
        draw = ImageDraw.Draw(img, "RGBA")
        for _ in range(390):
            sx = rng.randrange(width)
            sy = rng.randrange(height)
            tone = rng.randrange(140, 246)
            alpha = rng.randrange(26, 110)
            if rng.random() < 0.95:
                draw.point((sx, sy), fill=(tone, min(255, tone + 8), 255, alpha))
            else:
                rr = rng.choice((1, 1, 2))
                draw.ellipse((sx - rr, sy - rr, sx + rr, sy + rr), fill=(tone, min(255, tone + 12), 255, alpha))

        cx, cy, radius = int(width * 0.69), int(height * 0.505), int(height * 0.405)
        box = (cx - radius, cy - radius, cx + radius, cy + radius)

        glow = Image.new("RGBA", (width, height), (0, 0, 0, 0))
        gd = ImageDraw.Draw(glow, "RGBA")
        for ring in range(54, 0, -3):
            alpha = int(2 + (54 - ring) * 0.95)
            gd.ellipse((cx - radius - ring, cy - radius - ring, cx + radius + ring, cy + radius + ring), outline=(52, 204, 255, alpha), width=3)
        img.alpha_composite(glow.filter(ImageFilter.GaussianBlur(radius=12)))

        moon = Image.new("RGBA", (width, height), (0, 0, 0, 0))
        mask = Image.new("L", (width, height), 0)
        ImageDraw.Draw(mask).ellipse(box, fill=255)
        mpx = moon.load()

        custom_wrap: Image.Image | None = None
        custom_px = None
        custom_w = custom_h = 1
        if wrap_path is not None:
            try:
                custom_wrap = Image.open(wrap_path).convert("RGB")
                # Normalize to a sane 2:1 working size while preserving user art.
                target_w = 2048
                target_h = 1024
                custom_wrap = custom_wrap.resize((target_w, target_h), Image.Resampling.LANCZOS)
                custom_px = custom_wrap.load()
                custom_w, custom_h = custom_wrap.size
            except Exception:
                custom_wrap = None
                custom_px = None

        noise_small = Image.effect_noise((260, 260), 42.0).convert("L").filter(ImageFilter.GaussianBlur(radius=1.4))
        noise_large = Image.effect_noise((96, 96), 65.0).convert("L").filter(ImageFilter.GaussianBlur(radius=3.0))
        noise_small = noise_small.resize((radius * 2 + 1, radius * 2 + 1), Image.Resampling.BICUBIC)
        noise_large = noise_large.resize((radius * 2 + 1, radius * 2 + 1), Image.Resampling.BICUBIC)
        nspx = noise_small.load()
        nlpx = noise_large.load()

        light_x, light_y, light_z = 0.74, -0.16, 0.64
        length = max(0.001, math.sqrt(light_x * light_x + light_y * light_y + light_z * light_z))
        light_x, light_y, light_z = light_x / length, light_y / length, light_z / length

        for y in range(cy - radius, cy + radius + 1):
            if y < 0 or y >= height:
                continue
            dy = (y - cy) / radius
            for x in range(cx - radius, cx + radius + 1):
                if x < 0 or x >= width:
                    continue
                dx = (x - cx) / radius
                r2 = dx * dx + dy * dy
                if r2 > 1.0:
                    continue
                dz = math.sqrt(max(0.0, 1.0 - r2))
                ndl = clamp(dx * light_x + dy * light_y + dz * light_z, 0.0, 1.0)
                rim = clamp(1.0 - dz, 0.0, 1.0)
                ix, iy = x - (cx - radius), y - (cy - radius)
                fine = (nspx[ix, iy] - 128) / 128.0
                broad = (nlpx[ix, iy] - 128) / 128.0
                side = clamp(0.46 + dx * 0.32 + ndl * 0.52 - rim * 0.12, 0.0, 1.0)
                frost = clamp(0.78 + broad * 0.10 + fine * 0.035, 0.0, 1.0)

                if custom_px is not None:
                    # Equirectangular sphere mapping: one wrap over the moon, not screen tiling.
                    lon = math.atan2(dx, dz)
                    lat = math.asin(clamp(dy, -1.0, 1.0))
                    u = (0.5 + lon / math.tau) % 1.0
                    v = clamp(0.5 - lat / math.pi, 0.0, 1.0)
                    tx = int(u * (custom_w - 1))
                    ty = int(v * (custom_h - 1))
                    cr, cg, cb = custom_px[tx, ty]
                    light = clamp(0.34 + side * 0.78 + ndl * 0.22, 0.0, 1.18)
                    r = cr * light + rim * 8
                    g = cg * light + rim * 13
                    b = cb * light + rim * 28
                    mpx[x, y] = (int(clamp(r, 0, 255)), int(clamp(g, 0, 255)), int(clamp(b, 0, 255)), 255)
                else:
                    tone = 104 + side * 132 + frost * 15 + fine * 5
                    g = tone + 8 + broad * 5
                    b = 145 + side * 82 + frost * 22 + rim * 24
                    mpx[x, y] = (int(clamp(tone, 0, 255)), int(clamp(g, 0, 255)), int(clamp(b, 0, 255)), 255)

        # Built-in detail only applies to the procedural fallback. A supplied wrap is respected.
        if custom_px is None:
            detail = Image.new("RGBA", (width, height), (0, 0, 0, 0))
            dd = ImageDraw.Draw(detail, "RGBA")
            cr_rng = random.Random(7210)
            for _ in range(240):
                ang = cr_rng.random() * math.tau
                rr = radius * math.sqrt(cr_rng.random()) * 0.93
                sx = cx + math.cos(ang) * rr
                sy = cy - radius * 0.26 + math.sin(ang) * rr * 0.72
                if (sx - cx) ** 2 + (sy - cy) ** 2 > radius * radius * 0.98:
                    continue
                rad = cr_rng.choice([1.4, 1.8, 2.3, 3.0, 3.8, 5.0])
                alpha = cr_rng.randrange(26, 78)
                dd.ellipse((sx - rad, sy - rad, sx + rad, sy + rad), outline=(36, 38, 44, alpha), width=1)
                dd.arc((sx - rad - 1, sy - rad - 1, sx + rad + 1, sy + rad + 1), 230, 55, fill=(255, 255, 255, alpha // 2), width=1)

            stripe_rng = random.Random(7211)
            for i in range(86):
                base_x = cx - radius * stripe_rng.uniform(0.36, 0.78) + i * radius * 0.012
                base_y = cy + radius * stripe_rng.uniform(0.03, 0.58)
                length = radius * stripe_rng.uniform(0.46, 0.88)
                angle = stripe_rng.uniform(-1.28, -0.82)
                curve = stripe_rng.uniform(-0.25, 0.26)
                pts = []
                for j in range(12):
                    t = j / 11.0
                    bend = math.sin(t * math.pi) * curve
                    wobble = math.sin(i * 0.71 + t * math.tau * 1.35) * radius * 0.017
                    x = base_x + math.cos(angle + bend) * length * t + wobble
                    y = base_y + math.sin(angle + bend) * length * t + math.cos(i + t * 5.6) * radius * 0.012
                    if (x - cx) ** 2 + (y - cy) ** 2 <= radius * radius * 0.98:
                        pts.append((x, y))
                if len(pts) < 2:
                    continue
                width_line = 1 if i % 6 else 2
                dd.line(pts, fill=(24, 34, 44, 115), width=width_line)
                dd.line([(x + 1.8, y - 1.2) for x, y in pts], fill=(238, 250, 255, 48), width=1)

            for i in range(14):
                r0 = random.Random(7300 + i)
                r1 = random.Random(7400 + i)
                start_x = cx - radius * r0.uniform(0.68, 0.18)
                start_y = cy - radius * r1.uniform(0.58, 0.02)
                pts = []
                for j in range(18):
                    t = j / 17.0
                    x = start_x + radius * (0.10 + t * 0.62) + math.sin(t * 8.0 + i) * radius * 0.020
                    y = start_y + radius * (t * 0.32) + math.sin(t * 5.0 + i) * radius * 0.018
                    if (x - cx) ** 2 + (y - cy) ** 2 <= radius * radius * 0.98:
                        pts.append((x, y))
                if len(pts) >= 2:
                    dd.line(pts, fill=(30, 38, 48, 72), width=2)
                    dd.line([(x + 2, y - 1) for x, y in pts], fill=(255, 255, 255, 34), width=1)
            detail.putalpha(Image.composite(detail.getchannel("A"), Image.new("L", (width, height), 0), mask))
            moon.alpha_composite(detail.filter(ImageFilter.GaussianBlur(radius=0.22)))

        baked_shadow = Image.new("RGBA", (width, height), (0, 0, 0, 0))
        spx = baked_shadow.load()
        for y in range(cy - radius, cy + radius + 1):
            if y < 0 or y >= height:
                continue
            dy = (y - cy) / radius
            for x in range(cx - radius, cx + radius + 1):
                if x < 0 or x >= width:
                    continue
                dx = (x - cx) / radius
                if dx * dx + dy * dy > 1.0:
                    continue
                alpha = int(clamp((0.18 - dx) / 0.72, 0.0, 1.0) * 105)
                spx[x, y] = (0, 0, 0, alpha)
        baked_shadow.putalpha(Image.composite(baked_shadow.getchannel("A"), Image.new("L", (width, height), 0), mask))
        moon.alpha_composite(baked_shadow.filter(ImageFilter.GaussianBlur(radius=2.4)))

        img.alpha_composite(moon)
        img.save(path)

    def _make_loading_shadow_mask(self, path: Path, width: int = 1920, height: int = 1080) -> None:
        img = Image.new("RGBA", (width, height), (0, 0, 0, 0))
        px = img.load()
        for y in range(height):
            ny = y / max(height - 1, 1)
            for x in range(width):
                nx = x / max(width - 1, 1)
                # Wide, soft moving terminator.  The card itself slides left as progress rises.
                edge = 0.68 + math.sin((ny - 0.5) * math.pi) * 0.045
                feather = clamp((edge - nx) / 0.34, 0.0, 1.0)
                feather = feather * feather * (3.0 - 2.0 * feather)
                vignette = clamp(1.0 - ((nx - 0.55) ** 2 + (ny - 0.50) ** 2) * 1.1, 0.0, 1.0)
                alpha = int(clamp(255 * feather + 58 * (1.0 - vignette), 0, 255))
                px[x, y] = (0, 0, 0, alpha)
        img = img.filter(ImageFilter.GaussianBlur(radius=1.1))
        img.save(path)

    def reset_hole_mask(self, holes: list[Hole]) -> None:
        size = self.hole_mask_size
        self.hole_mask_image = Image.new("L", (size, size), 255)
        for hole in holes:
            self.paint_hole(hole, save=False)
        self._save_hole_assets()

    def paint_hole(self, hole: Hole, save: bool = True) -> None:
        if self.hole_mask_image is None:
            self.reset_hole_mask([])
        assert self.hole_mask_image is not None
        size = self.hole_mask_size
        def to_px(v: float) -> int:
            return int(((v / (WORLD_HALF * 2.0)) + 0.5) * (size - 1))
        cx = to_px(hole.x)
        cy = to_px(-hole.y)
        rr = int((hole.radius / (WORLD_HALF * 2.0)) * (size - 1) * 1.12)
        draw = ImageDraw.Draw(self.hole_mask_image)
        draw.ellipse((cx - rr, cy - rr, cx + rr, cy + rr), fill=0)
        if rr > 5:
            draw.ellipse((cx - rr - 4, cy - rr - 4, cx + rr + 4, cy + rr + 4), outline=72, width=8)
        if save:
            self._save_hole_assets()

    def _save_hole_assets(self) -> None:
        assert self.hole_mask_image is not None
        self.hole_mask_image.save(self.hole_mask_path)
        base = Image.open(self._surface_base_path).convert("RGBA")
        detail = Image.open(self._surface_detail_path).convert("RGBA")
        alpha = self.hole_mask_image.resize(base.size, Image.Resampling.LANCZOS)
        merged = base.copy()
        merged.alpha_composite(detail)
        merged.putalpha(alpha)
        merged.save(self.hole_overlay_path)

    def _tileable_blur(self, img: Image.Image, radius: float) -> Image.Image:
        if radius <= 0.0:
            return img
        w, h = img.size
        tiled = Image.new("RGBA", (w * 3, h * 3), (0, 0, 0, 0))
        for oy in range(3):
            for ox in range(3):
                tiled.paste(img, (ox * w, oy * h))
        blurred = tiled.filter(ImageFilter.GaussianBlur(radius=radius))
        return blurred.crop((w, h, w * 2, h * 2))

    def _draw_wrapped_ellipse(self, draw: ImageDraw.ImageDraw, size: int, box: tuple[float, float, float, float], *, fill=None, outline=None, width: int = 1) -> None:
        # Draw a stamp across all tile offsets so craters remain continuous when
        # Panda3D repeats the material over the terrain mesh.
        for ox in (-size, 0, size):
            for oy in (-size, 0, size):
                shifted = (box[0] + ox, box[1] + oy, box[2] + ox, box[3] + oy)
                draw.ellipse(shifted, fill=fill, outline=outline, width=width)

    def _mimas_tileable_grain(self, nx: float, ny: float) -> float:
        tau = math.tau
        return (
            math.sin((nx * 17.0 + ny * 5.0) * tau + 0.37) * 0.46
            + math.cos((nx * -9.0 + ny * 19.0) * tau - 1.12) * 0.31
            + math.sin((nx * 31.0 + ny * 23.0) * tau + 2.41) * 0.17
            + math.cos((nx * 43.0 - ny * 37.0) * tau + 0.88) * 0.08
        )

    def _make_mimas_snow_base(self, path: Path, size: int = 1024) -> None:
        """Tile-safe dusty snow/ice regolith for Mimas.

        The texture is intentionally warm gray/off-white instead of blue.  Every
        base-wave frequency is an integer cycle and every crater stamp is wrapped
        around the texture edges, so repeated UVs do not leave hard seams or
        mismatched border patterns on large terrain tiles.
        """
        img = Image.new("RGBA", (size, size), (220, 218, 210, 255))
        px = img.load()
        tau = math.tau
        for y in range(size):
            ny = y / max(size, 1)
            for x in range(size):
                nx = x / max(size, 1)
                broad = (
                    math.sin(nx * tau * 1.0 + 0.32) * 0.22
                    + math.cos(ny * tau * 2.0 - 0.54) * 0.18
                    + math.sin((nx + ny) * tau * 3.0 + 0.17) * 0.12
                    + math.cos((nx - ny) * tau * 4.0 - 1.31) * 0.08
                )
                dust_lens = max(0.0, math.sin((nx * 3.0 + ny * 2.0) * tau + 0.44)) ** 5.0
                compacted = max(0.0, math.cos((nx * -2.0 + ny * 5.0) * tau - 0.27)) ** 4.0
                grain = self._mimas_tileable_grain(nx, ny)
                tone = int(clamp(218 + broad * 33.0 - dust_lens * 23.0 - compacted * 13.0 + grain * 5.0, 156, 246))
                # Slight beige/gray contamination matches dirty icy regolith; avoid
                # the Enceladus cyan ice palette.
                r = int(clamp(tone + 8, 0, 255))
                g = int(clamp(tone + 5, 0, 255))
                b = int(clamp(tone - 5, 0, 255))
                px[x, y] = (r, g, b, 255)
        draw = ImageDraw.Draw(img, "RGBA")
        for i in range(76):
            cx = (i * 149 + 37) % size
            cy = (i * 211 + 83) % size
            rr = 8 + (i * 17) % 64
            shade = 126 + (i % 9) * 7
            box = (cx - rr, cy - rr * 0.86, cx + rr, cy + rr * 0.86)
            self._draw_wrapped_ellipse(draw, size, box, outline=(shade, shade - 1, shade - 9, 38), width=2 + (i % 2))
            if i % 3 == 0:
                inner = (cx - rr * 0.48, cy - rr * 0.38, cx + rr * 0.48, cy + rr * 0.38)
                self._draw_wrapped_ellipse(draw, size, inner, fill=(118, 116, 108, 18))
            if i % 5 == 0:
                rim = (cx - rr * 1.04, cy - rr * 0.90, cx + rr * 1.04, cy + rr * 0.90)
                self._draw_wrapped_ellipse(draw, size, rim, outline=(236, 234, 224, 24), width=1)
        img = self._tileable_blur(img, 0.36)
        img.save(path)

    def _make_mimas_subsurface_base(self, path: Path, size: int = 1024) -> None:
        """Tile-safe darker buried crust texture for exposed crater rims/walls."""
        img = Image.new("RGBA", (size, size), (188, 184, 174, 255))
        px = img.load()
        tau = math.tau
        for y in range(size):
            ny = y / max(size, 1)
            for x in range(size):
                nx = x / max(size, 1)
                broad = (
                    math.sin(nx * tau * 2.0 + 0.11) * 0.25
                    + math.cos(ny * tau * 3.0 - 0.73) * 0.20
                    + math.sin((nx - ny) * tau * 4.0 + 1.2) * 0.13
                )
                slump = max(0.0, math.sin((nx * 6.0 + ny * 2.0) * tau + 0.21)) ** 6.0 * 27.0
                dark_dust = max(0.0, math.cos((nx * 3.0 - ny * 7.0) * tau - 0.68)) ** 5.0 * 20.0
                grain = self._mimas_tileable_grain(nx + 0.19, ny - 0.07)
                tone = int(clamp(184 + broad * 30.0 - slump - dark_dust + grain * 6.0, 112, 226))
                px[x, y] = (int(clamp(tone + 8,0,255)), int(clamp(tone + 5,0,255)), int(clamp(tone - 6,0,255)), 255)
        draw = ImageDraw.Draw(img, "RGBA")
        for i in range(48):
            cx = (i * 181 + 61) % size
            cy = (i * 127 + 29) % size
            rr = 14 + (i * 23) % 88
            box = (cx - rr, cy - rr * 0.72, cx + rr, cy + rr * 0.72)
            self._draw_wrapped_ellipse(draw, size, box, outline=(104, 102, 96, 36), width=2)
            if i % 4 == 0:
                self._draw_wrapped_ellipse(draw, size, (cx - rr * 0.32, cy - rr * 0.22, cx + rr * 0.32, cy + rr * 0.22), fill=(92, 90, 84, 14))
        img = self._tileable_blur(img, 0.30)
        img.save(path)

    def _iapetus_texture_grain(self, nx: float, ny: float) -> float:
        tau = math.tau
        return (
            math.sin((nx * 19.0 + ny * 5.0) * tau + 0.61) * 0.40
            + math.cos((nx * -11.0 + ny * 23.0) * tau - 0.47) * 0.30
            + math.sin((nx * 37.0 + ny * 29.0) * tau + 1.73) * 0.20
            + math.cos((nx * 61.0 - ny * 43.0) * tau + 0.28) * 0.10
        )

    def _make_iapetus_regolith_base(self, path: Path, size: int = 1024) -> None:
        size = min(size, 512)
        """Neutral gray/dark regolith for low Iapetus plains.

        This replaces the inherited cyan Enceladus ice palette when the active moon
        is Iapetus.  The texture has Cassini Regio dark patches, bright icy flecks,
        and wrapped crater stamps so the flat lowlands no longer read as blue ice.
        """
        img = Image.new("RGBA", (size, size), (176, 174, 168, 255))
        px = img.load()
        tau = math.tau
        for y in range(size):
            ny = y / max(size, 1)
            for x in range(size):
                nx = x / max(size, 1)
                broad = (
                    math.sin(nx * tau * 1.0 + 0.42) * 0.22
                    + math.cos(ny * tau * 2.0 - 0.26) * 0.17
                    + math.sin((nx + ny) * tau * 3.0 + 1.0) * 0.13
                    + math.cos((nx - ny) * tau * 4.0 - 0.35) * 0.08
                )
                cassini_patch = max(0.0, math.sin((nx * 2.0 + ny * 1.0) * tau + 0.35)) ** 3.4
                bright_ice = max(0.0, math.cos((nx * -3.0 + ny * 2.0) * tau - 0.75)) ** 5.0
                grain = self._iapetus_texture_grain(nx, ny)
                tone = clamp(174 + broad * 42.0 - cassini_patch * 84.0 + bright_ice * 34.0 + grain * 7.0, 62, 232)
                warm = cassini_patch * 12.0
                px[x, y] = (
                    int(clamp(tone + 3 + warm, 0, 255)),
                    int(clamp(tone + 1 + warm * 0.45, 0, 255)),
                    int(clamp(tone - 6 - cassini_patch * 10.0, 0, 255)),
                    255,
                )
        draw = ImageDraw.Draw(img, "RGBA")
        for i in range(118):
            cx = (i * 137 + 41) % size
            cy = (i * 197 + 73) % size
            rr = 5 + (i * 19) % 82
            shade = 72 + (i % 11) * 8
            box = (cx - rr, cy - rr * 0.88, cx + rr, cy + rr * 0.88)
            self._draw_wrapped_ellipse(draw, size, box, outline=(shade + 24, shade + 24, shade + 18, 20), width=1 + (i % 3 == 0))
            if i % 4 == 0:
                self._draw_wrapped_ellipse(draw, size, (cx - rr * 0.50, cy - rr * 0.38, cx + rr * 0.50, cy + rr * 0.38), fill=(54, 52, 48, 7))
            if i % 5 == 0:
                self._draw_wrapped_ellipse(draw, size, (cx - rr * 1.03, cy - rr * 0.94, cx + rr * 1.03, cy + rr * 0.94), outline=(224, 224, 216, 16), width=1)
        img = self._tileable_blur(img, 0.24)
        img.save(path)

    def _make_iapetus_cassini_ridge_base(self, path: Path, size: int = 1024) -> None:
        size = min(size, 512)
        """High-contrast Cassini Regio ridge material.

        The exposed ridge needs cratered dark/bright albedo, diagonal scar bands,
        and bright icy cuts rather than the old neutral-white Enceladus mountain
        material.
        """
        img = Image.new("RGBA", (size, size), (188, 186, 180, 255))
        px = img.load()
        tau = math.tau
        for y in range(size):
            ny = y / max(size, 1)
            for x in range(size):
                nx = x / max(size, 1)
                long_bands = (
                    math.sin((nx * 2.0 + ny * 0.55) * tau + 0.18) * 0.28
                    + math.sin((nx * 5.0 - ny * 1.20) * tau - 1.22) * 0.14
                    + math.cos((nx * -1.0 + ny * 4.0) * tau + 0.44) * 0.13
                )
                dark_lens = max(0.0, math.sin((nx * 1.0 + ny * 1.0) * tau + 0.9)) ** 2.2
                black_scar = max(0.0, math.sin((nx * 7.0 + ny * 2.0) * tau - 0.2)) ** 9.0
                bright_cut = max(0.0, math.cos((nx * 4.0 - ny * 6.0) * tau + 0.5)) ** 7.0
                grain = self._iapetus_texture_grain(nx + 0.13, ny - 0.09)
                tone = clamp(176 + long_bands * 44.0 - dark_lens * 100.0 - black_scar * 52.0 + bright_cut * 62.0 + grain * 8.0, 46, 244)
                px[x, y] = (
                    int(clamp(tone + 5 + dark_lens * 10.0, 0, 255)),
                    int(clamp(tone + 3 + dark_lens * 4.0, 0, 255)),
                    int(clamp(tone - 7 - dark_lens * 14.0, 0, 255)),
                    255,
                )
        draw = ImageDraw.Draw(img, "RGBA")
        for i in range(142):
            cx = (i * 163 + 23) % size
            cy = (i * 109 + 151) % size
            rr = 4 + (i * 29) % 96
            elongated = 0.60 + (i % 5) * 0.08
            box = (cx - rr, cy - rr * elongated, cx + rr, cy + rr * elongated)
            self._draw_wrapped_ellipse(draw, size, box, outline=(82, 80, 74, 22), width=1 + (i % 4 == 0))
            if i % 3 == 0:
                self._draw_wrapped_ellipse(draw, size, (cx - rr * 0.46, cy - rr * 0.30, cx + rr * 0.46, cy + rr * 0.30), fill=(42, 40, 36, 8))
            if i % 6 == 0:
                self._draw_wrapped_ellipse(draw, size, (cx - rr * 1.04, cy - rr * elongated * 1.08, cx + rr * 1.04, cy + rr * elongated * 1.08), outline=(230, 228, 218, 16), width=1)
        # Diagonal eroded scar lines, wrapped by drawing shifted copies.
        for i in range(46):
            y0 = (i * 53 + 19) % size
            length = 320 + (i * 37) % 420
            x0 = (i * 127 + 11) % size
            pts = []
            for step in range(10):
                t = step / 9.0
                pts.append((x0 + t * length, y0 + math.sin(t * math.pi) * 20.0 + t * length * 0.23))
            for ox in (-size, 0, size):
                for oy in (-size, 0, size):
                    shifted = [(x + ox, y + oy) for x, y in pts]
                    draw.line(shifted, fill=(40, 40, 38, 7), width=1)
                    draw.line([(x + 1.5, y - 1.0) for x, y in shifted], fill=(238, 238, 232, 4), width=1)
        img = self._tileable_blur(img, 0.22)
        img.save(path)


    def _make_triton_frost_base(self, path: Path, size: int = 1024) -> None:
        img = Image.new("RGBA", (size, size), (206, 214, 224, 255))
        px = img.load(); tau = math.tau
        for y in range(size):
            ny = y / max(size - 1, 1)
            for x in range(size):
                nx = x / max(size - 1, 1)
                valley_streak = math.sin((nx * 1.16 + ny * 0.24) * tau * 3.0 + math.sin(ny * tau * 0.82) * 1.1) * 0.14
                frost = 0.5 + 0.5 * math.cos((nx * 2.4 - ny * 1.5) * tau * 2.1)
                broken = math.sin((nx * 5.2 + ny * 3.6) * tau) * 0.045 + math.cos((nx * 3.3 - ny * 4.4) * tau) * 0.040
                fan_field = 0.5 + 0.5 * math.sin(nx * tau * 0.72 - ny * tau * 0.24 + 0.4)
                fan_field += 0.5 + 0.5 * math.cos(nx * tau * -0.28 + ny * tau * 0.68 - 0.7)
                fan = max(0.0, fan_field * 0.5 - 0.57) ** 1.7
                tone = clamp(0.60 + valley_streak + broken + frost * 0.10 - fan * 0.48, 0.10, 0.96)
                px[x, y] = (
                    int(clamp(152 + tone * 96 - fan * 48, 0, 255)),
                    int(clamp(160 + tone * 92 - fan * 42, 0, 255)),
                    int(clamp(174 + tone * 86 - fan * 30, 0, 255)),
                    255,
                )
        img = self._tileable_blur(img, 0.36)
        img.save(path)

    def _make_triton_rock_base(self, path: Path, size: int = 1024) -> None:
        img = Image.new("RGBA", (size, size), (112, 120, 130, 255))
        px = img.load(); tau = math.tau
        for y in range(size):
            ny = y / max(size - 1, 1)
            for x in range(size):
                nx = x / max(size - 1, 1)
                ridge = math.sin((nx * 1.35 + ny * 0.28) * tau * 4.0) * 0.16 + math.cos((nx * -0.48 + ny * 1.10) * tau * 3.2) * 0.12
                fracture = max(0.0, math.sin((nx * 2.8 - ny * 2.1) * tau + 0.5)) ** 6 * 0.22
                frost = max(0.0, math.cos((nx * 4.0 + ny * 1.2) * tau)) ** 8 * 0.20
                tone = clamp(0.30 + ridge - fracture + frost, 0.06, 0.78)
                px[x, y] = (int(74 + tone * 108), int(80 + tone * 112), int(90 + tone * 122), 255)
        img = self._tileable_blur(img, 0.30)
        img.save(path)

    def _make_mars_regolith_base(self, path: Path, size: int = 1024) -> None:
        img = Image.new("RGBA", (size, size), (148, 94, 54, 255))
        px = img.load(); tau = math.tau
        rng = random.Random(43043)
        for y in range(size):
            ny = y / max(size - 1, 1)
            for x in range(size):
                nx = x / max(size - 1, 1)
                dune = math.sin((nx * 5.2 + ny * 0.84) * tau + math.sin(ny * tau * 1.2) * 0.75) * 0.12
                broad = math.sin((nx * 0.48 + ny * 0.74) * tau * 1.6) * 0.13 + math.cos((nx * 0.28 - ny * 0.78) * tau * 1.9) * 0.09
                dust = 0.5 + 0.5 * math.sin((nx * 0.62 + ny * 0.29) * tau)
                frost = max(0.0, (abs(ny - 0.5) - 0.23) / 0.27) ** 1.6
                grain = rng.randrange(-6, 7)
                tone = clamp(0.44 + dune + broad + dust * 0.04 - frost * 0.12, 0.14, 0.92)
                r = int(clamp(96 + tone * 118 + frost * 34 + grain, 0, 255))
                g = int(clamp(52 + tone * 82 + frost * 28 + grain * 0.35, 0, 255))
                b = int(clamp(26 + tone * 42 + frost * 36, 0, 255))
                px[x, y] = (r, g, b, 255)
        img = img.filter(ImageFilter.GaussianBlur(radius=0.80))
        img.save(path)

    def _make_mars_rock_base(self, path: Path, size: int = 1024) -> None:
        img = Image.new("RGBA", (size, size), (118, 82, 54, 255))
        px = img.load(); tau = math.tau
        for y in range(size):
            ny = y / max(size - 1, 1)
            for x in range(size):
                nx = x / max(size - 1, 1)
                fractured = math.sin(nx * tau * 5.4 + ny * tau * 1.2) * 0.15 + math.cos(ny * tau * 4.8) * 0.10
                dust = max(0.0, math.sin((nx * 2.2 - ny * 2.8) * tau)) ** 6 * 0.18
                frost = max(0.0, (abs(ny - 0.5) - 0.24) / 0.26) ** 1.7 * 0.32
                tone = clamp(0.34 + fractured - dust + frost, 0.10, 0.84)
                px[x, y] = (int(74 + tone * 122), int(48 + tone * 86), int(28 + tone * 58 + frost * 28), 255)
        img = img.filter(ImageFilter.GaussianBlur(radius=0.60))
        img.save(path)

    def _make_titan_tholin_base(self, path: Path, size: int = 1024) -> None:
        img = Image.new("RGBA", (size, size), (146, 96, 28, 255))
        px = img.load(); tau = math.tau
        rng = random.Random(33033)
        for y in range(size):
            ny = y / max(size - 1, 1)
            for x in range(size):
                nx = x / max(size - 1, 1)
                # Softer dune fields.  Pass32's texture was too scratchy and read
                # like wire/grid lines under low-angle haze, so high-frequency marks
                # are pushed into broad tonal bands instead.
                dune = math.sin((nx * 5.4 + ny * 0.92) * tau + math.sin(ny * tau * 1.4) * 0.85) * 0.135
                dune += math.sin((nx * 9.8 + ny * 1.40) * tau) * 0.028
                broad = math.sin((nx * 0.50 + ny * 0.86) * tau * 1.7) * 0.145 + math.cos((nx * 0.36 - ny * 0.88) * tau * 2.1) * 0.10
                wet = max(0.0, math.sin((nx * 1.1 - ny * 1.35) * tau * 1.8)) ** 7
                haze = 0.5 + 0.5 * math.sin((nx * 0.55 + ny * 0.35) * tau)
                grain = rng.randrange(-7, 8)
                tone = clamp(0.43 + dune + broad - wet * 0.24 + haze * 0.045, 0.14, 0.92)
                r = int(clamp(102 + tone * 120 + grain, 0, 255))
                g = int(clamp(66 + tone * 84 + grain * 0.40, 0, 255))
                b = int(clamp(18 + tone * 26 - wet * 8, 0, 255))
                px[x, y] = (r, g, b, 255)
        img = img.filter(ImageFilter.GaussianBlur(radius=0.82))
        img.save(path)

    def _make_titan_ice_rock_base(self, path: Path, size: int = 1024) -> None:
        img = Image.new("RGBA", (size, size), (108, 72, 32, 255))
        px = img.load(); tau = math.tau
        for y in range(size):
            ny = y / max(size - 1, 1)
            for x in range(size):
                nx = x / max(size - 1, 1)
                fractured = math.sin(nx * tau * 6.0 + ny * tau * 1.4) * 0.17 + math.cos(ny * tau * 5.2) * 0.12
                tar = max(0.0, math.sin((nx * 2.4 - ny * 3.2) * tau)) ** 8 * 0.40
                evaporite = max(0.0, math.cos((nx * 3.8 + ny * 1.1) * tau)) ** 10 * 0.18
                tone = clamp(0.32 + fractured - tar + evaporite, 0.10, 0.82)
                px[x, y] = (int(72 + tone * 118), int(48 + tone * 82), int(22 + tone * 40), 255)
        img = img.filter(ImageFilter.GaussianBlur(radius=0.65))
        img.save(path)

    def _make_titan_methane_texture(self, path: Path, size: int = 768) -> None:
        img = Image.new("RGBA", (size, size), (10, 8, 5, 255))
        px = img.load(); tau = math.tau
        for y in range(size):
            ny = y / max(size - 1, 1)
            for x in range(size):
                nx = x / max(size - 1, 1)
                # Broad, low-contrast hydrocarbon ripples: avoid screen-door bands or
                # grid-like stripes when the plane alpha fades across shorelines.
                ripple_a = math.sin((nx * 3.3 + ny * 1.15) * tau + math.sin(ny * tau * 1.6) * 0.9) * 0.030
                ripple_b = math.cos((nx * 1.1 - ny * 2.25) * tau + math.sin(nx * tau * 0.7) * 0.7) * 0.024
                drift = math.sin((nx * 0.80 + ny * 0.55) * tau) * 0.020
                glint = max(0.0, math.sin((nx * 1.35 - ny * 0.82) * tau * 2.0 + 0.4)) ** 18
                haze_reflect = max(0.0, math.cos((nx * 0.62 + ny * 1.10) * tau)) ** 9
                depth = clamp(0.15 + ripple_a + ripple_b + drift + glint * 0.52 + haze_reflect * 0.08, 0.0, 1.0)
                px[x, y] = (int(10 + depth * 104), int(8 + depth * 70), int(5 + depth * 26), 255)
        img = img.filter(ImageFilter.GaussianBlur(radius=0.90))
        img.save(path)

    def _make_pluto_nitrogen_base(self, path: Path, size: int = 1024) -> None:
        img = Image.new("RGBA", (size, size), (196, 202, 210, 255))
        px = img.load(); tau = math.tau
        for y in range(size):
            ny = y / max(size - 1, 1)
            for x in range(size):
                nx = x / max(size - 1, 1)
                long_wave = math.sin((nx * 1.18 + ny * 0.24) * tau * 3.4 + math.sin(ny * tau * 0.74) * 0.9) * 0.18
                long_wave += math.cos((nx * -0.58 + ny * 1.02) * tau * 2.5) * 0.11
                rugged = max(0.0, math.sin((nx * 1.92 - ny * 0.42) * tau * 2.6 + 0.7)) ** 4.4 * 0.15
                polygonal = math.sin((nx * 4.8 + ny * 3.9) * tau) * 0.05 + math.cos((nx * 2.8 - ny * 3.0) * tau) * 0.05
                spray_field = 0.5 + 0.5 * math.sin(nx * tau * 0.72 + ny * tau * 0.18 + 0.4)
                spray_field += 0.5 + 0.5 * math.cos(nx * tau * -0.22 + ny * tau * 0.66 - 0.2)
                spray_field += 0.5 + 0.5 * math.sin(nx * tau * 1.04 - ny * tau * 0.14 + 1.2)
                spray_field /= 3.0
                spray_shape = max(0.0, (spray_field - 0.54) / 0.46) ** 1.45
                spray_speckle = 0.5 + 0.5 * math.sin(nx * tau * 7.6 + ny * tau * 4.8)
                spray_speckle += 0.5 + 0.5 * math.cos(nx * tau * 6.2 - ny * tau * 5.6 + 0.8)
                spray_speckle *= 0.5
                spray = clamp(spray_shape * (0.68 + spray_speckle * 0.52), 0.0, 1.0)
                crack_a = max(0.0, 1.0 - abs(math.sin((nx * 2.7 + ny * 0.82) * tau + 0.18)) / 0.078) ** 5.0
                crack_b = max(0.0, 1.0 - abs(math.sin((nx * -1.1 + ny * 2.35) * tau - 0.42)) / 0.064) ** 5.2
                crack_c = max(0.0, 1.0 - abs(math.sin((nx * 3.7 - ny * 0.44) * tau + 0.61)) / 0.058) ** 5.6
                crack = clamp(max(crack_a, crack_b * 0.88, crack_c * 0.72), 0.0, 1.0)
                tone = clamp(0.56 + long_wave + rugged + polygonal - spray * 0.20 - crack * 0.22, 0.06, 0.88)
                rust = clamp(spray * 0.44 + crack * 0.18, 0.0, 0.72)
                px[x, y] = (
                    int(clamp(158 + tone * 66 + rust * 60 - crack * 40, 0, 255)),
                    int(clamp(162 + tone * 58 - rust * 34 - crack * 34, 0, 255)),
                    int(clamp(172 + tone * 48 - rust * 66 - crack * 44, 0, 255)),
                    255,
                )
        img = self._tileable_blur(img, 0.32)
        img.save(path)

    def _make_pluto_water_ice_base(self, path: Path, size: int = 1024) -> None:
        img = Image.new("RGBA", (size, size), (138, 136, 142, 255))
        px = img.load(); tau = math.tau
        for y in range(size):
            ny = y / max(size - 1, 1)
            for x in range(size):
                nx = x / max(size - 1, 1)
                wave = math.sin((nx * 1.16 + ny * 0.18) * tau * 4.2) * 0.17 + math.cos((nx * -0.52 + ny * 0.94) * tau * 3.2) * 0.13
                fracture = max(0.0, math.cos((nx * 2.1 - ny * 1.15) * tau * 2.55 - 0.2)) ** 6.4 * 0.18
                block = math.sin(nx * tau * 2.4 + ny * tau * 0.54) * 0.10 + math.cos(ny * tau * 3.2) * 0.09
                spray_field = 0.5 + 0.5 * math.sin(nx * tau * 0.76 + ny * tau * 0.16 + 0.1)
                spray_field += 0.5 + 0.5 * math.cos(nx * tau * -0.18 + ny * tau * 0.70 - 0.35)
                spray_field += 0.5 + 0.5 * math.sin(nx * tau * 1.12 - ny * tau * 0.12 + 0.95)
                spray_field /= 3.0
                spray_shape = max(0.0, (spray_field - 0.54) / 0.46) ** 1.38
                spray_speckle = 0.5 + 0.5 * math.sin(nx * tau * 7.0 + ny * tau * 4.4)
                spray_speckle += 0.5 + 0.5 * math.cos(nx * tau * 6.0 - ny * tau * 5.1 + 0.65)
                spray_speckle *= 0.5
                spray = clamp(spray_shape * (0.66 + spray_speckle * 0.54), 0.0, 1.0)
                crack_a = max(0.0, 1.0 - abs(math.sin((nx * 2.55 + ny * 0.94) * tau + 0.22)) / 0.070) ** 5.0
                crack_b = max(0.0, 1.0 - abs(math.sin((nx * -1.35 + ny * 2.12) * tau - 0.47)) / 0.060) ** 5.4
                crack = clamp(max(crack_a, crack_b * 0.92), 0.0, 1.0)
                tone = clamp(0.25 + wave + fracture + block - spray * 0.18 - crack * 0.18, 0.02, 0.78)
                rust = clamp(spray * 0.34 + crack * 0.18, 0.0, 0.64)
                px[x, y] = (
                    int(clamp(94 + tone * 96 + rust * 48 - crack * 34, 0, 255)),
                    int(clamp(98 + tone * 88 - rust * 26 - crack * 28, 0, 255)),
                    int(clamp(110 + tone * 98 - rust * 50 - crack * 38, 0, 255)),
                    255,
                )
        img = self._tileable_blur(img, 0.28)
        img.save(path)

    def _make_ice_base(self, path: Path, size: int = 1024) -> None:
        if IS_MIMAS_LEVEL:
            self._make_mimas_snow_base(path, size)
            return
        if IS_IAPETUS_LEVEL:
            self._make_iapetus_regolith_base(path, size)
            return
        if IS_TITAN_LEVEL:
            self._make_titan_tholin_base(path, size)
            return
        if IS_MARS_LEVEL:
            self._make_mars_regolith_base(path, size)
            return
        if IS_PLUTO_LEVEL:
            self._make_pluto_nitrogen_base(path, size)
            return
        if IS_TRITON_LEVEL:
            self._make_triton_frost_base(path, size)
            return
        img = Image.new("RGBA", (size, size), (176, 230, 248, 255))
        px = img.load()
        tau = math.tau
        for y in range(size):
            ny = y / size
            for x in range(size):
                nx = x / size
                large = (
                    math.sin(nx * tau * 2) * 0.10
                    + math.cos(ny * tau * 3) * 0.09
                    + math.sin((nx + ny) * tau * 4) * 0.07
                    + math.cos((nx - ny) * tau * 5) * 0.06
                )
                medium = (
                    math.sin(nx * tau * 9) * 0.035
                    + math.cos(ny * tau * 11) * 0.03
                    + math.sin((nx * 2.0 + ny) * tau * 7) * 0.025
                )
                frost = 0.5 + 0.5 * math.cos((nx * 3.0 - ny * 2.0) * tau * 2)
                shade = clamp(0.56 + large + medium, 0.0, 1.0)
                r = int(clamp(102 + shade * 74 + frost * 6, 0, 255))
                g = int(clamp(176 + shade * 72 + frost * 18, 0, 255))
                b = int(clamp(206 + shade * 82 + frost * 30, 0, 255))
                px[x, y] = (r, g, b, 255)
        img = img.filter(ImageFilter.GaussianBlur(radius=0.6))
        img.save(path)
    def _make_mountain_base(self, path: Path, size: int = 1024) -> None:
        if IS_MIMAS_LEVEL:
            self._make_mimas_subsurface_base(path, size)
            return
        if IS_IAPETUS_LEVEL:
            self._make_iapetus_cassini_ridge_base(path, size)
            return
        if IS_TITAN_LEVEL:
            self._make_titan_ice_rock_base(path, size)
            return
        if IS_MARS_LEVEL:
            self._make_mars_rock_base(path, size)
            return
        if IS_PLUTO_LEVEL:
            self._make_pluto_water_ice_base(path, size)
            return
        if IS_TRITON_LEVEL:
            self._make_triton_rock_base(path, size)
            return
        """White frost/stone texture for exposed Enceladus mountain terrain.

        Pass 82 keeps the material white but darkens fracture/slope shading so
        the raised mountain rows have stronger moonlit relief against cyan ice.
        """
        img = Image.new("RGBA", (size, size), (222, 224, 226, 255))
        px = img.load()
        rng = random.Random(8110)
        tau = math.tau
        for y in range(size):
            ny = y / max(size - 1, 1)
            for x in range(size):
                nx = x / max(size - 1, 1)
                broad = (
                    math.sin(nx * tau * 2.15 + 0.35) * 0.34
                    + math.cos(ny * tau * 1.85 - 0.15) * 0.28
                    + math.sin((nx + ny) * tau * 1.22 + 1.55) * 0.22
                    + math.cos((nx - ny) * tau * 2.65 - 0.70) * 0.16
                )
                # Long wind-scraped bands: bright crests paired with darker fracture
                # troughs.  These are neutral gray/white, not blue/cyan.
                band_a = math.sin((nx * 3.8 + ny * 1.15) * tau + 0.35)
                band_b = math.sin((nx * -1.2 + ny * 4.4) * tau - 0.90)
                crest = max(0.0, band_a) ** 6.0 * 24.0 + max(0.0, band_b) ** 7.0 * 16.0
                fracture = max(0.0, -band_a) ** 8.0 * 34.0 + max(0.0, -band_b) ** 9.0 * 22.0
                fine = (
                    math.sin((nx * 24.0 + ny * 4.0) * tau) * 2.3
                    + math.cos((nx * 5.0 - ny * 18.0) * tau) * 2.0
                    + rng.randrange(-5, 6)
                )
                tone = int(clamp(214 + broad * 21.0 + crest - fracture + fine, 160, 255))
                # Tiny warm-neutral bias prevents the mountains from reading cyan.
                r = int(clamp(tone + 3, 0, 255))
                g = int(clamp(tone + 2, 0, 255))
                b = int(clamp(tone + 1, 0, 255))
                px[x, y] = (r, g, b, 255)
        img = img.filter(ImageFilter.GaussianBlur(radius=0.34))
        img.save(path)

    def _make_ice_detail(self, path: Path, size: int = 1024) -> None:
        if IS_PLUTO_LEVEL:
            img = Image.new("RGBA", (size, size), (0, 0, 0, 0))
            px = img.load()
            tau = math.tau
            for y in range(size):
                ny = y / max(size, 1)
                for x in range(size):
                    nx = x / max(size, 1)
                    flow = math.sin((nx * 7.0 + ny * 1.4) * tau) * 0.26 + math.cos((nx * 2.2 - ny * 6.4) * tau) * 0.18
                    alpha = int(clamp(8 + (flow + 0.7) * 8.0, 0, 20))
                    tone = int(clamp(204 + flow * 20.0, 168, 236))
                    px[x, y] = (tone, tone + 4, min(255, tone + 16), alpha)
            img = img.filter(ImageFilter.GaussianBlur(radius=0.55))
            img.save(path)
            return
        if IS_MIMAS_LEVEL:
            img = Image.new("RGBA", (size, size), (0, 0, 0, 0))
            px = img.load()
            tau = math.tau
            # Very low-alpha, tile-safe compacted regolith grain.  Avoid the old
            # bright scratch-network look; Mimas should read cratered and dusty.
            for y in range(size):
                ny = y / max(size, 1)
                for x in range(size):
                    nx = x / max(size, 1)
                    dust = (
                        math.sin((nx * 13.0 + ny * 7.0) * tau + 0.44) * 0.36
                        + math.cos((nx * -21.0 + ny * 17.0) * tau - 0.21) * 0.24
                        + math.sin((nx * 37.0 - ny * 31.0) * tau + 1.6) * 0.15
                    )
                    alpha = int(clamp(5 + (dust + 0.75) * 7.0, 0, 16))
                    tone = int(clamp(202 + dust * 18.0, 162, 232))
                    px[x, y] = (tone, tone - 1, tone - 8, alpha)
            draw = ImageDraw.Draw(img, "RGBA")
            for i in range(54):
                cx = (i * 173 + 51) % size
                cy = (i * 137 + 99) % size
                rr = 9 + (i * 19) % 70
                shade = 114 + (i % 6) * 8
                self._draw_wrapped_ellipse(draw, size, (cx - rr, cy - rr * 0.78, cx + rr, cy + rr * 0.78), outline=(shade, shade - 2, shade - 9, 15), width=1 + (i % 5 == 0))
            # A few broad, wrapped scuff bands at low opacity provide scale without
            # creating visible texture tile breaks.
            for i in range(34):
                seed = i + 6400
                x0 = (seed * 71) % size
                y0 = (seed * 113) % size
                length = 120 + (seed * 17) % 260
                angle = -0.12 + math.sin(seed * 0.23) * 0.18
                for ox in (-size, 0, size):
                    for oy in (-size, 0, size):
                        x1 = x0 + math.cos(angle) * length
                        y1 = y0 + math.sin(angle) * length
                        draw.line((x0 + ox, y0 + oy, x1 + ox, y1 + oy), fill=(238, 232, 214, 10), width=1)
            img = self._tileable_blur(img, 0.30)
            img.save(path)
            return
        img = Image.new("RGBA", (size, size), (0, 0, 0, 0))
        draw = ImageDraw.Draw(img)

        def wrap_line(points, fill, width):
            for ox in (-size, 0, size):
                for oy in (-size, 0, size):
                    draw.line([(x + ox, y + oy) for x, y in points], fill=fill, width=width)

        tau = math.tau
        for i in range(380):
            seed = i + 1
            x = ((seed * 73) % size) + 0.5
            y = ((seed * 127) % size) + 0.5
            angle = ((seed * 0.2137) % 1.0) * tau
            points = [(x % size, y % size)]
            segments = 3 + (i % 4)
            for step in range(segments):
                step_len = 14 + ((seed * 19 + step * 13) % 34)
                angle += math.sin(seed * 0.17 + step * 1.31) * 0.45
                x += math.cos(angle) * step_len
                y += math.sin(angle) * step_len
                points.append((x % size, y % size))
            alpha = 40 + (i % 24)
            wrap_line(points, fill=(230, 240, 255, alpha), width=1 + (i % 7 == 0))
            if i % 3 == 0:
                branch = [points[min(1, len(points)-1)]]
                bx, by = branch[0]
                b_ang = angle + (0.6 if i % 2 else -0.6)
                for step in range(2):
                    step_len = 10 + ((seed * 11 + step * 7) % 18)
                    bx += math.cos(b_ang) * step_len
                    by += math.sin(b_ang) * step_len
                    branch.append((bx % size, by % size))
                    b_ang += (0.35 if step == 0 else -0.22)
                wrap_line(branch, fill=(216, 228, 245, 34 + (i % 16)), width=1)

        # Long shallow grain streaks echo the icy ridges and scoured look in the reference.
        for i in range(160):
            seed = i + 901
            y0 = (seed * 41) % size
            x0 = (seed * 67) % size
            length = 180 + (seed * 29) % 420
            angle = -0.18 + math.sin(seed * 0.19) * 0.22
            pts = []
            for j in range(8):
                t = j / 7.0
                xx = x0 + math.cos(angle) * length * (t - 0.5)
                yy = y0 + math.sin(angle) * length * (t - 0.5) + math.sin(t * math.tau + seed) * 7.0
                pts.append((xx % size, yy % size))
            wrap_line(pts, fill=(245, 252, 255, 28 + (i % 18)), width=1 + (i % 9 == 0))

        px = img.load()
        for y in range(size):
            ny = y / size
            for x in range(size):
                nx = x / size
                haze = (
                    math.sin(nx * tau * 3.0) * 0.08
                    + math.cos(ny * tau * 4.0) * 0.08
                    + math.sin((nx + ny) * tau * 5.0) * 0.06
                    + math.cos((nx * 1.7 - ny * 1.4) * tau * 6.0) * 0.04
                )
                boost = int(clamp(12 + (haze + 0.24) * 28.0, 0.0, 32.0))
                r, g, b, a = px[x, y]
                px[x, y] = (min(255, r + boost), min(255, g + boost), min(255, b + boost + 6), min(96, a + boost // 4))
        img = img.filter(ImageFilter.GaussianBlur(radius=0.72))
        img.save(path)

    def _make_water_texture(self, path: Path, size: int = 768) -> None:
        if IS_TITAN_LEVEL:
            self._make_titan_methane_texture(path, size)
            return
        img = Image.new("RGBA", (size, size), (0, 0, 0, 255))
        px = img.load()
        tau = math.tau
        for y in range(size):
            ny = y / size
            for x in range(size):
                nx = x / size
                wave = (
                    math.sin(nx * tau * 4) * 0.09
                    + math.cos(ny * tau * 5) * 0.08
                    + math.sin((nx + ny) * tau * 7) * 0.06
                    + math.cos((nx - ny) * tau * 6) * 0.05
                )
                caustic = 0.5 + 0.5 * math.sin((nx * 2.0 + ny * 3.0) * tau * 3)
                depth = clamp(0.12 + wave + caustic * 0.10, 0.0, 1.0)
                r = int(clamp(2 + depth * 14, 0, 255))
                g = int(clamp(12 + depth * 68, 0, 255))
                b = int(clamp(24 + depth * 120, 0, 255))
                px[x, y] = (r, g, b, 255)
        img = img.filter(ImageFilter.GaussianBlur(radius=1.0))
        img.save(path)

    def _make_underwater_blur_texture(self, path: Path, size: int = 512) -> None:
        img = Image.new("RGBA", (size, size), (0, 0, 0, 0))
        draw = ImageDraw.Draw(img, "RGBA")
        rng = random.Random(3737 + len(MOON_LEVEL_ID) * 19)
        # Large soft cyan/green lobes plus darker middle smears.  This gives the
        # cards a real blurred underwater volume instead of hard rectangles.
        for i in range(38):
            cx = rng.randrange(-size // 5, size + size // 5)
            cy = rng.randrange(-size // 5, size + size // 5)
            rx = rng.randrange(size // 8, size // 2)
            ry = rng.randrange(size // 18, size // 5)
            alpha = rng.randrange(22, 74)
            color = (42 + rng.randrange(38), 150 + rng.randrange(64), 164 + rng.randrange(52), alpha)
            draw.ellipse((cx - rx, cy - ry, cx + rx, cy + ry), fill=color)
        for i in range(14):
            cx = rng.randrange(0, size)
            cy = rng.randrange(0, size)
            rx = rng.randrange(size // 10, size // 3)
            ry = rng.randrange(size // 28, size // 10)
            draw.ellipse((cx - rx, cy - ry, cx + rx, cy + ry), fill=(0, 18, 20, rng.randrange(26, 72)))
        img = img.filter(ImageFilter.GaussianBlur(radius=18.0))
        img.save(path)

    def _make_seafloor_texture(self, path: Path, size: int = 1024) -> None:
        img = Image.new("RGBA", (size, size), (10, 12, 18, 255))
        px = img.load()
        tau = math.tau
        for y in range(size):
            ny = y / size
            for x in range(size):
                nx = x / size
                rough = (
                    math.sin(nx * tau * 6) * 0.08
                    + math.cos(ny * tau * 7) * 0.08
                    + math.sin((nx + ny) * tau * 5) * 0.06
                    + math.cos((nx - ny) * tau * 4) * 0.05
                )
                shade = clamp(0.28 + rough, 0.0, 1.0)
                r = int(clamp(18 + shade * 70, 0, 255))
                g = int(clamp(22 + shade * 78, 0, 255))
                b = int(clamp(30 + shade * 88, 0, 255))
                px[x, y] = (r, g, b, 255)
        img = img.filter(ImageFilter.GaussianBlur(radius=0.9))
        draw = ImageDraw.Draw(img)
        for i in range(420):
            x0 = (i * 89) % size
            y0 = (i * 233) % size
            length = 8 + (i * 17) % 34
            ang = ((i * 0.61) % 1.0) * tau
            x1 = (x0 + math.cos(ang) * length) % size
            y1 = (y0 + math.sin(ang) * length) % size
            for ox in (-size, 0, size):
                for oy in (-size, 0, size):
                    draw.line((x0 + ox, y0 + oy, x1 + ox, y1 + oy), fill=(120, 135, 160, 14 + (i % 20)), width=1)
        img.save(path)
    def _make_hole_ring_texture(self, path: Path, size: int = 512) -> None:
        if IS_PLUTO_LEVEL:
            img = Image.new("RGBA", (size, size), (0, 0, 0, 0))
            px = img.load()
            tau = math.tau
            for y in range(size):
                ny = y / max(size, 1)
                for x in range(size):
                    nx = x / max(size, 1)
                    flow = math.sin((nx * 7.0 + ny * 1.4) * tau) * 0.26 + math.cos((nx * 2.2 - ny * 6.4) * tau) * 0.18
                    alpha = int(clamp(8 + (flow + 0.7) * 8.0, 0, 20))
                    tone = int(clamp(204 + flow * 20.0, 168, 236))
                    px[x, y] = (tone, tone + 4, min(255, tone + 16), alpha)
            img = img.filter(ImageFilter.GaussianBlur(radius=0.55))
            img.save(path)
            return
        if IS_MIMAS_LEVEL:
            img = Image.new("RGBA", (size, size), (0, 0, 0, 0))
            draw = ImageDraw.Draw(img)
            outer = size * 0.49
            inner = size * 0.31
            cx = cy = size * 0.5
            for r in range(int(outer), int(inner), -1):
                t = (r - inner) / max(outer - inner, 1.0)
                alpha = int(94 * (1.0 - t) + 12)
                tone = int(205 + (1.0 - t) * 28)
                draw.ellipse((cx - r, cy - r, cx + r, cy + r), outline=(tone, tone - 2, tone - 10, alpha), width=2)
            img = img.filter(ImageFilter.GaussianBlur(radius=1.35))
            img.save(path)
            return
        img = Image.new("RGBA", (size, size), (0, 0, 0, 0))
        draw = ImageDraw.Draw(img)
        outer = size * 0.49
        inner = size * 0.33
        cx = cy = size * 0.5
        for r in range(int(outer), int(inner), -1):
            t = (r - inner) / max(outer - inner, 1.0)
            alpha = int(84 * (1.0 - t) + 10)
            tone = int(210 + (1.0 - t) * 22)
            color = (tone, tone + 12, 255, alpha)
            draw.ellipse((cx - r, cy - r, cx + r, cy + r), outline=color, width=2)
        img = img.filter(ImageFilter.GaussianBlur(radius=1.25))
        img.save(path)

    def _make_hole_wall_texture(self, path: Path, size: int = 768) -> None:
        if IS_MIMAS_LEVEL:
            img = Image.new("RGBA", (size, size), (0, 0, 0, 255))
            px = img.load()
            tau = math.tau
            for y in range(size):
                ny = y / max(size - 1, 1)
                compacted = 0.5 + 0.5 * math.sin(ny * tau * 11.0)
                dust_band = 0.5 + 0.5 * math.cos(ny * tau * 3.0 + 0.4)
                for x in range(size):
                    nx = x / max(size - 1, 1)
                    grain = 0.5 + 0.5 * math.sin(nx * tau * 14.0 + ny * tau * 1.7)
                    tone = int(clamp(126 + (1.0 - ny) * 82 + compacted * 36 - dust_band * 30 + grain * 12, 86, 238))
                    px[x, y] = (tone + 8, tone + 5, tone - 6, 255)
            draw = ImageDraw.Draw(img)
            for i in range(88):
                y = int((i / 87.0) * (size - 1))
                draw.line((0, y, size, y), fill=(230, 226, 212, 9 + (i % 9)), width=1)
            img = img.filter(ImageFilter.GaussianBlur(radius=0.68))
            img.save(path)
            return
        img = Image.new("RGBA", (size, size), (0, 0, 0, 255))
        px = img.load()
        tau = math.tau
        for y in range(size):
            ny = y / max(size - 1, 1)
            band = 0.5 + 0.5 * math.sin(ny * tau * 7.0 + math.sin(ny * tau * 1.7) * 0.8)
            micro = 0.5 + 0.5 * math.cos(ny * tau * 23.0)
            base = 0.18 + (1.0 - ny) * 0.28 + band * 0.12 + micro * 0.05
            for x in range(size):
                nx = x / max(size - 1, 1)
                grain = 0.5 + 0.5 * math.sin(nx * tau * 9.0 + ny * tau * 2.0)
                haze = 0.5 + 0.5 * math.cos((nx * 2.3 - ny * 0.6) * tau * 4.0)
                r = int(clamp(86 + base * 110 + grain * 14, 0, 255))
                g = int(clamp(116 + base * 112 + haze * 18, 0, 255))
                b = int(clamp(148 + base * 96 + band * 22, 0, 255))
                px[x, y] = (r, g, b, 255)
        draw = ImageDraw.Draw(img)
        for i in range(150):
            x = (i * 47) % size
            y = (i * 131) % size
            w = 6 + (i % 10)
            h = 14 + (i % 24)
            draw.ellipse((x, y, x + w, y + h), fill=(220, 236, 255, 18 + (i % 24)))
        for i in range(64):
            y = int((i / 63.0) * (size - 1))
            draw.line((0, y, size, y), fill=(238, 247, 255, 10 + (i % 10)), width=1)
        img = img.filter(ImageFilter.GaussianBlur(radius=0.65))
        img.save(path)

    def _make_sky_mist_texture(self, path: Path, size: int = 1024) -> None:
        img = Image.new("RGBA", (size, size), (0, 0, 0, 0))
        if IS_MIMAS_LEVEL:
            img.save(path)
            return
        haze = Image.new("RGBA", (size, size), (0, 0, 0, 0))
        draw = ImageDraw.Draw(haze)
        for band in range(22):
            frac = band / 21.0
            x = int(size * (0.04 + frac * 0.92))
            y = int(size * (0.44 + math.sin(band * 0.48) * 0.12))
            w = int(size * (0.26 + (band % 5) * 0.06))
            h = int(size * (0.032 + (band % 3) * 0.012))
            alpha = int(18 + (1.0 - abs(frac - 0.5) * 1.5) * 58)
            tint = 166 + (band % 5) * 10
            draw.ellipse((x - w, y - h, x + w, y + h), fill=(tint, tint + 24, 255, alpha))
        veil = haze.filter(ImageFilter.GaussianBlur(radius=30))
        img.alpha_composite(veil)
        streak = Image.new("RGBA", (size, size), (0, 0, 0, 0))
        sd = ImageDraw.Draw(streak)
        for band in range(16):
            y = int(size * (0.38 + band * 0.025))
            sd.rectangle((0, y, size, y + int(size * 0.012)), fill=(196, 220, 255, 16 + (band % 4) * 7))
        img.alpha_composite(streak.filter(ImageFilter.GaussianBlur(radius=20)))
        img.save(path)

    def _make_vapor_cloud_texture(self, path: Path, size: int = 768) -> None:
        img = Image.new("RGBA", (size, size), (0, 0, 0, 0))
        if IS_MIMAS_LEVEL:
            img.save(path)
            return
        base = Image.new("RGBA", (size, size), (0, 0, 0, 0))
        draw = ImageDraw.Draw(base)
        cx = cy = size // 2
        for i in range(42):
            ang = (i / 42.0) * math.tau
            radius = size * (0.08 + (i % 7) * 0.018)
            ox = math.cos(ang) * size * (0.12 + (i % 5) * 0.018)
            oy = math.sin(ang) * size * (0.08 + (i % 6) * 0.015)
            w = radius * (1.6 + (i % 3) * 0.28)
            h = radius * (0.86 + (i % 4) * 0.18)
            alpha = 18 + (i % 5) * 8
            tint = 188 + (i % 4) * 8
            draw.ellipse((cx + ox - w, cy + oy - h, cx + ox + w, cy + oy + h), fill=(tint, tint + 24, 255, alpha))
        img.alpha_composite(base.filter(ImageFilter.GaussianBlur(radius=22)))
        rim = Image.new("RGBA", (size, size), (0, 0, 0, 0))
        rd = ImageDraw.Draw(rim)
        for i in range(12):
            scale = 0.18 + i * 0.026
            a = 16 - i if i < 12 else 4
            rd.ellipse((cx - size * scale * 1.45, cy - size * scale * 0.72, cx + size * scale * 1.45, cy + size * scale * 0.72), outline=(142, 208, 255, max(3, a)), width=2)
        img.alpha_composite(rim.filter(ImageFilter.GaussianBlur(radius=9)))
        img = img.filter(ImageFilter.GaussianBlur(radius=2.2))
        img.save(path)

    def _make_ground_haze_texture(self, path: Path, size: int = 768) -> None:
        img = Image.new("RGBA", (size, size), (0, 0, 0, 0))
        cx = cy = size // 2
        px = img.load()
        for y in range(size):
            ny = (y - cy) / (size * 0.5)
            for x in range(size):
                nx = (x - cx) / (size * 0.5)
                r = math.sqrt(nx * nx + ny * ny)
                if r > 1.0:
                    continue
                ring = 0.5 + 0.5 * math.sin((r * 5.2 + math.sin(nx * 5.0) * 0.12) * math.pi)
                streak = 0.5 + 0.5 * math.cos((nx * 7.5 - ny * 2.2) * math.pi)
                core = math.exp(-(r * 2.05) ** 2)
                falloff = clamp(1.0 - r, 0.0, 1.0)
                alpha = int(clamp((core * 0.42 + falloff ** 1.8 * 0.54 + ring * streak * 0.10) * 155, 0, 180))
                if IS_MIMAS_LEVEL:
                    px[x, y] = (230, 224, 205, int(alpha * 0.62))
                else:
                    px[x, y] = (88, 226, 255, alpha)
        draw = ImageDraw.Draw(img)
        for i in range(18):
            rr = int(size * (0.12 + i * 0.041))
            alpha = max(5, 34 - i)
            if IS_MIMAS_LEVEL:
                draw.ellipse((cx - rr, cy - rr, cx + rr, cy + rr), outline=(232, 226, 210, int(alpha * 0.72)), width=2)
            else:
                draw.ellipse((cx - rr, cy - rr, cx + rr, cy + rr), outline=(88, 232, 255, alpha), width=2)
        img = img.filter(ImageFilter.GaussianBlur(radius=5.5))
        img.save(path)

    def _make_holo_tech_texture(self, path: Path, size: int = 1024) -> None:
        """Generate a reusable HoloVerse-style technical surface texture.

        Dark graphite/teal base with cyan circuitry, scan bars, and panel seams.
        This is meant for drone/robot shells so their silhouettes stay the same while
        their surfaces gain a more distinct techno-holographic identity.
        """
        img = Image.new("RGBA", (size, size), (104, 142, 158, 255))
        draw = ImageDraw.Draw(img)

        # Base panel seams / large module fields
        panel_cols = 8
        panel_rows = 8
        for gy in range(panel_rows):
            for gx in range(panel_cols):
                x0 = int(gx * size / panel_cols)
                y0 = int(gy * size / panel_rows)
                x1 = int((gx + 1) * size / panel_cols)
                y1 = int((gy + 1) * size / panel_rows)
                shade = 92 + ((gx * 5 + gy * 7) % 48)
                draw.rectangle((x0, y0, x1, y1), fill=(shade, min(shade + 34, 220), min(shade + 52, 245), 255))
                draw.rectangle((x0, y0, x1, y1), outline=(130, 226, 250, 230), width=2)

        # Fine technical grid
        for i in range(0, size, 32):
            alpha = 24 if (i // 32) % 4 else 42
            draw.line((i, 0, i, size), fill=(142, 236, 255, min(alpha + 46, 160)), width=2)
            draw.line((0, i, size, i), fill=(142, 236, 255, min(alpha + 46, 160)), width=2)

        # Circuit traces and nodes
        for band in range(18):
            y = int(size * (0.06 + band * 0.05))
            x = int(size * (0.08 + (band % 3) * 0.05))
            segment_w = int(size * (0.08 + (band % 4) * 0.03))
            for step in range(5):
                x2 = min(size - 40, x + segment_w + step * int(size * 0.10))
                draw.line((x, y, x2, y), fill=(170, 252, 255, 225), width=5)
                draw.line((x2, y, x2, y + int(size * 0.024)), fill=(170, 252, 255, 210), width=5)
                node_r = 5 + (step % 2) * 2
                draw.ellipse((x2 - node_r, y - node_r, x2 + node_r, y + node_r), fill=(146, 246, 255, 205))
                x = x2 + int(size * 0.038)
                y += int(size * 0.012) * (1 if step % 2 == 0 else -1)

        # Diagonal scanning bars
        for i in range(-size, size, 84):
            draw.line((i, 0, i + size * 0.35, size), fill=(150, 238, 255, 72), width=16)

        # Soft glowing ports / holo emitters
        ports = Image.new("RGBA", (size, size), (0, 0, 0, 0))
        pd = ImageDraw.Draw(ports)
        for row in range(4):
            for col in range(5):
                cx = int(size * (0.14 + col * 0.18))
                cy = int(size * (0.16 + row * 0.20))
                rx = int(size * 0.022)
                ry = int(size * 0.010)
                pd.ellipse((cx - rx, cy - ry, cx + rx, cy + ry), fill=(130, 246, 255, 175))
                pd.ellipse((cx - rx * 2, cy - ry * 2, cx + rx * 2, cy + ry * 2), outline=(155, 248, 255, 92), width=2)
        img.alpha_composite(ports.filter(ImageFilter.GaussianBlur(radius=8)))

        # Thin edge frame so the wrap still reads technical when projected on round forms
        frame = Image.new("RGBA", (size, size), (0, 0, 0, 0))
        fd = ImageDraw.Draw(frame)
        for inset, alpha in ((12, 92), (34, 60), (58, 34)):
            fd.rectangle((inset, inset, size - inset, size - inset), outline=(96, 228, 255, alpha), width=2)
        img.alpha_composite(frame.filter(ImageFilter.GaussianBlur(radius=1.5)))
        img = img.filter(ImageFilter.GaussianBlur(radius=0.45))
        img.save(path)

    def _make_sheet_metal_texture(self, path: Path, size: int = 512) -> None:
        img = Image.new("RGBA", (size, size), (108, 128, 137, 255))
        draw = ImageDraw.Draw(img)
        for y in range(size):
            tone = 96 + int(22 * math.sin(y * 0.055)) + ((y // 17) % 3) * 4
            draw.line((0, y, size, y), fill=(tone, tone + 18, tone + 24, 255))
        # Brushed sheet-metal grain and riveted module seams.
        for x in range(0, size, 38):
            draw.line((x, 0, x, size), fill=(172, 194, 202, 72), width=1)
        for y in range(0, size, 64):
            draw.line((0, y, size, y), fill=(56, 74, 82, 130), width=2)
            draw.line((0, y + 3, size, y + 3), fill=(166, 190, 198, 68), width=1)
        for y in range(32, size, 64):
            for x in range(24, size, 64):
                r = 4
                draw.ellipse((x - r, y - r, x + r, y + r), fill=(56, 70, 76, 220))
                draw.ellipse((x - r + 1, y - r + 1, x + r - 1, y + r - 1), outline=(205, 226, 232, 90), width=1)
        # Light scratches, not noise-heavy; panels should read clean at distance.
        for i in range(90):
            x = (i * 83 + 19) % size
            y = (i * 47 + 31) % size
            length = 20 + (i % 4) * 12
            draw.line((x, y, min(size, x + length), y + (i % 3) - 1), fill=(218, 236, 240, 32), width=1)
        img = img.filter(ImageFilter.GaussianBlur(radius=0.25))
        img.save(path)

    def _make_solar_panel_texture(self, path: Path, size: int = 512) -> None:
        img = Image.new("RGBA", (size, size), (10, 24, 34, 255))
        draw = ImageDraw.Draw(img)
        cell = size // 8
        for gy in range(8):
            for gx in range(8):
                x0 = gx * cell + 4
                y0 = gy * cell + 4
                x1 = (gx + 1) * cell - 4
                y1 = (gy + 1) * cell - 4
                shade = 28 + ((gx * 9 + gy * 13) % 24)
                draw.rectangle((x0, y0, x1, y1), fill=(8, shade + 18, shade + 36, 255))
                draw.rectangle((x0, y0, x1, y1), outline=(78, 212, 245, 130), width=2)
                draw.line((x0 + 4, y0 + 6, x1 - 4, y0 + 6), fill=(150, 240, 255, 50), width=1)
        for i in range(0, size, 32):
            draw.line((i, 0, i + size // 3, size), fill=(120, 232, 255, 24), width=5)
        glow = Image.new("RGBA", (size, size), (0, 0, 0, 0))
        gd = ImageDraw.Draw(glow)
        gd.rectangle((18, 18, size - 18, size - 18), outline=(92, 238, 255, 80), width=4)
        img.alpha_composite(glow.filter(ImageFilter.GaussianBlur(radius=5)))
        img.save(path)

    def _make_star_texture(self, path: Path, size: int = 1024) -> None:
        if IS_PLUTO_LEVEL:
            img = Image.new("RGBA", (size, size), (0, 0, 3, 255))
            draw = ImageDraw.Draw(img)
            for i in range(1240):
                x = (i * 331 + 97) % size
                y = (i * 227 + 41) % size
                bright = 120 + (i * 29) % 120
                radius = 1 if (i % 9) else 2
                alpha = 188 if radius == 1 else 230
                draw.ellipse((x - radius, y - radius, x + radius, y + radius), fill=(bright, bright, min(255, bright + 28), alpha))
            for i in range(120):
                x = (i * 593 + 33) % size
                y = (i * 821 + 77) % size
                draw.ellipse((x - 2, y - 2, x + 2, y + 2), fill=(210, 225, 255, 186))
            haze = Image.new("RGBA", (size, size), (0, 0, 0, 0))
            haze_draw = ImageDraw.Draw(haze)
            for i in range(34):
                x = int(size * 0.08 + i * size * 0.026)
                y = int(size * 0.55 + math.sin(i * 0.52) * size * 0.08)
                w = int(size * 0.26)
                h = int(size * 0.05)
                haze_draw.ellipse((x - w, y - h, x + w, y + h), fill=(52, 72, 116, 10))
            img.alpha_composite(haze.filter(ImageFilter.GaussianBlur(radius=20)))
            img = img.filter(ImageFilter.GaussianBlur(radius=0.15))
            img.save(path)
            return
        img = Image.new("RGBA", (size, size), (2, 3, 7, 255))
        draw = ImageDraw.Draw(img)
        # Keep the sky mostly dark from Enceladus' colder Saturn-lit perspective,
        # with only a restrained field of colder stars.
        for i in range(520):
            x = (i * 331 + 97) % size
            y = (i * 227 + 41) % size
            bright = 120 + (i * 19) % 96
            radius = 1 if (i % 11) else 2
            draw.ellipse((x - radius, y - radius, x + radius, y + radius), fill=(bright, bright, min(255, bright + 22), 220))
        # A very faint broad galactic haze keeps the background from feeling empty.
        haze = Image.new("RGBA", (size, size), (0, 0, 0, 0))
        haze_draw = ImageDraw.Draw(haze)
        for i in range(28):
            x = int(size * 0.16 + i * size * 0.024)
            y = int(size * 0.62 + math.sin(i * 0.55) * size * 0.06)
            w = int(size * 0.22)
            h = int(size * 0.05)
            haze_draw.ellipse((x - w, y - h, x + w, y + h), fill=(72, 84, 112, 10))
        haze = haze.filter(ImageFilter.GaussianBlur(radius=18))
        img.alpha_composite(haze)
        img = img.filter(ImageFilter.GaussianBlur(radius=0.18))
        img.save(path)

    def _make_saturn_body_texture(self, path: Path, width: int = 1800, height: int = 900) -> None:
        """Generate a more Saturn-like wrapped body texture:
        - fewer, broader atmospheric bands
        - softer cream/gold color variation
        - polar storm features at both ends, inspired by Saturn's polar look

        Because the sphere now shares the ring axis, these polar features will
        remain aligned to that same axis in-world.
        """
        img = Image.new("RGBA", (width, height), (0, 0, 0, 255))
        px = img.load()
        tau = math.tau

        for y in range(height):
            v = y / max(height - 1, 1)
            lat = (v - 0.5) * math.pi  # -pi/2..pi/2
            lat_norm = math.sin(lat)
            colat_n = v * math.pi
            colat_s = (1.0 - v) * math.pi

            # Broader, softer band language with far fewer stripes.
            broad_band = 0.5 + 0.5 * math.sin((v * 4.2 + 0.025 * math.sin(v * tau * 2.0)) * tau)
            mid_band = 0.5 + 0.5 * math.sin((v * 8.6 + 0.015 * math.sin(v * tau * 3.0)) * tau)
            gentle_swirl = 0.5 + 0.5 * math.cos((v - 0.5) * tau * 1.25)
            equator_brightness = math.exp(-((v - 0.5) / 0.18) ** 2)
            polar_fade = max(0.0, abs(lat_norm) - 0.64) / 0.36
            warm_lat_shift = 0.5 + 0.5 * math.cos((v - 0.5) * tau * 0.7)

            for x in range(width):
                u = x / max(width - 1, 1)
                lon = u * tau

                longitudinal_drift = 0.5 + 0.5 * math.sin(lon * 1.3 + v * tau * 0.9)
                cloud_noise = 0.5 + 0.5 * math.sin(lon * 3.4 + v * tau * 5.1)
                seam_soft = 0.985 + 0.015 * math.cos((u - 0.5) * tau)

                base_r = 184 + broad_band * 24 + mid_band * 10 + gentle_swirl * 16 + equator_brightness * 10 + longitudinal_drift * 4
                base_g = 160 + broad_band * 20 + mid_band * 8 + gentle_swirl * 13 + equator_brightness * 8 + cloud_noise * 3
                base_b = 122 + broad_band * 12 + mid_band * 5 + gentle_swirl * 8 + equator_brightness * 3

                # Polar color cool-down and soft desaturation like Saturn's poles.
                polar_cool = polar_fade * (0.35 + 0.20 * cloud_noise)
                r = base_r * (1.0 - 0.14 * polar_fade)
                g = base_g * (1.0 - 0.06 * polar_fade)
                b = base_b * (1.0 + 0.08 * polar_fade)

                # North/south polar vortex rings inspired by Saturn imagery.
                north_ring = math.exp(-((colat_n - 0.34) / 0.10) ** 2)
                north_core = math.exp(-(colat_n / 0.17) ** 2)
                south_ring = math.exp(-((colat_s - 0.34) / 0.10) ** 2)
                south_core = math.exp(-(colat_s / 0.17) ** 2)
                hex_mod = 0.78 + 0.22 * math.cos(lon * 6.0)
                storm_texture = 0.86 + 0.14 * math.sin(lon * 12.0 + v * tau * 1.8)

                north_blue = north_ring * hex_mod * storm_texture
                south_blue = south_ring * hex_mod * storm_texture * 0.88
                pole_ring_total = north_blue + south_blue
                pole_core_total = north_core * 0.75 + south_core * 0.65

                r += 18.0 * warm_lat_shift - 30.0 * pole_ring_total - 16.0 * pole_core_total
                g += 11.0 * warm_lat_shift + 12.0 * pole_ring_total + 6.0 * pole_core_total
                b += 4.0 * warm_lat_shift + 92.0 * pole_ring_total + 46.0 * pole_core_total + 22.0 * polar_cool

                # Reduce stripe harshness overall.
                softness = 1.0 - 0.08 * polar_fade
                px[x, y] = (
                    int(clamp(r * softness * seam_soft, 0, 255)),
                    int(clamp(g * softness * seam_soft, 0, 255)),
                    int(clamp(b * softness * seam_soft, 0, 255)),
                    255,
                )

        # Add a few broad atmospheric lanes only, not many tight stripes.
        band_overlay = Image.new("RGBA", (width, height), (0, 0, 0, 0))
        bd = ImageDraw.Draw(band_overlay)
        broad_lanes = [
            (0.19, 12, (234, 217, 184, 10)),
            (0.33, 10, (214, 194, 160, 8)),
            (0.50, 14, (244, 226, 190, 12)),
            (0.66, 10, (204, 182, 150, 8)),
            (0.80, 12, (228, 208, 180, 9)),
        ]
        for center, thickness, color in broad_lanes:
            yy = int(height * center)
            bd.rectangle((0, yy - thickness, width, yy + thickness), fill=color)

        # Subtle ring-shadow streaks across the equatorial region.
        shadow = Image.new("RGBA", (width, height), (0, 0, 0, 0))
        sd = ImageDraw.Draw(shadow)
        for offset, alpha, thick in ((0.497, 24, 6), (0.529, 11, 3), (0.468, 10, 3)):
            yy = int(height * offset)
            sd.rectangle((0, yy - thick, width, yy + thick), fill=(0, 0, 0, alpha))

        img.alpha_composite(band_overlay.filter(ImageFilter.GaussianBlur(radius=6.0)))
        img.alpha_composite(shadow.filter(ImageFilter.GaussianBlur(radius=4.0)))
        img = img.filter(ImageFilter.GaussianBlur(radius=0.55))
        img.save(path)

    def _make_neptune_texture(self, path: Path, width: int = 1800, height: int = 900) -> None:
        """Generate a soft, gas-heavy Neptune wrap.  Triton's sky view should read
        as layered blue atmosphere rather than bright painted stripes.
        """
        img = Image.new("RGBA", (width, height), (18, 52, 138, 255))
        px = img.load()
        tau = math.tau
        for y in range(height):
            v = y / max(height - 1, 1)
            lat = abs(math.sin((v - 0.5) * math.pi))
            broad_a = 0.5 + 0.5 * math.sin((v * 2.35 + 0.055 * math.sin(v * tau * 1.4)) * tau + 0.25)
            broad_b = 0.5 + 0.5 * math.sin((v * 4.70 + 0.036 * math.cos(v * tau * 2.2)) * tau + 1.30)
            broad_c = 0.5 + 0.5 * math.cos((v * 1.35 - 0.028 * math.sin(v * tau * 3.0)) * tau - 0.55)
            for x in range(width):
                u = x / max(width - 1, 1)
                lon = u * tau
                gas_flow = 0.5 + 0.5 * math.sin(lon * 1.65 + v * tau * 2.05 + math.sin(v * tau * 1.1) * 0.75)
                gas_flow_2 = 0.5 + 0.5 * math.cos(lon * 2.55 - v * tau * 1.65 + math.sin(lon * 0.7) * 0.55)
                haze = 0.5 + 0.5 * math.sin(lon * 0.82 + v * tau * 0.95 + 1.20)
                cloud_soft = max(0.0, math.sin(lon * 3.6 - v * tau * 3.1 + math.sin(v * tau * 1.8) * 0.9)) ** 3.0

                # Broad, overlapping gas zones.  Contrast is intentionally low so
                # the sphere reads as a blended gas giant from Triton's horizon.
                r = 16 + broad_a * 8 + broad_b * 5 + broad_c * 4 + gas_flow * 3 + haze * 2 + cloud_soft * 10
                g = 56 + broad_a * 18 + broad_b * 11 + broad_c * 8 + gas_flow * 7 + gas_flow_2 * 5 + haze * 4 + cloud_soft * 18
                b = 150 + broad_a * 30 + broad_b * 18 + broad_c * 14 + gas_flow * 10 + gas_flow_2 * 7 + haze * 5 + cloud_soft * 22

                polar = max(0.0, lat - 0.62) / 0.38
                r += polar * 5
                g += polar * 8
                b += polar * 9

                # Keep a muted storm oval, but blend it into the gas instead of
                # carving a sharp mark into the surface.
                dx = ((u - 0.68 + 0.5) % 1.0) - 0.5
                dy = v - 0.56
                storm = math.exp(-((dx / 0.092) ** 2 + (dy / 0.064) ** 2))
                storm_wake = math.exp(-(((dx + 0.095) / 0.19) ** 2 + ((dy - 0.004) / 0.052) ** 2))
                r -= storm * 8
                g -= storm * 13
                b -= storm * 18
                r += storm_wake * 4
                g += storm_wake * 7
                b += storm_wake * 9

                px[x, y] = (
                    int(clamp(r, 0, 255)),
                    int(clamp(g, 0, 255)),
                    int(clamp(b, 0, 255)),
                    255,
                )

        # A heavier final blur removes the diagonal line artifacts that were
        # reading as hard painted stripes on the sphere.
        img = img.filter(ImageFilter.GaussianBlur(radius=3.8))
        img.save(path)

    def _make_jupiter_texture(self, path: Path, width: int = 1800, height: int = 900) -> None:
        """Generate Europa's seamless, band-first equirectangular Jupiter wrap.

        Pass95 removes the global mottled/turbulence treatment.  Jupiter's readable
        identity comes from alternating light zones and darker orange/brown belts;
        only low-amplitude longitudinal waviness and cloud streaks disturb those
        horizontal lanes.  The Great Red Spot remains localized in the wrapped
        storm frames instead of contaminating the entire planet texture.
        """
        img = Image.new("RGBA", (width, height), (0, 0, 0, 255))
        px = img.load()
        tau = math.tau

        # Authored latitude palette: broad cream zones alternate with darker tan /
        # orange belts.  Interpolation keeps transitions natural and avoids flat
        # painted stripes while preserving the dominant horizontal grammar.
        controls = (
            (0.00, (172.0, 143.0, 116.0)),
            (0.07, (216.0, 196.0, 168.0)),
            (0.13, (151.0, 111.0, 78.0)),
            (0.20, (232.0, 211.0, 178.0)),
            (0.28, (166.0, 120.0, 82.0)),
            (0.35, (239.0, 220.0, 187.0)),
            (0.43, (181.0, 132.0, 91.0)),
            (0.50, (229.0, 202.0, 159.0)),
            (0.57, (238.0, 220.0, 188.0)),
            (0.64, (159.0, 109.0, 76.0)),
            (0.72, (228.0, 203.0, 165.0)),
            (0.80, (174.0, 127.0, 91.0)),
            (0.89, (221.0, 200.0, 173.0)),
            (1.00, (171.0, 143.0, 119.0)),
        )

        def palette_at(v: float) -> tuple[float, float, float]:
            vv = clamp(v, 0.0, 1.0)
            for idx in range(len(controls) - 1):
                p0, c0 = controls[idx]
                p1, c1 = controls[idx + 1]
                if vv <= p1:
                    t = clamp((vv - p0) / max(p1 - p0, 1e-6), 0.0, 1.0)
                    # Smoothstep interpolation softens belt boundaries.
                    t = t * t * (3.0 - 2.0 * t)
                    return (
                        c0[0] + (c1[0] - c0[0]) * t,
                        c0[1] + (c1[1] - c0[1]) * t,
                        c0[2] + (c1[2] - c0[2]) * t,
                    )
            return controls[-1][1]

        for y in range(height):
            v = y / max(height - 1, 1)
            lat = (v - 0.5) * math.pi
            polar = clamp((abs(math.sin(lat)) - 0.67) / 0.33, 0.0, 1.0)
            for x in range(width):
                u = x / max(width - 1, 1)
                lon = u * tau
                # Small periodic latitude warps make belts flow around the planet
                # without breaking them into blotches.  All terms are seamless at U.
                band_warp = (
                    0.0048 * math.sin(lon * 1.0 + v * tau * 0.7)
                    + 0.0024 * math.sin(lon * 3.0 - v * tau * 1.4 + 0.8)
                    + 0.0012 * math.sin(lon * 7.0 + v * tau * 2.1 - 1.2)
                )
                r, g, b = palette_at(v + band_warp)

                # Restrained cloud streak variation stays aligned with the belts.
                streak_a = math.sin(lon * 4.0 + v * tau * 10.0)
                streak_b = math.sin(lon * 9.0 - v * tau * 6.0 + 1.1)
                fine = math.sin(lon * 17.0 + v * tau * 15.0 - 0.4)
                streak = streak_a * 3.6 + streak_b * 1.9 + fine * 0.7
                r += streak
                g += streak * 0.82
                b += streak * 0.58

                # Jupiter's poles stay slightly cooler/desaturated than the warm
                # equatorial belt field.
                r *= 1.0 - polar * 0.07
                g *= 1.0 - polar * 0.025
                b *= 1.0 + polar * 0.07

                px[x, y] = (
                    int(clamp(r, 0, 255)),
                    int(clamp(g, 0, 255)),
                    int(clamp(b, 0, 255)),
                    255,
                )

        # A light blur merges individual streak samples while retaining the authored
        # belts/zones.  This is intentionally much less destructive than the old
        # high-frequency turbulence + heavy blur lane.
        img = img.filter(ImageFilter.GaussianBlur(radius=0.85))
        img.save(path)

    def _make_jupiter_storm_shell_frames(self, paths: list[Path], width: int = 1200, height: int = 600) -> None:
        """Build seamless equirectangular storm/lightning frames for a UV sphere.

        The old Pass92 frames were local billboard sprites.  Pass93 writes the
        Great Red Spot into its true longitude/latitude neighborhood on a full 2:1
        alpha wrap.  These sources are composited into complete opaque Jupiter
        wraps; swapping those wraps animates turbulence on the original sphere.
        Tiny lightning filaments are baked into selected frames so they inherit the
        same UV curvature and terminator.
        """
        frame_count = max(len(paths), 1)
        tau = math.tau
        storm_u = 0.2556
        storm_v = 0.5777
        flash_pattern = (0.00, 0.16, 1.00, 0.08, 0.00, 0.72, 0.05, 0.88)

        for frame_idx, path in enumerate(paths):
            phase = (frame_idx / float(frame_count)) * tau
            flash_strength = flash_pattern[frame_idx % len(flash_pattern)]
            img = Image.new("RGBA", (width, height), (0, 0, 0, 0))
            px = img.load()
            for y in range(height):
                v = y / max(height - 1, 1)
                dy = v - storm_v
                # Quick latitude reject keeps regeneration inexpensive.
                if abs(dy) > 0.045:
                    continue
                for x in range(width):
                    u = x / max(width - 1, 1)
                    dx = ((u - storm_u + 0.5) % 1.0) - 0.5
                    if abs(dx) > 0.055:
                        continue

                    ex = dx / 0.0315
                    ey = dy / 0.0235
                    radius = math.sqrt(ex * ex + ey * ey)
                    if radius > 1.24:
                        continue
                    angle = math.atan2(ey, ex)

                    radial_warp = (
                        math.sin(angle * 5.0 + phase * 1.30) * 0.060
                        + math.sin(angle * 9.0 - phase * 0.90 + radius * 8.0) * 0.035
                        + math.sin(angle * 14.0 + phase * 2.20 - radius * 13.0) * 0.022
                    )
                    # A second, lower-frequency edge warp breaks the old perfect
                    # oval silhouette into hurricane-like lobes and trailing lanes.
                    edge_warp = (
                        math.sin(angle * 3.0 - phase * 0.72) * 0.060
                        + math.sin(angle * 8.0 + phase * 1.10) * 0.034
                        + math.sin(ex * 6.5 - ey * 4.0 + phase * 0.85) * 0.022
                    )
                    warped_r = radius + radial_warp
                    edge_r = radius + edge_warp + radial_warp * 0.42
                    if edge_r > 1.14:
                        continue
                    spiral_a = 0.5 + 0.5 * math.sin(angle * 4.0 - warped_r * 20.0 + phase * 1.05)
                    spiral_b = 0.5 + 0.5 * math.sin(angle * 7.0 - warped_r * 35.0 - phase * 1.72 + 0.8)
                    spiral_c = 0.5 + 0.5 * math.sin(angle * 12.0 - warped_r * 54.0 + phase * 2.45 - 1.2)
                    cross_shear = 0.5 + 0.5 * math.sin(ex * 16.0 - ey * 8.0 + phase * 1.9 + math.sin(angle * 6.0) * 1.25)
                    turbulence = clamp(spiral_a * 0.54 + spiral_b * 0.40 + spiral_c * 0.34, 0.0, 1.0)
                    broken_lane = clamp(turbulence * (0.56 + cross_shear * 0.62), 0.0, 1.0)

                    outer = clamp((1.14 - edge_r) / 0.23, 0.0, 1.0)
                    body = clamp((1.00 - edge_r) / 0.17, 0.0, 1.0)
                    eye = math.exp(-((ex / 0.22) ** 2 + (ey / 0.18) ** 2))
                    eye_rim = math.exp(-((radius - 0.25) / 0.068) ** 2)
                    outer_ring = math.exp(-((warped_r - 0.67) / 0.15) ** 2)

                    eddies = 0.0
                    for eddy_idx, (orbit_r, orbit_y, strength) in enumerate(((0.50, 0.22, 0.82), (0.72, -0.17, 0.66), (0.86, 0.11, 0.52), (0.61, -0.29, 0.46))):
                        eddy_phase = phase * (1.18 + eddy_idx * 0.39) + eddy_idx * 1.85
                        cx = math.cos(eddy_phase) * orbit_r
                        cy = math.sin(eddy_phase) * orbit_y
                        sx = 0.15 + eddy_idx * 0.018
                        sy = 0.12 + eddy_idx * 0.014
                        eddies += math.exp(-(((ex - cx) / sx) ** 2 + ((ey - cy) / sy) ** 2)) * strength
                    eddies = clamp(eddies, 0.0, 1.0)

                    wake = math.exp(-(((ex + 0.58 + math.sin(phase) * 0.06) / 0.54) ** 2 + ((ey + 0.02) / 0.23) ** 2))
                    alpha = outer * (32.0 + body * 68.0 + broken_lane * 76.0 + outer_ring * 24.0 + eddies * 48.0 + wake * 22.0)
                    alpha *= 1.0 - eye * 0.12
                    alpha *= clamp((1.14 - edge_r) / 0.12, 0.0, 1.0)
                    # Fragment the outer third so red cloud lanes taper and break
                    # instead of ending at one uniformly opaque oval boundary.
                    edge_mix = clamp((edge_r - 0.66) / 0.38, 0.0, 1.0)
                    lane_fragment = clamp(0.28 + broken_lane * 0.64 + cross_shear * 0.24 + eddies * 0.26, 0.0, 1.0)
                    alpha *= (1.0 - edge_mix) + edge_mix * lane_fragment

                    lane_ridge = broken_lane ** 1.35
                    lane_trough = (1.0 - broken_lane) ** 1.75
                    red = 148.0 + body * 52.0 + lane_ridge * 62.0 - lane_trough * body * 20.0 + outer_ring * 22.0 + eddies * 30.0
                    green = 58.0 + lane_ridge * 34.0 - lane_trough * body * 8.0 + outer_ring * 20.0 + eddies * 17.0 + eye_rim * 14.0
                    blue = 38.0 + lane_ridge * 10.0 - lane_trough * body * 3.0 + eye_rim * 6.0
                    red -= eye * 48.0
                    green -= eye * 18.0
                    blue -= eye * 6.0

                    # Distant lightning: narrow, intermittent filaments wholly inside
                    # the storm wrap.  They are deliberately only a few texels wide
                    # so Europa sees a tiny atmospheric flicker, not floating sprites.
                    lightning = 0.0
                    if flash_strength > 0.0 and radius < 0.93:
                        for bolt_idx, (base_y, bend, width_scale) in enumerate(((-0.22, 0.13, 1.0), (0.10, -0.11, 0.82), (0.31, 0.08, 0.72))):
                            local_phase = phase * (1.8 + bolt_idx * 0.32) + bolt_idx * 2.1
                            curve = base_y + bend * math.sin(ex * 5.2 + local_phase) + 0.035 * math.sin(ex * 15.0 - local_phase * 1.7)
                            x_window = math.exp(-((ex - (-0.06 + bolt_idx * 0.08)) / (0.55 - bolt_idx * 0.06)) ** 6)
                            dist = abs(ey - curve)
                            lightning = max(lightning, math.exp(-((dist / (0.016 * width_scale)) ** 2)) * x_window)
                        lightning *= flash_strength * clamp((0.94 - radius) / 0.12, 0.0, 1.0)

                    if lightning > 0.01:
                        alpha = max(alpha, 118.0 + lightning * 132.0)
                        red = red * (1.0 - lightning) + 248.0 * lightning
                        green = green * (1.0 - lightning) + 244.0 * lightning
                        blue = blue * (1.0 - lightning) + 218.0 * lightning

                    px[x, y] = (
                        int(clamp(red, 0, 255)),
                        int(clamp(green, 0, 255)),
                        int(clamp(blue, 0, 255)),
                        int(clamp(alpha, 0, 255)),
                    )
            img = img.filter(ImageFilter.GaussianBlur(radius=0.42))
            img.save(path)

    def _make_jupiter_wrapped_fx_frames(
        self,
        base_path: Path,
        shadow_path: Path,
        storm_paths: list[Path],
        output_paths: list[Path],
    ) -> None:
        """Composite the complete Jupiter presentation into full 2:1 wraps.

        Each output is opaque and contains the base belts, curved storm/lightning,
        and curved terminator in the same equirectangular coordinate space.  Runtime
        animation swaps these complete wraps on the original Jupiter sphere.
        """
        with Image.open(base_path) as source_base:
            base = source_base.convert("RGBA")
        target_size = base.size
        with Image.open(shadow_path) as source_shadow:
            shadow = source_shadow.convert("RGBA")
            if shadow.size != target_size:
                shadow = shadow.resize(target_size, Image.Resampling.LANCZOS)
        for storm_path, output_path in zip(storm_paths, output_paths):
            with Image.open(storm_path) as source_storm:
                storm = source_storm.convert("RGBA")
                if storm.size != target_size:
                    storm = storm.resize(target_size, Image.Resampling.LANCZOS)
            frame = base.copy()
            frame.alpha_composite(storm)
            frame.alpha_composite(shadow)
            frame.save(output_path)

    def _make_jupiter_shadow_texture(self, path: Path, width: int = 1200, height: int = 600) -> None:
        """Generate a seamless spherical terminator mask for Jupiter.

        Alpha is derived from each equirectangular texel's sphere normal and a
        fixed local light vector.  When mapped to the outer UV sphere the shadow
        curves across the gas giant instead of behaving like a camera-facing card.
        """
        img = Image.new("RGBA", (width, height), (0, 0, 0, 0))
        px = img.load()
        lx, ly, lz = (0.86, -0.50, 0.08)
        inv_len = 1.0 / math.sqrt(lx * lx + ly * ly + lz * lz)
        lx, ly, lz = lx * inv_len, ly * inv_len, lz * inv_len
        tau = math.tau
        for y in range(height):
            tex_v = y / max(height - 1, 1)
            sphere_v = 1.0 - tex_v
            theta = sphere_v * math.pi
            st = math.sin(theta)
            ct = math.cos(theta)
            for x in range(width):
                tex_u = x / max(width - 1, 1)
                sphere_u = 1.0 - tex_u
                phi = sphere_u * tau
                nx = math.cos(phi) * st
                ny = math.sin(phi) * st
                nz = ct
                light = nx * lx + ny * ly + nz * lz
                # Wide penumbra, strong night side, and a restrained deep-shadow
                # lift preserve some band detail rather than painting half black.
                night = clamp((0.55 - light) / 0.75, 0.0, 1.0)
                deep = clamp((-0.10 - light) / 0.42, 0.0, 1.0)
                alpha = (night ** 1.10) * 178.0 + (deep ** 1.7) * 40.0
                polar_soft = 0.93 + 0.07 * math.cos((tex_v - 0.5) * math.pi)
                px[x, y] = (0, 0, 0, int(clamp(alpha * polar_soft, 0, 205)))
        img = img.filter(ImageFilter.GaussianBlur(radius=2.4))
        img.save(path)

    def _make_moon_texture(self, path: Path, size: int = 256) -> None:
        img = Image.new("RGBA", (size, size), (0, 0, 0, 0))
        draw = ImageDraw.Draw(img)
        cx = cy = size // 2
        radius = int(size * 0.42)
        for y in range(size):
            dy = (y - cy) / radius
            if abs(dy) > 1.0:
                continue
            for x in range(size):
                dx = (x - cx) / radius
                dist = math.sqrt(dx * dx + dy * dy)
                if dist > 1.0:
                    continue
                shade = math.sqrt(max(0.0, 1.0 - dist * dist))
                crater = 0.5 + 0.5 * math.sin((dx * 9.0 + dy * 6.0) * math.pi)
                ridge = 0.5 + 0.5 * math.cos((dx * 3.0 - dy * 7.0) * math.pi)
                base = 118 + crater * 28 + ridge * 16
                r = int(clamp(base + shade * 18, 0, 255))
                g = int(clamp(base + shade * 18, 0, 255))
                b = int(clamp(base + shade * 20, 0, 255))
                a = int(clamp(255 * (shade ** 0.78), 0, 255))
                draw.point((x, y), fill=(r, g, b, a))
        img = img.filter(ImageFilter.GaussianBlur(radius=0.28))
        img.save(path)

    def _make_sun_texture(self, path: Path, size: int = 512) -> None:
        img = Image.new("RGBA", (size, size), (0, 0, 0, 0))
        draw = ImageDraw.Draw(img)
        cx = cy = size // 2
        max_r = int(size * 0.44)
        for r in range(max_r, 0, -1):
            t = r / max_r
            alpha = int(255 * ((1.0 - t) ** 0.25) * 0.22)
            if r < max_r * 0.35:
                alpha = int(alpha * 2.0)
            color = (255, int(250 - t * 24), int(210 - t * 70), int(clamp(alpha, 0, 255)))
            draw.ellipse((cx - r, cy - r, cx + r, cy + r), fill=color)
        img = img.filter(ImageFilter.GaussianBlur(radius=8))
        img.save(path)


class WorldGenerator:
    def __init__(self, seed: int = 42013) -> None:
        if IS_MIMAS_LEVEL and seed == 42013:
            seed = 69031
        self.seed = seed
        self.small_cell = 500.0 if IS_MIMAS_LEVEL else (820.0 if IS_PLUTO_LEVEL else 620.0)
        self.large_cell = 1240.0 if IS_MIMAS_LEVEL else (2120.0 if IS_PLUTO_LEVEL else 1460.0)
        # Pass 37 stability cache:
        # Keep the full Pass 36 procedural terrain, but avoid repeating thousands
        # of deterministic hash/height calculations during mesh construction,
        # scanner updates, plumes, and verification shots.
        self._hash_cache: dict[tuple[int, int, int], float] = {}
        self._subsurface_cache: dict[tuple[float, float], float] = {}
        self._surface_cache: dict[tuple[float, float], float] = {}
        self._seafloor_cache: dict[tuple[float, float], float] = {}

    def _hash01(self, ix: int, iy: int, salt: int = 0) -> float:
        key = (ix, iy, salt)
        cached = self._hash_cache.get(key)
        if cached is not None:
            return cached
        n = (ix * 374761393 + iy * 668265263 + self.seed * 982451653 + salt * 362437) & 0xFFFFFFFF
        n = (n ^ (n >> 13)) * 1274126177 & 0xFFFFFFFF
        n = (n ^ (n >> 16)) & 0xFFFFFFFF
        value = n / 4294967295.0
        self._hash_cache[key] = value
        return value

    def _layer_craters(self, x: float, y: float, cell_size: float, rad_min: float, rad_max: float, depth_scale: float, rim_scale: float) -> float:
        cx = math.floor(x / cell_size)
        cy = math.floor(y / cell_size)
        total = 0.0
        for iy in range(cy - 1, cy + 2):
            for ix in range(cx - 1, cx + 2):
                center_x = (ix + 0.22 + self._hash01(ix, iy, 1) * 0.56) * cell_size
                center_y = (iy + 0.22 + self._hash01(ix, iy, 2) * 0.56) * cell_size
                radius = rad_min + self._hash01(ix, iy, 3) * (rad_max - rad_min)
                depth = radius * depth_scale * (0.90 + self._hash01(ix, iy, 4) * 0.42)
                dx = x - center_x
                dy = y - center_y
                dist = math.sqrt(dx * dx + dy * dy)
                if dist > radius * 1.85:
                    continue
                t = dist / radius
                bowl = -depth * 1.18 * math.exp(-((t / 0.80) ** 2.12))
                flat_floor = -depth * 0.24 * max(0.0, 1.0 - (t / 0.34) ** 2.0)
                inner_scarp = -depth * 0.12 * math.exp(-(((t - 0.46) / 0.16) ** 2.0))
                rim = depth * rim_scale * 1.18 * math.exp(-(((t - 1.02) / 0.18) ** 2.0))
                outer_slump = -depth * 0.08 * math.exp(-(((t - 1.28) / 0.20) ** 2.0))
                lift = depth * 0.05 * math.exp(-(((t - 1.46) / 0.24) ** 2.0))
                total += bowl + flat_floor + inner_scarp + rim + outer_slump + lift
        return total

    def _rolling_hill_fields(self, x: float, y: float, cell_size: float, height_min: float, height_max: float) -> float:
        """Broad smooth frozen uplands; keeps terrain as real heightfield, not props."""
        cx = math.floor(x / cell_size)
        cy = math.floor(y / cell_size)
        total = 0.0
        for iy in range(cy - 1, cy + 2):
            for ix in range(cx - 1, cx + 2):
                if self._hash01(ix, iy, 71) > 0.82:
                    continue
                center_x = (ix + 0.16 + self._hash01(ix, iy, 72) * 0.68) * cell_size
                center_y = (iy + 0.18 + self._hash01(ix, iy, 73) * 0.64) * cell_size
                angle = self._hash01(ix, iy, 74) * math.tau
                ca = math.cos(angle)
                sa = math.sin(angle)
                rx = cell_size * (0.50 + self._hash01(ix, iy, 75) * 0.34)
                ry = cell_size * (0.38 + self._hash01(ix, iy, 76) * 0.30)
                dx = x - center_x
                dy = y - center_y
                lx = dx * ca + dy * sa
                ly = -dx * sa + dy * ca
                r2 = (lx / rx) ** 2 + (ly / ry) ** 2
                if r2 > 3.8:
                    continue
                height = height_min + self._hash01(ix, iy, 77) * (height_max - height_min)
                dome = height * math.exp(-(r2 ** 1.30))
                total += dome
        return total

    def _valley_network(self, x: float, y: float) -> float:
        """Long shadowable troughs similar to the reference image's ice cuts."""
        total = 0.0
        families = (
            (x, y, 1120.0, 97, 0.86),
            (y, x, 1460.0, 143, 0.54),
        )
        for primary, secondary, spacing, salt, weight in families:
            ci = math.floor(primary / spacing)
            for idx in range(ci - 2, ci + 3):
                base = (idx + 0.16 + self._hash01(idx, salt, salt + 1) * 0.68) * spacing
                amp_a = 130.0 + self._hash01(idx, salt, salt + 2) * 155.0
                amp_b = 56.0 + self._hash01(idx, salt, salt + 3) * 74.0
                freq_a = 0.00070 + self._hash01(idx, salt, salt + 4) * 0.00052
                freq_b = 0.0017 + self._hash01(idx, salt, salt + 5) * 0.00078
                phase_a = self._hash01(idx, salt, salt + 6) * math.tau
                phase_b = self._hash01(idx, salt, salt + 7) * math.tau
                line = base + math.sin(secondary * freq_a + phase_a) * amp_a + math.sin(secondary * freq_b + phase_b) * amp_b
                width = 98.0 + self._hash01(idx, salt, salt + 8) * 112.0
                depth = (22.0 + self._hash01(idx, salt, salt + 9) * 28.0) * weight
                dist = abs(primary - line)
                if dist > width * 5.0:
                    continue
                trough = -depth * math.exp(-((dist / width) ** 1.55))
                shoulder = depth * 0.22 * math.exp(-(((dist - width * 1.45) / (width * 0.95)) ** 2.0))
                total += trough + shoulder
        return total

    def _ravine_network(self, x: float, y: float) -> float:
        """Darker, narrower cuts nested in some trough floors; still terrain height only."""
        total = 0.0
        families = (
            (x, y, 2140.0, 211),
            (y, x, 2560.0, 263),
        )
        for primary, secondary, spacing, salt in families:
            ci = math.floor(primary / spacing)
            for idx in range(ci - 1, ci + 2):
                if self._hash01(idx, salt, salt + 1) > 0.56:
                    continue
                base = (idx + 0.12 + self._hash01(idx, salt, salt + 2) * 0.76) * spacing
                amp = 170.0 + self._hash01(idx, salt, salt + 3) * 210.0
                freq = 0.00052 + self._hash01(idx, salt, salt + 4) * 0.00036
                phase = self._hash01(idx, salt, salt + 5) * math.tau
                line = base + math.sin(secondary * freq + phase) * amp + math.sin(secondary * (freq * 2.15) + phase * 0.61) * amp * 0.18
                width = 34.0 + self._hash01(idx, salt, salt + 6) * 38.0
                depth = 15.0 + self._hash01(idx, salt, salt + 7) * 18.0
                dist = abs(primary - line)
                if dist > width * 4.8:
                    continue
                cut = -depth * math.exp(-((dist / width) ** 1.30))
                lip = depth * 0.10 * math.exp(-(((dist - width * 1.35) / (width * 0.85)) ** 2.0))
                total += cut + lip
        return total

    def _wind_ripple_relief(self, x: float, y: float) -> float:
        # Tiny wind/frost ridges help the terrain catch light like the reference.
        return (
            math.sin(x * 0.012 + math.sin(y * 0.0011) * 2.0) * 1.45
            + math.cos((x * 0.0085 + y * 0.0032)) * 1.10
            + math.sin((x - y) * 0.0064) * 0.85
        )

    def snow_drift_specs(self) -> list[dict[str, float]]:
        return []

    def _eroded_peak_fields(self, x: float, y: float) -> float:
        """Rare tall mountains with worn, walkable shoulders and eroded cuts."""
        cx = math.floor(x / 2400.0)
        cy = math.floor(y / 2400.0)
        total = 0.0
        for iy in range(cy - 1, cy + 2):
            for ix in range(cx - 1, cx + 2):
                if self._hash01(ix, iy, 301) > 0.44:
                    continue
                center_x = (ix + 0.18 + self._hash01(ix, iy, 302) * 0.64) * 2400.0
                center_y = (iy + 0.16 + self._hash01(ix, iy, 303) * 0.66) * 2400.0
                angle = self._hash01(ix, iy, 304) * math.tau
                ca = math.cos(angle)
                sa = math.sin(angle)
                rx = 560.0 + self._hash01(ix, iy, 305) * 480.0
                ry = 420.0 + self._hash01(ix, iy, 306) * 420.0
                dx = x - center_x
                dy = y - center_y
                lx = dx * ca + dy * sa
                ly = -dx * sa + dy * ca
                r = math.sqrt((lx / rx) ** 2 + (ly / ry) ** 2)
                if r > 2.6:
                    continue
                core_height = 96.0 + self._hash01(ix, iy, 307) * 116.0
                # Smooth mountain body
                mass = core_height * math.exp(-(r ** 1.55))
                # Broad shoulder keeps it walkable, not spiky.
                shoulder = core_height * 0.22 * math.exp(-(((r - 0.92) / 0.48) ** 2.0))
                # A gentle erosion shelf flattens the summit a bit.
                summit_shelf = -core_height * 0.10 * math.exp(-((r / 0.26) ** 2.0))
                # Carve long weathered channels down the flanks.
                gully = math.sin(lx * 0.008 + ly * 0.004 + self._hash01(ix, iy, 308) * math.tau)
                gully += math.sin(lx * 0.014 - ly * 0.003 + self._hash01(ix, iy, 309) * math.tau) * 0.55
                erosion = -max(0.0, gully) * (8.0 + self._hash01(ix, iy, 310) * 10.0) * math.exp(-(((r - 0.72) / 0.62) ** 2.0))
                total += mass + shoulder + summit_shelf + erosion
        return total

    def _subsurface_mountain_range_lift(self, x: float, y: float) -> float:
        """Raise long connected terrain ranges from the buried hard-ice layer.

        The flat sheet ice remains untouched at Z=0. This only changes the
        subsurface heightfield so ranges naturally clip through the ice plane
        and stretch toward the existing dark-side area.

        Pass 77 keeps the adjacent parallel rows and adds impact craters to the
        exposed mountain belts so the raised terrain feels more geologically worked.
        """
        # Fewer, broader families keep this fast while still producing visible
        # adjacent belts. Each family spawns aligned parallel rows offset along
        # the local normal, so rows line up and step away from one another.
        family_specs = (
            (-5000.0, 2500.0, DARK_SIDE_CENTER_X + 120.0, DARK_SIDE_CENTER_Y + 860.0, 380.0, 148.0, 0.82, 901),
            (-4700.0,  500.0, DARK_SIDE_CENTER_X + 920.0, DARK_SIDE_CENTER_Y - 220.0, 420.0, 162.0, 0.76, 941),
            (-2100.0, 1200.0, DARK_SIDE_CENTER_X + 40.0,  DARK_SIDE_CENTER_Y - 1320.0, 300.0, 116.0, 1.02, 967),
        )
        total = 0.0
        row_offsets = (-1560.0, 0.0, 1560.0)
        for sx, sy, ex, ey, width, height, crooked, salt in family_specs:
            min_x = min(sx, ex) - 2600.0
            max_x = max(sx, ex) + 2600.0
            min_y = min(sy, ey) - 2600.0
            max_y = max(sy, ey) + 2600.0
            if x < min_x or x > max_x or y < min_y or y > max_y:
                continue
            vx = ex - sx
            vy = ey - sy
            length_sq = vx * vx + vy * vy
            if length_sq <= 1.0:
                continue
            length = math.sqrt(length_sq)
            ux = vx / length
            uy = vy / length
            nx = -uy
            ny = ux
            for row_index, row_offset in enumerate(row_offsets):
                row_width = width * (1.0 if row_offset == 0.0 else 0.84)
                row_height = height * (1.0 if row_offset == 0.0 else 0.72)
                rsx = sx + nx * row_offset
                rsy = sy + ny * row_offset
                t = ((x - rsx) * vx + (y - rsy) * vy) / length_sq
                if t < -0.10 or t > 1.10:
                    continue
                tc = clamp(t, 0.0, 1.0)
                px = rsx + vx * tc
                py = rsy + vy * tc
                bend = math.sin(tc * math.pi * 2.4 + self._hash01(salt, row_index, 1) * math.tau) * row_width * 0.26 * crooked
                if row_offset != 0.0:
                    bend += math.sin(tc * math.pi * 5.3 + row_index * 1.7) * row_width * 0.05
                px += nx * bend
                py += ny * bend
                dist = (x - px) * nx + (y - py) * ny
                abs_dist = abs(dist)
                if abs_dist > row_width * 4.0:
                    continue
                end_fade = clamp(min((tc + 0.08) / 0.22, (1.10 - tc) / 0.24), 0.0, 1.0)
                dark_push = 0.76 + tc * 0.44
                core = math.exp(-((abs_dist / row_width) ** 1.36))
                shoulder = math.exp(-(((abs_dist - row_width * 1.16) / (row_width * 0.82)) ** 2.0)) * 0.28
                bank = math.exp(-(((abs_dist - row_width * 2.14) / (row_width * 1.02)) ** 2.0)) * 0.13
                knots = 0.88 + 0.12 * math.sin(tc * math.pi * 6.5 + self._hash01(salt, row_index, 2) * math.tau)
                flank_cut = -row_height * 0.16 * math.exp(-(((abs_dist - row_width * 1.62) / (row_width * 0.32)) ** 2.0))
                gully = -row_height * 0.06 * max(0.0, math.sin(tc * math.pi * 14.0 + dist * 0.008 + self._hash01(salt, row_index, 3) * math.tau))
                gully *= math.exp(-(((abs_dist - row_width * 0.64) / (row_width * 0.50)) ** 2.0))
                # Mountain-row crater fields: localized bowl depressions with faint uplift rims.
                crater_delta = 0.0
                crater_positions = (0.22, 0.48, 0.74)
                for crater_index, crater_t in enumerate(crater_positions):
                    crater_t += (self._hash01(salt, row_index, 20 + crater_index) - 0.5) * 0.06
                    crater_center_offset = (self._hash01(salt, row_index, 30 + crater_index) - 0.5) * row_width * 0.55
                    crater_radius = row_width * (0.32 + self._hash01(salt, row_index, 40 + crater_index) * 0.18)
                    crater_depth = row_height * (0.10 + self._hash01(salt, row_index, 50 + crater_index) * 0.07)
                    crater_rim = crater_depth * 0.40
                    along_world = (tc - crater_t) * length
                    across_world = dist - crater_center_offset
                    crater_norm = math.sqrt((along_world / (crater_radius * 1.45)) ** 2 + (across_world / crater_radius) ** 2)
                    if crater_norm < 1.85:
                        bowl = -crater_depth * math.exp(-((crater_norm / 0.84) ** 2.0))
                        rim = crater_rim * math.exp(-(((crater_norm - 1.02) / 0.30) ** 2.0))
                        crater_delta += bowl + rim
                lift = row_height * (core + shoulder + bank) * knots * dark_push + flank_cut + gully + crater_delta
                total += lift * end_fade
        return total

    def _seafloor_trench_network(self, x: float, y: float) -> float:
        """Deep submerged trenches; keeps the underwater relief far below the surface."""
        total = 0.0
        families = (
            (x, y, 2800.0, 501),
            (y, x, 3600.0, 557),
        )
        for primary, secondary, spacing, salt in families:
            ci = math.floor(primary / spacing)
            for idx in range(ci - 2, ci + 3):
                base = (idx + 0.10 + self._hash01(idx, salt, salt + 1) * 0.82) * spacing
                amp = 240.0 + self._hash01(idx, salt, salt + 2) * 260.0
                freq = 0.00034 + self._hash01(idx, salt, salt + 3) * 0.00018
                phase = self._hash01(idx, salt, salt + 4) * math.tau
                line = base + math.sin(secondary * freq + phase) * amp + math.sin(secondary * (freq * 2.2) + phase * 0.58) * amp * 0.22
                width = 150.0 + self._hash01(idx, salt, salt + 5) * 170.0
                depth = 72.0 + self._hash01(idx, salt, salt + 6) * 88.0
                dist = abs(primary - line)
                if dist > width * 5.2:
                    continue
                trough = -depth * math.exp(-((dist / width) ** 1.26))
                wall = depth * 0.12 * math.exp(-(((dist - width * 1.38) / (width * 0.88)) ** 2.0))
                total += trough + wall
        return total

    def _seafloor_abyssal_peaks(self, x: float, y: float) -> float:
        """Submerged volcanic/tectonic mountains; some rise high but default floor stays deep."""
        cx = math.floor(x / 3200.0)
        cy = math.floor(y / 3200.0)
        total = 0.0
        for iy in range(cy - 1, cy + 2):
            for ix in range(cx - 1, cx + 2):
                if self._hash01(ix, iy, 601) > 0.54:
                    continue
                center_x = (ix + 0.20 + self._hash01(ix, iy, 602) * 0.60) * 3200.0
                center_y = (iy + 0.18 + self._hash01(ix, iy, 603) * 0.64) * 3200.0
                rx = 420.0 + self._hash01(ix, iy, 604) * 540.0
                ry = 380.0 + self._hash01(ix, iy, 605) * 500.0
                dx = x - center_x
                dy = y - center_y
                r2 = (dx / rx) ** 2 + (dy / ry) ** 2
                if r2 > 3.6:
                    continue
                height = 42.0 + self._hash01(ix, iy, 606) * 84.0
                mound = height * math.exp(-(r2 ** 1.18))
                erosion = -height * 0.14 * max(0.0, math.sin(dx * 0.010 + dy * 0.004 + self._hash01(ix, iy, 607) * math.tau)) * math.exp(-(((math.sqrt(max(r2, 1e-6)) - 0.85) / 0.58) ** 2.0))
                total += mound + erosion
        return total

    def _branching_exposure_trenches(self, x: float, y: float) -> float:
        """Natural branching trench networks carved into exposed terrain.

        These cuts are intended to drop parts of raised terrain back toward the flat
        ice plane so the ice shows through as connected trench networks rather than
        isolated pits or hard wall pieces.
        """
        total = 0.0
        families = (
            (x, y, 1780.0, 701),
            (y, x, 2260.0, 761),
            (x * 0.78 + y * 0.22, y * 0.84 - x * 0.16, 2480.0, 821),
        )
        for primary, secondary, spacing, salt in families:
            ci = math.floor(primary / spacing)
            for idx in range(ci - 2, ci + 3):
                if self._hash01(idx, salt, salt + 1) > 0.74:
                    continue
                base = (idx + 0.14 + self._hash01(idx, salt, salt + 2) * 0.72) * spacing
                amp_a = 120.0 + self._hash01(idx, salt, salt + 3) * 150.0
                amp_b = 42.0 + self._hash01(idx, salt, salt + 4) * 76.0
                freq_a = 0.00054 + self._hash01(idx, salt, salt + 5) * 0.00032
                freq_b = 0.00112 + self._hash01(idx, salt, salt + 6) * 0.00052
                phase_a = self._hash01(idx, salt, salt + 7) * math.tau
                phase_b = self._hash01(idx, salt, salt + 8) * math.tau
                trunk_line = base + math.sin(secondary * freq_a + phase_a) * amp_a + math.sin(secondary * freq_b + phase_b) * amp_b
                width = 62.0 + self._hash01(idx, salt, salt + 9) * 72.0
                depth = 46.0 + self._hash01(idx, salt, salt + 10) * 40.0
                dist = abs(primary - trunk_line)
                if dist <= width * 6.0:
                    trunk = -depth * math.exp(-((dist / width) ** 1.18))
                    shoulder = depth * 0.10 * math.exp(-(((dist - width * 1.20) / (width * 0.82)) ** 2.0))
                    total += trunk + shoulder

                branch_count = 3 + int(self._hash01(idx, salt, salt + 11) * 2.4)
                for branch_index in range(branch_count):
                    anchor = (idx + 0.10 + (branch_index + 1) / (branch_count + 1) + self._hash01(idx, salt, salt + 20 + branch_index) * 0.16) * spacing
                    branch_line_anchor = base + math.sin(anchor * freq_a + phase_a) * amp_a + math.sin(anchor * freq_b + phase_b) * amp_b
                    branch_length = 520.0 + self._hash01(idx, salt, salt + 30 + branch_index) * 920.0
                    sdist = secondary - anchor
                    if abs(sdist) > branch_length:
                        continue
                    side = -1.0 if self._hash01(idx, salt, salt + 40 + branch_index) < 0.5 else 1.0
                    slope = side * (0.18 + self._hash01(idx, salt, salt + 41 + branch_index) * 0.46)
                    branch_offset = side * (width * (0.55 + self._hash01(idx, salt, salt + 42 + branch_index) * 0.35))
                    branch_line = branch_line_anchor + branch_offset + sdist * slope
                    bwidth = width * (0.62 + self._hash01(idx, salt, salt + 43 + branch_index) * 0.36)
                    bdepth = depth * (0.82 + self._hash01(idx, salt, salt + 44 + branch_index) * 0.34)
                    bdist = abs(primary - branch_line)
                    if bdist > bwidth * 5.0:
                        continue
                    fade = math.exp(-((abs(sdist) / max(branch_length * 0.72, 1.0)) ** 1.35))
                    branch_cut = -bdepth * math.exp(-((bdist / bwidth) ** 1.12)) * fade
                    branch_shoulder = bdepth * 0.08 * math.exp(-(((bdist - bwidth * 1.12) / (bwidth * 0.76)) ** 2.0)) * fade
                    total += branch_cut + branch_shoulder
        return total

    def _jagged_mountain_patches(self, x: float, y: float, *, strength: float = 1.0) -> float:
        """Localized sharp ridge/spire fields for visual drama without fake props.

        The mountains are part of the same deterministic heightfield, so they cast
        real parallax and keep snap/placement rules honest. They are deliberately
        sparse and mixed with lower shoulders so player movement can climb around
        them instead of being trapped by sudden invisible collision.
        """
        cell_size = 3200.0
        cx = math.floor(x / cell_size)
        cy = math.floor(y / cell_size)
        total = 0.0
        for iy in range(cy - 1, cy + 2):
            for ix in range(cx - 1, cx + 2):
                # About one out of four cells becomes a mountain patch; enough to
                # find visually, not enough to turn the terrain into constant teeth.
                if self._hash01(ix, iy, 811) > 0.28:
                    continue
                center_x = (ix + 0.18 + self._hash01(ix, iy, 812) * 0.64) * cell_size
                center_y = (iy + 0.16 + self._hash01(ix, iy, 813) * 0.68) * cell_size
                dx = x - center_x
                dy = y - center_y
                angle = self._hash01(ix, iy, 814) * math.tau
                ca = math.cos(angle)
                sa = math.sin(angle)
                lx = dx * ca + dy * sa
                ly = -dx * sa + dy * ca
                ridge_len = 760.0 + self._hash01(ix, iy, 815) * 620.0
                ridge_width = 135.0 + self._hash01(ix, iy, 816) * 145.0
                envelope = math.exp(-((abs(lx) / ridge_len) ** 2.0 + (abs(ly) / (ridge_width * 3.6)) ** 1.45))
                if envelope < 0.012:
                    continue

                # A steep central blade plus uneven spires along the blade. The
                # saw/ridge term creates jagged crests while the envelope controls
                # the footprint.
                blade = math.exp(-((abs(ly) / ridge_width) ** 0.82)) * envelope
                along = lx / max(ridge_len, 1.0)
                teeth = max(0.0, math.sin(along * math.tau * (3.0 + self._hash01(ix, iy, 817) * 3.0) + self._hash01(ix, iy, 818) * math.tau))
                secondary_teeth = max(0.0, math.sin(lx * 0.017 + ly * 0.006 + self._hash01(ix, iy, 819) * math.tau))
                crest = blade * (0.58 + teeth ** 1.7 * 0.34 + secondary_teeth ** 2.4 * 0.18)
                shoulders = math.exp(-((abs(ly) / (ridge_width * 2.25)) ** 1.55)) * envelope * 0.28
                base_height = (92.0 + self._hash01(ix, iy, 820) * 128.0) * strength
                notch = -base_height * 0.14 * max(0.0, math.sin(lx * 0.011 - ly * 0.015 + self._hash01(ix, iy, 821) * math.tau)) * envelope
                total += base_height * (crest + shoulders) + notch
        return total

    def _mimas_herschel_basin(self, x: float, y: float) -> float:
        # A single giant crater landmark inspired by Herschel.  Scale is gameplay-
        # compressed, but the important geometry is a broad bowl, raised rim, and
        # central peak complex.
        cx, cy = 1180.0, -920.0
        dx = x - cx
        dy = y - cy
        radius = 1120.0
        dist = math.sqrt(dx * dx + dy * dy)
        if dist > radius * 1.85:
            return 0.0
        t = dist / radius
        bowl = -154.0 * math.exp(-((t / 0.74) ** 2.30))
        floor_sink = -28.0 * max(0.0, 1.0 - (t / 0.30) ** 2.0)
        rim = 94.0 * math.exp(-(((t - 1.02) / 0.13) ** 2.0))
        outer_slump = -34.0 * math.exp(-(((t - 1.29) / 0.22) ** 2.0))
        central_peak = 54.0 * math.exp(-((t / 0.15) ** 2.1))
        return bowl + floor_sink + rim + outer_slump + central_peak

    def _mimas_named_crater_pool_relief(self, x: float, y: float) -> float:
        total = 0.0
        for index, spec in enumerate(MIMAS_CRATER_ICE_POOLS):
            cx = float(spec["x"])
            cy = float(spec["y"])
            pool_radius = float(spec["radius"])
            crater_radius = pool_radius * float(spec.get("crater_scale", 2.05 + (index % 2) * 0.22))
            dx = x - cx
            dy = y - cy
            dist = math.sqrt(dx * dx + dy * dy)
            if dist > crater_radius * 1.75:
                continue
            t = dist / max(crater_radius, 1.0)
            depth = 112.0 + pool_radius * 0.205 + (index == 1) * 60.0
            floor = -depth * (0.88 + 0.08 * math.sin((x * 0.006 + y * 0.004) + index))
            bowl = -depth * 1.10 * math.exp(-((t / 0.66) ** 2.08))
            floor_sink = -depth * 0.18 * max(0.0, 1.0 - (t / 0.32) ** 2.0)
            if t < 0.46:
                # Compacted crater-floor ice lens: mostly level, not a jagged ravine.
                local = floor * (1.0 - t / 0.46) + (bowl + floor_sink) * (t / 0.46)
            else:
                local = bowl + floor_sink
            rim = depth * 0.98 * math.exp(-(((t - 1.02) / 0.13) ** 2.0))
            outer_slump = -depth * 0.22 * math.exp(-(((t - 1.28) / 0.22) ** 2.0))
            ejecta = depth * 0.10 * math.exp(-(((t - 1.50) / 0.19) ** 2.0))
            total += local + rim + outer_slump + ejecta
        return total

    def _mimas_cratered_snow_relief(self, x: float, y: float) -> float:
        micro = self._layer_craters(x, y, 360.0, 54.0, 170.0, 0.19, 0.18)
        medium = self._layer_craters(x, y, 840.0, 150.0, 380.0, 0.17, 0.16)
        broad = self._layer_craters(x, y, 1760.0, 360.0, 880.0, 0.12, 0.13)
        overlap = self._layer_craters(x + 210.0, y - 260.0, 620.0, 110.0, 250.0, 0.20, 0.21)
        overlap += self._layer_craters(x - 340.0, y + 180.0, 1240.0, 220.0, 520.0, 0.14, 0.16) * 0.82
        # Random background crater texture is allowed to drift with the macro warp.
        # Named drillable basins are added in world coordinates below so their
        # terrain bowls line up exactly with the visible ice-pool meshes and sonar
        # hotspots.  Pass112 mixed these coordinate spaces, which made the changes
        # easy to miss in normal play.
        return micro * 1.42 + medium * 1.24 + broad * 1.04 + overlap * 0.96


    def _iapetus_ridge_axis_offset(self, x: float) -> float:
        # Cassini Regio is a long equatorial seam, not a random mountain cluster.
        # Keep the axis continuous across the whole enlarged world with only slow
        # planetary-scale waviness so the player sees a horizon-spanning scar.
        return -260.0 + math.sin(x * 0.000135) * 360.0 + math.sin(x * 0.00062 + 1.8) * 92.0

    def _iapetus_ridge_factor_at(self, x: float, y: float) -> float:
        distance = abs(y - self._iapetus_ridge_axis_offset(x))
        # Pass21 broadens the mission/ridge band to support a Cassini-style system:
        # a central 20-km-class wall, broad triangular flanks, shoulders, and long
        # approach plains rather than a short local slope.
        return clamp(1.0 - distance / 12800.0, 0.0, 1.0)

    def _iapetus_cassini_dark_factor(self, x: float, y: float) -> float:
        """World-space dark/bright albedo split for Iapetus.

        Iapetus has a strong Cassini Regio dark-terrain identity.  This factor is
        used by vertex tint/tests so the two-tone look is anchored to the moon
        surface instead of being a repeated texture accident.
        """
        ridge_y = self._iapetus_ridge_axis_offset(x)
        signed = y - ridge_y
        ridge_band = self._iapetus_ridge_factor_at(x, y)
        broad_leading_side = 0.5 + 0.5 * math.sin(x * 0.000105 + y * 0.000040 - 1.2)
        equatorial_dust = max(0.0, 1.0 - abs(signed - 1800.0) / 11800.0)
        streaks = 0.5 + 0.5 * math.sin(x * 0.00085 + math.sin(y * 0.00022) * 2.4)
        patch = 0.5 + 0.5 * math.sin((x * 0.00031 - y * 0.00018) + math.sin(x * 0.00009) * 3.0)
        dark = 0.18 + broad_leading_side * 0.38 + equatorial_dust * 0.30 + ridge_band * 0.20 + streaks * patch * 0.16
        return clamp(dark, 0.0, 1.0)

    def _iapetus_void_factor_at(self, x: float, y: float) -> float:
        """Outer-horizon darkness for Iapetus.

        The actual heightfield remains square, but the playable/readable space is
        treated as a circular globe slice.  This lets the horizon fade to black
        before the mesh edge can be seen, creating the wraparound optical illusion
        the project wants.
        """
        if not IS_IAPETUS_LEVEL:
            return 0.0
        radius = math.hypot(x, y)
        return clamp((radius - IAPETUS_HORIZON_FADE_START) / max(IAPETUS_HORIZON_FADE_END - IAPETUS_HORIZON_FADE_START, 1.0), 0.0, 1.0)

    def _iapetus_equatorial_ridge_relief(self, x: float, y: float) -> float:
        # Pass21: Cassini Regio-style ridge.  The real Iapetus ridge is famous for
        # long continuous triangular sections, steep flanks, battered cratered
        # surfaces, and dark/bright albedo contrast.  This remains actual heightfield
        # terrain: walking, scanning, drilling, validation, and screenshots all read
        # from the same surface instead of scenery-card mountains.
        ridge_y = self._iapetus_ridge_axis_offset(x)
        signed = y - ridge_y
        distance = abs(signed)

        # Triangular, wall-like profile: long approach ramp + steep inner face +
        # sharp crest.  The linear-ish exponents are intentional; they avoid the
        # rounded dome look from the older pass and make the ridge read like the
        # Cassini limb images.
        super_outer = max(0.0, 1.0 - distance / 19800.0)
        outer = max(0.0, 1.0 - distance / 14600.0)
        shoulders = max(0.0, 1.0 - distance / 9800.0)
        inner = max(0.0, 1.0 - distance / 4200.0)
        spine = max(0.0, 1.0 - distance / 760.0)
        knife = max(0.0, 1.0 - distance / 260.0)

        ridge = (
            super_outer ** 0.88 * 420.0
            + outer ** 0.96 * 1250.0
            + shoulders ** 1.10 * 1960.0
            + inner ** 1.55 * 2550.0
            + spine ** 2.42 * 1980.0
            + knife ** 3.20 * 880.0
        )

        # Longitudinal peaks and sags keep the crest ancient/broken without turning
        # it into random hills.  Everything varies along the equatorial direction.
        crest_wave = (
            math.sin(x * 0.00026 + 0.4) * 340.0
            + math.sin(x * 0.00073 - 1.1) * 190.0
            + math.sin(x * 0.00185 + 2.2) * 78.0
        )
        ridge += crest_wave * (inner * 0.42 + spine * 0.58)
        ridge += abs(math.sin(x * 0.00046 + 0.8)) * 210.0 * shoulders

        # Broken parallel ridge segments and shoulders on both sides, matching the
        # "complex system" look instead of one smooth wall.
        row_specs = (
            (-1.0, 1500.0, 540.0, 250.0),
            (1.0, 1750.0, 620.0, 235.0),
            (-1.0, 3150.0, 760.0, 205.0),
            (1.0, 3550.0, 860.0, 190.0),
            (-1.0, 5600.0, 980.0, 160.0),
            (1.0, 6350.0, 1120.0, 140.0),
            (-1.0, 8950.0, 1460.0, 105.0),
            (1.0, 10300.0, 1640.0, 88.0),
            (-1.0, 13200.0, 2100.0, 60.0),
            (1.0, 14800.0, 2400.0, 52.0),
        )
        parallel_rows = 0.0
        for sign, offset, width, amp in row_specs:
            row_dist = abs(signed - sign * offset)
            row = max(0.0, 1.0 - row_dist / width)
            broken = 0.62 + 0.38 * max(0.0, math.sin(x * 0.00058 + sign * 1.35 + offset * 0.0002))
            parallel_rows += (row ** 1.34) * amp * broken
        ridge += parallel_rows

        # Step terraces and slump shelves along the flanks.  These create the visible
        # layered/battered look in the in-game camera without invisible blockers.
        terrace = 0.0
        for offset, width, amp in (
            (1250.0, 430.0, 125.0),
            (2350.0, 580.0, 112.0),
            (3900.0, 760.0, 96.0),
            (6100.0, 980.0, 78.0),
            (8600.0, 1280.0, 58.0),
            (11600.0, 1650.0, 42.0),
        ):
            t = max(0.0, 1.0 - abs(distance - offset) / width)
            terrace += (t ** 1.18) * amp
        ridge += terrace

        # Vertical scar/gully texture running down the flanks.  This is height relief,
        # not just a texture, so the slope catches light like the Cassini photos.
        flank = clamp((distance - 650.0) / 7200.0, 0.0, 1.0) * shoulders
        groove_a = max(0.0, math.sin(x * 0.0028 + signed * 0.00018 + 1.0)) ** 8.0
        groove_b = max(0.0, math.sin(x * 0.0053 - signed * 0.00011 - 0.6)) ** 10.0
        ridge -= (groove_a * 105.0 + groove_b * 62.0) * flank

        # Dense impact wear.  Craters directly affect the ridge and flanks so they
        # read as ancient battered terrain instead of clean procedural slopes.
        ridge_band_boost = 0.50 + self._iapetus_ridge_factor_at(x, y) * 0.60
        craters = self._layer_craters(x + 220.0, y - 540.0, 780.0, 118.0, 420.0, 0.165, 0.154) * 0.72 * ridge_band_boost
        craters += self._layer_craters(x - 980.0, y + 420.0, 1640.0, 300.0, 880.0, 0.118, 0.104) * 0.58 * ridge_band_boost
        craters += self._layer_craters(x + 1840.0, y - 1560.0, 3120.0, 640.0, 1780.0, 0.078, 0.070) * 0.42
        craters += self._layer_craters(x - 2600.0, y + 2200.0, 5200.0, 1050.0, 2750.0, 0.050, 0.046) * 0.30

        # Low rolling regolith is kept modest so it does not compete with the wall.
        drifts = self._rolling_hill_fields(x * 1.02, y * 0.96, 1540.0, 26.0, 82.0)
        drifts += self._rolling_hill_fields(x, y, 3440.0, 22.0, 64.0)
        drifts += self._rolling_hill_fields(x * 0.86, y * 0.92, 6400.0, 18.0, 46.0)
        return ridge + craters + drifts

    def _titan_basin_specs(self) -> tuple[tuple[float, float, float, float, float], ...]:
        # cx, cy, radius_x, radius_y, strength.
        # Titan now favors one major methane sea with linked interior basins rather
        # than isolated puddles, so the horizon reads as a real oceanic body.
        return (
            (420.0, 5480.0, 6900.0, 2440.0, 1.00),
            (-2860.0, 2140.0, 2420.0, 1320.0, 0.92),
            (1080.0, 2580.0, 2820.0, 1460.0, 0.92),
            (3860.0, 760.0, 1740.0, 860.0, 0.74),
            (-4480.0, -1040.0, 1980.0, 980.0, 0.76),
            (-980.0, 4280.0, 3200.0, 1320.0, 0.82),
        )

    def titan_liquid_signal(self, x: float, y: float) -> float:
        signal = 0.0
        for cx, cy, rx, ry, strength in self._titan_basin_specs():
            dx = (x - cx) / rx
            dy = (y - cy) / ry
            d2 = dx * dx + dy * dy
            if d2 < 1.0:
                t = 1.0 - d2
                basin = (t * t * (3.0 - 2.0 * t)) * strength
                # A very low-frequency warped threshold keeps coasts organic while
                # avoiding the noisy sawtooth look of the previous hard cell mask.
                edge_warp = (
                    math.sin((x + cx * 0.17) * 0.00072 + y * 0.00031) * 0.024
                    + math.sin(x * 0.00023 - (y + cy * 0.11) * 0.00054) * 0.018
                )
                signal = max(signal, basin + edge_warp * (1.0 - abs(t - 0.42)))
        # Branching drainage / estuary network from the plain into the main methane sea.
        trunk_center = math.sin(x * 0.00050) * 470.0 + 720.0 + math.sin(x * 0.00134) * 90.0
        trunk_width = 420.0 + 92.0 * math.sin(x * 0.00041 + 0.8)
        trunk = max(0.0, 1.0 - abs(y - trunk_center) / max(trunk_width, 180.0))
        trunk *= clamp((6800.0 - abs(x)) / 6800.0, 0.0, 1.0)

        north_branch_center = 1680.0 + math.sin((x - 920.0) * 0.00058) * 420.0
        north_branch_width = 240.0 + 56.0 * math.sin(x * 0.00066 + 0.2)
        north_branch = max(0.0, 1.0 - abs(y - north_branch_center) / max(north_branch_width, 120.0))
        north_branch *= clamp((x + 4200.0) / 7800.0, 0.0, 1.0) * clamp((5200.0 - x) / 7600.0, 0.0, 1.0)

        south_branch_center = -420.0 + math.sin((x + 1140.0) * 0.00064) * 360.0
        south_branch_width = 220.0 + 48.0 * math.sin(x * 0.00059 + 1.1)
        south_branch = max(0.0, 1.0 - abs(y - south_branch_center) / max(south_branch_width, 110.0))
        south_branch *= clamp((x + 5200.0) / 8800.0, 0.0, 1.0) * clamp((4600.0 - x) / 7000.0, 0.0, 1.0)

        inlet_center_x = math.sin(y * 0.00042) * 520.0 - 620.0
        inlet_width = 300.0 + 84.0 * math.sin(y * 0.00037 + 0.6)
        inlet = max(0.0, 1.0 - abs(x - inlet_center_x) / max(inlet_width, 140.0))
        inlet *= clamp((y + 1200.0) / 2600.0, 0.0, 1.0) * clamp((6200.0 - y) / 3200.0, 0.0, 1.0)

        channel_signal = max(trunk ** 2.08 * 0.88, north_branch ** 2.16 * 0.64, south_branch ** 2.22 * 0.56, inlet ** 2.05 * 0.62)
        signal = max(signal, channel_signal)
        return clamp(signal, 0.0, 1.0)

    def titan_liquid_alpha(self, x: float, y: float) -> float:
        signal = self.titan_liquid_signal(x, y)
        t = clamp((signal - 0.355) / 0.185, 0.0, 1.0)
        return t * t * (3.0 - 2.0 * t)

    def titan_shore_alpha(self, x: float, y: float) -> float:
        signal = self.titan_liquid_signal(x, y)
        # Broad wet shelf: strongest just outside the liquid line, then fades into
        # dry tholin dunes so the coast reads smooth instead of grid-cut.
        outer = clamp((signal - 0.245) / 0.135, 0.0, 1.0)
        inner = 1.0 - clamp((signal - 0.595) / 0.165, 0.0, 1.0)
        a = outer * inner
        return a * a * (3.0 - 2.0 * a)

    def titan_liquid_mask(self, x: float, y: float) -> bool:
        return self.titan_liquid_alpha(x, y) >= 0.04

    def titan_shore_mask(self, x: float, y: float) -> bool:
        return self.titan_shore_alpha(x, y) >= 0.04

    def _titan_lake_basin_relief(self, x: float, y: float) -> float:
        signal = self.titan_liquid_signal(x, y)
        smooth = signal * signal * (3.0 - 2.0 * signal)
        # The basins must clearly fall below methane level, with carved drainage
        # channels feeding the larger ocean body.
        relief = -244.0 * smooth
        shelf = self.titan_shore_alpha(x, y)
        inner_shelf = max(0.0, 1.0 - abs(signal - 0.50) / 0.12)
        edge_cut = max(0.0, 1.0 - abs(signal - 0.42) / 0.10)
        channel = max(0.0, math.sin(x * 0.00034 - y * 0.00019 + math.sin(y * 0.00007) * 1.7)) ** 3.4
        trench = max(0.0, math.sin(x * 0.00062 + y * 0.00014 + math.sin(x * 0.00011) * 1.8)) ** 4.0
        relief -= (shelf ** 1.45) * 72.0
        relief -= (inner_shelf ** 2.0) * 30.0
        relief -= (edge_cut ** 2.5) * (20.0 + channel * 16.0)
        relief -= smooth * trench * 28.0
        # Slight raised beach/levee outside the wet shelf helps the shoreline curve
        # remain visible through Titan haze without making a hard wall.
        beach = max(0.0, 1.0 - abs(signal - 0.30) / 0.075)
        outer_bank = max(0.0, 1.0 - abs(signal - 0.22) / 0.060)
        relief += (beach ** 2.1) * 8.0
        relief += (outer_bank ** 2.3) * 16.0
        return relief

    def _triton_valley_network_relief(self, x: float, y: float) -> float:
        """Long connected valley troughs with restrained shoulders.

        Pass107 reduces the old stacked wall/shelf buildup so the valley network
        reads as continuous terrain instead of repeated raised cutouts.
        """
        total = 0.0
        families = (
            (x, y, 2450.0, 1201, 1.00),
            (x * 0.84 + y * 0.22, y * 0.92 - x * 0.12, 3180.0, 1249, 0.82),
            (y * 0.72 - x * 0.18, x * 0.86 + y * 0.14, 4020.0, 1297, 0.58),
        )
        for primary, secondary, spacing, salt, weight in families:
            ci = math.floor(primary / spacing)
            for idx in range(ci - 2, ci + 3):
                base = (idx + 0.18 + self._hash01(idx, salt, salt + 1) * 0.64) * spacing
                amp_a = 420.0 + self._hash01(idx, salt, salt + 2) * 540.0
                amp_b = 120.0 + self._hash01(idx, salt, salt + 3) * 210.0
                freq_a = 0.00024 + self._hash01(idx, salt, salt + 4) * 0.00019
                freq_b = 0.00068 + self._hash01(idx, salt, salt + 5) * 0.00031
                phase_a = self._hash01(idx, salt, salt + 6) * math.tau
                phase_b = self._hash01(idx, salt, salt + 7) * math.tau
                line = base + math.sin(secondary * freq_a + phase_a) * amp_a + math.sin(secondary * freq_b + phase_b) * amp_b
                width = 430.0 + self._hash01(idx, salt, salt + 8) * 360.0
                depth = (118.0 + self._hash01(idx, salt, salt + 9) * 122.0) * weight
                dist = abs(primary - line)
                if dist > width * 4.2:
                    continue
                floor = -depth * math.exp(-((dist / width) ** 1.28))
                inner_wall = depth * 0.20 * math.exp(-(((dist - width * 1.02) / (width * 0.52)) ** 2.0))
                outer_wall = depth * 0.08 * math.exp(-(((dist - width * 1.78) / (width * 0.82)) ** 2.0))
                shelf_cut = -depth * 0.10 * math.exp(-(((dist - width * 1.36) / (width * 0.34)) ** 2.0))
                total += floor + inner_wall + outer_wall + shelf_cut
        return total

    def _triton_ridge_shelves(self, x: float, y: float) -> float:
        band = math.sin(x * 0.00034 + y * 0.00008 + math.sin(y * 0.00014) * 1.4)
        cross = math.cos(x * -0.00012 + y * 0.00039 + 0.8)
        shelf = max(0.0, band) ** 2.2 * 38.0 + max(0.0, cross) ** 2.7 * 26.0
        breaks = max(0.0, math.sin((x * 0.00072 - y * 0.00028) * math.tau + 0.4)) ** 6.0 * 16.0
        return shelf - breaks

    def _triton_volatile_fan_relief(self, x: float, y: float) -> float:
        fan_a = 0.5 + 0.5 * math.sin(x * 0.00018 - y * 0.00009 + 0.2)
        fan_b = 0.5 + 0.5 * math.cos(x * -0.00007 + y * 0.00022 - 0.8)
        fan = max(0.0, fan_a * 0.58 + fan_b * 0.42 - 0.61) ** 1.85
        streak = max(0.0, math.sin(x * 0.00112 + y * 0.00021 + math.sin(y * 0.00011) * 1.6)) ** 5.0
        return -fan * (22.0 + streak * 18.0)

    def _titan_dune_relief(self, x: float, y: float) -> float:
        band = math.sin(x * 0.00135 + y * 0.00030 + math.sin(y * 0.00011) * 2.0)
        cross = math.sin(x * 0.00022 - y * 0.00070)
        long = max(0.0, band) ** 2.2 * 36.0 - max(0.0, -band) ** 2.5 * 8.0
        shore_cut = self.titan_liquid_alpha(x, y) * 12.0 + self.titan_shore_alpha(x, y) * 10.0
        return long + cross * 7.5 - shore_cut

    def heightmap_ground_raw(self, x: float, y: float) -> float:
        # Pass 34 heightmap preserved as the Enceladus buried terrain mass source.
        # Mimas uses the same procedural authority but swaps the geology toward
        # crater basins, compact snowpack, and dust-coated ice rather than active
        # fissure/mountain-row terrain.
        warp_x = x + math.sin(y * 0.00031) * 260.0 + math.cos(x * 0.00018) * 115.0
        warp_y = y + math.cos(x * 0.00028) * 235.0 + math.sin(y * 0.00016) * 135.0
        if IS_TITAN_LEVEL:
            macro = (
                math.sin(warp_x * 0.00022) * 18.0
                + math.cos(warp_y * 0.00019) * 14.0
                + math.sin((warp_x - warp_y) * 0.00015) * 11.0
            )
            dunes = self._titan_dune_relief(warp_x, warp_y)
            basins = self._titan_lake_basin_relief(warp_x, warp_y)
            hummocks = self._rolling_hill_fields(warp_x, warp_y, 1120.0, 14.0, 36.0)
            shore_terraces = self._rolling_hill_fields(warp_x + 420.0, warp_y - 280.0, 1940.0, 12.0, 34.0) * self.titan_shore_alpha(warp_x, warp_y)
            cut_banks = self._rolling_hill_fields(warp_x - 520.0, warp_y + 340.0, 1280.0, 7.0, 22.0) * self.titan_shore_alpha(warp_x, warp_y)
            jagged = self._jagged_mountain_patches(warp_x + 760.0, warp_y - 420.0, strength=0.74)
            wind = self._wind_ripple_relief(warp_x * 1.35, warp_y * 0.85) * 0.38
            return (macro + dunes + basins + hummocks + shore_terraces + cut_banks + jagged + wind) * 0.94
        if IS_MARS_LEVEL:
            macro = (
                math.sin(warp_x * 0.00022) * 18.0
                + math.cos(warp_y * 0.00019) * 14.0
                + math.sin((warp_x - warp_y) * 0.00015) * 11.0
            )
            dunes = self._titan_dune_relief(warp_x, warp_y) * 0.74
            basins = self._titan_lake_basin_relief(warp_x, warp_y) * 0.92
            hummocks = self._rolling_hill_fields(warp_x, warp_y, 1120.0, 14.0, 36.0)
            terraces = self._rolling_hill_fields(warp_x + 420.0, warp_y - 280.0, 1940.0, 11.0, 28.0)
            cut_banks = self._rolling_hill_fields(warp_x - 520.0, warp_y + 340.0, 1280.0, 6.0, 18.0)
            jagged = self._jagged_mountain_patches(warp_x + 760.0, warp_y - 420.0, strength=0.70)
            wind = self._wind_ripple_relief(warp_x * 1.35, warp_y * 0.85) * 0.34
            return (macro + dunes + basins + hummocks + terraces + cut_banks + jagged + wind) * 0.95
        if IS_TRITON_LEVEL:
            macro = (
                math.sin(warp_x * 0.00014) * 20.0
                + math.cos(warp_y * 0.00012) * 18.0
                + math.sin((warp_x + warp_y) * 0.000055) * 14.0
            )
            valleys = self._triton_valley_network_relief(warp_x, warp_y)
            shelves = self._triton_ridge_shelves(warp_x, warp_y)
            uplands = self._rolling_hill_fields(warp_x, warp_y, 1980.0, 20.0, 58.0)
            uplands += self._rolling_hill_fields(warp_x + 680.0, warp_y - 420.0, 4300.0, 24.0, 70.0)
            round_pits = self._layer_craters(warp_x, warp_y, 1580.0, 180.0, 520.0, 0.070, 0.055) * 0.42
            jagged = self._jagged_mountain_patches(warp_x - 520.0, warp_y + 740.0, strength=0.62) * 0.35
            volatile_fans = self._triton_volatile_fan_relief(warp_x, warp_y)
            wind = self._wind_ripple_relief(warp_x * 0.72, warp_y * 0.82) * 0.42
            return (macro + valleys + shelves + uplands + round_pits + jagged + volatile_fans + wind) * 1.04
        if IS_MIMAS_LEVEL:
            macro = (
                math.sin(warp_x * 0.00030) * 11.0
                + math.cos(warp_y * 0.00027) * 10.0
                + math.sin((warp_x + warp_y) * 0.00011) * 9.0
            )
            low_drifts = self._rolling_hill_fields(warp_x, warp_y, 780.0, 4.0, 12.0)
            low_drifts += self._rolling_hill_fields(warp_x, warp_y, 1620.0, 7.0, 20.0)
            crater_relief = self._mimas_cratered_snow_relief(warp_x, warp_y)
            crater_relief += self._mimas_herschel_basin(x, y)
            crater_relief += self._mimas_named_crater_pool_relief(x, y)
            jagged = self._jagged_mountain_patches(warp_x - 380.0, warp_y + 620.0, strength=0.66)
            wind = self._wind_ripple_relief(warp_x, warp_y) * 0.68
            return (macro + low_drifts + crater_relief * 1.36 + jagged * 0.80 + wind * 0.44) * 0.98
        if IS_IAPETUS_LEVEL:
            macro = (
                math.sin(warp_x * 0.00024) * 8.0
                + math.cos(warp_y * 0.00021) * 7.0
                + math.sin((warp_x + warp_y) * 0.00008) * 6.0
            )
            ridge = self._iapetus_equatorial_ridge_relief(warp_x, warp_y)
            jagged = self._jagged_mountain_patches(warp_x + 1200.0, warp_y, strength=0.92) * self._iapetus_ridge_factor_at(x, y)
            wind = self._wind_ripple_relief(warp_x * 0.8, warp_y * 0.8) * 0.46
            return (macro + ridge + jagged + wind) * 0.98
        if IS_PLUTO_LEVEL:
            macro = (
                math.sin(warp_x * 0.00017) * 14.0
                + math.cos(warp_y * 0.00015) * 13.0
                + math.sin((warp_x + warp_y) * 0.00005) * 10.0
            )
            plain = -82.0 * math.exp(-(((warp_x + 260.0) / 3600.0) ** 2 + ((warp_y - 420.0) / 2800.0) ** 2))
            wave_a = math.sin((warp_x * 0.00034 + warp_y * 0.00006) * math.tau) * 18.0
            wave_b = math.cos((warp_x * -0.00016 + warp_y * 0.00031) * math.tau) * 13.0
            long_wave = wave_a + wave_b
            rugged_wave = max(0.0, math.sin((warp_x * 0.00058 - warp_y * 0.00020) * math.tau + 0.5)) ** 3.0 * 16.0
            crack_a = max(0.0, 1.0 - abs(math.sin((warp_x * 0.00086 + warp_y * 0.00023) * math.tau + 0.12)) / 0.070) ** 5.0
            crack_b = max(0.0, 1.0 - abs(math.sin((warp_x * -0.00034 + warp_y * 0.00074) * math.tau - 0.28)) / 0.060) ** 5.5
            crack_cut = max(crack_a, crack_b * 0.9) * 24.0
            mountain_belt = self._rolling_hill_fields(warp_x + 900.0, warp_y - 300.0, 1700.0, 42.0, 86.0)
            mountain_belt += self._jagged_mountain_patches(warp_x - 120.0, warp_y + 540.0, strength=1.02)
            mountain_belt += self._layer_craters(warp_x, warp_y, self.large_cell, 380.0, 860.0, 0.026, 0.10) * 0.18
            # Pass106 Pluto terrain cleanup: the old radial ring-wall/ridge lift
            # formed an artificial perimeter bowl that read as a cut-off level edge.
            # Keep the natural basin, mountain belt, long waves, cracks and distant
            # Pass104 continuation; do not raise a second invisible-looking wall.
            dark_uplands = (0.5 + 0.5 * math.sin(warp_x * 0.00031 - warp_y * 0.00026)) * 8.0
            return (macro + plain + long_wave + rugged_wave + mountain_belt - dark_uplands - crack_cut) * 0.98
        macro = (
            math.sin(warp_x * 0.00034) * 16.0
            + math.cos(warp_y * 0.00031) * 13.0
            + math.sin((warp_x + warp_y) * 0.00012) * 18.0
            + math.cos((warp_x - warp_y) * 0.00010) * 10.0
        )
        hills = self._rolling_hill_fields(warp_x, warp_y, 900.0, 42.0, 88.0)
        hills += self._rolling_hill_fields(warp_x, warp_y, 1700.0, 46.0, 112.0)
        peaks = self._eroded_peak_fields(warp_x, warp_y)
        jagged = self._jagged_mountain_patches(warp_x, warp_y, strength=0.78)
        valleys = self._valley_network(warp_x, warp_y)
        ravines = self._ravine_network(warp_x, warp_y)
        craters = self._layer_craters(warp_x, warp_y, self.small_cell, 92.0, 260.0, 0.11, 0.10)
        craters += self._layer_craters(warp_x + 320.0, warp_y - 440.0, self.large_cell, 240.0, 560.0, 0.070, 0.075) * 0.72
        impact_basins = self._layer_craters(warp_x - 660.0, warp_y + 380.0, 1180.0, 180.0, 460.0, 0.108, 0.094)
        impact_basins += self._layer_craters(warp_x + 1280.0, warp_y - 1040.0, 2380.0, 360.0, 920.0, 0.076, 0.068) * 0.76
        relief = macro + hills + peaks + jagged + valleys + ravines + craters * 0.34 + impact_basins * 0.58 + self._wind_ripple_relief(warp_x, warp_y)
        return relief * 1.22

    def _height_key(self, x: float, y: float) -> tuple[float, float]:
        # Sub-centimeter rounding keeps deterministic terrain while allowing
        # repeat cache hits from mesh/grid/camera systems.
        return (round(x, 4), round(y, 4))

    def subsurface_terrain_height(self, x: float, y: float) -> float:
        # Ground mass below the ice: mostly buried, with the tallest mountains
        # punching through the flat ice plane at Z=0. Branching trenches carve into
        # the exposed terrain and often cut back down to the flat ice surface.
        key = self._height_key(x, y)
        cached = self._subsurface_cache.get(key)
        if cached is not None:
            return cached
        base = self.heightmap_ground_raw(x, y) * SUBSURFACE_TERRAIN_SCALE + SUBSURFACE_TERRAIN_OFFSET
        if IS_TITAN_LEVEL:
            haze_settle = math.sin(x * 0.00016 + y * 0.00011) * 5.0 + math.cos(y * 0.00021) * 4.0
            value = base + haze_settle + 26.0
            # Pass52: Titan liquid must cut through every neighboring terrain edge
            # it touches.  The methane plane is a surface over a basin, not a
            # transparent decal stretched across dunes.  Clamp any liquid-alpha
            # terrain below the liquid surface while keeping a shallow wet bank
            # outside the waterline for sampling.
            liquid_alpha = self.titan_liquid_alpha(x, y)
            if liquid_alpha >= TITAN_LIQUID_TERRAIN_CUT_ALPHA:
                contact = clamp((liquid_alpha - TITAN_LIQUID_TERRAIN_CUT_ALPHA) / max(1.0 - TITAN_LIQUID_TERRAIN_CUT_ALPHA, 1e-6), 0.0, 1.0)
                cut_target = WATER_Z - 7.0 - 112.0 * (contact ** 0.72)
                value = min(value, cut_target)
            elif self.titan_shore_alpha(x, y) >= 0.12:
                # Flatten the wet neighbor terrain enough that shoreline cuts read
                # as banks on all sides instead of high terrain showing through.
                shore = self.titan_shore_alpha(x, y)
                value = min(value, WATER_Z + 28.0 - 22.0 * shore)
            self._subsurface_cache[key] = value
            return value
        if IS_MARS_LEVEL:
            broad_settle = math.sin(x * 0.00016 + y * 0.00011) * 5.0 + math.cos(y * 0.00021) * 4.0
            value = base + broad_settle + 22.0
            self._subsurface_cache[key] = value
            return value
        if IS_TRITON_LEVEL:
            cold_settle = math.sin(x * 0.00012 + y * 0.00008) * 4.5 + math.cos(y * 0.00015) * 3.5
            value = base + cold_settle + 10.0
            self._subsurface_cache[key] = value
            return value
        if IS_MIMAS_LEVEL:
            # Snow-coated world: keep the top surface continuous and cratered,
            # with thicker hidden ice/ocean layers under the drilling loop.
            broad_settle = math.sin(x * 0.00023 + y * 0.00009) * 8.0 + math.cos(y * 0.00019) * 6.0
            value = base + broad_settle + 34.0
            self._subsurface_cache[key] = value
            return value
        if IS_PLUTO_LEVEL:
            broad_settle = math.sin(x * 0.00011 + y * 0.00008) * 5.0 + math.cos(y * 0.00014) * 3.5
            # Pass106: keep gameplay terrain continuous with the rendered Pluto
            # surface.  The old second barrier_wall/barrier_teeth layer duplicated
            # the perimeter lift and could make collision/surface elevations jump
            # into a synthetic ring near the outer basin.
            crack_a = max(0.0, 1.0 - abs(math.sin((x * 0.00086 + y * 0.00023) * math.tau + 0.12)) / 0.070) ** 5.0
            crack_b = max(0.0, 1.0 - abs(math.sin((x * -0.00034 + y * 0.00074) * math.tau - 0.28)) / 0.060) ** 5.5
            crack_cut = max(crack_a, crack_b * 0.9) * 20.0
            value = base + broad_settle + 12.0 - crack_cut
            self._subsurface_cache[key] = value
            return value
        if IS_IAPETUS_LEVEL:
            foothill_settle = math.sin(x * 0.00018 + y * 0.00007) * 6.0 + math.cos(y * 0.00016) * 4.0
            value = base + foothill_settle + 18.0
            self._subsurface_cache[key] = value
            return value
        # Pass 76: raise additional long mountain-range structure from the buried
        # hard terrain only, now with adjacent parallel rows. The flat ice plane
        # remains a separate Z=0 layer.
        range_lift = self._subsurface_mountain_range_lift(x, y)
        if IS_ENCELADUS_LEVEL:
            range_lift *= 1.05
        raised_base = base + range_lift
        trench = self._branching_exposure_trenches(x, y)
        exposure = clamp((raised_base + 10.0) / 96.0, 0.0, 1.0)
        exposure = exposure * exposure * (3.0 - 2.0 * exposure)
        if IS_ENCELADUS_LEVEL:
            trench *= 1.26
            exposure = clamp(exposure * 1.08, 0.0, 1.0)
        value = raised_base + trench * exposure
        self._subsurface_cache[key] = value
        return value

    def flat_ice_height(self, x: float, y: float) -> float:
        return ICE_PLANE_Z

    def surface_height(self, x: float, y: float) -> float:
        # Gameplay surface resolution: walk on flat ice unless a true subsurface
        # peak breaks above the ice plane.
        key = self._height_key(x, y)
        cached = self._surface_cache.get(key)
        if cached is not None:
            return cached
        if IS_MIMAS_LEVEL or IS_IAPETUS_LEVEL or IS_TITAN_LEVEL or IS_PLUTO_LEVEL or IS_EUROPA_LEVEL or IS_TRITON_LEVEL:
            value = self.subsurface_terrain_height(x, y)
        else:
            value = max(ICE_PLANE_Z, self.subsurface_terrain_height(x, y))
        self._surface_cache[key] = value
        return value

    def seafloor_height(self, x: float, y: float) -> float:
        # Keep the default underwater world far below the surface, but add deep trenches
        # and occasional tall submerged peaks.
        key = self._height_key(x, y)
        cached = self._seafloor_cache.get(key)
        if cached is not None:
            return cached
        macro = (
            math.sin(x * 0.00034) * 18.0
            + math.cos(y * 0.00039) * 20.0
            + math.sin((x - y) * 0.00013) * 28.0
        )
        troughs = self._layer_craters(x, y, 980.0, 180.0, 420.0, 0.34, 0.12)
        deep = self._layer_craters(x, y, 2100.0, 420.0, 900.0, 0.22, 0.16)
        trenches = self._seafloor_trench_network(x, y)
        peaks = self._seafloor_abyssal_peaks(x, y)
        value = SEA_FLOOR_Z - 72.0 + macro + troughs + deep * 0.8 + trenches + peaks
        self._seafloor_cache[key] = value
        return value


class MeshFactory:
    @staticmethod
    def make_heightfield_square(name: str, half: float, resolution: int, height_func, uv_scale: float, holes: list[Hole] | None = None, color_func=None) -> NodePath:
        fmt = GeomVertexFormat.getV3n3c4t2() if color_func is not None else GeomVertexFormat.getV3n3t2()
        vdata = GeomVertexData(name, fmt, Geom.UHStatic)
        vwriter = GeomVertexWriter(vdata, "vertex")
        nwriter = GeomVertexWriter(vdata, "normal")
        cwriter = GeomVertexWriter(vdata, "color") if color_func is not None else None
        twriter = GeomVertexWriter(vdata, "texcoord")
        step = (half * 2.0) / resolution
        heights: list[list[float]] = []
        for iy in range(resolution + 1):
            y = -half + iy * step
            row = []
            for ix in range(resolution + 1):
                x = -half + ix * step
                row.append(height_func(x, y))
            heights.append(row)
        for iy in range(resolution + 1):
            y = -half + iy * step
            y0 = max(iy - 1, 0)
            y1 = min(iy + 1, resolution)
            for ix in range(resolution + 1):
                x = -half + ix * step
                x0 = max(ix - 1, 0)
                x1 = min(ix + 1, resolution)
                z = heights[iy][ix]
                dzdx = (heights[iy][x1] - heights[iy][x0]) / max((x1 - x0) * step, 1e-4)
                dzdy = (heights[y1][ix] - heights[y0][ix]) / max((y1 - y0) * step, 1e-4)
                normal = Vec3(-dzdx, -dzdy, 1.0)
                normal.normalize()
                vwriter.addData3(x, y, z)
                nwriter.addData3(normal)
                if cwriter is not None:
                    cwriter.addData4(*color_func(x, y, z, normal))
                twriter.addData2(0.5 + x * uv_scale, 0.5 + y * uv_scale)
        tris = GeomTriangles(Geom.UHStatic)
        row = resolution + 1
        cut_holes = holes or []

        def cell_is_cut(cx: float, cy: float) -> bool:
            for hole in cut_holes:
                # Slightly overcut the mesh so the visual terrain never shows inside
                # the ice-fishing shaft. The fitted cylinder/rim hides the square-cell edge.
                r = hole.radius * 1.20
                if (cx - hole.x) ** 2 + (cy - hole.y) ** 2 <= r * r:
                    return True
            return False

        for iy in range(resolution):
            cy = -half + (iy + 0.5) * step
            for ix in range(resolution):
                cx = -half + (ix + 0.5) * step
                if cell_is_cut(cx, cy):
                    continue
                i0 = iy * row + ix
                i1 = i0 + 1
                i2 = i0 + row
                i3 = i2 + 1
                tris.addVertices(i0, i2, i1)
                tris.addVertices(i1, i2, i3)
        geom = Geom(vdata)
        geom.addPrimitive(tris)
        node = GeomNode(name)
        node.addGeom(geom)
        return NodePath(node)

    @staticmethod
    def make_square_horizon_ring(
        name: str,
        inner_half: float,
        outer_half: float,
        segments: int,
        bands: int,
        height_func,
        uv_scale: float,
        outer_drop: float = 0.0,
        color_func=None,
        fade_alpha: bool = False,
    ) -> NodePath:
        """Build a visual-only continuation ring around a finite square terrain.

        Band zero samples the exact same world-space height function at the original
        terrain boundary.  Later bands continue the same function outward and gently
        lower the final edge into atmospheric fog.  Gameplay/collision authority stays
        inside ``inner_half``; this mesh exists only to prevent a visible cut world.
        """
        segments = max(8, int(segments))
        bands = max(1, int(bands))
        outer_half = max(float(outer_half), float(inner_half) + 1.0)
        fmt = GeomVertexFormat.getV3n3c4t2() if color_func is not None else GeomVertexFormat.getV3n3t2()
        vdata = GeomVertexData(name, fmt, Geom.UHStatic)
        vwriter = GeomVertexWriter(vdata, "vertex")
        nwriter = GeomVertexWriter(vdata, "normal")
        cwriter = GeomVertexWriter(vdata, "color") if color_func is not None else None
        twriter = GeomVertexWriter(vdata, "texcoord")
        perimeter_count = segments * 4
        normal_step = max((inner_half * 2.0) / segments, 8.0)

        def perimeter_point(half: float, index: int) -> tuple[float, float]:
            side = index // segments
            local = index % segments
            t = local / float(segments)
            if side == 0:
                return (-half + (2.0 * half * t), -half)
            if side == 1:
                return (half, -half + (2.0 * half * t))
            if side == 2:
                return (half - (2.0 * half * t), half)
            return (-half, half - (2.0 * half * t))

        for band in range(bands + 1):
            t = band / float(bands)
            smooth = t * t * (3.0 - 2.0 * t)
            half = inner_half + (outer_half - inner_half) * t
            drop = outer_drop * smooth
            alpha_scale = (1.0 - smooth) ** 2 if fade_alpha else 1.0
            for index in range(perimeter_count):
                x, y = perimeter_point(half, index)
                natural_z = float(height_func(x, y))
                z = natural_z - drop
                dzdx = (float(height_func(x + normal_step, y)) - float(height_func(x - normal_step, y))) / (normal_step * 2.0)
                dzdy = (float(height_func(x, y + normal_step)) - float(height_func(x, y - normal_step))) / (normal_step * 2.0)
                normal = Vec3(-dzdx, -dzdy, 1.0)
                normal.normalize()
                vwriter.addData3(x, y, z)
                nwriter.addData3(normal)
                if cwriter is not None:
                    rgba = list(color_func(x, y, z, normal))
                    if len(rgba) < 4:
                        rgba.append(1.0)
                    rgba[3] *= alpha_scale
                    cwriter.addData4(*rgba[:4])
                twriter.addData2(0.5 + x * uv_scale, 0.5 + y * uv_scale)

        tris = GeomTriangles(Geom.UHStatic)
        for band in range(bands):
            inner_base = band * perimeter_count
            outer_base = (band + 1) * perimeter_count
            for index in range(perimeter_count):
                nxt = (index + 1) % perimeter_count
                i0 = inner_base + index
                i1 = inner_base + nxt
                o0 = outer_base + index
                o1 = outer_base + nxt
                tris.addVertices(i0, o0, i1)
                tris.addVertices(i1, o0, o1)
        geom = Geom(vdata)
        geom.addPrimitive(tris)
        node = GeomNode(name)
        node.addGeom(geom)
        return NodePath(node)

    @staticmethod
    def make_masked_flat_plane(
        name: str,
        half: float,
        z: float,
        uv_scale: float,
        segments: int,
        include_cell_func=None,
        holes: list[Hole] | None = None,
    ) -> NodePath:
        fmt = GeomVertexFormat.getV3n3t2()
        vdata = GeomVertexData(name, fmt, Geom.UHStatic)
        vwriter = GeomVertexWriter(vdata, "vertex")
        nwriter = GeomVertexWriter(vdata, "normal")
        twriter = GeomVertexWriter(vdata, "texcoord")
        step = (half * 2.0) / segments
        for iy in range(segments + 1):
            y = -half + iy * step
            for ix in range(segments + 1):
                x = -half + ix * step
                vwriter.addData3(x, y, z)
                nwriter.addData3(0, 0, 1)
                twriter.addData2(0.5 + x * uv_scale, 0.5 + y * uv_scale)
        tris = GeomTriangles(Geom.UHStatic)
        row = segments + 1
        cut_holes = holes or []

        def cell_is_hole(cx: float, cy: float) -> bool:
            for hole in cut_holes:
                r = hole.radius * 1.20
                if (cx - hole.x) ** 2 + (cy - hole.y) ** 2 <= r * r:
                    return True
            return False

        for iy in range(segments):
            cy = -half + (iy + 0.5) * step
            for ix in range(segments):
                cx = -half + (ix + 0.5) * step
                if cell_is_hole(cx, cy):
                    continue
                if include_cell_func is not None and not include_cell_func(cx, cy):
                    continue
                i0 = iy * row + ix
                i1 = i0 + 1
                i2 = i0 + row
                i3 = i2 + 1
                tris.addVertices(i0, i2, i1)
                tris.addVertices(i1, i2, i3)
        geom = Geom(vdata)
        geom.addPrimitive(tris)
        node = GeomNode(name)
        node.addGeom(geom)
        return NodePath(node)

    @staticmethod
    def make_alpha_flat_plane(
        name: str,
        half: float,
        z: float,
        uv_scale: float,
        segments: int,
        alpha_func,
        color_func=None,
    ) -> NodePath:
        """Transparent full plane with vertex alpha for smooth organic coastlines.

        The older masked-cell plane produced stair-stepped edges because whole
        grid cells were either present or absent.  This version keeps the mesh
        continuous and lets alpha fade across vertices, which reads as a smooth
        methane shoreline while preserving a cheap static mesh.
        """
        fmt = GeomVertexFormat.getV3n3c4t2()
        vdata = GeomVertexData(name, fmt, Geom.UHStatic)
        vwriter = GeomVertexWriter(vdata, "vertex")
        nwriter = GeomVertexWriter(vdata, "normal")
        cwriter = GeomVertexWriter(vdata, "color")
        twriter = GeomVertexWriter(vdata, "texcoord")
        step = (half * 2.0) / segments
        alpha_grid: list[list[float]] = []
        for iy in range(segments + 1):
            y = -half + iy * step
            alpha_row: list[float] = []
            for ix in range(segments + 1):
                x = -half + ix * step
                alpha = clamp(float(alpha_func(x, y)), 0.0, 1.0)
                alpha_row.append(alpha)
                color = color_func(x, y, alpha) if color_func is not None else (1.0, 1.0, 1.0, alpha)
                vwriter.addData3(x, y, z)
                nwriter.addData3(0, 0, 1)
                cwriter.addData4(*color)
                twriter.addData2(0.5 + x * uv_scale, 0.5 + y * uv_scale)
            alpha_grid.append(alpha_row)
        tris = GeomTriangles(Geom.UHStatic)
        row = segments + 1
        for iy in range(segments):
            for ix in range(segments):
                amax = max(alpha_grid[iy][ix], alpha_grid[iy][ix + 1], alpha_grid[iy + 1][ix], alpha_grid[iy + 1][ix + 1])
                if amax <= 0.025:
                    continue
                i0 = iy * row + ix
                i1 = i0 + 1
                i2 = i0 + row
                i3 = i2 + 1
                tris.addVertices(i0, i2, i1)
                tris.addVertices(i1, i2, i3)
        geom = Geom(vdata)
        geom.addPrimitive(tris)
        node = GeomNode(name)
        node.addGeom(geom)
        return NodePath(node)

    @staticmethod
    def make_snow_drift_patch(name: str, world: WorldGenerator, spec: dict[str, float], segments: int = 24) -> NodePath:
        fmt = GeomVertexFormat.getV3n3c4()
        vdata = GeomVertexData(name, fmt, Geom.UHStatic)
        vwriter = GeomVertexWriter(vdata, "vertex")
        nwriter = GeomVertexWriter(vdata, "normal")
        cwriter = GeomVertexWriter(vdata, "color")
        x0 = float(spec["x"])
        y0 = float(spec["y"])
        sx = float(spec["sx"])
        sy = float(spec["sy"])
        sz = float(spec["sz"])
        angle = math.radians(float(spec["h"]))
        ca, sa = math.cos(angle), math.sin(angle)
        alpha = float(spec.get("alpha", 0.70))
        for iy in range(segments + 1):
            v = (iy / segments) * 2.0 - 1.0
            for ix in range(segments + 1):
                u = (ix / segments) * 2.0 - 1.0
                # Elliptical footprint with a wind-carved asymmetry.
                r2 = u * u + (v * 1.08) * (v * 1.08)
                taper = clamp(1.0 - r2, 0.0, 1.0)
                ridge = 0.12 * math.sin((u * 2.6 + v * 0.7) * math.pi) * taper
                height = sz * (taper ** 1.55) * (0.88 + ridge)
                lx = u * sx
                ly = v * sy
                wx = x0 + ca * lx - sa * ly
                wy = y0 + sa * lx + ca * ly
                wz = world.surface_height(wx, wy) + 0.78 + height
                vwriter.addData3(wx, wy, wz)
                nwriter.addData3(0, 0, 1)
                edge = clamp(taper * 1.25, 0.0, 1.0)
                shade = 0.72 + taper * 0.24 + max(0.0, ridge) * 0.18
                cwriter.addData4(
                    clamp(shade * 0.92, 0.0, 1.0),
                    clamp(shade * 0.99, 0.0, 1.0),
                    1.0,
                    alpha * edge,
                )
        tris = GeomTriangles(Geom.UHStatic)
        row = segments + 1
        for iy in range(segments):
            for ix in range(segments):
                u0 = (ix / segments) * 2.0 - 1.0
                v0 = (iy / segments) * 2.0 - 1.0
                u1 = ((ix + 1) / segments) * 2.0 - 1.0
                v1 = ((iy + 1) / segments) * 2.0 - 1.0
                if max(u0 * u0 + v0 * v0, u1 * u1 + v1 * v1) > 1.18:
                    continue
                i0 = iy * row + ix
                i1 = i0 + 1
                i2 = i0 + row
                i3 = i2 + 1
                tris.addVertices(i0, i2, i1)
                tris.addVertices(i1, i2, i3)
        geom = Geom(vdata)
        geom.addPrimitive(tris)
        node = GeomNode(name)
        node.addGeom(geom)
        return NodePath(node)

    @staticmethod
    def make_crater_ice_pool_patch(name: str, world: WorldGenerator, spec: dict[str, float | str], holes: list[Hole] | None = None, segments: int = 38) -> NodePath:
        """Terrain-fitted frozen crater-floor ice lens.

        The center is gently leveled like compacted exposed ice, while the outer
        ring blends back to the crater terrain so it does not float or leave gaps.
        Drilled holes are cut out of the pool mesh so the dark aperture remains visible.
        """
        fmt = GeomVertexFormat.getV3n3c4t2()
        vdata = GeomVertexData(name, fmt, Geom.UHStatic)
        vwriter = GeomVertexWriter(vdata, "vertex")
        nwriter = GeomVertexWriter(vdata, "normal")
        cwriter = GeomVertexWriter(vdata, "color")
        twriter = GeomVertexWriter(vdata, "texcoord")
        cx = float(spec["x"])
        cy = float(spec["y"])
        radius = float(spec["radius"])
        sx = float(spec.get("sx", 1.0))
        sy = float(spec.get("sy", 0.82))
        angle = math.radians(float(spec.get("h", 0.0)))
        ca, sa = math.cos(angle), math.sin(angle)
        cut_holes = holes or []
        center_z = world.surface_height(cx, cy)
        positions: list[list[tuple[float, float, float]]] = []
        colors: list[list[tuple[float, float, float, float]]] = []
        texcoords: list[list[tuple[float, float]]] = []

        for iy in range(segments + 1):
            v = (iy / segments) * 2.0 - 1.0
            prow: list[tuple[float, float, float]] = []
            crow: list[tuple[float, float, float, float]] = []
            trow: list[tuple[float, float]] = []
            for ix in range(segments + 1):
                u = (ix / segments) * 2.0 - 1.0
                lx = u * radius * sx
                ly = v * radius * sy
                wx = cx + ca * lx - sa * ly
                wy = cy + sa * lx + ca * ly
                ellipse_r = math.sqrt(u * u + v * v)
                terrain_z = world.surface_height(wx, wy)
                edge = clamp((ellipse_r - 0.54) / 0.42, 0.0, 1.0)
                level = center_z + math.sin((u * 4.0 + v * 1.3) * math.pi) * 0.16 + math.cos((u - v) * 2.4 * math.pi) * 0.10
                z = (level * (1.0 - edge) + terrain_z * edge) + 0.58
                frost = clamp(1.0 - ellipse_r, 0.0, 1.0)
                dirt_edge = clamp((ellipse_r - 0.62) / 0.36, 0.0, 1.0)
                blue = 0.86 + frost * 0.13
                warm = 0.74 + dirt_edge * 0.15
                fracture = 0.5 + 0.5 * math.sin((u * 10.0 - v * 4.0) * math.pi)
                color = (
                    clamp(0.22 + frost * 0.16 + dirt_edge * 0.25 + fracture * 0.028, 0.0, 1.0),
                    clamp(0.48 + frost * 0.22 + dirt_edge * 0.15 + fracture * 0.028, 0.0, 1.0),
                    clamp(0.68 + frost * 0.20 + fracture * 0.040 - dirt_edge * 0.07, 0.0, 1.0),
                    1.0,
                )
                # Dusty snow edge prevents the pools from looking like open water.
                if dirt_edge > 0.0:
                    color = (
                        clamp(color[0] * (1.0 - dirt_edge) + warm * dirt_edge, 0.0, 1.0),
                        clamp(color[1] * (1.0 - dirt_edge) + (warm * 0.98) * dirt_edge, 0.0, 1.0),
                        clamp(color[2] * (1.0 - dirt_edge) + (warm * 0.90) * dirt_edge, 0.0, 1.0),
                        1.0,
                    )
                prow.append((wx, wy, z))
                crow.append(color)
                trow.append((0.5 + u * 0.5, 0.5 + v * 0.5))
            positions.append(prow)
            colors.append(crow)
            texcoords.append(trow)

        for iy in range(segments + 1):
            for ix in range(segments + 1):
                wx, wy, z = positions[iy][ix]
                x0 = max(ix - 1, 0)
                x1 = min(ix + 1, segments)
                y0 = max(iy - 1, 0)
                y1 = min(iy + 1, segments)
                dzdx = (positions[iy][x1][2] - positions[iy][x0][2]) / max(math.hypot(positions[iy][x1][0] - positions[iy][x0][0], positions[iy][x1][1] - positions[iy][x0][1]), 1e-4)
                dzdy = (positions[y1][ix][2] - positions[y0][ix][2]) / max(math.hypot(positions[y1][ix][0] - positions[y0][ix][0], positions[y1][ix][1] - positions[y0][ix][1]), 1e-4)
                normal = Vec3(-dzdx, -dzdy, 1.0)
                normal.normalize()
                vwriter.addData3(wx, wy, z)
                nwriter.addData3(normal)
                cwriter.addData4(*colors[iy][ix])
                twriter.addData2(*texcoords[iy][ix])

        tris = GeomTriangles(Geom.UHStatic)
        row = segments + 1

        def cell_cut_or_out(ix: int, iy: int) -> bool:
            u = ((ix + 0.5) / segments) * 2.0 - 1.0
            v = ((iy + 0.5) / segments) * 2.0 - 1.0
            if u * u + v * v > 1.02:
                return True
            wx = (positions[iy][ix][0] + positions[iy + 1][ix + 1][0]) * 0.5
            wy = (positions[iy][ix][1] + positions[iy + 1][ix + 1][1]) * 0.5
            for hole in cut_holes:
                r = hole.radius * 1.32
                if (wx - hole.x) ** 2 + (wy - hole.y) ** 2 <= r * r:
                    return True
            return False

        for iy in range(segments):
            for ix in range(segments):
                if cell_cut_or_out(ix, iy):
                    continue
                i0 = iy * row + ix
                i1 = i0 + 1
                i2 = i0 + row
                i3 = i2 + 1
                tris.addVertices(i0, i2, i1)
                tris.addVertices(i1, i2, i3)
        geom = Geom(vdata)
        geom.addPrimitive(tris)
        node = GeomNode(name)
        node.addGeom(geom)
        return NodePath(node)

    @staticmethod
    def make_plume_rift_patch(
        name: str,
        world: WorldGenerator,
        center_x: float,
        center_y: float,
        angle: float,
        length: float,
        width: float,
        ridge_height: float,
        channel_depth: float,
        *,
        segments_u: int = 30,
        segments_v: int = 18,
        alpha: float = 0.96,
    ) -> NodePath:
        fmt = GeomVertexFormat.getV3n3c4()
        vdata = GeomVertexData(name, fmt, Geom.UHStatic)
        vwriter = GeomVertexWriter(vdata, "vertex")
        nwriter = GeomVertexWriter(vdata, "normal")
        cwriter = GeomVertexWriter(vdata, "color")
        ca, sa = math.cos(angle), math.sin(angle)
        heights: list[list[float]] = []
        world_pos: list[list[tuple[float, float]]] = []

        def sample_height(u: float, v: float, wx: float, wy: float) -> tuple[float, tuple[float, float, float, float]]:
            ridge_gain = math.pow(max(0.0, 1.0 - abs(u)), 0.78)
            channel_half = width * (0.10 + 0.16 * abs(u))
            bank_width = width * (0.16 + 0.05 * abs(u))
            dist = abs(v)
            depression = 0.0
            if dist < channel_half:
                center = 1.0 - dist / max(channel_half, 1e-4)
                depression = -channel_depth * math.pow(center, 1.55) * (0.58 + 0.42 * ridge_gain)
            bank_center = channel_half + bank_width * (0.34 + 0.66 * ridge_gain)
            bank = math.exp(-((dist - bank_center) / max(bank_width, 1e-4)) ** 2) * ridge_height * (0.30 + 0.70 * ridge_gain)
            outer = math.exp(-((dist - width * 0.86) / max(width * 0.22, 1e-4)) ** 2) * ridge_height * 0.16
            undulation = math.sin((wx * 0.012 + wy * 0.009) + u * 4.6 + v * 0.07) * 0.95
            z = world.surface_height(wx, wy) + bank + outer + depression + undulation
            edge = clamp(1.0 - max(0.0, dist - width * 0.78) / max(width * 0.26, 1e-4), 0.0, 1.0)
            cold = 0.80 + ridge_gain * 0.12 + max(bank, 0.0) / max(ridge_height, 1e-4) * 0.04
            shadow = 0.08 if depression < 0.0 else 0.0
            color = (clamp(cold - shadow, 0.0, 1.0), clamp(cold + 0.05 - shadow, 0.0, 1.0), 1.0, alpha * edge)
            return z, color

        for iy in range(segments_v + 1):
            fv = iy / segments_v
            lv = (fv * 2.0 - 1.0) * width
            hrow = []
            prow = []
            for ix in range(segments_u + 1):
                fu = ix / segments_u
                lu = (fu * 2.0 - 1.0)
                local_x = lu * (length * 0.5)
                local_y = lv
                wx = center_x + ca * local_x - sa * local_y
                wy = center_y + sa * local_x + ca * local_y
                z, _ = sample_height(lu, lv, wx, wy)
                hrow.append(z)
                prow.append((wx, wy))
            heights.append(hrow)
            world_pos.append(prow)

        for iy in range(segments_v + 1):
            fv = iy / segments_v
            lv = (fv * 2.0 - 1.0) * width
            y0 = max(iy - 1, 0)
            y1 = min(iy + 1, segments_v)
            for ix in range(segments_u + 1):
                fu = ix / segments_u
                lu = (fu * 2.0 - 1.0)
                x0 = max(ix - 1, 0)
                x1 = min(ix + 1, segments_u)
                wx, wy = world_pos[iy][ix]
                z = heights[iy][ix]
                dzdx = (heights[iy][x1] - heights[iy][x0]) / max((x1 - x0) * (length / segments_u), 1e-4)
                dzdy = (heights[y1][ix] - heights[y0][ix]) / max((y1 - y0) * ((width * 2.0) / segments_v), 1e-4)
                normal = Vec3(-dzdx, -dzdy, 1.0)
                normal.normalize()
                _, color = sample_height(lu, lv, wx, wy)
                vwriter.addData3(wx, wy, z)
                nwriter.addData3(normal)
                cwriter.addData4(*color)

        tris = GeomTriangles(Geom.UHStatic)
        row = segments_u + 1
        for iy in range(segments_v):
            for ix in range(segments_u):
                i0 = iy * row + ix
                i1 = i0 + 1
                i2 = i0 + row
                i3 = i2 + 1
                tris.addVertices(i0, i2, i1)
                tris.addVertices(i1, i2, i3)
        geom = Geom(vdata)
        geom.addPrimitive(tris)
        node = GeomNode(name)
        node.addGeom(geom)
        return NodePath(node)

    @staticmethod
    def make_plume_water_ribbon(
        name: str,
        world: WorldGenerator,
        center_x: float,
        center_y: float,
        angle: float,
        length: float,
        width: float,
        channel_depth: float,
        *,
        segments_u: int = 26,
        segments_v: int = 12,
    ) -> NodePath:
        fmt = GeomVertexFormat.getV3n3c4()
        vdata = GeomVertexData(name, fmt, Geom.UHStatic)
        vwriter = GeomVertexWriter(vdata, "vertex")
        nwriter = GeomVertexWriter(vdata, "normal")
        cwriter = GeomVertexWriter(vdata, "color")
        ca, sa = math.cos(angle), math.sin(angle)
        heights: list[list[float]] = []

        def sample(u: float, v: float, wx: float, wy: float) -> tuple[float, tuple[float, float, float, float]]:
            channel_half = width * (0.09 + 0.15 * abs(u))
            dist = abs(v)
            if dist >= channel_half:
                glow = 0.0
            else:
                glow = math.pow(1.0 - dist / max(channel_half, 1e-4), 1.35)
            axial = 0.62 + (1.0 - abs(u)) * 0.38
            z = world.surface_height(wx, wy) - channel_depth * (0.58 + glow * 0.16) + 0.45 + math.sin((wx + wy) * 0.015) * 0.10
            alpha_local = clamp(glow * axial * 0.46, 0.0, 0.46)
            color = (0.18 + glow * 0.08, 0.76 + glow * 0.16, 0.92 + glow * 0.08, alpha_local)
            return z, color

        positions: list[list[tuple[float, float]]] = []
        for iy in range(segments_v + 1):
            fv = iy / segments_v
            lv = (fv * 2.0 - 1.0) * width
            hrow = []
            prow = []
            for ix in range(segments_u + 1):
                fu = ix / segments_u
                lu = (fu * 2.0 - 1.0)
                local_x = lu * (length * 0.5)
                local_y = lv
                wx = center_x + ca * local_x - sa * local_y
                wy = center_y + sa * local_x + ca * local_y
                z, _ = sample(lu, lv, wx, wy)
                hrow.append(z)
                prow.append((wx, wy))
            heights.append(hrow)
            positions.append(prow)

        for iy in range(segments_v + 1):
            fv = iy / segments_v
            lv = (fv * 2.0 - 1.0) * width
            y0 = max(iy - 1, 0)
            y1 = min(iy + 1, segments_v)
            for ix in range(segments_u + 1):
                fu = ix / segments_u
                lu = (fu * 2.0 - 1.0)
                x0 = max(ix - 1, 0)
                x1 = min(ix + 1, segments_u)
                wx, wy = positions[iy][ix]
                z = heights[iy][ix]
                dzdx = (heights[iy][x1] - heights[iy][x0]) / max((x1 - x0) * (length / segments_u), 1e-4)
                dzdy = (heights[y1][ix] - heights[y0][ix]) / max((y1 - y0) * ((width * 2.0) / segments_v), 1e-4)
                normal = Vec3(-dzdx, -dzdy, 1.0)
                normal.normalize()
                _, color = sample(lu, lv, wx, wy)
                vwriter.addData3(wx, wy, z)
                nwriter.addData3(normal)
                cwriter.addData4(*color)

        tris = GeomTriangles(Geom.UHStatic)
        row = segments_u + 1
        for iy in range(segments_v):
            for ix in range(segments_u):
                i0 = iy * row + ix
                i1 = i0 + 1
                i2 = i0 + row
                i3 = i2 + 1
                tris.addVertices(i0, i2, i1)
                tris.addVertices(i1, i2, i3)
        geom = Geom(vdata)
        geom.addPrimitive(tris)
        node = GeomNode(name)
        node.addGeom(geom)
        return NodePath(node)

    @staticmethod
    def make_jagged_rock_spire(
        name: str,
        height: float,
        radius: float,
        *,
        sides: int = 7,
        rings: int = 7,
        seed: int = 0,
        base_color: tuple[float, float, float, float] = (0.22, 0.21, 0.20, 1.0),
        tip_color: tuple[float, float, float, float] = (0.74, 0.72, 0.68, 1.0),
        tip_radius_scale: float = 0.035,
        taper_exponent: float = 0.92,
    ) -> NodePath:
        """Faceted vertical shard mesh used for real 3D jagged mountain/rock silhouettes.

        This is intentionally a static render mesh with no collision solid. The
        movement controller follows the sampled terrain, so the rocks sell sharp
        geology without creating new hidden blockers.
        """
        sides = max(5, int(sides))
        rings = max(3, int(rings))
        fmt = GeomVertexFormat.getV3n3c4t2()
        vdata = GeomVertexData(name, fmt, Geom.UHStatic)
        vwriter = GeomVertexWriter(vdata, "vertex")
        nwriter = GeomVertexWriter(vdata, "normal")
        cwriter = GeomVertexWriter(vdata, "color")
        twriter = GeomVertexWriter(vdata, "texcoord")
        phase = (seed % 997) * 0.037
        side_warp = [0.72 + 0.46 * (0.5 + 0.5 * math.sin(phase + i * 1.713 + math.sin(i * 0.91 + phase))) for i in range(sides)]
        lean_x = math.sin(phase * 1.9) * radius * 0.22
        lean_y = math.cos(phase * 1.4) * radius * 0.18
        for ring in range(rings + 1):
            v = ring / rings
            taper = max(0.0, (1.0 - v) ** clamp(float(taper_exponent), 0.10, 2.0))
            saw = 0.86 + 0.14 * math.sin(phase + ring * 2.37)
            ring_radius = radius * taper * saw
            if ring == rings:
                ring_radius = radius * clamp(float(tip_radius_scale), 0.01, 0.85)
            z = height * (v ** 1.04)
            # Slight crookedness keeps the silhouette 3D and hand-built rather than conical.
            center_x = lean_x * (v ** 1.3) + math.sin(phase + v * 4.0) * radius * 0.055
            center_y = lean_y * (v ** 1.25) + math.cos(phase * 0.7 + v * 5.0) * radius * 0.045
            for side in range(sides):
                a = (side / sides) * math.tau
                local_radius = ring_radius * side_warp[side] * (0.88 + 0.12 * math.sin(phase + ring * 1.3 + side * 2.1))
                x = center_x + math.cos(a) * local_radius
                y = center_y + math.sin(a) * local_radius
                normal = Vec3(math.cos(a) * 0.85, math.sin(a) * 0.85, 0.34 + v * 0.28)
                normal.normalize()
                shade = clamp(0.68 + normal.z * 0.28 + math.sin(phase + side * 1.7) * 0.055, 0.50, 1.05)
                r = (base_color[0] * (1.0 - v) + tip_color[0] * v) * shade
                g = (base_color[1] * (1.0 - v) + tip_color[1] * v) * shade
                b = (base_color[2] * (1.0 - v) + tip_color[2] * v) * shade
                vwriter.addData3(x, y, z)
                nwriter.addData3(normal)
                cwriter.addData4(clamp(r, 0.0, 1.0), clamp(g, 0.0, 1.0), clamp(b, 0.0, 1.0), base_color[3])
                twriter.addData2(side / sides, v)
        tris = GeomTriangles(Geom.UHStatic)
        for ring in range(rings):
            row = ring * sides
            next_row = (ring + 1) * sides
            for side in range(sides):
                i0 = row + side
                i1 = row + ((side + 1) % sides)
                i2 = next_row + side
                i3 = next_row + ((side + 1) % sides)
                tris.addVertices(i0, i2, i1)
                tris.addVertices(i1, i2, i3)
        # simple bottom cap so the rock intersects terrain cleanly instead of looking hollow
        center_index = (rings + 1) * sides
        vwriter.addData3(0.0, 0.0, -height * 0.035)
        nwriter.addData3(0.0, 0.0, -1.0)
        cwriter.addData4(*base_color)
        twriter.addData2(0.5, 0.5)
        for side in range(sides):
            tris.addVertices(center_index, (side + 1) % sides, side)
        geom = Geom(vdata)
        geom.addPrimitive(tris)
        node = GeomNode(name)
        node.addGeom(geom)
        np = NodePath(node)
        np.setTwoSided(False)
        return np

    @staticmethod
    def make_plane(name: str, half: float, z_func, uv_scale: float, segments: int = 120) -> NodePath:
        fmt = GeomVertexFormat.getV3n3t2()
        vdata = GeomVertexData(name, fmt, Geom.UHStatic)
        vwriter = GeomVertexWriter(vdata, "vertex")
        nwriter = GeomVertexWriter(vdata, "normal")
        twriter = GeomVertexWriter(vdata, "texcoord")
        step = (half * 2.0) / segments
        for iy in range(segments + 1):
            y = -half + iy * step
            for ix in range(segments + 1):
                x = -half + ix * step
                z = z_func(x, y)
                vwriter.addData3(x, y, z)
                nwriter.addData3(0, 0, 1)
                twriter.addData2(0.5 + x * uv_scale, 0.5 + y * uv_scale)
        tris = GeomTriangles(Geom.UHStatic)
        row = segments + 1
        for iy in range(segments):
            for ix in range(segments):
                i0 = iy * row + ix
                i1 = i0 + 1
                i2 = i0 + row
                i3 = i2 + 1
                tris.addVertices(i0, i2, i1)
                tris.addVertices(i1, i2, i3)
        geom = Geom(vdata)
        geom.addPrimitive(tris)
        node = GeomNode(name)
        node.addGeom(geom)
        return NodePath(node)


    @staticmethod
    def make_local_hole_patch(name: str, cx: float, cy: float, inner_radius: float, outer_radius: float, height_func, seed_func, segments: int = 72, rings: int = 6) -> NodePath:
        """Terrain-following annular patch with a real open center.

        This is intentionally local and stable: the main ice sheet keeps its pretty
        layered material while the drilled hole owns its rim/opening geometry.
        """
        fmt = GeomVertexFormat.getV3n3t2()
        vdata = GeomVertexData(name, fmt, Geom.UHStatic)
        vwriter = GeomVertexWriter(vdata, "vertex")
        nwriter = GeomVertexWriter(vdata, "normal")
        twriter = GeomVertexWriter(vdata, "texcoord")
        center_z = height_func(cx, cy)
        # Deterministic uneven edge so the cut does not read as a perfect prop.
        edge_wobble: list[float] = []
        for i in range(segments + 1):
            a = (i / segments) * math.tau
            wob = (seed_func(int(cx // 17) + i, int(cy // 17), 600 + i) - 0.5) * inner_radius * 0.10
            wob += math.sin(a * 5.0 + seed_func(int(cx // 31), int(cy // 31), 712) * math.tau) * inner_radius * 0.035
            edge_wobble.append(wob)
        for ring in range(rings + 1):
            t = ring / max(rings, 1)
            # Inner cut is slightly irregular; outer edge is stable and terrain matched.
            for i in range(segments + 1):
                a = (i / segments) * math.tau
                cut_wobble = edge_wobble[i] * (1.0 - t)
                radius = inner_radius + cut_wobble + (outer_radius - inner_radius) * t
                wx = cx + math.cos(a) * radius
                wy = cy + math.sin(a) * radius
                # Small low chipped lip, not a large raised mound.
                chip = math.sin(a * 9.0 + t * 2.7) * 0.10 + math.cos(a * 4.0) * 0.08
                lip = (1.0 - t) ** 1.8 * 0.42 + chip * (1.0 - t)
                z = height_func(wx, wy) - center_z + 0.10 + lip
                vwriter.addData3(wx - cx, wy - cy, z)
                nwriter.addData3(0.0, 0.0, 1.0)
                uv_r = 0.48 + t * 0.32
                twriter.addData2(0.5 + math.cos(a) * uv_r, 0.5 + math.sin(a) * uv_r)
        tris = GeomTriangles(Geom.UHStatic)
        row = segments + 1
        for ring in range(rings):
            for i in range(segments):
                i0 = ring * row + i
                i1 = i0 + 1
                i2 = i0 + row
                i3 = i2 + 1
                tris.addVertices(i0, i2, i1)
                tris.addVertices(i1, i2, i3)
        geom = Geom(vdata)
        geom.addPrimitive(tris)
        node = GeomNode(name)
        node.addGeom(geom)
        np = NodePath(node)
        np.setPos(cx, cy, center_z)
        return np

    @staticmethod
    def make_hole_shaft(name: str, cx: float, cy: float, radius: float, top_func, bottom_func, segments: int = 48) -> NodePath:
        fmt = GeomVertexFormat.getV3n3t2()
        vdata = GeomVertexData(name, fmt, Geom.UHStatic)
        vwriter = GeomVertexWriter(vdata, "vertex")
        nwriter = GeomVertexWriter(vdata, "normal")
        twriter = GeomVertexWriter(vdata, "texcoord")

        center_top = top_func(cx, cy)
        for i in range(segments + 1):
            ang = (i / segments) * math.tau
            lx = math.cos(ang) * radius
            ly = math.sin(ang) * radius
            wx = cx + lx
            wy = cy + ly
            top_z = top_func(wx, wy) - center_top
            bottom_z = bottom_func(wx, wy) - center_top
            normal = Vec3(math.cos(ang), math.sin(ang), 0.0)
            vwriter.addData3(lx, ly, top_z)
            nwriter.addData3(normal)
            twriter.addData2(i / segments, 0.0)
            vwriter.addData3(lx, ly, bottom_z)
            nwriter.addData3(normal)
            twriter.addData2(i / segments, 1.0)

        tris = GeomTriangles(Geom.UHStatic)
        for i in range(segments):
            i0 = i * 2
            i1 = i0 + 1
            i2 = i0 + 2
            i3 = i0 + 3
            tris.addVertices(i0, i1, i2)
            tris.addVertices(i2, i1, i3)
        geom = Geom(vdata)
        geom.addPrimitive(tris)
        node = GeomNode(name)
        node.addGeom(geom)
        np = NodePath(node)
        np.setPos(cx, cy, center_top)
        return np

    @staticmethod
    def make_disc(name: str, radius: float, segments: int = 40) -> NodePath:
        fmt = GeomVertexFormat.getV3n3t2()
        vdata = GeomVertexData(name, fmt, Geom.UHStatic)
        vwriter = GeomVertexWriter(vdata, "vertex")
        nwriter = GeomVertexWriter(vdata, "normal")
        twriter = GeomVertexWriter(vdata, "texcoord")
        vwriter.addData3(0.0, 0.0, 0.0)
        nwriter.addData3(0.0, 0.0, 1.0)
        twriter.addData2(0.5, 0.5)
        for i in range(segments + 1):
            ang = (i / segments) * math.tau
            x = math.cos(ang) * radius
            y = math.sin(ang) * radius
            vwriter.addData3(x, y, 0.0)
            nwriter.addData3(0.0, 0.0, 1.0)
            twriter.addData2(0.5 + (x / (radius * 2.0)), 0.5 + (y / (radius * 2.0)))
        tris = GeomTriangles(Geom.UHStatic)
        for i in range(1, segments + 1):
            tris.addVertices(0, i, i + 1)
        geom = Geom(vdata)
        geom.addPrimitive(tris)
        node = GeomNode(name)
        node.addGeom(geom)
        return NodePath(node)


class EnceladusIce(ShowBase):
    def _sfx_is_available(self) -> bool:
        return not any(flag in sys.argv for flag in AUDIO_DISABLED_FLAGS)

    def _ensure_sfx_assets(self) -> None:
        """Create tiny, soft PCM cues so the prototype stays portable."""
        SFX_DIR.mkdir(parents=True, exist_ok=True)
        specs = {
            "drill_start.wav": (0.42, self._sample_drill_start),
            "drill_loop.wav": (1.20, self._sample_drill_loop),
            "drill_deep_crack.wav": (1.55, self._sample_drill_deep_crack),
            "drill_breakthrough.wav": (0.66, self._sample_drill_breakthrough),
            "robot_activate.wav": (0.78, self._sample_robot_activate),
            "robot_anchor.wav": (0.46, self._sample_robot_anchor),
            "robot_braced.wav": (0.62, self._sample_robot_braced),
            "sonar_ping.wav": (0.72, self._sample_sonar_ping),
            "sonar_lock.wav": (0.58, self._sample_sonar_lock),
            "magnet_attach.wav": (0.55, self._sample_magnet_attach),
            "cargo_hoist.wav": (1.12, self._sample_cargo_hoist),
            "cargo_collect.wav": (0.48, self._sample_cargo_collect),
            "ambience_enceladus.wav": (7.20, self._sample_ambience_enceladus),
            "ambience_mimas.wav": (7.20, self._sample_ambience_mimas),
            "ambience_iapetus.wav": (7.20, self._sample_ambience_iapetus),
            "ambience_titan.wav": (7.20, self._sample_ambience_titan),
            "ambience_pluto.wav": (7.20, self._sample_ambience_pluto),
            "signal_static.wav": (0.92, self._sample_signal_static),
            "drone_disabled.wav": (0.70, self._sample_drone_disabled),
            "rescue_pull.wav": (1.10, self._sample_rescue_pull),
            "rescue_complete.wav": (0.62, self._sample_rescue_complete),
        }
        for filename, (duration, sampler) in specs.items():
            path = SFX_DIR / filename
            if not path.exists() or "--regen-sfx" in sys.argv:
                self._write_sfx(path, duration, sampler)

    def _write_sfx(self, path: Path, duration: float, sampler, sample_rate: int = 44100) -> None:
        count = max(1, int(duration * sample_rate))
        frames = bytearray()
        fade_samples = max(1, int(0.025 * sample_rate))
        for i in range(count):
            t = i / sample_rate
            fade_in = clamp(i / fade_samples, 0.0, 1.0)
            fade_out = clamp((count - i - 1) / fade_samples, 0.0, 1.0)
            envelope = min(fade_in, fade_out)
            value = int(clamp(sampler(t, duration) * envelope, -1.0, 1.0) * 32767)
            frames.extend(value.to_bytes(2, "little", signed=True))
        with wave.open(str(path), "wb") as wav:
            wav.setnchannels(1)
            wav.setsampwidth(2)
            wav.setframerate(sample_rate)
            wav.writeframes(bytes(frames))

    def _noise01(self, t: float, salt: int) -> float:
        n = int(t * 44100.0) + salt * 374761393
        n = (n ^ (n >> 13)) * 1274126177
        n = (n ^ (n >> 16)) & 0xFFFF
        return (n / 32767.5) - 1.0

    def _sample_drill_start(self, t: float, duration: float) -> float:
        sweep = 55.0 + 118.0 * (t / duration)
        motor = math.sin(math.tau * sweep * t) * 0.12
        servo = math.sin(math.tau * (260.0 + 80.0 * t) * t) * 0.035
        return (motor + servo + self._noise01(t, 3) * 0.012) * 0.42

    def _sample_drill_loop(self, t: float, duration: float) -> float:
        # Loopable, low, and intentionally distant/faint under the visual drill.
        base = math.sin(math.tau * 92.0 * t) * 0.10
        wobble = math.sin(math.tau * 184.0 * t + math.sin(math.tau * 2.0 * t) * 0.6) * 0.055
        scrape_gate = 0.5 + 0.5 * math.sin(math.tau * 7.0 * t)
        scrape = self._noise01(t, 11) * 0.030 * scrape_gate
        return (base + wobble + scrape) * 0.33

    def _sample_drill_deep_crack(self, t: float, duration: float) -> float:
        # Faint sub-ice stress: low groans plus spaced crack transients while drilling.
        u = (t / duration) % 1.0
        groan = math.sin(math.tau * 32.0 * t + math.sin(math.tau * 0.9 * t) * 1.8) * 0.055
        flex = math.sin(math.tau * 51.0 * t + math.sin(math.tau * 1.7 * t) * 0.9) * 0.035
        crack = 0.0
        for point, salt, pitch in ((0.18, 41, 92.0), (0.47, 43, 64.0), (0.76, 47, 118.0)):
            d = abs(u - point)
            snap = math.exp(-190.0 * d)
            crack += snap * (math.sin(math.tau * pitch * t) * 0.075 + self._noise01(t, salt) * 0.050)
        rumble_gate = 0.55 + 0.45 * math.sin(math.tau * 0.65 * t)
        rumble = self._noise01(t, 53) * 0.018 * rumble_gate
        return (groan + flex + crack + rumble) * 0.34

    def _sample_drill_breakthrough(self, t: float, duration: float) -> float:
        decay = math.exp(-5.2 * t)
        crack = self._noise01(t, 21) * 0.13 * decay
        thunk = math.sin(math.tau * 58.0 * t) * 0.16 * math.exp(-7.0 * t)
        ice_ring = math.sin(math.tau * 410.0 * t) * 0.035 * math.exp(-3.0 * t)
        return (crack + thunk + ice_ring) * 0.38

    def _sample_robot_activate(self, t: float, duration: float) -> float:
        u = t / duration
        chirp = math.sin(math.tau * (420.0 + 260.0 * u) * t) * 0.045
        servo = math.sin(math.tau * 132.0 * t + math.sin(math.tau * 4.0 * t) * 1.7) * 0.080
        pulse = (1.0 if 0.18 < u < 0.28 or 0.52 < u < 0.62 else 0.45)
        return (chirp + servo * pulse) * 0.36

    def _sample_robot_anchor(self, t: float, duration: float) -> float:
        u = t / duration
        clicks = 0.0
        for point in (0.14, 0.33, 0.53):
            d = abs(u - point)
            clicks += math.exp(-260.0 * d) * math.sin(math.tau * 720.0 * t) * 0.09
        settle = math.sin(math.tau * 74.0 * t) * 0.05 * math.exp(-3.5 * t)
        return (clicks + settle + self._noise01(t, 31) * 0.010) * 0.42

    def _sample_robot_braced(self, t: float, duration: float) -> float:
        confirm = math.sin(math.tau * 300.0 * t) * 0.045 * math.exp(-1.5 * t)
        sub = math.sin(math.tau * 64.0 * t) * 0.060 * math.exp(-2.8 * t)
        return (confirm + sub) * 0.42

    def _sample_sonar_ping(self, t: float, duration: float) -> float:
        # Faint wide-sweep sonar return: soft chirp plus a dark under-ice echo.
        u = t / duration
        decay = math.exp(-4.2 * t)
        chirp_freq = 540.0 + 210.0 * u
        chirp = math.sin(math.tau * chirp_freq * t) * 0.050 * decay
        echo = math.sin(math.tau * 146.0 * t) * 0.030 * math.exp(-2.4 * max(t - 0.12, 0.0))
        second_echo = math.sin(math.tau * 96.0 * t) * 0.022 * math.exp(-2.8 * max(t - 0.32, 0.0))
        return (chirp + echo + second_echo) * 0.36

    def _sample_sonar_lock(self, t: float, duration: float) -> float:
        # Short confirmation chirp when the crosshair is inside a drillable hotspot.
        u = t / duration
        gate_a = math.exp(-170.0 * abs(u - 0.18))
        gate_b = math.exp(-130.0 * abs(u - 0.52))
        tone_a = math.sin(math.tau * 620.0 * t) * 0.055 * gate_a
        tone_b = math.sin(math.tau * 770.0 * t) * 0.045 * gate_b
        body = math.sin(math.tau * 108.0 * t) * 0.030 * math.exp(-3.6 * t)
        return (tone_a + tone_b + body) * 0.42

    def _sample_magnet_attach(self, t: float, duration: float) -> float:
        # Low magnetic thump when the line tip physically grabs a metal object.
        u = t / duration
        snap = math.exp(-190.0 * abs(u - 0.16)) * math.sin(math.tau * 92.0 * t) * 0.12
        clamp_click = math.exp(-230.0 * abs(u - 0.29)) * math.sin(math.tau * 640.0 * t) * 0.045
        field = math.sin(math.tau * 54.0 * t + math.sin(math.tau * 3.2 * t) * 0.9) * 0.050 * math.exp(-2.3 * t)
        return (snap + clamp_click + field + self._noise01(t, 67) * 0.010) * 0.38

    def _sample_cargo_hoist(self, t: float, duration: float) -> float:
        # Soft winch/motor ramp while the drone pulls cargo up under its chassis.
        u = t / duration
        ramp = min(u * 2.2, 1.0) * min((1.0 - u) * 3.0, 1.0)
        motor = math.sin(math.tau * (88.0 + 18.0 * math.sin(math.tau * 0.8 * t)) * t) * 0.070
        spool = math.sin(math.tau * 176.0 * t + math.sin(math.tau * 5.0 * t) * 0.7) * 0.033
        cable = self._noise01(t, 71) * 0.016 * (0.55 + 0.45 * math.sin(math.tau * 9.0 * t))
        return (motor + spool + cable) * ramp * 0.32

    def _sample_cargo_collect(self, t: float, duration: float) -> float:
        # Compact pickup cue: small latch release plus mineral confirm tone.
        u = t / duration
        click_a = math.exp(-260.0 * abs(u - 0.10)) * math.sin(math.tau * 780.0 * t) * 0.060
        click_b = math.exp(-240.0 * abs(u - 0.24)) * math.sin(math.tau * 520.0 * t) * 0.044
        tone = math.sin(math.tau * 312.0 * t) * 0.045 * math.exp(-3.2 * max(t - 0.08, 0.0))
        sub = math.sin(math.tau * 68.0 * t) * 0.030 * math.exp(-4.0 * t)
        return (click_a + click_b + tone + sub) * 0.44

    def _sample_world_ambience(self, t: float, duration: float, *, salt: int, low: float, mid: float, shimmer: float, wind: float) -> float:
        # Loopable low-cost bed: quiet wind/noise plus a slow tonal body.
        u = (t / duration) % 1.0
        loop_fade = 0.5 - 0.5 * math.cos(math.tau * u)
        body = math.sin(math.tau * low * t + math.sin(math.tau * 0.11 * t) * 0.9) * 0.030
        tone = math.sin(math.tau * mid * t + math.sin(math.tau * 0.07 * t + salt) * 0.7) * 0.020
        frost = self._noise01(t, salt) * wind * (0.65 + 0.35 * math.sin(math.tau * 0.19 * t))
        glint = math.sin(math.tau * shimmer * t) * 0.010 * (0.35 + 0.65 * loop_fade)
        return (body + tone + frost + glint) * 0.30

    def _sample_ambience_enceladus(self, t: float, duration: float) -> float:
        return self._sample_world_ambience(t, duration, salt=101, low=28.0, mid=87.0, shimmer=224.0, wind=0.030)

    def _sample_ambience_mimas(self, t: float, duration: float) -> float:
        return self._sample_world_ambience(t, duration, salt=131, low=22.0, mid=61.0, shimmer=176.0, wind=0.026)

    def _sample_ambience_iapetus(self, t: float, duration: float) -> float:
        return self._sample_world_ambience(t, duration, salt=151, low=18.0, mid=44.0, shimmer=119.0, wind=0.034)

    def _sample_ambience_titan(self, t: float, duration: float) -> float:
        haze = math.sin(math.tau * 13.0 * t + math.sin(math.tau * 0.05 * t) * 1.2) * 0.035
        return self._sample_world_ambience(t, duration, salt=181, low=16.0, mid=52.0, shimmer=142.0, wind=0.038) + haze * 0.18

    def _sample_ambience_pluto(self, t: float, duration: float) -> float:
        haze = math.sin(math.tau * 9.0 * t + math.sin(math.tau * 0.03 * t) * 0.8) * 0.020
        return self._sample_world_ambience(t, duration, salt=211, low=11.0, mid=33.0, shimmer=88.0, wind=0.028) + haze * 0.16

    def _sample_signal_static(self, t: float, duration: float) -> float:
        # Soft radio crackle used only when a rover/drone approaches mission-zone edge.
        u = t / max(duration, 0.001)
        gate = 0.35 + 0.65 * (1.0 if int(u * 18.0) % 3 == 0 else 0.0)
        hiss = self._noise01(t, 209) * 0.105 * gate
        chirp = math.sin(math.tau * (820.0 + 120.0 * math.sin(t * 21.0)) * t) * 0.025 * math.exp(-1.8 * t)
        low = math.sin(math.tau * 48.0 * t) * 0.035 * (0.5 + 0.5 * math.sin(math.tau * 3.0 * t))
        return (hiss + chirp + low) * 0.34

    def _sample_drone_disabled(self, t: float, duration: float) -> float:
        u = t / max(duration, 0.001)
        fall = math.exp(-2.6 * t)
        tone = math.sin(math.tau * (360.0 - 190.0 * u) * t) * 0.075 * fall
        click = math.exp(-260.0 * abs(u - 0.18)) * math.sin(math.tau * 690.0 * t) * 0.08
        static = self._noise01(t, 211) * 0.055 * fall
        return (tone + click + static) * 0.42

    def _sample_rescue_pull(self, t: float, duration: float) -> float:
        u = t / max(duration, 0.001)
        ramp = min(u * 2.5, 1.0) * min((1.0 - u) * 3.0, 1.0)
        motor = math.sin(math.tau * (84.0 + 18.0 * math.sin(t * 4.0)) * t) * 0.078
        cable = self._noise01(t, 223) * 0.024 * (0.65 + 0.35 * math.sin(math.tau * 9.0 * t))
        return (motor + cable) * ramp * 0.36

    def _sample_rescue_complete(self, t: float, duration: float) -> float:
        u = t / max(duration, 0.001)
        ping = math.sin(math.tau * 540.0 * t) * 0.060 * math.exp(-4.0 * t)
        confirm = math.sin(math.tau * 720.0 * t) * 0.044 * math.exp(-130.0 * abs(u - 0.36))
        sub = math.sin(math.tau * 70.0 * t) * 0.045 * math.exp(-3.2 * t)
        return (ping + confirm + sub) * 0.44

    def _init_sfx(self) -> None:
        self.sfx: dict[str, object] = {}
        self.sfx_base_volumes = {
            "drill_start": 0.24,
            "drill_loop": 0.16,
            "drill_deep_crack": 0.115,
            "drill_breakthrough": 0.22,
            "robot_activate": 0.20,
            "robot_anchor": 0.17,
            "robot_braced": 0.18,
            "sonar_ping": 0.105,
            "sonar_lock": 0.135,
            "magnet_attach": 0.17,
            "cargo_hoist": 0.15,
            "cargo_collect": 0.19,
            "ambience_enceladus": 0.070,
            "ambience_mimas": 0.060,
            "ambience_iapetus": 0.066,
            "ambience_titan": 0.074,
            "ambience_pluto": 0.064,
            "signal_static": 0.080,
            "drone_disabled": 0.145,
            "rescue_pull": 0.105,
            "rescue_complete": 0.155,
        }
        self.active_ambience_name = WORLD_AMBIENCE_SFX.get(MOON_LEVEL_ID, "ambience_enceladus")
        self._world_ambience_active = False
        self._drill_loop_active = False
        try:
            self._ensure_sfx_assets()
        except Exception as exc:
            print(f"Enceladus Ice SFX asset generation skipped: {exc}")
        if not self._sfx_is_available():
            return
        try:
            for name in self.sfx_base_volumes:
                sound = self.loader.loadSfx(panda_path(SFX_DIR / f"{name}.wav"))
                sound.setVolume(self.sfx_base_volumes[name])
                if name in ("drill_loop", "drill_deep_crack") or name.startswith("ambience_"):
                    sound.setLoop(True)
                self.sfx[name] = sound
            self._set_world_ambience(True)
        except Exception as exc:
            print(f"Enceladus Ice SFX disabled: {exc}")
            self.sfx = {}

    def _set_world_ambience(self, active: bool) -> None:
        if active == self._world_ambience_active:
            return
        self._world_ambience_active = active
        for name, sound in list(self.sfx.items()):
            if not name.startswith("ambience_"):
                continue
            try:
                if active and name == self.active_ambience_name:
                    sound.setVolume(self.sfx_base_volumes.get(name, 0.065))
                    sound.play()
                else:
                    sound.stop()
            except Exception:
                pass

    def _stop_all_sfx(self) -> None:
        self._world_ambience_active = False
        self._drill_loop_active = False
        for sound in list(getattr(self, "sfx", {}).values()):
            try:
                sound.stop()
            except Exception:
                pass

    def _play_sfx(self, name: str, volume_scale: float = 1.0) -> None:
        sound = self.sfx.get(name)
        if sound is None:
            return
        try:
            base_volume = self.sfx_base_volumes.get(name, 0.20)
            sound.setVolume(clamp(base_volume * volume_scale, 0.0, 1.0))
            if name != "drill_loop":
                sound.stop()
            sound.play()
        except Exception:
            pass

    def _set_drill_loop(self, active: bool) -> None:
        if active == self._drill_loop_active:
            return
        self._drill_loop_active = active
        for name in ("drill_loop", "drill_deep_crack"):
            sound = self.sfx.get(name)
            if sound is None:
                continue
            try:
                if active:
                    sound.setVolume(self.sfx_base_volumes.get(name, 0.14))
                    sound.play()
                else:
                    sound.stop()
            except Exception:
                pass

    def _configure_texture(self, tex, *, repeat: bool = True, clamp: bool = False):
        if tex is None:
            return None
        if repeat:
            tex.setWrapU(Texture.WM_repeat)
            tex.setWrapV(Texture.WM_repeat)
        if clamp:
            tex.setWrapU(Texture.WM_clamp)
            tex.setWrapV(Texture.WM_clamp)
        tex.setMinfilter(Texture.FT_linear_mipmap_linear)
        tex.setMagfilter(Texture.FT_linear)
        try:
            tex.setAnisotropicDegree(8)
        except Exception:
            pass
        return tex

    def _load_texture(self, path: Path, *, repeat: bool = True, clamp: bool = False):
        tex = self.loader.loadTexture(panda_path(path))
        return self._configure_texture(tex, repeat=repeat, clamp=clamp)

    def _apply_holoverse_surface(self, node: NodePath, *, tint: tuple[float, float, float] = (0.66, 0.92, 1.0), alpha: float = 1.0, emission: tuple[float, float, float] = (0.035, 0.09, 0.12), shininess: float = 22.0, tex_scale: tuple[float, float] = (1.0, 1.0), transparent: bool | None = None) -> None:
        if node is None or getattr(node, 'isEmpty', lambda: True)():
            return
        tex = self._load_texture(self.texture_paths["holo_tech"], repeat=True, clamp=False)
        node.setTexture(tex, 1)
        node.setTexScale(TextureStage.getDefault(), tex_scale[0], tex_scale[1])
        if transparent is None:
            transparent = alpha < 0.995
        visible_alpha = alpha if transparent else 1.0
        visible_r = min(0.42 + tint[0] * 0.72, 1.0)
        visible_g = min(0.42 + tint[1] * 0.72, 1.0)
        visible_b = min(0.42 + tint[2] * 0.72, 1.0)
        node.setColorScale(visible_r, visible_g, visible_b, visible_alpha)
        node.setColor(visible_r, visible_g, visible_b, visible_alpha, 1)
        if not transparent:
            node.setTextureOff(1)
        mat = Material()
        mat.setBaseColor((visible_r, visible_g, visible_b, 1.0))
        mat.setEmission((emission[0], emission[1], emission[2], 1.0))
        mat.setShininess(shininess)
        node.setMaterial(mat, 1)
        node.setLightOff(1)
        node.setFogOff(1)
        node.setShaderOff(1)
        if transparent:
            node.setTransparency(TransparencyAttrib.MAlpha)
        else:
            node.clearTransparency()

    def _attach_holoverse_trim_rings(self, parent: NodePath, name: str, radius: float, z_levels: list[float], *, color: tuple[float, float, float, float] = (0.26, 0.90, 1.0, 0.58), thickness: float = 1.4, y_scale: float = 1.0) -> NodePath:
        root = parent.attachNewNode(name)
        segs = LineSegs(name + '_lines')
        segs.setThickness(thickness)
        segs.setColor(*color)
        segments = 48
        for z in z_levels:
            for i in range(segments + 1):
                a = (i / segments) * math.tau
                x = math.cos(a) * radius
                y = math.sin(a) * radius * y_scale
                if i == 0:
                    segs.moveTo(x, y, z)
                else:
                    segs.drawTo(x, y, z)
        np = root.attachNewNode(segs.create())
        np.setTransparency(TransparencyAttrib.MAlpha)
        np.setDepthWrite(False)
        np.setDepthTest(False)
        np.setLightOff(1)
        np.setBin('transparent', 82)
        return root

    def _find_jupiter_media(self) -> Path | None:
        # Pass 24 intentionally uses the generated static Saturn texture.
        return None

    def _load_jupiter_media_texture(self):
        return None

    def _rig_hash01(self, ix: int, iy: int, salt: int = 0) -> float:
        return self.world._hash01(ix, iy, salt)

    def _water_height(self, x: float, y: float) -> float:
        return WATER_Z + math.sin(x * 0.0032 + y * 0.0017) * 1.1 + math.cos(y * 0.0036) * 0.8

    def _build_scanner_pip(self) -> None:
        # Pass30: the sonar is no longer an old conditional moon-HUD widget.
        # It is part of the shared Starfall planet UI so it remains readable on
        # Mimas, Enceladus, and Iapetus, including embedded Starfall launches.
        self.sonar_meter_root = self.aspect2d.attachNewNode("starfall_universal_sonar_meter")
        self.sonar_meter_root.setBin("fixed", 9095)
        self.sonar_meter_root.setDepthTest(False)
        self.sonar_meter_root.setDepthWrite(False)

        self.pip_root = self.aspect2d.attachNewNode("scanner_pip")
        self.pip_root.setPos(-1.010, 0.0, 0.802)
        self.pip_root.setScale(0.205)
        self.pip_root.setBin("fixed", 9095)
        self.sound_pip_np = self.pip_root.attachNewNode("sound_pip")
        self.heat_pip_np = self.pip_root.attachNewNode("heat_pip")
        self.bearing_pip_np = self.pip_root.attachNewNode("bearing_pip")

        self.sonar_title_text = OnscreenText(
            text="SONAR 000%",
            parent=self.aspect2d,
            pos=(-0.925, 0.842),
            scale=0.026,
            fg=(0.68, 0.96, 1.0, 0.84),
            align=TextNode.ALeft,
            mayChange=True,
        )
        self.sonar_trace_text = OnscreenText(
            text="SOUND 000% | MOVE 000%",
            parent=self.aspect2d,
            pos=(-0.925, 0.806),
            scale=0.021,
            fg=(0.78, 0.96, 1.0, 0.76),
            align=TextNode.ALeft,
            mayChange=True,
        )
        self.sonar_state_text = OnscreenText(
            text="SWEEP CROSSHAIR",
            parent=self.aspect2d,
            pos=(-0.925, 0.770),
            scale=0.020,
            fg=(1.0, 0.78, 0.36, 0.76),
            align=TextNode.ALeft,
            mayChange=True,
        )
        for node in (self.sonar_title_text, self.sonar_trace_text, self.sonar_state_text):
            node.setBin("fixed", 9096)
            node.setDepthTest(False)
            node.setDepthWrite(False)
        self.pip_root.show()
        self._rebuild_scanner_graphics(0.03, False, 0.0, 0.02, None, 0.0, False)
        self._update_universal_sonar_meter(0.0)

    def _rebuild_scanner_graphics(self, sound_signal: float, has_target: bool, time_value: float, movement_signal: float | None = None, bearing_angle: float | None = None, bearing_signal: float = 0.0, ready: bool = False) -> None:
        """Draw the two existing sonar waves.

        The cyan circular wave is the sound ping.  The orange plume wave is the
        movement/thermal trace.  Survey mode feeds them independently; depth
        fishing mode feeds both from the active rig signal.
        """
        movement_signal = sound_signal if movement_signal is None else movement_signal
        sound_signal = clamp(sound_signal, 0.0, 1.0)
        movement_signal = clamp(movement_signal, 0.0, 1.0)
        bearing_signal = clamp(bearing_signal, 0.0, 1.0)
        for node in (self.sound_pip_np, self.heat_pip_np, self.bearing_pip_np):
            node.node().removeAllChildren() if hasattr(node.node(), 'removeAllChildren') else None
            for child in node.getChildren():
                child.removeNode()

        sound = LineSegs("sound_pip_lines")
        sound.setThickness(2.0 + sound_signal * 0.8)
        sound.setColor(0.22 + sound_signal * 0.22, 0.82 + sound_signal * 0.16, 1.0, 0.42 + sound_signal * 0.52)
        ring_count = 4
        for ring_index in range(ring_count):
            phase = time_value * (1.25 + ring_index * 0.32 + sound_signal * 0.35) + ring_index * 0.73
            radius = 0.12 + ring_index * 0.11 + sound_signal * 0.10
            radius *= 0.75 + 0.25 * ((math.sin(phase) + 1.0) * 0.5)
            segments = 44
            for i in range(segments + 1):
                ang = (i / segments) * math.tau
                pulse = 1.0 + math.sin(ang * 3.0 + phase) * (0.035 + sound_signal * 0.075)
                x = math.cos(ang) * radius * pulse
                y = math.sin(ang) * radius * (0.72 + sound_signal * 0.18) * pulse
                if i == 0:
                    sound.moveTo(x, 0.0, y)
                else:
                    sound.drawTo(x, 0.0, y)
        sound_np = self.sound_pip_np.attachNewNode(sound.create())
        sound_np.setTransparency(TransparencyAttrib.MAlpha)
        sound_np.setDepthWrite(False)
        sound_np.setDepthTest(False)
        sound_np.setBin("fixed", 9096)
        sound_np.setLightOff(1)

        movement = LineSegs("movement_pip_lines")
        movement.setThickness(2.2 + movement_signal * 0.8)
        if has_target:
            movement.setColor(1.0, 0.48 + movement_signal * 0.28, 0.10 + movement_signal * 0.14, 0.38 + movement_signal * 0.58)
        else:
            movement.setColor(0.50, 0.22, 0.10, 0.20)
        plume_count = 3
        for plume in range(plume_count):
            offset_x = 0.34 + (plume - 1) * (0.14 + movement_signal * 0.06)
            segments = 28
            for i in range(segments + 1):
                t = i / segments
                y = -0.30 + t * 0.60
                amp = (0.014 + movement_signal * 0.075) * (1.0 - abs(y) * 0.75)
                wobble = math.sin(time_value * (2.0 + movement_signal * 1.4) + plume * 1.7 + t * 11.0) * amp
                skew = math.sin(time_value * 1.9 + plume * 0.9 + t * 6.0) * amp * 0.8
                x = offset_x + wobble + skew
                if i == 0:
                    movement.moveTo(x, 0.0, y)
                else:
                    movement.drawTo(x, 0.0, y)
        movement_np = self.heat_pip_np.attachNewNode(movement.create())
        movement_np.setTransparency(TransparencyAttrib.MAlpha)
        movement_np.setDepthWrite(False)
        movement_np.setDepthTest(False)
        movement_np.setBin("fixed", 9097)
        movement_np.setLightOff(1)

        if bearing_angle is not None and bearing_signal > 0.035:
            bearing = LineSegs("bearing_pip_lines")
            bearing.setThickness(2.3 + bearing_signal * 1.1)
            if ready:
                bearing.setColor(1.0, 0.82, 0.28, 0.64 + bearing_signal * 0.28)
            else:
                bearing.setColor(0.32, 0.88, 1.0, 0.28 + bearing_signal * 0.44)
            arc_radius = 0.50
            pointer_len = 0.16 + bearing_signal * 0.08
            cx = math.sin(bearing_angle) * arc_radius
            cy = math.cos(bearing_angle) * arc_radius
            bearing.moveTo(cx * 0.66, 0.0, cy * 0.66)
            bearing.drawTo(cx, 0.0, cy)
            # Small angled chevrons make the wide-return direction readable without
            # turning the sparse hotspots into obvious map markers.
            for side in (-1.0, 1.0):
                wing_ang = bearing_angle + side * 0.48
                wx = cx - math.sin(wing_ang) * pointer_len
                wy = cy - math.cos(wing_ang) * pointer_len
                bearing.moveTo(cx, 0.0, cy)
                bearing.drawTo(wx, 0.0, wy)
            bearing_np = self.bearing_pip_np.attachNewNode(bearing.create())
            bearing_np.setTransparency(TransparencyAttrib.MAlpha)
            bearing_np.setDepthWrite(False)
            bearing_np.setDepthTest(False)
            bearing_np.setBin("fixed", 9098)
            bearing_np.setLightOff(1)

    def _update_universal_sonar_meter(self, time_value: float = 0.0) -> None:
        sonar = getattr(self, "current_sonar", {}) or {}
        signal = clamp(float(sonar.get("signal", 0.0)), 0.0, 1.0)
        sound = clamp(float(sonar.get("sound", signal * 0.55)), 0.0, 1.0)
        movement = clamp(float(sonar.get("movement", signal * 0.35)), 0.0, 1.0)
        bearing_signal = clamp(float(sonar.get("bearing_signal", 0.0)), 0.0, 1.0)
        ready = bool(sonar.get("ready", False))
        detected = bool(sonar.get("detected", False))
        display_signal = clamp(max(signal, bearing_signal * 0.72, sound * 0.60, movement * 0.60), 0.0, 1.0)

        if ready:
            state = "LOCK READY - DRILL"
            title_fg = (1.0, 0.86, 0.36, 0.94)
            state_fg = (1.0, 0.78, 0.30, 0.94)
        elif signal >= SIGNAL_CATCH_THRESHOLD:
            state = "LOCKED RESOURCE RETURN"
            title_fg = (0.92, 1.0, 0.74, 0.92)
            state_fg = (0.92, 1.0, 0.74, 0.90)
        elif signal > 0.18 or detected:
            state = "TRACE - ALIGN DRONE"
            title_fg = (0.68, 0.96, 1.0, 0.88)
            state_fg = (0.72, 0.96, 1.0, 0.84)
        elif bearing_signal > 0.06:
            state = "WIDE PING - SWEEP"
            title_fg = (0.60, 0.90, 1.0, 0.80)
            state_fg = (0.72, 0.92, 1.0, 0.78)
        else:
            state = "SWEEP CROSSHAIR"
            title_fg = (0.48, 0.76, 0.88, 0.68)
            state_fg = (0.82, 0.86, 0.74, 0.64)

        root = getattr(self, "sonar_meter_root", None)
        if root is not None and hasattr(root, "show"):
            root.show()
        if hasattr(self, "pip_root") and self.pip_root is not None:
            try:
                self.pip_root.show()
            except Exception:
                pass
        if hasattr(self, "sonar_title_text"):
            self.sonar_title_text.setText(f"SONAR {display_signal*100:03.0f}%")
            self.sonar_title_text.setFg(title_fg)
        if hasattr(self, "sonar_trace_text"):
            self.sonar_trace_text.setText(f"SOUND {sound*100:03.0f}% | MOVE {movement*100:03.0f}%")
            self.sonar_trace_text.setFg((0.78, 0.96, 1.0, 0.72 + display_signal * 0.18))
        if hasattr(self, "sonar_state_text"):
            self.sonar_state_text.setText(state)
            self.sonar_state_text.setFg(state_fg)

    def _spawn_hole_cracks(self, hole: Hole) -> None:
        branch_count = 7 + int(self._rig_hash01(int(hole.x // 50), int(hole.y // 50), 81) * 4)
        branches = []
        for branch_index in range(branch_count):
            angle = (branch_index / branch_count) * math.tau + self._rig_hash01(int(hole.x // 40), int(hole.y // 40), 90 + branch_index) * 0.6
            px = hole.x + math.cos(angle) * (hole.radius * 0.9)
            py = hole.y + math.sin(angle) * (hole.radius * 0.9)
            points = [(px, py)]
            direction = angle
            segment_count = 3 + (branch_index % 3)
            for seg in range(segment_count):
                seg_len = 24.0 + self._rig_hash01(int(hole.x // 30) + branch_index, int(hole.y // 30) + seg, 120 + seg) * 58.0
                direction += (self._rig_hash01(int(px // 20) + seg, int(py // 20) + branch_index, 140 + seg) - 0.5) * 0.95
                px += math.cos(direction) * seg_len
                py += math.sin(direction) * seg_len
                points.append((px, py))
                if seg < segment_count - 1 and self._rig_hash01(int(px // 35), int(py // 35), 170 + seg) > 0.72:
                    bdir = direction + (0.65 if seg % 2 == 0 else -0.65)
                    bx = px + math.cos(bdir) * (seg_len * 0.42)
                    by = py + math.sin(bdir) * (seg_len * 0.42)
                    points.append((bx, by))
            branches.append(points)
        effect = {"hole": hole, "branches": branches, "grow": 0.0, "node": self.hole_root.attachNewNode(f"cracks_{len(self.crack_effects)}")}
        self.crack_effects.append(effect)

    def _rebuild_crack_effect(self, effect: dict[str, object]) -> None:
        node = effect["node"]
        for child in node.getChildren():
            child.removeNode()
        segs = LineSegs("hole_cracks")
        segs.setThickness(2.4)
        segs.setColor(0.90, 0.96, 1.0, 0.92)
        grow = float(effect["grow"])
        for points in effect["branches"]:
            total_segments = max(len(points) - 1, 1)
            progress = grow * total_segments
            completed = int(progress)
            frac = progress - completed
            start_x, start_y = points[0]
            start_z = self.world.surface_height(start_x, start_y) + 0.48
            segs.moveTo(start_x, start_y, start_z)
            for idx in range(total_segments):
                x0, y0 = points[idx]
                x1, y1 = points[idx + 1]
                if idx < completed:
                    z1 = self.world.surface_height(x1, y1) + 0.48
                    segs.drawTo(x1, y1, z1)
                elif idx == completed and frac > 0.0:
                    xi = x0 + (x1 - x0) * frac
                    yi = y0 + (y1 - y0) * frac
                    zi = self.world.surface_height(xi, yi) + 0.48
                    segs.drawTo(xi, yi, zi)
                    break
                else:
                    break
        crack_np = node.attachNewNode(segs.create())
        crack_np.setDepthWrite(True)
        crack_np.setDepthTest(True)
        crack_np.setLightOff(1)

    def _adopt_embedded_parent(self, parent) -> None:
        """Run the moon operation inside Starfall's existing ShowBase.

        Starfall already owns Panda3D's ShowBase.  Creating another ShowBase here
        crashes with "Attempt to spawn multiple ShowBase instances".  In embedded
        mode, copy the parent runtime handles and isolate all world/UI nodes under
        removable operation roots.
        """
        self.embedded_parent = parent
        self.embedded_operation = True
        self.taskMgr = parent.taskMgr
        self.loader = parent.loader
        self.win = parent.win
        self.graphicsEngine = parent.graphicsEngine
        self.globalClock = getattr(parent, "globalClock", ClockObject.getGlobalClock())
        self.mouseWatcherNode = parent.mouseWatcherNode
        self.render2d = getattr(parent, "render2d", None)
        self.pixel2d = getattr(parent, "pixel2d", None)
        self.pipe = getattr(parent, "pipe", None)
        self.operation_render_root = parent.render.attachNewNode(f"embedded_world_operation_render_{MOON_LEVEL_ID}")
        self.operation_ui_root = parent.aspect2d.attachNewNode(f"embedded_world_operation_ui_{MOON_LEVEL_ID}")
        self.render = self.operation_render_root
        self.aspect2d = self.operation_ui_root
        # Pass108: embedded worlds render through the ship's dedicated 16:9
        # remote-drone camera. The shell camera stays aboard and never reparents
        # into the planetary scene.
        feed_factory = getattr(parent, "_create_operation_feed_camera", None)
        if callable(feed_factory):
            self.camera = feed_factory(self.operation_render_root)
            self.cam = self.camera
            self.camNode = self.camera.node()
            self.camLens = self.camNode.getLens()
        else:
            self.camera = parent.camera
            self.cam = getattr(parent, "cam", None)
            self.camNode = getattr(parent, "camNode", None)
            self.camLens = parent.camLens
        for name in (
            "a2dTopLeft", "a2dTopCenter", "a2dTopRight",
            "a2dLeftCenter", "a2dRightCenter",
            "a2dBottomLeft", "a2dBottomCenter", "a2dBottomRight",
        ):
            if hasattr(parent, name):
                setattr(self, name, getattr(parent, name))
        self.disableMouse = lambda *args, **kwargs: None

    def _operation_task_names(self) -> tuple[str, ...]:
        return (
            "update_camera", "update_environment_lighting", "update_sky", "animate_surface",
            "animate_dynamic_plumes", "animate_rigs", "animate_drone_dispatch", "animate_support_rover",
            "update_remote_signal_and_rescue", "animate_rover_transfer", "animate_drilling", "animate_cracks", "update_scanner_pip",
            "update_status_panel", "runtime_sanity_checks", "update_build_preview", "update_base_power_system",
            "animate_falling_hazards", "fade_out_boot_loading_screen", "restore_center_mouse_after_menu",
            "test_shot", "drill_regression_test", "finish_drill_regression_test",
            "universal_ui_self_test", "drone_camera_runtime_test", "jupiter_spatial_runtime_test",
        )

    def embedded_ui_is_hidden(self) -> bool:
        # Embedded Starfall keeps the operation UI root alive so ESC can show a
        # return/settings panel. The Starfall shell owns all normal telemetry
        # and HUD chrome while a remote feed is active.
        leaked_names = (
            "status_back_frame", "resource_back_frame", "status_title", "status_text",
            "depth_text", "catch_text", "toast_text", "crosshair_text",
            "sonar_meter_root", "pip_root", "sonar_title_text", "sonar_trace_text",
            "sonar_state_text", "planet_vision_overlay_root", "access_text",
            "flight_drone_stats_text", "universal_access_title",
            "universal_access_summary_text",
        )
        for name in leaked_names:
            node = getattr(self, name, None)
            try:
                if node is not None and hasattr(node, "isHidden") and not node.isHidden():
                    return False
            except Exception:
                pass
        for btn in getattr(self, "universal_access_buttons", []) or []:
            try:
                if btn is not None and hasattr(btn, "isHidden") and not btn.isHidden():
                    return False
            except Exception:
                pass
        options_frame = getattr(self, "options_frame", None)
        try:
            if options_frame is not None and hasattr(options_frame, "isHidden") and not options_frame.isHidden():
                return bool(getattr(self, "options_visible", False))
        except Exception:
            pass
        return True

    def _hide_embedded_moon_hud(self) -> None:
        # The Starfall shell is the sole telemetry owner in embedded mode.
        # Keep the operation UI root alive for ESC/options, but suppress every
        # normal planet-local HUD layer that shares the shell's aspect2d.
        for name in (
            "status_back_frame", "resource_back_frame", "status_title",
            "status_text", "depth_text", "catch_text", "toast_text",
            "crosshair_text", "sonar_meter_root", "pip_root",
            "sonar_title_text", "sonar_trace_text", "sonar_state_text",
            "planet_vision_overlay_root", "access_text", "flight_drone_stats_text",
            "universal_access_title", "universal_access_summary_text",
        ):
            node = getattr(self, name, None)
            try:
                if node is not None and hasattr(node, "hide"):
                    node.hide()
            except Exception:
                pass
        for btn in getattr(self, "universal_access_buttons", []) or []:
            try:
                if btn is not None and hasattr(btn, "hide"):
                    btn.hide()
            except Exception:
                pass

    def shutdown_embedded_operation(self) -> None:
        # The shared ShowBase camera must never be removed with the embedded
        # operation root. The shell normally reclaims it first, but keep this
        # lifecycle guard here as a second line of defense.
        try:
            parent = getattr(self, "embedded_parent", None)
            operation_root = getattr(self, "operation_render_root", None)
            if (
                parent is not None
                and operation_root is not None
                and not operation_root.isEmpty()
                and self.camera is not None
                and not self.camera.isEmpty()
                and self.camera.getParent() == operation_root
                and self.camera == getattr(parent, "camera", None)
            ):
                self.camera.wrtReparentTo(parent.render)
        except Exception:
            pass
        try:
            self._stop_all_sfx()
        except Exception:
            pass
        filters = getattr(self, "filters", None)
        if filters is not None:
            try:
                filters.cleanup()
            except Exception:
                pass
            self.filters = None
        for task_name in self._operation_task_names():
            try:
                self.taskMgr.remove(task_name)
            except Exception:
                pass
        try:
            self.ignoreAll()
        except Exception:
            pass
        for attr in (
            "operation_ui_root", "operation_render_root", "boot_loading_root", "pip_root", "sonar_meter_root",
            "status_frame", "resource_frame", "upgrade_frame", "options_frame", "help_frame",
        ):
            node = getattr(self, attr, None)
            try:
                if node is not None and hasattr(node, "removeNode") and not node.isEmpty():
                    node.removeNode()
            except Exception:
                pass
        self.remote_drones.clear()
        self.remote_drone_velocity.clear()
        self.flight_drone_dock_links_root = None
        self.support_rover = None
        self.persistent_drill_drone = None
        self.operation_ui_root = None
        self.operation_render_root = None
        self.embedded_parent = None
        self.embedded_operation = False
        global EMBEDDED_INSTANCE
        if EMBEDDED_INSTANCE is self:
            EMBEDDED_INSTANCE = None

