    def _build_atmospheric_fx_layers(self, mist_texture) -> None:
        old = getattr(self, "atmospheric_fx_root", None)
        if old is not None and hasattr(old, "removeNode"):
            old.removeNode()
        self.atmospheric_fx_root = self.sky_anchor.attachNewNode("atmospheric_fx_authority_root")
        self.atmospheric_fx_layers = []
        for index, spec in enumerate(self._atmospheric_layer_specs()[:ATMOSPHERIC_FX_MAX_LAYERS]):
            cm = CardMaker(f"atmospheric_fx_{MOON_LEVEL_ID}_{index}_{spec['name']}")
            cm.setFrame(-1.0, 1.0, -0.22, 0.22)
            band = NodePath(cm.generate())
            band.reparentTo(self.atmospheric_fx_root)
            band.setScale(float(spec["width"]), 1.0, float(spec["height"]))
            band.setPos(spec["pos"])
            band.setBillboardPointEye()
            band.setTwoSided(True)
            band.setLightOff(1)
            band.setFogOff(1)
            band.setShaderOff(1)
            band.setBin("background", 4)
            band.setDepthWrite(False)
            band.setTransparency(TransparencyAttrib.MAlpha)
            band.setTexture(mist_texture)
            band.setColorScale(*spec["color"])
            self._pin_no_cull(band)
            self.atmospheric_fx_layers.append({"node": band, **spec})
        self.atmospheric_profile_line = f"ATMOS: {MOON_THEME['display_name']} // {ACTIVE_ATMOSPHERIC_FX_PROFILE['palette']}"

    def _make_uv_sphere(
        self,
        name: str,
        radius: float,
        lat_segments: int = 24,
        lon_segments: int = 48,
        texture: Path | None = None,
        color: tuple[float, float, float, float] = (1.0, 1.0, 1.0, 1.0),
    ) -> NodePath:
        fmt = GeomVertexFormat.getV3n3t2()
        vdata = GeomVertexData(name, fmt, Geom.UHStatic)
        vertex = GeomVertexWriter(vdata, "vertex")
        normal = GeomVertexWriter(vdata, "normal")
        texcoord = GeomVertexWriter(vdata, "texcoord")

        for iy in range(lat_segments + 1):
            v = iy / float(lat_segments)
            theta = v * math.pi
            st = math.sin(theta)
            ct = math.cos(theta)
            for ix in range(lon_segments + 1):
                u = ix / float(lon_segments)
                phi = u * math.tau
                sp = math.sin(phi)
                cp = math.cos(phi)
                nx = cp * st
                ny = sp * st
                nz = ct
                vertex.addData3f(nx * radius, ny * radius, nz * radius)
                normal.addData3f(nx, ny, nz)
                texcoord.addData2f(1.0 - u, 1.0 - v)

        tris = GeomTriangles(Geom.UHStatic)
        stride = lon_segments + 1
        for iy in range(lat_segments):
            for ix in range(lon_segments):
                a = iy * stride + ix
                b = a + 1
                c = a + stride
                d = c + 1
                tris.addVertices(a, c, b)
                tris.addVertices(b, c, d)

        geom = Geom(vdata)
        geom.addPrimitive(tris)
        node = GeomNode(name)
        node.addGeom(geom)
        np = NodePath(node)
        np.setTwoSided(True)
        np.setFogOff(1)
        np.setColorScale(*color)
        if texture is not None:
            np.setTexture(self._load_texture(texture, repeat=False, clamp=True))
        self._pin_no_cull(np)
        return np


    def _make_annulus_band(self, name: str, inner_radius: float, outer_radius: float, inner_color: tuple[float, float, float, float], outer_color: tuple[float, float, float, float], segments: int = 160) -> NodePath:
        vformat = GeomVertexFormat.getV3n3c4()
        vdata = GeomVertexData(name, vformat, Geom.UHStatic)
        vertex = GeomVertexWriter(vdata, "vertex")
        normal = GeomVertexWriter(vdata, "normal")
        color = GeomVertexWriter(vdata, "color")

        for i in range(segments + 1):
            ang = (i / float(segments)) * math.tau
            ca = math.cos(ang)
            sa = math.sin(ang)
            for radius, rgba in ((inner_radius, inner_color), (outer_radius, outer_color)):
                vertex.addData3f(ca * radius, sa * radius, 0.0)
                normal.addData3f(0.0, 0.0, 1.0)
                color.addData4f(*rgba)

        tris = GeomTriangles(Geom.UHStatic)
        for i in range(segments):
            idx = i * 2
            tris.addVertices(idx, idx + 1, idx + 3)
            tris.addVertices(idx, idx + 3, idx + 2)

        geom = Geom(vdata)
        geom.addPrimitive(tris)
        node = GeomNode(name)
        node.addGeom(geom)
        np = NodePath(node)
        np.setTransparency(TransparencyAttrib.MAlpha)
        np.setTwoSided(True)
        np.setDepthWrite(False)
        np.setFogOff(1)
        np.setBin("background", 1)
        self._pin_no_cull(np)
        return np

    def _build_saturn_system(self) -> NodePath:
        root = self.sky_anchor.attachNewNode("saturn_system")
        root.setPos(self.jupiter_center)
        root.setHpr(-12.0, 0.0, 0.0)
        if IS_IAPETUS_LEVEL:
            root.setScale(IAPETUS_SATURN_SCALE)
        elif IS_TITAN_LEVEL:
            root.setScale(0.024)

        # Root origin is now the exact snap/pivot point: the center of Saturn's
        # sphere and the exact center of the ring system.
        ring_hpr = Vec3(24.0, 60.0, -8.0)
        # Pass 59 fix: Saturn must use the exact same axis basis as the rings.
        # Create a shared tilted axis node and parent both the planet body and
        # ring system to it so the banding and ring plane live in the same frame.
        saturn_axis = root.attachNewNode("saturn_shared_axis")
        saturn_axis.setHpr(ring_hpr)
        self.saturn_shared_axis = saturn_axis
        planet = self._make_uv_sphere(
            "saturn_sphere_centered",
            radius=3460.0,
            lat_segments=84,
            lon_segments=168,
            texture=self.texture_paths["saturn_body"],
            color=(1.0, 1.0, 1.0, 1.0),
        )
        planet.reparentTo(saturn_axis)
        planet.setPos(0.0, 0.0, -420.0)
        planet.setHpr(0.0, 0.0, 0.0)
        planet.setBin("background", 5)
        planet.clearTransparency()
        planet.setDepthWrite(True)
        planet.setDepthTest(True)
        saturn_material = Material()
        saturn_material.setAmbient((0.50, 0.46, 0.39, 1.0))
        saturn_material.setDiffuse((1.02, 0.95, 0.82, 1.0))
        saturn_material.setEmission((0.010, 0.009, 0.008, 1.0))
        saturn_material.setSpecular((0.16, 0.14, 0.10, 1.0))
        saturn_material.setShininess(5.0)
        planet.setMaterial(saturn_material, 1)
        if IS_TITAN_LEVEL:
            planet.setColorScale(1.10, 0.58, 0.24, 0.055)
            planet.setTransparency(TransparencyAttrib.MAlpha)
        self.jupiter_planet = planet

        ring_group = saturn_axis.attachNewNode("saturn_ring_group")
        ring_group.setHpr(0.0, 0.0, 0.0)
        ring_back_root = ring_group.attachNewNode("saturn_ring_back")
        ring_front_root = ring_group.attachNewNode("saturn_ring_front")

        back_bands = [
            # Leave a much cleaner gap around Saturn itself so the inner translucent rings
            # do not wash over the planet from Enceladus' viewpoint.
            (9800.0, 16680.0, (0.82, 0.68, 0.50, 0.24), (0.60, 0.46, 0.32, 0.16)),
            (15100.0, 27350.0, (0.76, 0.62, 0.46, 0.26), (0.56, 0.44, 0.32, 0.16)),
            (26500.0, 32950.0, (0.70, 0.58, 0.44, 0.15), (0.52, 0.44, 0.34, 0.09)),
            (33800.0, 38800.0, (0.62, 0.54, 0.46, 0.07), (0.48, 0.42, 0.38, 0.035)),
        ]
        front_bands = [
            (15250.0, 27350.0, (0.80, 0.66, 0.50, 0.14), (0.60, 0.48, 0.36, 0.085)),
            (27400.0, 32950.0, (0.72, 0.60, 0.46, 0.08), (0.54, 0.44, 0.34, 0.04)),
        ]
        self.saturn_ring_bands = []
        for idx, (inner_r, outer_r, inner_c, outer_c) in enumerate(back_bands):
            band = self._make_annulus_band(f"saturn_ring_back_{idx}", inner_r, outer_r, inner_c, outer_c, segments=240)
            band.reparentTo(ring_back_root)
            band.setBin("background", 1)
            band.setZ(idx * 0.6)
            self.saturn_ring_bands.append(band)
        dust = self._make_annulus_band("saturn_ring_dust", 33350.0, 36850.0, (0.62, 0.54, 0.46, 0.030), (0.46, 0.40, 0.36, 0.012), segments=260)
        dust.reparentTo(ring_back_root)
        dust.setBin("background", 1)
        dust.setZ(3.8)
        self.saturn_ring_bands.append(dust)

        for idx, (inner_r, outer_r, inner_c, outer_c) in enumerate(front_bands):
            band = self._make_annulus_band(f"saturn_ring_front_{idx}", inner_r, outer_r, inner_c, outer_c, segments=240)
            band.reparentTo(ring_front_root)
            band.setBin("background", 3)
            band.setZ(40.0 + idx * 2.0)
            self.saturn_ring_bands.append(band)

        shadow = self._make_annulus_band("saturn_ring_shadow", 9200.0, 14400.0, (0.0, 0.0, 0.0, 0.035), (0.0, 0.0, 0.0, 0.008), segments=160)
        shadow.reparentTo(ring_back_root)
        shadow.setBin("background", 1)
        shadow.setH(180.0)
        shadow.setZ(-1.2)
        self.saturn_ring_bands.append(shadow)

        self._pin_no_cull(ring_group)
        if IS_TITAN_LEVEL:
            ring_group.setColorScale(1.0, 0.50, 0.22, 0.0)
            ring_group.hide()
        self.jupiter_rings = ring_group
        self._pin_no_cull(root)
        return root

    def _build_neptune_system(self) -> NodePath:
        root = self.sky_anchor.attachNewNode("neptune_system")
        root.setPos(self.jupiter_center)
        axis = root.attachNewNode("neptune_axis")
        axis.setHpr(-8.0, 14.0, -3.0)
        planet = self._make_uv_sphere(
            "neptune_sphere",
            radius=3420.0,
            lat_segments=84,
            lon_segments=168,
            texture=self.texture_paths["neptune"],
            color=(0.88, 0.94, 1.0, 1.0),
        )
        planet.reparentTo(axis)
        planet.setScale(1.04, 1.0, 1.0)
        planet.setBin("background", 5)
        planet.setDepthWrite(True)
        planet.setDepthTest(True)
        mat = Material()
        mat.setAmbient((0.24, 0.36, 0.66, 1.0))
        mat.setDiffuse((0.50, 0.70, 1.08, 1.0))
        mat.setEmission((0.010, 0.020, 0.044, 1.0))
        mat.setSpecular((0.12, 0.18, 0.26, 1.0))
        mat.setShininess(6.0)
        planet.setMaterial(mat, 1)
        cloud = self._make_uv_sphere(
            "neptune_cloud_shell",
            radius=3490.0,
            lat_segments=70,
            lon_segments=140,
            texture=self.texture_paths["neptune"],
            color=(0.82, 0.94, 1.0, 0.18),
        )
        cloud.reparentTo(axis)
        cloud.setTransparency(TransparencyAttrib.MAlpha)
        cloud.setDepthWrite(False)
        cloud.setDepthTest(True)
        cloud.setBin("background", 6)
        cloud.setColorScale(0.78, 0.90, 1.0, 0.11)
        self.neptune_planet = planet
        self.neptune_cloud_shell = cloud
        self.jupiter_planet = None
        self.jupiter_cloud_shell = None
        self.jupiter_rings = None
        self._pin_no_cull(root)
        return root

    def _build_jupiter_system(self) -> NodePath:
        # Pass95 spatial authority: Europa's Jupiter is no longer a direct child of
        # the exact camera-follow sky anchor.  A dedicated celestial anchor follows
        # only part of camera translation, preserving a stable sky body while adding
        # enough directional parallax to stop the globe feeling HUD-locked.
        if IS_EUROPA_LEVEL:
            self.jupiter_celestial_anchor = self.render.attachNewNode("jupiter_celestial_anchor")
            root = self.jupiter_celestial_anchor.attachNewNode("jupiter_system")
        else:
            self.jupiter_celestial_anchor = None
            root = self.sky_anchor.attachNewNode("jupiter_system")
        root.setPos(self.jupiter_center)
        root.setHpr(-8.0, 0.0, 0.0)
        axis = root.attachNewNode("jupiter_axis")
        axis.setHpr(10.0, 18.0, -4.0)
        planet_radius = 3560.0 if IS_EUROPA_LEVEL else 2980.0
        cloud_radius = planet_radius + (18.0 if IS_EUROPA_LEVEL else 70.0)
        planet = self._make_uv_sphere(
            "jupiter_sphere",
            radius=planet_radius,
            lat_segments=84,
            lon_segments=168,
            texture=self.texture_paths["jupiter"],
            color=(1.0, 1.0, 1.0, 1.0),
        )
        planet.reparentTo(axis)
        # Jupiter is an oblate spheroid: both equatorial axes remain broader than
        # the polar axis.  Pass93 stretched one axis only, which read like a flat oval.
        planet.setScale((1.07 if IS_EUROPA_LEVEL else 1.10), (1.07 if IS_EUROPA_LEVEL else 0.98), (0.98 if IS_EUROPA_LEVEL else 0.98))
        planet.setBin("background", 5)
        planet.clearTransparency()
        planet.setDepthWrite(True)
        planet.setDepthTest(True)
        mat = Material()
        mat.setAmbient((0.56, 0.48, 0.40, 1.0))
        mat.setDiffuse((1.16, 1.06, 0.96, 1.0) if IS_EUROPA_LEVEL else (1.10, 1.02, 0.94, 1.0))
        mat.setEmission((0.014, 0.011, 0.010, 1.0) if IS_EUROPA_LEVEL else (0.012, 0.010, 0.009, 1.0))
        mat.setSpecular((0.20, 0.18, 0.16, 1.0))
        mat.setShininess(8.0)
        planet.setMaterial(mat, 1)
        self.jupiter_planet = planet

        cloud = self._make_uv_sphere(
            "jupiter_cloud_shell",
            radius=cloud_radius,
            lat_segments=72,
            lon_segments=144,
            texture=self.texture_paths["jupiter"],
            color=(1.0, 1.0, 1.0, 0.24 if IS_EUROPA_LEVEL else 0.16),
        )
        cloud.reparentTo(axis)
        cloud.setScale((1.181 if IS_EUROPA_LEVEL else 1.106), (0.981 if IS_EUROPA_LEVEL else 0.985), (0.981 if IS_EUROPA_LEVEL else 0.985))
        cloud.setTransparency(TransparencyAttrib.MAlpha)
        cloud.setDepthWrite(False)
        cloud.setDepthTest(True)
        cloud.setBin("background", 6)
        cloud.setColorScale((1.10, 1.00, 0.97, 0.26) if IS_EUROPA_LEVEL else (1.0, 0.98, 0.96, 0.18))
        self.jupiter_cloud_shell = cloud

        # Pass93 final authority: every animated Jupiter frame is a complete
        # equirectangular wrap.  The original planet sphere owns the presentation;
        # no billboard, extra FX sphere, or fixed-function multitexture layer is used.
        self.jupiter_shadow_card = None
        self.jupiter_storm_glow = None
        self.jupiter_storm_core = None
        self.jupiter_storm_arcs = []
        self.jupiter_shadow_shell = None
        self.jupiter_storm_shell = None
        self.jupiter_storm_stage = None
        self.jupiter_shadow_stage = None
        self.jupiter_storm_textures = []
        self.jupiter_wrapped_textures = []
        self.jupiter_storm_frame_index = -1
        if IS_EUROPA_LEVEL:
            self.jupiter_wrapped_textures = [
                self._load_texture(self.texture_paths[f"jupiter_wrap_frame_{idx}"], repeat=False, clamp=True)
                for idx in range(8)
            ]
            planet.setTexture(self.jupiter_wrapped_textures[0], 1)
            self.jupiter_storm_frame_index = 0
            # The old duplicate cloud sphere would reintroduce an unshadowed copy of
            # the base bands over the wrapped terminator, so Europa hides it.
            cloud.hide()
        self.jupiter_rings = None
        self._pin_no_cull(root)
        return root

    def _make_billboard(self, texture: Path, scale: float, pos: Vec3, color: tuple[float, float, float, float], alpha: bool) -> NodePath:
        cm = CardMaker(texture.stem)
        cm.setFrame(-0.5, 0.5, -0.5, 0.5)
        card = NodePath(cm.generate())
        card.setScale(scale)
        card.setPos(pos)
        card.setBillboardPointEye()
        card.setLightOff(1)
        card.setFogOff(1)
        card.setShaderOff(1)
        card.setTexture(self._load_texture(texture, repeat=False, clamp=True))
        card.setColorScale(*color)
        if alpha:
            card.setTransparency(TransparencyAttrib.MAlpha)
        self._pin_no_cull(card)
        return card

    def _setup_lights(self) -> None:
        # Low ambient + a hard directional key gives Enceladus a bright but unforgiving
        # far-Saturn solar look.  Shadows are enabled where Panda3D/shader support is
        # available, while the color fallback still creates strong terminator contrast.
        enable_shader_shadows = ("--enable-shadows" in sys.argv) and not self.is_offscreen
        if enable_shader_shadows:
            self.render.setShaderAuto()

        ambient = AmbientLight("terminator_ambient")
        if IS_IAPETUS_LEVEL:
            ambient.setColor((0.020, 0.020, 0.024, 1.0))
        elif IS_TITAN_LEVEL:
            ambient.setColor((0.54, 0.24, 0.070, 1.0))
        elif IS_MARS_LEVEL:
            ambient.setColor((0.22, 0.11, 0.060, 1.0))
        elif IS_TRITON_LEVEL:
            ambient.setColor((0.045, 0.075, 0.145, 1.0))
        elif IS_PLUTO_LEVEL:
            ambient.setColor((0.026, 0.029, 0.040, 1.0))
        else:
            ambient.setColor((0.070, 0.078, 0.105, 1.0))
        self.ambient_light = ambient
        self.ambient_np = self.render.attachNewNode(ambient)
        self.render.setLight(self.ambient_np)

        sun = DirectionalLight("distant_saturn_sun")
        if IS_IAPETUS_LEVEL:
            sun.setColor((1.38, 1.34, 1.14, 1.0))
        elif IS_TITAN_LEVEL:
            sun.setColor((2.45, 1.38, 0.45, 1.0))
        elif IS_MARS_LEVEL:
            sun.setColor((2.85, 2.42, 2.00, 1.0))
        elif IS_TRITON_LEVEL:
            sun.setColor((1.18, 1.28, 1.48, 1.0))
        elif IS_PLUTO_LEVEL:
            sun.setColor((0.84, 0.90, 1.00, 1.0))
        else:
            sun.setColor((2.35, 2.22, 1.92, 1.0))
        try:
            sun.setShadowCaster(True, 2048, 2048)
            sun.getLens().setFilmSize(11800, 11800)
            sun.getLens().setNearFar(80, 26000)
        except Exception:
            pass
        self.sun_light = sun
        self.sun_np = self.render.attachNewNode(sun)
        self.sun_np.setPos(*IAPETUS_SUN_POS) if IS_IAPETUS_LEVEL else (self.sun_np.setPos(-9400.0, 20600.0, 5200.0) if IS_TITAN_LEVEL else (self.sun_np.setPos(9200.0, 18400.0, 5400.0) if IS_MARS_LEVEL else (self.sun_np.setPos(-24800.0, -45200.0, 13800.0) if IS_TRITON_LEVEL else (self.sun_np.setPos(-21400.0, -40200.0, 13200.0) if IS_PLUTO_LEVEL else self.sun_np.setPos(-16800.0, -31400.0, 10400.0)))))
        self.sun_np.lookAt(Point3(0.0, 0.0, 0.0))
        self.render.setLight(self.sun_np)
        self.solar_key_vector = Vec3(-IAPETUS_SUN_POS[0], -IAPETUS_SUN_POS[1], -IAPETUS_SUN_POS[2]) if IS_IAPETUS_LEVEL else (Vec3(24800.0, 45200.0, -13800.0) if IS_TRITON_LEVEL else (Vec3(-9200.0, -18400.0, -5400.0) if IS_MARS_LEVEL else Vec3(16800.0, 31400.0, -10400.0)))
        self.solar_key_vector.normalize()

        fill = DirectionalLight("saturn_ring_fill")
        if IS_IAPETUS_LEVEL:
            fill.setColor((0.008, 0.014, 0.026, 1.0))
        elif IS_MARS_LEVEL:
            fill.setColor((0.080, 0.040, 0.024, 1.0))
        elif IS_TRITON_LEVEL:
            fill.setColor((0.020, 0.060, 0.150, 1.0))
        else:
            fill.setColor((0.015, 0.032, 0.070, 1.0))
        self.fill_light = fill
        self.fill_np = self.render.attachNewNode(fill)
        self.fill_np.setHpr(-122, -10, 0)
        self.render.setLight(self.fill_np)

        rim = DirectionalLight("cold_rim")
        if IS_IAPETUS_LEVEL:
            rim.setColor((0.015, 0.024, 0.042, 1.0))
        elif IS_MARS_LEVEL:
            rim.setColor((0.14, 0.07, 0.034, 1.0))
        elif IS_TRITON_LEVEL:
            rim.setColor((0.040, 0.095, 0.210, 1.0))
        else:
            rim.setColor((0.030, 0.050, 0.090, 1.0))
        self.rim_light = rim
        self.rim_np = self.render.attachNewNode(rim)
        self.rim_np.setHpr(170, -14, 0)
        self.render.setLight(self.rim_np)

        self.current_dark_side_factor = 0.0

    def _build_dark_side_zone(self) -> None:
        """Build a reachable, terrain-conforming far-side shadow field."""
        old_root = getattr(self, "dark_side_root", None)
        if old_root is not None and not old_root.isEmpty():
            old_root.removeNode()
        self.dark_side_root = self.render.attachNewNode("reachable_dark_side_terminator")

        fmt = GeomVertexFormat.getV3n3c4()
        vdata = GeomVertexData("dark_side_shadow_mesh", fmt, Geom.UHStatic)
        vwriter = GeomVertexWriter(vdata, "vertex")
        nwriter = GeomVertexWriter(vdata, "normal")
        cwriter = GeomVertexWriter(vdata, "color")
        rings = 12
        segments = 84
        for ring in range(rings + 1):
            rr = ring / rings
            radius = DARK_SIDE_OUTER_RADIUS * (rr ** 0.82)
            for seg in range(segments):
                a = seg / segments * math.tau
                wobble = 1.0 + 0.08 * math.sin(a * 3.0 + 0.7) + 0.035 * math.sin(a * 7.0 + 1.9)
                x = DARK_SIDE_CENTER_X + math.cos(a) * radius * wobble
                y = DARK_SIDE_CENTER_Y + math.sin(a) * radius * wobble
                z = self.world.surface_height(x, y) + 1.16 + rr * 0.10
                factor = self._dark_side_factor_at(x, y)
                alpha = 0.03 + factor * 0.44
                vwriter.addData3(x, y, z)
                nwriter.addData3(0, 0, 1)
                cwriter.addData4(0.005, 0.010 + factor * 0.015, 0.030 + factor * 0.035, alpha)
        tris = GeomTriangles(Geom.UHStatic)
        for ring in range(rings):
            for seg in range(segments):
                i0 = ring * segments + seg
                i1 = ring * segments + ((seg + 1) % segments)
                i2 = (ring + 1) * segments + seg
                i3 = (ring + 1) * segments + ((seg + 1) % segments)
                tris.addVertices(i0, i2, i1)
                tris.addVertices(i1, i2, i3)
        geom = Geom(vdata)
        geom.addPrimitive(tris)
        node = GeomNode("dark_side_shadow_mesh")
        node.addGeom(geom)
        shadow = self.dark_side_root.attachNewNode(node)
        shadow.setTransparency(TransparencyAttrib.MAlpha)
        shadow.setDepthWrite(False)
        shadow.setDepthTest(True)
        shadow.setBin("transparent", 16)
        shadow.setLightOff(1)
        self._pin_no_cull(shadow)
        self.dark_side_shadow = shadow

        # A thin terminator horizon ring makes the destination visible from the lit plains
        # without adding collision or fake walls.
        ring = LineSegs("dark_side_terminator_edge")
        ring.setThickness(2.2)
        ring.setColor(0.24, 0.42, 0.72, 0.34)
        edge_radius = DARK_SIDE_OUTER_RADIUS * 0.96
        for step in range(96):
            a0 = step / 96.0 * math.tau
            a1 = (step + 1) / 96.0 * math.tau
            x0 = DARK_SIDE_CENTER_X + math.cos(a0) * edge_radius
            y0 = DARK_SIDE_CENTER_Y + math.sin(a0) * edge_radius
            x1 = DARK_SIDE_CENTER_X + math.cos(a1) * edge_radius
            y1 = DARK_SIDE_CENTER_Y + math.sin(a1) * edge_radius
            ring.moveTo(x0, y0, self.world.surface_height(x0, y0) + 2.2)
            ring.drawTo(x1, y1, self.world.surface_height(x1, y1) + 2.2)
        edge_np = self.dark_side_root.attachNewNode(ring.create())
        edge_np.setTransparency(TransparencyAttrib.MAlpha)
        edge_np.setLightOff(1)
        edge_np.setDepthWrite(False)
        edge_np.setDepthTest(True)

    def _update_environment_lighting(self, task: Task) -> int:
        factor = self._dark_side_factor_for_player()
        self.current_dark_side_factor = factor
        if hasattr(self, "ambient_light"):
            if IS_TITAN_LEVEL:
                self.ambient_light.setColor((
                    0.54 * (1.0 - factor * 0.20) + 0.12 * factor,
                    0.24 * (1.0 - factor * 0.28) + 0.060 * factor,
                    0.070 * (1.0 - factor * 0.34) + 0.018 * factor,
                    1.0,
                ))
            elif IS_MARS_LEVEL:
                self.ambient_light.setColor((
                    0.22 * (1.0 - factor * 0.28) + 0.060 * factor,
                    0.11 * (1.0 - factor * 0.32) + 0.040 * factor,
                    0.060 * (1.0 - factor * 0.38) + 0.024 * factor,
                    1.0,
                ))
            elif IS_TRITON_LEVEL:
                self.ambient_light.setColor((0.045, 0.075, 0.145, 1.0))
            else:
                self.ambient_light.setColor((
                    0.070 * (1.0 - factor) + 0.008 * factor,
                    0.078 * (1.0 - factor) + 0.012 * factor,
                    0.105 * (1.0 - factor) + 0.026 * factor,
                    1.0,
                ))
        if hasattr(self, "sun_light"):
            if IS_TITAN_LEVEL:
                self.sun_light.setColor((
                    2.45 * (1.0 - factor * 0.12),
                    1.38 * (1.0 - factor * 0.18),
                    0.45 * (1.0 - factor * 0.26),
                    1.0,
                ))
            elif IS_MARS_LEVEL:
                self.sun_light.setColor((
                    2.85 * (1.0 - factor * 0.16),
                    2.42 * (1.0 - factor * 0.20),
                    2.00 * (1.0 - factor * 0.26),
                    1.0,
                ))
            elif IS_TRITON_LEVEL:
                self.sun_light.setColor((1.18, 1.28, 1.48, 1.0))
            else:
                self.sun_light.setColor((
                    2.35 * (1.0 - factor * 0.18),
                    2.22 * (1.0 - factor * 0.22),
                    1.92 * (1.0 - factor * 0.30),
                    1.0,
                ))
        if hasattr(self, "fill_light"):
            if IS_TITAN_LEVEL:
                self.fill_light.setColor((
                    0.070 * (1.0 - factor) + 0.030 * factor,
                    0.034 * (1.0 - factor) + 0.015 * factor,
                    0.012 * (1.0 - factor) + 0.006 * factor,
                    1.0,
                ))
            elif IS_MARS_LEVEL:
                self.fill_light.setColor((
                    0.080 * (1.0 - factor) + 0.030 * factor,
                    0.040 * (1.0 - factor) + 0.018 * factor,
                    0.024 * (1.0 - factor) + 0.010 * factor,
                    1.0,
                ))
            elif IS_TRITON_LEVEL:
                self.fill_light.setColor((0.020, 0.060, 0.150, 1.0))
            else:
                self.fill_light.setColor((
                    0.015 * (1.0 - factor),
                    0.032 * (1.0 - factor) + 0.008 * factor,
                    0.070 * (1.0 - factor) + 0.020 * factor,
                    1.0,
                ))
        if hasattr(self, "rim_light"):
            if IS_TITAN_LEVEL:
                self.rim_light.setColor((
                    0.22 * (1.0 - factor) + 0.055 * factor,
                    0.09 * (1.0 - factor) + 0.025 * factor,
                    0.025 * (1.0 - factor) + 0.010 * factor,
                    1.0,
                ))
            elif IS_MARS_LEVEL:
                self.rim_light.setColor((
                    0.14 * (1.0 - factor) + 0.050 * factor,
                    0.07 * (1.0 - factor) + 0.030 * factor,
                    0.034 * (1.0 - factor) + 0.018 * factor,
                    1.0,
                ))
            elif IS_TRITON_LEVEL:
                self.rim_light.setColor((0.040, 0.095, 0.210, 1.0))
            else:
                self.rim_light.setColor((
                    0.030 * (1.0 - factor) + 0.016 * factor,
                    0.050 * (1.0 - factor) + 0.024 * factor,
                    0.090 * (1.0 - factor) + 0.058 * factor,
                    1.0,
                ))
        if not getattr(self, "_underwater", False):
            if IS_IAPETUS_LEVEL:
                pos = self.camera.getPos(self.render)
                void_factor = self.world._iapetus_void_factor_at(pos.x, pos.y)
                shade = clamp(factor * 0.65 + void_factor * 0.95, 0.0, 1.0)
                self.fog_surface.setColor(
                    0.010 * (1.0 - shade) + 0.0006 * shade,
                    0.010 * (1.0 - shade) + 0.0007 * shade,
                    0.013 * (1.0 - shade) + 0.0012 * shade,
                )
                self.fog_surface.setExpDensity(0.00042 + factor * 0.00020 + void_factor * 0.00074)
                self.render.setFog(self.fog_surface)
                self.setBackgroundColor(
                    0.0010 * (1.0 - shade) + 0.00003 * shade,
                    0.0011 * (1.0 - shade) + 0.00004 * shade,
                    0.0018 * (1.0 - shade) + 0.00006 * shade,
                    1.0,
                )
            elif IS_TITAN_LEVEL:
                pos = self.camera.getPos(self.render)
                shore = self.world.titan_liquid_signal(pos.x, pos.y)
                haze = clamp(0.48 + factor * 0.26 + shore * 0.18, 0.0, 1.0)
                gas_tint = 0.12 + 0.08 * (0.5 + 0.5 * math.sin(task.time * 0.05))
                self.fog_surface.setColor(
                    0.56 * (1.0 - haze) + 0.26 * haze - gas_tint * 0.05,
                    0.32 * (1.0 - haze) + 0.14 * haze + gas_tint * 0.06,
                    0.110 * (1.0 - haze) + 0.055 * haze + gas_tint * 0.10,
                )
                self.fog_surface.setExpDensity(0.00056 + factor * 0.00014 + shore * 0.00008)
                self.render.setFog(self.fog_surface)
                self.setBackgroundColor(
                    0.34 * (1.0 - haze) + 0.17 * haze,
                    0.22 * (1.0 - haze) + 0.12 * haze,
                    0.12 * (1.0 - haze) + 0.075 * haze,
                    1.0,
                )
            elif IS_MARS_LEVEL:
                haze = clamp(0.18 + factor * 0.20, 0.0, 1.0)
                self.fog_surface.setColor(
                    0.20 * (1.0 - haze) + 0.08 * haze,
                    0.12 * (1.0 - haze) + 0.05 * haze,
                    0.075 * (1.0 - haze) + 0.030 * haze,
                )
                self.fog_surface.setExpDensity(0.00020 + factor * 0.00016)
                self.render.setFog(self.fog_surface)
                self.setBackgroundColor(
                    0.15 * (1.0 - haze) + 0.05 * haze,
                    0.09 * (1.0 - haze) + 0.035 * haze,
                    0.06 * (1.0 - haze) + 0.020 * haze,
                    1.0,
                )
            elif IS_TRITON_LEVEL:
                haze = clamp(0.12 + factor * 0.12, 0.0, 1.0)
                self.fog_surface.setColor(0.060, 0.105, 0.165)
                self.fog_surface.setExpDensity(0.00022 + factor * 0.00012)
                self.render.setFog(self.fog_surface)
                self.setBackgroundColor(0.006, 0.016, 0.048, 1.0)
            elif IS_PLUTO_LEVEL:
                haze = clamp(0.12 + factor * 0.22, 0.0, 1.0)
                self.fog_surface.setColor(
                    0.036 * (1.0 - haze) + 0.012 * haze,
                    0.042 * (1.0 - haze) + 0.020 * haze,
                    0.070 * (1.0 - haze) + 0.048 * haze,
                )
                self.fog_surface.setExpDensity(0.00018 + factor * 0.00020)
                self.render.setFog(self.fog_surface)
                self.setBackgroundColor(
                    0.00045 * (1.0 - haze) + 0.00010 * haze,
                    0.00055 * (1.0 - haze) + 0.00016 * haze,
                    0.0018 * (1.0 - haze) + 0.00048 * haze,
                    1.0,
                )
            else:
                self.fog_surface.setColor(
                    0.10 * (1.0 - factor) + 0.018 * factor,
                    0.12 * (1.0 - factor) + 0.024 * factor,
                    0.17 * (1.0 - factor) + 0.052 * factor,
                )
                self.fog_surface.setExpDensity(0.00022 + factor * 0.00036)
                self.render.setFog(self.fog_surface)
                self.setBackgroundColor(
                    0.004 * (1.0 - factor) + 0.0005 * factor,
                    0.005 * (1.0 - factor) + 0.0010 * factor,
                    0.014 * (1.0 - factor) + 0.0040 * factor,
                    1.0,
                )
        return Task.cont

    def _build_pressure_ridge_landmarks(self) -> None:
        # Pass 27 removes extra wall-like landmark pieces so the terrain itself carries
        # the hilly silhouette.
        old_root = getattr(self, "landmark_root", None)
        if old_root is not None and not old_root.isEmpty():
            old_root.removeNode()
        self.landmark_root = self.render.attachNewNode("pressure_ridge_landmarks")

    def _build_visible_snow_hill_landmarks(self) -> None:
        # Pass 27 removes above-surface snow cap props; the hills are now in the terrain.
        old_root = getattr(self, "snow_hill_root", None)
        if old_root is not None and not old_root.isEmpty():
            old_root.removeNode()
        self.snow_hill_root = self.render.attachNewNode("visible_snow_hill_landmarks")

    def _build_valley_ravine_guides(self) -> None:
        pass

    def _build_dynamic_plume_system(self) -> None:
        """Rare Enceladus cryovolcanic plume events spawned as live world geometry."""
        old_root = getattr(self, "plume_root", None)
        if old_root is not None and not old_root.isEmpty():
            old_root.removeNode()
        self.plume_root = self.render.attachNewNode("dynamic_cryo_plume_events")
        self._pin_no_cull(self.plume_root)
        self.active_plumes = []
        self.dynamic_plume_timer = self.plume_rng.uniform(6.0, 16.0)

    def _dynamic_plume_delay(self) -> float:
        # Long gaps keep eruptions rare during normal play; the event itself is large
        # enough that one plume changes the whole horizon when it appears.
        return self.plume_rng.uniform(DYNAMIC_PLUME_MIN_DELAY, DYNAMIC_PLUME_MAX_DELAY)

    def _choose_dynamic_plume_position(self, near: tuple[float, float] | None = None) -> tuple[float, float]:
        # Use broad south-polar tiger-stripe style bands instead of a static backdrop row.
        # These are real terrain coordinates, so player movement gives parallax.
        cam = self.camera.getPos() if hasattr(self, "camera") else Vec3(0, 0, 0)
        bands = (
            (-4300.0, -0.18),
            (-3420.0, 0.13),
            (-2580.0, -0.10),
            (-1760.0, 0.16),
            (-920.0, -0.12),
            (420.0, 0.08),
            (1460.0, -0.06),
            (2460.0, 0.11),
        )
        if near is not None:
            base_x, base_y = near
            return (
                clamp(base_x + self.plume_rng.choice((-1.0, 1.0)) * self.plume_rng.uniform(1650.0, 2850.0), -WORLD_HALF + 520.0, WORLD_HALF - 520.0),
                clamp(base_y + self.plume_rng.choice((-1.0, 1.0)) * self.plume_rng.uniform(1450.0, 2550.0), -WORLD_HALF + 520.0, WORLD_HALF - 520.0),
            )
        for _attempt in range(80):
            x = self.plume_rng.uniform(-WORLD_HALF * 0.86, WORLD_HALF * 0.86)
            offset, slope = self.plume_rng.choice(bands)
            y = offset + x * slope + self.plume_rng.uniform(-340.0, 340.0)
            x = clamp(x, -WORLD_HALF + 420.0, WORLD_HALF - 420.0)
            y = clamp(y, -WORLD_HALF + 420.0, WORLD_HALF - 420.0)
            dx = x - cam.x
            dy = y - cam.y
            if dx * dx + dy * dy > 1850.0 * 1850.0:
                return x, y
        return self.plume_rng.uniform(-3600.0, 3600.0), self.plume_rng.uniform(-3600.0, 3600.0)

    def _spawn_dynamic_plume(
        self,
        x: float | None = None,
        y: float | None = None,
        *,
        height: float | None = None,
        spread: float | None = None,
        duration: float | None = None,
        age: float = 0.0,
        label: str = "random",
    ) -> dict[str, object]:
        if x is None or y is None:
            x, y = self._choose_dynamic_plume_position()
        surface_z = self.world.surface_height(float(x), float(y)) + 1.2
        plume_height = height if height is not None else self.plume_rng.uniform(2600.0, 4550.0)
        plume_spread = spread if spread is not None else self.plume_rng.uniform(240.0, 460.0)
        submerged_base_depth = clamp(plume_spread * 0.10, 28.0, 54.0)
        column_base_z = surface_z - submerged_base_depth
        plume_duration = duration if duration is not None else self.plume_rng.uniform(22.0, 36.0)
        strand_count = int(clamp(plume_height / 112.0, 20.0, 38.0))
        strand_data: list[tuple[float, float, float, float]] = []
        for strand in range(strand_count):
            frac = strand / max(strand_count - 1, 1)
            angle = self.plume_rng.uniform(0.0, math.tau)
            radius = self.plume_rng.uniform(0.05, 1.0) ** 0.65
            phase = self.plume_rng.uniform(0.0, math.tau) + strand * 0.17
            lean = self.plume_rng.uniform(-0.65, 0.65)
            strand_data.append((angle, radius, phase, lean + frac * 0.18))
        drift_angle = self.plume_rng.uniform(0.0, math.tau)
        drift = Vec2(math.cos(drift_angle), math.sin(drift_angle)) * self.plume_rng.uniform(90.0, 220.0)
        cap_rays = [self.plume_rng.uniform(0.55, 1.05) for _ in range(18)]
        node = self.plume_root.attachNewNode(f"dynamic_plume_{len(self.active_plumes):02d}_{label}")
        self._pin_no_cull(node)
        terrain_root = node.attachNewNode("terrain_features")
        fx_root = node.attachNewNode("plume_fx")
        self._pin_no_cull(terrain_root)
        self._pin_no_cull(fx_root)
        primary_angle = self.plume_rng.uniform(0.0, math.tau)
        secondary_angle = primary_angle + self.plume_rng.uniform(0.72, 1.28) * (1.0 if self.plume_rng.random() < 0.5 else -1.0)
        rift_specs = [
            {
                "angle": primary_angle,
                "length": plume_spread * self.plume_rng.uniform(7.0, 9.6),
                "width": plume_spread * self.plume_rng.uniform(0.46, 0.68),
                "ridge_height": self.plume_rng.uniform(22.0, 42.0),
                "channel_depth": self.plume_rng.uniform(7.5, 13.5),
                "offset_x": 0.0,
                "offset_y": 0.0,
            },
            {
                "angle": secondary_angle,
                "length": plume_spread * self.plume_rng.uniform(4.6, 6.6),
                "width": plume_spread * self.plume_rng.uniform(0.28, 0.42),
                "ridge_height": self.plume_rng.uniform(10.0, 18.0),
                "channel_depth": self.plume_rng.uniform(4.0, 7.0),
                "offset_x": math.cos(secondary_angle) * plume_spread * self.plume_rng.uniform(0.10, 0.22),
                "offset_y": math.sin(secondary_angle) * plume_spread * self.plume_rng.uniform(0.10, 0.22),
            },
        ]
        orbital_counterflow = Vec2(-1.0, 0.18)
        orbital_counterflow.normalize()
        cloud_specs = []
        cloud_count = 10 + int(plume_spread / 55.0)
        for index in range(cloud_count):
            cloud_specs.append({
                "trail": self.plume_rng.uniform(180.0, plume_spread * 7.6),
                "height": self.plume_rng.uniform(plume_height * 0.28, plume_height * 0.74),
                "rise": self.plume_rng.uniform(120.0, 520.0),
                "width": self.plume_rng.uniform(plume_spread * 6.2, plume_spread * 11.8),
                "height_scale": self.plume_rng.uniform(plume_spread * 1.9, plume_spread * 4.2),
                "lateral": self.plume_rng.uniform(-plume_spread * 0.86, plume_spread * 0.86),
                "phase": self.plume_rng.uniform(0.0, math.tau),
                "alpha": self.plume_rng.uniform(0.22, 0.40),
            })
        spout_cloud_specs = []
        spout_cloud_count = 18 + int(plume_height / 180.0)
        for index in range(spout_cloud_count):
            level = self.plume_rng.uniform(0.05, 0.92)
            spout_cloud_specs.append({
                "level": level,
                "angle": self.plume_rng.uniform(0.0, math.tau),
                "radius": self.plume_rng.uniform(plume_spread * 0.28, plume_spread * 1.02) * (0.92 + level * 1.04),
                "width": self.plume_rng.uniform(plume_spread * 2.4, plume_spread * 5.6) * (0.92 + level * 1.18),
                "height_scale": self.plume_rng.uniform(plume_spread * 1.45, plume_spread * 3.25) * (0.94 + level * 0.94),
                "phase": self.plume_rng.uniform(0.0, math.tau),
                "alpha": self.plume_rng.uniform(0.38, 0.64),
                "lift": self.plume_rng.uniform(220.0, 760.0),
            })
        streak_specs = []
        streak_count = 4 + int(plume_spread / 120.0)
        for index in range(streak_count):
            streak_specs.append({
                "trail": self.plume_rng.uniform(plume_spread * 1.8, plume_spread * 4.4),
                "height": self.plume_rng.uniform(plume_height * 0.56, plume_height * 0.92),
                "z_drift": self.plume_rng.uniform(180.0, 520.0),
                "width": self.plume_rng.uniform(plume_spread * 11.0, plume_spread * 22.0),
                "height_scale": self.plume_rng.uniform(plume_spread * 1.2, plume_spread * 2.8),
                "lateral": self.plume_rng.uniform(-plume_spread * 1.10, plume_spread * 1.10),
                "phase": self.plume_rng.uniform(0.0, math.tau),
                "alpha": self.plume_rng.uniform(0.10, 0.22),
                "rotation_speed": self.plume_rng.uniform(6.0, 14.0),
            })
        haze_specs = []
        haze_count = 4 + int(plume_spread / 95.0)
        for index in range(haze_count):
            haze_specs.append({
                "offset": self.plume_rng.uniform(-plume_spread * 0.18, plume_spread * 0.18),
                "radius": self.plume_rng.uniform(plume_spread * 2.8, plume_spread * 5.2),
                "ratio": self.plume_rng.uniform(0.48, 0.82),
                "angle": primary_angle + self.plume_rng.uniform(-0.42, 0.42),
                "phase": self.plume_rng.uniform(0.0, math.tau),
                "alpha": self.plume_rng.uniform(0.13, 0.24),
            })
        plume: dict[str, object] = {
            "node": node,
            "terrain_root": terrain_root,
            "fx_root": fx_root,
            "x": float(x),
            "y": float(y),
            "base_z": surface_z,
            "surface_z": surface_z,
            "column_base_z": column_base_z,
            "submerged_base_depth": submerged_base_depth,
            "height": plume_height,
            "spread": plume_spread,
            "duration": plume_duration,
            "age": max(0.0, min(age, plume_duration * 0.92)),
            "phase": self.plume_rng.uniform(0.0, math.tau),
            "strand_data": strand_data,
            "cap_rays": cap_rays,
            "drift": drift,
            "rift_specs": rift_specs,
            "cloud_specs": cloud_specs,
            "cloud_flow": orbital_counterflow * self.plume_rng.uniform(84.0, 148.0),
            "spout_cloud_specs": spout_cloud_specs,
            "streak_specs": streak_specs,
            "haze_specs": haze_specs,
        }
        self.active_plumes.append(plume)
        self._build_dynamic_plume_terrain(plume)
        self._rebuild_dynamic_plume(plume, 0.0)
        return plume

    def _build_dynamic_plume_terrain(self, plume: dict[str, object]) -> None:
        terrain_root = plume.get("terrain_root")
        if terrain_root is None or not hasattr(terrain_root, "getChildren"):
            return
        for child in terrain_root.getChildren():
            child.removeNode()
        for index, spec in enumerate(plume.get("rift_specs", [])):
            if not isinstance(spec, dict):
                continue
            patch = MeshFactory.make_plume_rift_patch(
                f"plume_rift_patch_{index}",
                self.world,
                float(plume.get("x", 0.0)) + float(spec.get("offset_x", 0.0)),
                float(plume.get("y", 0.0)) + float(spec.get("offset_y", 0.0)),
                float(spec.get("angle", 0.0)),
                float(spec.get("length", 900.0)),
                float(spec.get("width", 132.0)),
                float(spec.get("ridge_height", 28.0)),
                float(spec.get("channel_depth", 9.0)),
            )
            patch.reparentTo(terrain_root)
            patch.setTwoSided(True)
            patch.setTransparency(TransparencyAttrib.MAlpha)
            patch.setDepthWrite(False)
            patch.setDepthTest(True)
            patch.setBin("transparent", 24)
            self._pin_no_cull(patch)
            water = MeshFactory.make_plume_water_ribbon(
                f"plume_rift_water_{index}",
                self.world,
                float(plume.get("x", 0.0)) + float(spec.get("offset_x", 0.0)),
                float(plume.get("y", 0.0)) + float(spec.get("offset_y", 0.0)),
                float(spec.get("angle", 0.0)),
                float(spec.get("length", 900.0)),
                float(spec.get("width", 132.0)) * 0.58,
                float(spec.get("channel_depth", 9.0)),
            )
            water.reparentTo(terrain_root)
            water.setTwoSided(True)
            water.setTransparency(TransparencyAttrib.MAlpha)
            water.setDepthWrite(False)
            water.setDepthTest(True)
            water.setBin("transparent", 34)
            self._pin_no_cull(water)

    def _build_dynamic_plume_ground_haze(self, plume: dict[str, object], parent: NodePath, time_value: float, alpha: float) -> None:
        haze_texture = self._load_texture(self.texture_paths["ground_haze"], repeat=False, clamp=True)
        x = float(plume.get("x", 0.0))
        y = float(plume.get("y", 0.0))
        base_z = float(plume.get("surface_z", plume.get("base_z", 0.0)))
        spread = float(plume.get("spread", 180.0))
        rift_specs = plume.get("rift_specs", [])
        flow_angle = 0.0
        if rift_specs and isinstance(rift_specs[0], dict):
            flow_angle = float(rift_specs[0].get("angle", 0.0))
        flow = Vec2(math.cos(flow_angle), math.sin(flow_angle))
        side = Vec2(-flow.y, flow.x)
        life = clamp(float(plume.get("age", 0.0)) / max(float(plume.get("duration", 1.0)), 0.1), 0.0, 1.0)
        pulse_base = 0.68 + 0.32 * (0.5 + 0.5 * math.sin(time_value * 0.76 + float(plume.get("phase", 0.0))))
        for index, spec in enumerate(plume.get("haze_specs", [])):
            offset = float(spec.get("offset", 0.0))
            phase = float(spec.get("phase", 0.0))
            radius = float(spec.get("radius", spread * 3.4)) * (0.72 + 0.30 * math.sin(time_value * 0.18 + phase))
            ratio = float(spec.get("ratio", 0.62))
            angle = float(spec.get("angle", flow_angle))
            travel = (life * 0.42 + 0.08 * math.sin(time_value * 0.13 + phase)) * spread * 1.25
            cx = x + flow.x * travel + side.x * offset
            cy = y + flow.y * travel + side.y * offset
            cz = self.world.surface_height(cx, cy) + 2.4 + index * 0.030
            cm = CardMaker(f"plume_ground_cyan_haze_{index}")
            cm.setFrame(-0.5, 0.5, -0.5, 0.5)
            card = NodePath(cm.generate())
            card.reparentTo(parent)
            card.setPos(cx, cy, cz)
            card.setHpr(math.degrees(angle) + math.sin(time_value * 0.07 + phase) * 3.0, -90.0, 0.0)
            card.setScale(radius, 1.0, radius * ratio)
            card.setTexture(haze_texture)
            card.setTransparency(TransparencyAttrib.MAlpha)
            card.setDepthWrite(False)
            card.setDepthTest(False)
            card.setBin("transparent", 66)
            card.setTwoSided(True)
            card.setShaderOff(1)
            card.setLightOff(1)
            self._pin_no_cull(card)
            local_alpha = float(spec.get("alpha", 0.16)) * alpha * pulse_base
            card.setColorScale(0.22, 0.92, 1.0, local_alpha)
        # Central hot glow at the vent throat, intentionally flatter and brighter than the drifting haze.
        cm = CardMaker("plume_vent_cyan_hotspot")
        cm.setFrame(-0.5, 0.5, -0.5, 0.5)
        hotspot = NodePath(cm.generate())
        hotspot.reparentTo(parent)
        hotspot.setPos(x, y, base_z + 2.8)
        hotspot.setHpr(0, -90.0, 0)
        hotspot.setScale(spread * 1.45, 1.0, spread * 1.45)
        hotspot.setTexture(haze_texture)
        hotspot.setTransparency(TransparencyAttrib.MAlpha)
        hotspot.setDepthWrite(False)
        hotspot.setDepthTest(False)
        hotspot.setBin("transparent", 67)
        hotspot.setTwoSided(True)
        hotspot.setShaderOff(1)
        hotspot.setLightOff(1)
        self._pin_no_cull(hotspot)
        hotspot.setColorScale(0.15, 1.0, 1.0, 0.28 * alpha * pulse_base)

    def _build_dynamic_spout_emitter_clouds(
        self,
        plume: dict[str, object],
        parent: NodePath,
        time_value: float,
        alpha: float,
        column_height: float,
        column_spread: float,
    ) -> None:
        """Layered near-column vapor puffs emitted directly from the water spout.

        These sit around the cryoplume column itself, then drift outward/upward so
        the water spout reads as the source of the volumetric vapor instead of a
        separate flat sky-card effect.
        """
        cloud_texture = self._load_texture(self.texture_paths["vapor_cloud"], repeat=False, clamp=True)
        x = float(plume.get("x", 0.0))
        y = float(plume.get("y", 0.0))
        base_z = float(plume.get("column_base_z", plume.get("base_z", 0.0)))
        life = clamp(float(plume.get("age", 0.0)) / max(float(plume.get("duration", 1.0)), 0.1), 0.0, 1.0)
        pulse = 0.72 + 0.28 * (0.5 + 0.5 * math.sin(time_value * 0.92 + float(plume.get("phase", 0.0))))
        solar = getattr(self, "solar_key_vector", Vec3(0.42, 0.78, -0.24))
        if solar.length() <= 0.001:
            solar = Vec3(0.42, 0.78, -0.24)
        wind = plume.get("cloud_flow", Vec2(-86.0, 18.0))
        if not isinstance(wind, Vec2) or wind.length() <= 0.001:
            wind = Vec2(-86.0, 18.0)
        wind_dir = Vec2(wind.x, wind.y)
        wind_dir.normalize()
        side = Vec2(-wind_dir.y, wind_dir.x)

        for index, spec in enumerate(plume.get("spout_cloud_specs", [])):
            if not isinstance(spec, dict):
                continue
            level = clamp(float(spec.get("level", 0.35)), 0.02, 0.94)
            phase = float(spec.get("phase", 0.0))
            base_angle = float(spec.get("angle", 0.0)) + time_value * (0.035 + level * 0.024)
            radius = float(spec.get("radius", column_spread * 0.42)) * (0.66 + 0.54 * life)
            swirl = math.sin(time_value * 0.42 + phase + level * 5.0) * column_spread * 0.20
            stream = math.sin(time_value * 0.20 + phase * 0.7) * column_spread * 0.14
            outward_x = math.cos(base_angle) * radius + wind_dir.x * stream + side.x * swirl
            outward_y = math.sin(base_angle) * radius + wind_dir.y * stream + side.y * swirl
            lift = float(spec.get("lift", 160.0)) * (0.32 + life * 0.78)
            center = Point3(
                x + outward_x,
                y + outward_y,
                base_z + column_height * level + lift + math.sin(time_value * 0.32 + phase) * column_spread * 0.18,
            )
            size_growth = 0.74 + level * 1.05 + life * 0.36
            width = float(spec.get("width", column_spread * 1.4)) * size_growth
            height_scale = float(spec.get("height_scale", column_spread * 0.8)) * (0.88 + level * 0.58)
            layer_alpha = float(spec.get("alpha", 0.25)) * alpha * pulse * (0.78 + level * 0.28)
            cyan_hit = clamp(0.68 + (-solar.z) * 0.22 + 0.16 * math.sin(time_value * 0.26 + phase), 0.58, 1.0)

            for layer_index, mul in enumerate((1.0, 0.68)):
                cm = CardMaker(f"spout_emitter_vapor_{index}_{layer_index}")
                cm.setFrame(-0.5, 0.5, -0.5, 0.5)
                card = NodePath(cm.generate())
                card.reparentTo(parent)
                card.setBillboardPointEye()
                card.setPos(center + Vec3(0.0, 0.0, layer_index * column_spread * 0.16))
                card.setScale(width * mul, 1.0, height_scale * mul)
                card.setTexture(cloud_texture)
                card.setTransparency(TransparencyAttrib.MAlpha)
                card.setDepthWrite(False)
                card.setDepthTest(False)
                card.setBin("transparent", 76 + layer_index)
                card.setTwoSided(True)
                card.setShaderOff(1)
                self._pin_no_cull(card)
                mat = Material()
                mat.setBaseColor((0.46 + cyan_hit * 0.28, 0.82 + cyan_hit * 0.13, 1.0, 1.0))
                mat.setEmission((0.10 + cyan_hit * 0.08, 0.26 + cyan_hit * 0.16, 0.42 + cyan_hit * 0.18, 1.0))
                mat.setShininess(6.0)
                card.setMaterial(mat, 1)
                card.setColorScale(0.36 + cyan_hit * 0.38, 0.86 + cyan_hit * 0.12, 1.0, layer_alpha * (1.0 - layer_index * 0.22))

    def _build_dynamic_plume_sky_streaks(self, plume: dict[str, object], parent: NodePath, time_value: float, alpha: float) -> None:
        """Render long high-altitude vapor streaks that stretch across the sky.

        These read like broad cloud formations pulled by Enceladus/Saturn sky motion,
        helping distant plume fog smear into the horizon instead of staying local.
        """
        cloud_texture = self._load_texture(self.texture_paths["vapor_cloud"], repeat=False, clamp=True)
        flow = plume.get("cloud_flow", Vec2(-90.0, 16.0))
        if not isinstance(flow, Vec2):
            flow = Vec2(-90.0, 16.0)
        x = float(plume.get("x", 0.0))
        y = float(plume.get("y", 0.0))
        base_z = float(plume.get("base_z", 0.0))
        plume_height = float(plume.get("height", 2200.0))
        spread = float(plume.get("spread", 180.0))
        along = Vec2(flow.x, flow.y)
        if along.length() <= 0.001:
            along = Vec2(-1.0, 0.18)
        along.normalize()
        side = Vec2(-along.y, along.x)
        life = clamp(float(plume.get("age", 0.0)) / max(float(plume.get("duration", 1.0)), 0.1), 0.0, 1.0)
        stretch = 0.28 + 0.90 * life
        for index, spec in enumerate(plume.get("streak_specs", [])):
            trail = float(spec.get("trail", spread * 2.8)) * stretch
            lateral = float(spec.get("lateral", 0.0))
            phase = float(spec.get("phase", 0.0))
            rotation_speed = float(spec.get("rotation_speed", 8.0))
            rotation_shift = math.sin(time_value * 0.010 * rotation_speed + phase) * spread * 1.8
            drift_shift = time_value * (5.0 + rotation_speed * 0.5)
            center = Point3(
                x + along.x * (trail + drift_shift + rotation_shift) + side.x * lateral,
                y + along.y * (trail + drift_shift + rotation_shift) + side.y * lateral,
                base_z + float(spec.get("height", plume_height * 0.74)) + float(spec.get("z_drift", 260.0)) * life + math.sin(time_value * 0.14 + phase) * spread * 0.18,
            )
            width = float(spec.get("width", spread * 14.0)) * (0.84 + life * 0.72)
            height_scale = float(spec.get("height_scale", spread * 1.6)) * (0.88 + life * 0.46)
            puff_alpha = float(spec.get("alpha", 0.16)) * alpha
            heading = math.degrees(math.atan2(along.y, along.x))
            for layer_index, scale_mul in enumerate((1.0, 0.74, 0.52)):
                cm = CardMaker(f"plume_sky_streak_{index}_{layer_index}")
                cm.setFrame(-0.5, 0.5, -0.5, 0.5)
                card = NodePath(cm.generate())
                card.reparentTo(parent)
                card.setBillboardPointEye()
                card.setPos(center + Vec3(0.0, 0.0, layer_index * spread * 0.06))
                card.setScale(width * scale_mul, 1.0, height_scale * scale_mul)
                card.setTexture(cloud_texture)
                card.setTransparency(TransparencyAttrib.MAlpha)
                card.setDepthWrite(False)
                card.setDepthTest(False)
                card.setBin("transparent", 67 + layer_index)
                card.setTwoSided(True)
                card.setShaderOff(1)
                card.setR(heading * 0.10)
                self._pin_no_cull(card)
                mat = Material()
                mat.setBaseColor((0.52, 0.84, 1.0, 1.0))
                mat.setEmission((0.11, 0.22, 0.34, 1.0))
                mat.setShininess(5.0)
                card.setMaterial(mat, 1)
                glow_alpha = puff_alpha * (1.0 - layer_index * 0.20)
                card.setColorScale(0.48, 0.84, 1.0, glow_alpha)

    def _build_dynamic_plume_vapor_clouds(self, plume: dict[str, object], parent: NodePath, time_value: float, alpha: float) -> None:
        cloud_texture = self._load_texture(self.texture_paths["vapor_cloud"], repeat=False, clamp=True)
        flow = plume.get("cloud_flow", Vec2(-90.0, 16.0))
        if not isinstance(flow, Vec2):
            flow = Vec2(-90.0, 16.0)
        x = float(plume.get("x", 0.0))
        y = float(plume.get("y", 0.0))
        base_z = float(plume.get("base_z", 0.0))
        plume_height = float(plume.get("height", 2200.0))
        spread = float(plume.get("spread", 180.0))
        sun_vec = getattr(self, "solar_key_vector", Vec3(0.45, 0.82, -0.27))
        if sun_vec.length() <= 0.001:
            sun_vec = Vec3(0.45, 0.82, -0.27)
        along = Vec2(flow.x, flow.y)
        if along.length() <= 0.001:
            along = Vec2(-1.0, 0.18)
        along.normalize()
        side = Vec2(-along.y, along.x)
        life = clamp(float(plume.get("age", 0.0)) / max(float(plume.get("duration", 1.0)), 0.1), 0.0, 1.0)
        emerge = clamp(life / 0.22, 0.0, 1.0)
        extend = 0.28 + 0.92 * life
        for index, spec in enumerate(plume.get("cloud_specs", [])):
            trail = float(spec.get("trail", 240.0)) * extend
            lateral = float(spec.get("lateral", 0.0))
            phase = float(spec.get("phase", 0.0))
            drift_x = along.x * trail + side.x * lateral + math.sin(time_value * 0.12 + phase) * spread * 0.28
            drift_y = along.y * trail + side.y * lateral + math.cos(time_value * 0.10 + phase * 1.2) * spread * 0.22
            center = Point3(
                x + drift_x,
                y + drift_y,
                base_z + float(spec.get("height", plume_height * 0.55)) + float(spec.get("rise", 180.0)) * emerge,
            )
            width = float(spec.get("width", spread * 3.0)) * (0.82 + emerge * 0.86)
            height_scale = float(spec.get("height_scale", spread * 1.1)) * (0.78 + emerge * 0.82)
            puff_alpha = float(spec.get("alpha", 0.22)) * alpha
            highlight = clamp(0.74 + sun_vec.z * 0.22 + 0.20 * math.sin(time_value * 0.16 + phase), 0.56, 1.0)

            for layer_index, scale_mul in enumerate((1.0, 0.78, 0.58)):
                cm = CardMaker(f"plume_vapor_cloud_{index}_{layer_index}")
                cm.setFrame(-0.5, 0.5, -0.5, 0.5)
                card = NodePath(cm.generate())
                card.reparentTo(parent)
                card.setBillboardPointEye()
                card.setPos(center + Vec3(0.0, 0.0, layer_index * spread * 0.10))
                card.setScale(width * scale_mul, 1.0, height_scale * scale_mul)
                card.setTexture(cloud_texture)
                card.setTransparency(TransparencyAttrib.MAlpha)
                card.setDepthWrite(False)
                card.setDepthTest(False)
                card.setBin("transparent", 69 + layer_index)
                card.setTwoSided(True)
                card.setShaderOff(1)
                self._pin_no_cull(card)
                mat = Material()
                mat.setBaseColor((0.56 + highlight * 0.20, 0.82 + highlight * 0.10, 1.0, 1.0))
                mat.setEmission((0.10 + highlight * 0.07, 0.26 + highlight * 0.12, 0.36 + highlight * 0.15, 1.0))
                mat.setShininess(8.0)
                card.setMaterial(mat, 1)
                glow_alpha = puff_alpha * (1.0 - layer_index * 0.18)
                card.setColorScale(0.44 + highlight * 0.32, 0.88 + highlight * 0.12, 1.0, glow_alpha)

    def _rebuild_dynamic_plume(self, plume: dict[str, object], time_value: float) -> None:
        node = plume.get("fx_root")
        if node is None or not hasattr(node, "getChildren"):
            return
        for child in node.getChildren():
            child.removeNode()
        age = float(plume.get("age", 0.0))
        duration = max(float(plume.get("duration", 1.0)), 0.1)
        life = clamp(age / duration, 0.0, 1.0)
        emerge = clamp(life / 0.18, 0.0, 1.0)
        fade = clamp((1.0 - life) / 0.24, 0.0, 1.0)
        emerge = emerge * emerge * (3.0 - 2.0 * emerge)
        fade = fade * fade * (3.0 - 2.0 * fade)
        alpha = emerge * fade
        if alpha <= 0.015:
            return

        x = float(plume.get("x", 0.0))
        y = float(plume.get("y", 0.0))
        surface_z = float(plume.get("surface_z", plume.get("base_z", 0.0)))
        column_base_z = float(plume.get("column_base_z", plume.get("base_z", 0.0)))
        height = float(plume.get("height", 1800.0)) * (0.18 + 0.82 * emerge)
        spread = float(plume.get("spread", 150.0)) * (0.42 + 0.74 * emerge)
        phase = float(plume.get("phase", 0.0))
        drift = plume.get("drift", Vec2(0, 0))
        if not isinstance(drift, Vec2):
            drift = Vec2(0, 0)

        core = LineSegs("dynamic_plume_core")
        core.setThickness(2.4 + 1.8 * alpha)
        core.setColor(0.82, 0.94, 1.0, 0.10 + alpha * 0.26)
        mist = LineSegs("dynamic_plume_mist")
        mist.setThickness(1.4 + 1.0 * alpha)
        mist.setColor(0.70, 0.88, 1.0, 0.04 + alpha * 0.14)
        strand_data = plume.get("strand_data", [])
        steps = 10
        for angle, radius, strand_phase, lean in strand_data:
            local_radius = float(radius) * spread
            base_angle = float(angle) + math.sin(time_value * 0.06 + float(strand_phase)) * 0.06
            ox = math.cos(base_angle) * local_radius * 0.18
            oy = math.sin(base_angle) * local_radius * 0.18
            previous_core: tuple[float, float, float] | None = None
            previous_mist: tuple[float, float, float] | None = None
            for step in range(steps + 1):
                t = step / steps
                tower = math.pow(t, 1.08)
                pulse = math.sin(time_value * 1.85 + phase + float(strand_phase) + t * 8.6)
                swirl = math.sin(t * 11.5 + phase + float(strand_phase) + time_value * 0.85)
                widening = spread * (0.10 + 0.92 * t * t) * (0.45 + float(radius) * 0.70)
                wind_x = drift.x * t * t
                wind_y = drift.y * t * t
                px = x + ox + math.cos(base_angle + swirl * 0.28) * widening * 0.18 + wind_x + pulse * spread * 0.020 * (1.0 + t)
                py = y + oy + math.sin(base_angle + swirl * 0.28) * widening * 0.18 + wind_y + math.cos(time_value * 1.1 + t * 5.2 + float(strand_phase)) * spread * 0.018
                start_lift = (1.0 - t) * (1.0 - t) * float(plume.get("submerged_base_depth", 32.0)) * 0.22
                pz = column_base_z + height * tower + start_lift
                point = (px, py, pz)
                if previous_core is not None:
                    core.moveTo(*previous_core)
                    core.drawTo(*point)
                previous_core = point

                mist_angle = base_angle + 0.35 + swirl * 0.35 + float(lean) * t
                mist_radius = widening * (0.34 + 0.76 * t)
                mx = x + math.cos(mist_angle) * mist_radius + wind_x * 1.28
                my = y + math.sin(mist_angle) * mist_radius + wind_y * 1.28
                mz = column_base_z + height * (0.18 + tower * 0.88)
                mist_point = (mx, my, mz)
                if previous_mist is not None and step > 1:
                    mist.moveTo(*previous_mist)
                    mist.drawTo(*mist_point)
                previous_mist = mist_point

        # Expanding basal frost shock and high ice-crystal cap make the plume read as a
        # physical eruption instead of a painted horizon streak.
        ring = LineSegs("dynamic_plume_ground_spray")
        ring.setThickness(2.2 + alpha * 2.2)
        ring.setColor(0.90, 0.98, 1.0, 0.10 + alpha * 0.34)
        ring_radius = spread * (0.72 + emerge * 1.70) * (0.86 + math.sin(time_value * 2.1 + phase) * 0.08)
        ring_steps = 36
        for step in range(ring_steps):
            a0 = step / ring_steps * math.tau
            a1 = (step + 1) / ring_steps * math.tau
            wob0 = 1.0 + math.sin(a0 * 3.0 + phase + time_value * 0.65) * 0.08
            wob1 = 1.0 + math.sin(a1 * 3.0 + phase + time_value * 0.65) * 0.08
            ring.moveTo(x + math.cos(a0) * ring_radius * wob0, y + math.sin(a0) * ring_radius * wob0, surface_z + 0.72)
            ring.drawTo(x + math.cos(a1) * ring_radius * wob1, y + math.sin(a1) * ring_radius * wob1, surface_z + 0.72)

        cap = LineSegs("dynamic_plume_ice_cap")
        cap.setThickness(1.1 + alpha * 0.9)
        cap.setColor(0.82, 0.94, 1.0, 0.08 + alpha * 0.22)
        cap_z = column_base_z + height * 0.92
        cap_cx = x + drift.x * 1.05
        cap_cy = y + drift.y * 1.05
        cap_radius = spread * (0.80 + emerge * 1.15)
        cap_rays = plume.get("cap_rays", [0.8] * 18)
        self._build_dynamic_plume_ground_haze(plume, node, time_value, alpha)
        self._build_dynamic_spout_emitter_clouds(plume, node, time_value, alpha, height, spread)
        self._build_dynamic_plume_sky_streaks(plume, node, time_value, alpha)
        self._build_dynamic_plume_vapor_clouds(plume, node, time_value, alpha)
        for ray in range(18):
            a = ray / 18.0 * math.tau + phase * 0.15
            inner = cap_radius * 0.18
            outer = cap_radius * float(cap_rays[ray % len(cap_rays)])
            cap.moveTo(cap_cx + math.cos(a) * inner, cap_cy + math.sin(a) * inner, cap_z)
            cap.drawTo(cap_cx + math.cos(a) * outer, cap_cy + math.sin(a) * outer, cap_z + math.sin(a + time_value) * spread * 0.16)

        for segs in (core, mist, ring, cap):
            np = node.attachNewNode(segs.create())
            np.setTransparency(TransparencyAttrib.MAlpha)
            np.setDepthWrite(False)
            np.setDepthTest(False)
            np.setLightOff(1)
            np.setBin("transparent", 72)
            self._pin_no_cull(np)

    def _animate_dynamic_plumes(self, task: Task) -> int:
        dt = min(globalClock.getDt(), 0.16)
        for plume in list(getattr(self, "active_plumes", [])):
            plume["age"] = float(plume.get("age", 0.0)) + dt
            if float(plume.get("age", 0.0)) >= float(plume.get("duration", 1.0)):
                node = plume.get("node")
                if node is not None and hasattr(node, "removeNode"):
                    node.removeNode()
                self.active_plumes.remove(plume)
                continue
            self._rebuild_dynamic_plume(plume, task.time)

        self.dynamic_plume_timer -= dt
        if self.dynamic_plume_timer <= 0.0 and len(self.active_plumes) < DYNAMIC_PLUME_MAX_ACTIVE:
            primary = self._spawn_dynamic_plume(label="event")
            # A secondary vent is possible but uncommon, creating rare big twin eruptions
            # without turning the horizon into constant background noise.
            if len(self.active_plumes) < DYNAMIC_PLUME_MAX_ACTIVE and self.plume_rng.random() < 0.18:
                self._spawn_dynamic_plume(
                    *self._choose_dynamic_plume_position((float(primary["x"]), float(primary["y"]))),
                    height=float(primary["height"]) * self.plume_rng.uniform(0.72, 1.08),
                    spread=float(primary["spread"]) * self.plume_rng.uniform(0.65, 0.95),
                    duration=float(primary["duration"]) * self.plume_rng.uniform(0.74, 0.96),
                    label="paired",
                )
            self.dynamic_plume_timer = self._dynamic_plume_delay()
        return Task.cont

