    def _make_universal_access_button(self, parent: NodePath, label: str, x: float, command, hint: str = "") -> DirectButton:
        text = label if not hint else f"{label}\n{hint}"
        btn = DirectButton(
            text=text,
            pos=(x, 0.0, 0.805),
            scale=1.0,
            frameSize=(-0.108, 0.108, -0.034, 0.034),
            frameColor=(0.012, 0.055, 0.075, 0.44),
            text_scale=0.017 if hint else 0.022,
            text_fg=(0.74, 0.96, 1.0, 0.88),
            relief=1,
            command=command,
        )
        btn.setTransparency(TransparencyAttrib.MAlpha)
        btn.setBin("fixed", 9100)
        btn.setDepthTest(False)
        btn.setDepthWrite(False)
        return btn

    def _build_universal_planet_access_strip(self) -> None:
        """Small shared Starfall command strip for every moon operation.

        Pass29 makes this the universal access layer so Mimas, Enceladus, and
        Iapetus do not feel like three separate prototypes.  It stays light and
        button-like, avoiding the heavy rectangle panels removed in Pass28.
        """
        root = self.aspect2d.attachNewNode("starfall_universal_planet_access_strip")
        root.setBin("fixed", 9100)
        root.setDepthTest(False)
        root.setDepthWrite(False)
        self.universal_access_root = root
        # Parent the actual readable controls directly to aspect2d; this avoids
        # child-bin ordering issues inside embedded operation roots while the empty
        # root still marks the feature for cleanup/testing.
        ui_parent = self.aspect2d
        self.universal_access_buttons: list[DirectButton] = []
        self.universal_access_title = OnscreenText(
            text=f"STARFALL LINK // {MOON_THEME['display_name']}",
            pos=(-1.30, 0.790),
            scale=0.020,
            fg=(0.62, 0.96, 1.0, 0.72),
            align=TextNode.ALeft,
            mayChange=True,
        )
        self.universal_access_title.setBin("fixed", 9100)
        self.universal_access_title.setDepthTest(False)
        self.universal_access_title.setDepthWrite(False)
        self.universal_access_summary_text = OnscreenText(
            text="RETURN  MAP  OPTIONS  HELP  ROBOTS  BUILD  UPGRADES",
            pos=(0.0, 0.740),
            scale=0.022,
            fg=(0.72, 0.98, 1.0, 0.82),
            align=TextNode.ACenter,
            mayChange=False,
        )
        self.universal_access_summary_text.setBin("fixed", 9100)
        self.universal_access_summary_text.setDepthTest(False)
        self.universal_access_summary_text.setDepthWrite(False)
        specs = [
            ("RETURN", -0.62, self._handle_tab_return, "TAB"),
            ("MAP", -0.41, self._open_universal_ops_map, "M"),
            ("OPTIONS", -0.20, self._open_universal_options_panel, "ESC/P"),
            ("HELP", 0.02, self._open_universal_help_panel, "F1"),
            ("ROBOTS", 0.23, self._open_universal_robot_panel, "F2/RMB"),
            ("BUILD", 0.44, self._open_universal_build_mode, "B"),
            ("UPGRADES", 0.66, self._open_universal_upgrade_panel, "U"),
        ]
        for label, x, command, hint in specs:
            self.universal_access_buttons.append(self._make_universal_access_button(ui_parent, label, x, command, hint))

    def _close_universal_panels_except(self, keep: str = "") -> None:
        keep = keep.upper()
        if keep != "OPTIONS" and getattr(self, "options_visible", False):
            self.options_visible = False
            if hasattr(self, "options_frame"):
                self.options_frame.hide()
        if keep != "HELP" and getattr(self, "help_visible", False):
            self.help_visible = False
            if hasattr(self, "help_frame"):
                self.help_frame.hide()
        if keep != "ROBOT" and getattr(self, "robot_panel_visible", False):
            self.robot_panel_visible = False
            if hasattr(self, "robot_frame"):
                self.robot_frame.hide()
        if keep != "UPGRADE" and getattr(self, "upgrade_visible", False):
            self.upgrade_visible = False
            if hasattr(self, "upgrade_frame"):
                self.upgrade_frame.hide()
        self._refresh_menu_input_lock(f"UNIVERSAL {keep or 'CLOSE'}")

    def _open_universal_ops_map(self) -> None:
        parent = getattr(self, "embedded_parent", None)
        if getattr(self, "embedded_operation", False) and parent is not None and hasattr(parent, "return_from_operation"):
            try:
                parent.return_from_operation()
                if hasattr(parent, "show_saturn_operations_map"):
                    parent.show_saturn_operations_map()
            except Exception as exc:
                self.last_status_message = f"OPS MAP RETURN FAILED: {exc}"
                self.status_flash_timer = 2.6
            return
        self.last_status_message = "OPS MAP IS AVAILABLE FROM THE STARFALL SHIP HUB"
        self.status_flash_timer = 2.0

    def _open_universal_options_panel(self) -> None:
        if getattr(self, "options_visible", False):
            self.close_options_panel()
            return
        self._close_universal_panels_except("OPTIONS")
        self.open_options_panel()

    def _open_universal_help_panel(self) -> None:
        if getattr(self, "help_visible", False):
            self.toggle_help()
            return
        self._close_universal_panels_except("HELP")
        self.toggle_help()

    def _open_universal_robot_panel(self) -> None:
        if getattr(self, "robot_panel_visible", False):
            self.close_robot_panel()
            return
        self._close_universal_panels_except("ROBOT")
        self.open_robot_panel("DRONE")

    def _open_universal_upgrade_panel(self) -> None:
        if getattr(self, "upgrade_visible", False):
            self.toggle_upgrade_panel()
            return
        self._close_universal_panels_except("UPGRADE")
        self.toggle_upgrade_panel()

    def _open_universal_build_mode(self) -> None:
        self._close_universal_panels_except("")
        self._toggle_build_mode()
        if getattr(self, "build_mode", False):
            self.last_status_message = f"UNIVERSAL BUILD ACCESS // {BASE_MODULE_DATA.get(self.selected_build_key, {}).get('label', self.selected_build_key)}"
            self.status_flash_timer = 1.8

    def _is_any_hud_panel_open(self) -> bool:
        return bool(
            getattr(self, "robot_panel_visible", False)
            or getattr(self, "upgrade_visible", False)
            or getattr(self, "help_visible", False)
            or getattr(self, "options_visible", False)
        )

    def _release_gameplay_keys_for_menu(self) -> None:
        for key in self.keys:
            self.keys[key] = False
        self.velocity = Vec3(0.0, 0.0, 0.0)

    def _apply_menu_input_lock(self, locked: bool, reason: str = "HUD PANEL") -> None:
        locked = bool(locked)
        if locked and not self.menu_input_locked:
            self._menu_lock_snapshot = {
                "mouse_centered": bool(getattr(self, "_mouse_centered", False)),
                "reason": reason,
            }
            self._release_gameplay_keys_for_menu()
        elif not locked and self.menu_input_locked:
            self._release_gameplay_keys_for_menu()
        self.menu_input_locked = locked
        self.menu_lock_reason = reason if locked else ""
        if self.is_offscreen:
            return
        try:
            props = WindowProperties()
            props.setCursorHidden(not locked)
            props.setMouseMode(WindowProperties.M_absolute)
            self.win.requestProperties(props)
            if locked:
                # Stop center-lock recentering so the pointer can reach DirectGUI buttons.
                self._mouse_centered = False
            else:
                # Recenter after the cursor is hidden again so camera look resumes without a jump.
                self._mouse_centered = False
                self.taskMgr.doMethodLater(0.03, self._restore_center_mouse_after_menu, "restore_center_mouse_after_menu")
        except Exception:
            pass

    def _refresh_menu_input_lock(self, reason: str = "HUD PANEL") -> None:
        self._apply_menu_input_lock(self._is_any_hud_panel_open(), reason)

    def _restore_center_mouse_after_menu(self, task: Task) -> int:
        if not self._is_any_hud_panel_open() and not self.is_offscreen:
            self._recenter_mouse()
        return Task.done

    def _set_menu_cursor(self, visible: bool) -> None:
        # Compatibility shim for older menu code; panel visibility now drives the real lock.
        self._apply_menu_input_lock(visible, "HUD PANEL")

    def _inventory_lines(self, inventory: dict[str, int], order: tuple[str, ...], limit: int = 5) -> str:
        entries = [(name, int(inventory.get(name, 0))) for name in order if int(inventory.get(name, 0)) > 0]
        if not entries:
            return "NONE"
        return "  ".join(f"{name}:{amount}" for name, amount in entries[:limit])

    def _first_inventory_item(self, inventory: dict[str, int], order: tuple[str, ...]) -> str | None:
        for name in order:
            if int(inventory.get(name, 0)) > 0:
                return name
        return None

    def _refined_for_raw(self, raw_name: str) -> str:
        return str(RESOURCE_REFINERY_DATA.get(raw_name, {}).get("refined", raw_name))

    def _resource_tool_class(self, raw_name: str) -> str:
        data = RESOURCE_REFINERY_DATA.get(raw_name, {})
        tool = str(data.get("tool", "unknown")).upper()
        klass = str(data.get("class", "RESOURCE"))
        return f"{tool} / {klass}"

    def _robot_panel_source_node(self) -> str | None:
        if 0 <= self.active_rig_index < len(self.rigs):
            rig = self.rigs[self.active_rig_index]
            node = rig.get("node")
            if self._crosshair_points_near_node(node, radius=0.28, max_distance=850.0):
                return "DRONE"
        if self.persistent_drill_drone is not None and not self.persistent_drill_drone.isEmpty():
            if self._crosshair_points_near_node(self.persistent_drill_drone, radius=0.28, max_distance=850.0):
                return "DRONE"
        # Rover click target will be added once the physical rover comes online; the
        # shared panel already uses the same action commands from either robot.
        rover = getattr(self, "support_rover", None)
        if rover is not None and hasattr(rover, "isEmpty") and not rover.isEmpty():
            if self._crosshair_points_near_node(rover, radius=0.32, max_distance=850.0):
                return "ROVER"
        return None

    def _handle_robot_or_reel_rmb(self) -> None:
        if self.menu_input_locked:
            self.keys["reel"] = False
            return
        source = self._robot_panel_source_node()
        if source is not None:
            self.open_robot_panel(source)
            return
        self._set_reel_key(True)

    def open_robot_panel(self, source: str = "DRONE") -> None:
        self.robot_panel_source = source
        self.robot_panel_visible = True
        if self.upgrade_visible:
            self.upgrade_visible = False
            self.upgrade_frame.hide()
        self.keys["reel"] = False
        self._update_robot_operations_panel()
        self.robot_frame.show()
        self._refresh_menu_input_lock(f"{source} ROBOT OPERATIONS")
        self.last_status_message = f"{source} OPERATIONS OPEN - CAMERA LOCKED / CURSOR FREE"
        self.status_flash_timer = 2.0

    def close_robot_panel(self) -> None:
        self.robot_panel_visible = False
        if hasattr(self, "robot_frame"):
            self.robot_frame.hide()
        self._refresh_menu_input_lock("ROBOT OPERATIONS CLOSED")
        self.last_status_message = "ROBOT OPERATIONS CLOSED - CAMERA CONTROLS RESTORED"
        self.status_flash_timer = 1.2

    def _send_raw_to_rover_refinery(self) -> None:
        moved = 0
        for name in RAW_RESOURCE_ORDER:
            amount = int(self.raw_inventory.get(name, 0))
            if amount <= 0:
                continue
            self.raw_inventory[name] = 0
            self.rover_raw_inventory[name] = int(self.rover_raw_inventory.get(name, 0)) + amount
            moved += amount
        if moved <= 0:
            self.last_status_message = "NO RAW CARGO READY FOR ROVER REFINERY"
            self.toast_text.setText("ROVER REFINERY // NO RAW CARGO")
            self.toast_text.setFg((1.0, 0.66, 0.42, 1.0))
        else:
            self.last_status_message = f"SENT RAW CARGO TO ROVER REFINERY x{moved}"
            self.toast_text.setText(f"ROVER RECEIVED RAW CARGO x{moved}")
            self.toast_text.setFg((0.72, 1.0, 0.92, 1.0))
        self.status_flash_timer = 2.2
        self._update_robot_operations_panel()

    def _rover_refine_duration_for(self, raw_name: str) -> float:
        data = RESOURCE_REFINERY_DATA.get(raw_name, {})
        tool = str(data.get("tool", "magnet"))
        klass = str(data.get("class", ""))
        if tool == "hook" or "CHEMISTRY" in klass or "VOLATILE" in klass:
            return ROVER_REFINING_SLOW_SECONDS
        if tool == "magnet":
            return ROVER_REFINING_FAST_SECONDS
        return ROVER_REFINING_BASE_SECONDS

    def _rover_refinery_progress_text(self) -> str:
        job = self.rover_refining_job
        if not job:
            return "[----------] 000%"
        progress = clamp(float(job.get("progress", 0.0)), 0.0, 1.0)
        filled = int(round(progress * 10.0))
        return "[" + "#" * filled + "-" * (10 - filled) + f"] {int(progress * 100):03d}%"

    def _start_rover_refining_job(self, raw_name: str) -> bool:
        amount = int(self.rover_raw_inventory.get(raw_name, 0))
        if amount <= 0:
            return False
        refined = self._refined_for_raw(raw_name)
        duration = self._rover_refine_duration_for(raw_name)
        self.rover_raw_inventory[raw_name] = amount - 1
        self.rover_refining_job = {
            "raw": raw_name,
            "refined": refined,
            "progress": 0.0,
            "elapsed": 0.0,
            "duration": duration,
            "complete": False,
        }
        self.last_status_message = f"ROVER REFINERY STARTED: {raw_name} -> {refined}"
        self.toast_text.setText(f"REFINING // {raw_name}")
        self.toast_text.setFg((0.58, 1.0, 1.0, 1.0))
        self.status_flash_timer = 2.6
        return True

    def _complete_rover_refining_job(self) -> None:
        job = self.rover_refining_job
        if not job or bool(job.get("complete", False)):
            return
        refined = str(job.get("refined", "UNKNOWN REFINED GOOD"))
        raw = str(job.get("raw", "UNKNOWN RAW MATERIAL"))
        self.rover_refined_inventory[refined] = int(self.rover_refined_inventory.get(refined, 0)) + 1
        job["progress"] = 1.0
        job["complete"] = True
        self.last_status_message = f"ROVER REFINED {raw} INTO {refined}"
        self.toast_text.setText(f"REFINED COMPLETE // {refined}")
        self.toast_text.setFg((0.58, 1.0, 1.0, 1.0))
        self.status_flash_timer = 2.4
        self._update_robot_operations_panel()
        self._update_upgrade_panel()

    def _refine_next_rover_material(self) -> None:
        if self.rover_refining_job and not bool(self.rover_refining_job.get("complete", False)):
            self.last_status_message = "ROVER REFINERY ALREADY PROCESSING - WAIT FOR PROGRESS TO COMPLETE"
            self.toast_text.setText("REFINERY BUSY // WATCH PROGRESS")
            self.toast_text.setFg((0.72, 0.96, 1.0, 1.0))
            self.status_flash_timer = 2.0
            self._update_robot_operations_panel()
            return
        raw_name = self._first_inventory_item(self.rover_raw_inventory, RAW_RESOURCE_ORDER)
        if raw_name is None:
            self.last_status_message = "ROVER HAS NO RAW MATERIAL TO REFINE"
            self.toast_text.setText("REFINERY IDLE // SEND RAW FIRST")
            self.toast_text.setFg((1.0, 0.66, 0.42, 1.0))
            self.status_flash_timer = 2.0
            self._update_robot_operations_panel()
            return
        self._start_rover_refining_job(raw_name)
        self._update_robot_operations_panel()

    def _transfer_manifest_from_rover(self) -> dict[str, int]:
        return {name: int(self.rover_refined_inventory.get(name, 0)) for name in REFINED_RESOURCE_ORDER if int(self.rover_refined_inventory.get(name, 0)) > 0}

    def _transfer_progress_text(self) -> str:
        job = self.rover_transfer_job
        if not job:
            return "[----------] 000%"
        progress = clamp(float(job.get("progress", 0.0)), 0.0, 1.0)
        filled = int(round(progress * 10.0))
        return "[" + "#" * filled + "-" * (10 - filled) + f"] {int(progress * 100):03d}%"

    def _transfer_refined_goods_to_drone(self) -> None:
        if self.rover_transfer_job and not bool(self.rover_transfer_job.get("complete", False)):
            self.last_status_message = "ROVER TRANSFER ALREADY ACTIVE - FOLLOW DOCKING PROGRESS"
            self.toast_text.setText("TRANSFER ACTIVE // ROVER DOCKING")
            self.toast_text.setFg((0.62, 0.94, 1.0, 1.0))
            self.status_flash_timer = 2.2
            self._update_robot_operations_panel()
            return
        manifest = self._transfer_manifest_from_rover()
        moved = sum(manifest.values())
        if moved <= 0:
            self.last_status_message = "NO REFINED GOODS READY TO TRANSFER"
            self.toast_text.setText("TRANSFER WAITING // REFINE GOODS FIRST")
            self.toast_text.setFg((1.0, 0.66, 0.42, 1.0))
            self.status_flash_timer = 2.2
            self._update_robot_operations_panel()
            return
        self.robot_transfer_requested = True
        self.rover_transfer_job = {
            "manifest": manifest,
            "progress": 0.0,
            "elapsed": 0.0,
            "duration": ROVER_TRANSFER_SECONDS,
            "complete": False,
            "moved": moved,
        }
        self.last_status_message = f"ROVER DOCKING TRANSFER STARTED x{moved} - DRIVE TO DRONE"
        self.toast_text.setText(f"TRANSFER STARTED // REFINED GOODS x{moved}")
        self.toast_text.setFg((0.62, 0.94, 1.0, 1.0))
        self.status_flash_timer = 2.8
        self._update_robot_operations_panel()

    def _complete_rover_transfer_job(self) -> None:
        job = self.rover_transfer_job
        if not job or bool(job.get("complete", False)):
            return
        manifest = job.get("manifest", {})
        moved = 0
        if isinstance(manifest, dict):
            for name, amount_obj in manifest.items():
                amount = int(amount_obj)
                if amount <= 0:
                    continue
                available = int(self.rover_refined_inventory.get(name, 0))
                amount = min(amount, available)
                if amount <= 0:
                    continue
                self.rover_refined_inventory[name] = available - amount
                self.resource_inventory[name] = int(self.resource_inventory.get(name, 0)) + amount
                moved += amount
        job["progress"] = 1.0
        job["complete"] = True
        self.robot_transfer_requested = False
        self.last_status_message = f"ROVER DOCKED - TRANSFER COMPLETE x{moved}"
        self.toast_text.setText(f"DRONE RECEIVED REFINED GOODS x{moved}")
        self.toast_text.setFg((0.62, 0.94, 1.0, 1.0))
        self.status_flash_timer = 3.0
        self._update_upgrade_panel()
        self._update_robot_operations_panel()

    def _open_upgrade_panel_from_robot(self) -> None:
        self.robot_panel_visible = False
        if hasattr(self, "robot_frame"):
            self.robot_frame.hide()
        if not self.upgrade_visible:
            self.toggle_upgrade_panel()
        else:
            self._refresh_menu_input_lock("UPGRADE PANEL")

    def _surface_relay_built(self) -> bool:
        return self._upgrade_level("SURFACE_RELAY") > 0

    def _fabrication_goal_text(self) -> str:
        if self._surface_relay_built():
            return "BUILD GOAL: SURFACE RELAY ONLINE - SONAR GRID EXPANDED"
        cost = dict(UPGRADE_DATA.get("SURFACE_RELAY", {}).get("cost", {}))
        have = []
        for name, amount in cost.items():
            have.append(f"{name} {int(self.resource_inventory.get(name, 0))}/{int(amount)}")
        return "BUILD GOAL: SURFACE RELAY NEEDS " + "  ".join(have)

    def _build_surface_relay_pylon(self) -> None:
        if self.surface_relay_node is not None and not self.surface_relay_node.isEmpty():
            return
        rover = getattr(self, "support_rover", None)
        if rover is not None and not rover.isEmpty():
            base = rover.getPos(self.render) + Vec3(24.0, 26.0, 0.0)
        else:
            base = self.camera.getPos(self.render) + Vec3(42.0, 48.0, 0.0)
        base.z = self.world.surface_height(base.x, base.y) + 1.0
        root = self.render.attachNewNode("surface_relay_pylon")
        root.setPos(base)
        self.surface_relay_node = root
        mast = self.loader.loadModel("models/misc/sphere")
        mast.reparentTo(root)
        mast.setScale(1.8, 1.8, 24.0)
        mast.setPos(0.0, 0.0, 24.0)
        mast.setColorScale(0.56, 0.84, 0.94, 1.0)
        mast.setLightOff(1)
        core = self.loader.loadModel("models/misc/sphere")
        core.reparentTo(root)
        core.setScale(5.8, 5.8, 3.0)
        core.setPos(0.0, 0.0, 48.0)
        core.setColorScale(0.16, 0.90, 1.0, 0.88)
        core.setTransparency(TransparencyAttrib.MAlpha)
        core.setLightOff(1)
        base_pad = self.loader.loadModel("models/misc/sphere")
        base_pad.reparentTo(root)
        base_pad.setScale(8.5, 8.5, 0.9)
        base_pad.setPos(0.0, 0.0, 1.5)
        base_pad.setColorScale(0.34, 0.58, 0.68, 1.0)
        base_pad.setLightOff(1)
        rings = LineSegs("surface_relay_signal_rings")
        rings.setThickness(1.6)
        rings.setColor(0.36, 0.96, 1.0, 0.62)
        for rz, radius in ((14.0, 9.0), (32.0, 11.0), (50.0, 13.0)):
            for i in range(65):
                a = (i / 64.0) * math.tau
                x = math.cos(a) * radius
                y = math.sin(a) * radius
                if i == 0:
                    rings.moveTo(x, y, rz)
                else:
                    rings.drawTo(x, y, rz)
        ring_np = root.attachNewNode(rings.create())
        ring_np.setTransparency(TransparencyAttrib.MAlpha)
        ring_np.setDepthWrite(False)
        ring_np.setLightOff(1)
        self._pin_no_cull(root)

    def _cost_text(self, cost: dict[str, int]) -> str:
        return " + ".join(f"{name}:{amount}" for name, amount in cost.items()) if cost else "FREE"

    def _module_count(self, key: str) -> int:
        return sum(1 for module in self.base_modules if str(module.get("key")) == key)

    def _base_power_capacity(self) -> float:
        return BASE_POWER_CAPACITY_DEFAULT + BASE_POWER_CAPACITY_PER_DOCK * self._module_count("CHARGE_DOCK")

    def _base_power_generation(self) -> float:
        solar_count = self._module_count("SOLAR_WING")
        if solar_count <= 0:
            return 0.0
        # Distant sunlight is weak near Saturn, but exposed solar wings still provide
        # a slow trickle. Dark-side positions reduce but do not completely kill it.
        player_pos = self.camera.getPos(self.render)
        dark = self._dark_side_factor_at(player_pos.x, player_pos.y) if hasattr(self, "_dark_side_factor_at") else 0.0
        return solar_count * SOLAR_POWER_PER_WING * (1.0 - dark * 0.55)

    def _can_afford_build_module(self, key: str) -> bool:
        data = BASE_MODULE_DATA.get(key, {})
        cost = dict(data.get("cost", {}))
        return all(int(self.resource_inventory.get(name, 0)) >= int(amount) for name, amount in cost.items())

    def _spend_build_module_cost(self, key: str) -> bool:
        if not self._can_afford_build_module(key):
            return False
        for name, amount in dict(BASE_MODULE_DATA[key].get("cost", {})).items():
            self.resource_inventory[name] = int(self.resource_inventory.get(name, 0)) - int(amount)
        return True

    def _select_build_module(self, key: str) -> None:
        if key not in BASE_MODULE_DATA:
            return
        self.selected_build_key = key
        self.build_mode = True
        self.last_status_message = f"BUILD MODE: {BASE_MODULE_DATA[key]['label']} SELECTED - LMB PLACE OR GRAB / G GRAB / Q,E ROTATE"
        self.status_flash_timer = 1.8
        self._refresh_build_ghost(force=True)

    def _toggle_build_mode(self) -> None:
        self.build_mode = not bool(getattr(self, "build_mode", False))
        if not self.build_mode:
            if getattr(self, "grabbed_base_module", None) is not None:
                self._release_grabbed_base_module()
            self.last_status_message = "BUILD MODE OFF - RESOURCE LOOP ACTIVE"
            self._remove_build_ghost()
            self._clear_base_snap_marker()
        else:
            label = BASE_MODULE_DATA.get(self.selected_build_key, {}).get("label", self.selected_build_key)
            self.last_status_message = f"BUILD MODE ON: {label} - LMB PLACE/GRAB, G GRAB, Q/E ROTATE"
            self._refresh_build_ghost(force=True)
        self.status_flash_timer = 1.6

    def _rotate_build_preview(self, step: int = 1) -> None:
        self.build_rotation_index = (int(getattr(self, "build_rotation_index", 0)) + step) % 4
        if getattr(self, "options_visible", False):
            return f"OPTIONS: {self.render_profile} / HUD {self.hud_style} / BLOOM {'ON' if self.render_bloom_enabled else 'OFF'}"
        grabbed = getattr(self, "grabbed_base_module", None)
        if grabbed is not None:
            grabbed["rotation_index"] = self.build_rotation_index
            node = grabbed.get("node")
            if hasattr(node, "setH"):
                node.setH(self.build_rotation_index * 90.0)
            self.last_status_message = f"MOVING {self._base_module_label(grabbed)} // ROTATION {self.build_rotation_index * 90}°"
            self.status_flash_timer = 1.2
            return
        if self.build_mode:
            self.last_status_message = f"BUILD ROTATION {self.build_rotation_index * 90}° - SNAP GRID LOCKED"
            self.status_flash_timer = 1.2
            self._refresh_build_ghost(force=True)

    def _remove_build_ghost(self) -> None:
        ghost = getattr(self, "build_ghost", None)
        if ghost is not None and not ghost.isEmpty():
            ghost.removeNode()
        self.build_ghost = None

    def _build_forward_flat(self) -> Vec3:
        try:
            forward = self.camera.getQuat(self.render).getForward()
        except Exception:
            forward = Vec3(math.sin(math.radians(self.heading)), math.cos(math.radians(self.heading)), 0.0)
        forward.z = 0.0
        if forward.length() <= 0.001:
            forward = Vec3(0.0, 1.0, 0.0)
        forward.normalize()
        return forward

    def _base_module_label(self, module: dict[str, object] | None) -> str:
        if module is None:
            return "MODULE"
        key = str(module.get("key", ""))
        return str(BASE_MODULE_DATA.get(key, {}).get("label", key or "MODULE"))

    def _flat_distance_to_module(self, pos: Vec3, module: dict[str, object]) -> float:
        other = Vec3(module.get("pos", Vec3(0.0, 0.0, 0.0)))
        return (Vec3(pos.x, pos.y, 0.0) - Vec3(other.x, other.y, 0.0)).length()

    def _aimed_base_module(self, radius: float = 0.42, max_distance: float = BASE_GRAB_MAX_DISTANCE) -> dict[str, object] | None:
        best = None
        best_score = 999.0
        for module in self.base_modules:
            node = module.get("node")
            if node is None or not hasattr(node, "isEmpty") or node.isEmpty():
                continue
            try:
                world_pos = node.getPos(self.render)
                distance = (world_pos - self.camera.getPos(self.render)).length()
                if distance > max_distance:
                    continue
                cam_pos = self.cam.getRelativePoint(self.render, world_pos)
                if cam_pos.y <= 0.0:
                    continue
                projected = Point2()
                if not self.camLens.project(cam_pos, projected):
                    continue
                score = math.hypot(float(projected.x), float(projected.y))
                # Larger modules are allowed a generous pick radius; closest to crosshair wins.
                if score <= radius and score < best_score:
                    best = module
                    best_score = score
            except Exception:
                continue
        return best

    def _magnetic_edge_snap_for_position(self, raw: Vec3, moving_module: dict[str, object] | None = None) -> tuple[Vec3, str, float]:
        best_pos = None
        best_dist = 999999.0
        for module in self.base_modules:
            if moving_module is not None and module is moving_module:
                continue
            node = module.get("node")
            if node is None or not hasattr(node, "isEmpty") or node.isEmpty():
                continue
            base = Vec3(module.get("pos", Vec3(0.0, 0.0, 0.0)))
            for dx, dy in BASE_MAGNET_SIDE_DIRS:
                sx = base.x + dx * BASE_GRID_SIZE
                sy = base.y + dy * BASE_GRID_SIZE
                dist = math.hypot(raw.x - sx, raw.y - sy)
                if dist < best_dist:
                    best_dist = dist
                    best_pos = Vec3(sx, sy, self.world.surface_height(sx, sy) + 1.0)
        if best_pos is not None and best_dist <= BASE_MAGNET_SNAP_DISTANCE:
            if moving_module is not None:
                moving_module["last_snap_pos"] = Vec3(best_pos)
            return best_pos, "EDGE SNAP", best_dist
        if moving_module is not None:
            held = moving_module.get("last_snap_pos")
            if held is not None:
                held_pos = Vec3(held)
                hold_dist = math.hypot(raw.x - held_pos.x, raw.y - held_pos.y)
                # Low-force magnetic hold: close pulls stay flush, but a deliberate
                # stronger pull breaks the snap for rearranging the base.
                if hold_dist <= BASE_MAGNET_RELEASE_DISTANCE:
                    held_pos.z = self.world.surface_height(held_pos.x, held_pos.y) + 1.0
                    return held_pos, "SOFT MAGNET HOLD", hold_dist
                moving_module.pop("last_snap_pos", None)
        free = Vec3(raw.x, raw.y, self.world.surface_height(raw.x, raw.y) + 1.0)
        return free, "FREE PULL", best_dist

    def _validate_base_module_position(self, pos: Vec3, moving_module: dict[str, object] | None = None, require_foundation: bool = False) -> tuple[bool, str]:
        if (pos - self.camera.getPos(self.render)).length() > BASE_BUILD_MAX_DISTANCE + 120.0:
            return False, "TOO FAR FROM ROBOT"
        samples = [
            self.world.surface_height(pos.x + sx, pos.y + sy)
            for sx, sy in ((-28, -28), (28, -28), (-28, 28), (28, 28), (0, 0))
        ]
        if max(samples) - min(samples) > 14.0:
            return False, "BAD SLOPE"
        for module in self.base_modules:
            if moving_module is not None and module is moving_module:
                continue
            other = Vec3(module.get("pos", Vec3(0.0, 0.0, 0.0)))
            dist = math.hypot(pos.x - other.x, pos.y - other.y)
            if dist < BASE_MAGNET_OVERLAP_DISTANCE:
                return False, "OVERLAPPING MODULE"
        if require_foundation:
            foundations = [m for m in self.base_modules if str(m.get("key")) == "FOUNDATION_PAD" and m is not moving_module]
            if not foundations:
                return False, "PLACE A FOUNDATION PAD FIRST"
        return True, "READY"

    def _grab_target_raw_position(self) -> Vec3:
        cam_pos = self.camera.getPos(self.render)
        forward = self._build_forward_flat()
        raw = cam_pos + forward * 126.0
        return Vec3(raw.x, raw.y, self.world.surface_height(raw.x, raw.y) + 1.0)

    def _begin_grab_base_module(self, module: dict[str, object] | None = None) -> bool:
        module = module or self._aimed_base_module()
        if module is None:
            self.last_status_message = "AIM AT A BASE MODULE TO GRAB IT"
            self.status_flash_timer = 1.4
            self.toast_text.setText("MAGNET GRAB // NO MODULE TARGET")
            self.toast_text.setFg((1.0, 0.70, 0.36, 1.0))
            return False
        node = module.get("node")
        if node is None or not hasattr(node, "isEmpty") or node.isEmpty():
            return False
        self.build_mode = True
        self._remove_build_ghost()
        self.grabbed_base_module = module
        self.grabbed_base_original = (Vec3(module.get("pos", node.getPos(self.render))), int(module.get("rotation_index", 0)))
        self.selected_build_key = str(module.get("key", self.selected_build_key))
        self.build_rotation_index = int(module.get("rotation_index", 0)) % 4
        self.last_status_message = f"MAGNET GRAB: {self._base_module_label(module)} - PULL TO DETACH / LMB OR G RELEASE"
        self.status_flash_timer = 2.0
        self.toast_text.setText("LOW-FORCE MAGNET GRAB // EDGE SNAP ACTIVE")
        self.toast_text.setFg((0.72, 0.96, 1.0, 1.0))
        self._update_grabbed_base_module(force=True)
        return True

    def _update_grabbed_base_module(self, force: bool = False) -> None:
        module = getattr(self, "grabbed_base_module", None)
        if module is None:
            return
        node = module.get("node")
        if node is None or not hasattr(node, "isEmpty") or node.isEmpty():
            self.grabbed_base_module = None
            self._clear_base_snap_marker()
            return
        raw = self._grab_target_raw_position()
        target_pos, snap_state, snap_dist = self._magnetic_edge_snap_for_position(raw, moving_module=module)
        valid, reason = self._validate_base_module_position(target_pos, moving_module=module)
        current = node.getPos(self.render)
        if force:
            display_pos = Vec3(target_pos)
        else:
            dt = min(globalClock.getDt(), 0.16)
            alpha = clamp(1.0 - math.exp(-BASE_MAGNET_SETTLE_RATE * dt), 0.0, 1.0)
            display_pos = current + (target_pos - current) * alpha
            display_pos.z = target_pos.z
        node.setPos(display_pos)
        node.setH(int(module.get("rotation_index", self.build_rotation_index)) * 90.0)
        # Target position is authoritative for snapping/collision. The node eases
        # toward it so movement reads like a low-force magnetic settle instead of
        # a hard teleport. Release snaps exactly to this target.
        module["pos"] = Vec3(target_pos)
        module["display_pos"] = Vec3(display_pos)
        module["target_pos"] = Vec3(target_pos)
        self.grab_preview_valid = valid
        self.grab_preview_reason = reason if not valid else snap_state
        self.grab_preview_snap_state = snap_state
        self._update_base_snap_marker(target_pos, valid, snap_state, self._base_module_label(module))
        if force or self.status_flash_timer <= 0.0:
            label = self._base_module_label(module)
            state = snap_state if valid else reason
            self.last_status_message = f"MOVING {label}: {state}"

    def _release_grabbed_base_module(self) -> bool:
        module = getattr(self, "grabbed_base_module", None)
        if module is None:
            return False
        self._update_grabbed_base_module(force=True)
        valid = bool(getattr(self, "grab_preview_valid", False))
        reason = str(getattr(self, "grab_preview_reason", ""))
        if not valid:
            self.last_status_message = f"MAGNET RELEASE BLOCKED: {reason}"
            self.status_flash_timer = 1.8
            self.toast_text.setText(f"RELEASE BLOCKED // {reason}")
            self.toast_text.setFg((1.0, 0.42, 0.26, 1.0))
            return True
        target_pos = Vec3(module.get("target_pos", module.get("pos", Vec3(0.0, 0.0, 0.0))))
        node = module.get("node")
        if hasattr(node, "setPos"):
            node.setPos(target_pos)
        module["pos"] = Vec3(target_pos)
        label = self._base_module_label(module)
        state = str(getattr(self, "grab_preview_snap_state", "FREE PULL"))
        self.grabbed_base_module = None
        self.grabbed_base_original = None
        self.last_status_message = f"PLACED: {label} // {state}"
        self.status_flash_timer = 1.8
        self.toast_text.setText(f"MAGNET SNAP // {state}")
        self.toast_text.setFg((0.66, 1.0, 0.88, 1.0))
        self._refresh_build_ghost(force=True)
        return True

    def _try_grab_or_release_base_module(self) -> bool:
        if getattr(self, "grabbed_base_module", None) is not None:
            return self._release_grabbed_base_module()
        return self._begin_grab_base_module()

    def _try_place_or_grab_build_module(self) -> bool:
        if getattr(self, "grabbed_base_module", None) is not None:
            return self._release_grabbed_base_module()
        target = self._aimed_base_module(radius=0.36, max_distance=BASE_GRAB_MAX_DISTANCE)
        if target is not None:
            return self._begin_grab_base_module(target)
        return self._try_place_build_module()

    def _snap_build_position(self, key: str | None = None) -> tuple[Vec3, bool, str]:
        key = key or self.selected_build_key
        cam_pos = self.camera.getPos(self.render)
        forward = self._build_forward_flat()
        raw = cam_pos + forward * 126.0
        x = round(raw.x / BASE_GRID_SIZE) * BASE_GRID_SIZE
        y = round(raw.y / BASE_GRID_SIZE) * BASE_GRID_SIZE
        pos = Vec3(x, y, self.world.surface_height(x, y) + 1.0)
        if key != "FOUNDATION_PAD":
            foundations = [m for m in self.base_modules if str(m.get("key")) == "FOUNDATION_PAD"]
            if not foundations:
                return pos, False, "PLACE A FOUNDATION PAD FIRST"
            edge_pos, snap_state, _snap_dist = self._magnetic_edge_snap_for_position(pos, moving_module=None)
            if snap_state == "EDGE SNAP":
                pos = edge_pos
            else:
                nearest = min(foundations, key=lambda m: (Vec3(m.get("pos", Vec3(0, 0, 0))) - Vec3(x, y, 0)).lengthSquared())
                base = Vec3(nearest.get("pos", Vec3(x, y, 0)))
                delta = Vec3(x - base.x, y - base.y, 0.0)
                if delta.length() <= 0.001:
                    delta = forward
                if abs(delta.x) > abs(delta.y):
                    x = base.x + (BASE_GRID_SIZE if delta.x >= 0.0 else -BASE_GRID_SIZE)
                    y = base.y
                else:
                    x = base.x
                    y = base.y + (BASE_GRID_SIZE if delta.y >= 0.0 else -BASE_GRID_SIZE)
                pos = Vec3(x, y, self.world.surface_height(x, y) + 1.0)
        if (pos - cam_pos).length() > BASE_BUILD_MAX_DISTANCE:
            return pos, False, "TOO FAR FROM ROBOT"
        valid, reason = self._validate_base_module_position(pos, moving_module=None, require_foundation=False)
        if not valid:
            return pos, False, reason
        return pos, True, "EDGE SNAP READY"

    def _make_build_card(self, parent: NodePath, name: str, width: float, height: float, texture_key: str, color: tuple[float, float, float, float], pos: tuple[float, float, float], hpr: tuple[float, float, float], preview: bool = False) -> NodePath:
        cm = CardMaker(name)
        cm.setFrame(-width * 0.5, width * 0.5, -height * 0.5, height * 0.5)
        card = parent.attachNewNode(cm.generate())
        card.setPos(*pos)
        card.setHpr(*hpr)
        card.setTexture(self._load_texture(self.texture_paths[texture_key], repeat=True, clamp=False))
        alpha = color[3] * (0.44 if preview else 1.0)
        card.setColorScale(color[0], color[1], color[2], alpha)
        card.setTransparency(TransparencyAttrib.MAlpha)
        card.setTwoSided(True)
        card.setLightOff(1)
        if preview:
            card.setDepthWrite(False)
            card.setBin("transparent", 76)
        return card

    def _add_build_post(self, parent: NodePath, x: float, y: float, z: float, height: float, color: tuple[float, float, float, float], preview: bool = False) -> NodePath:
        post = self.loader.loadModel("models/misc/sphere")
        post.reparentTo(parent)
        post.setScale(1.5, 1.5, height * 0.5)
        post.setPos(x, y, z + height * 0.5)
        post.setColorScale(color[0], color[1], color[2], color[3] * (0.46 if preview else 1.0))
        if preview or color[3] < 1.0:
            post.setTransparency(TransparencyAttrib.MAlpha)
        post.setLightOff(1)
        return post

    def _build_base_module_visual(self, root: NodePath, key: str, preview: bool = False, valid: bool = True) -> None:
        tint = (0.52, 0.94, 1.0, 0.58) if valid else (1.0, 0.25, 0.18, 0.56)
        metal = (0.72, 0.86, 0.92, 1.0) if not preview else tint
        dark_metal = (0.36, 0.48, 0.55, 1.0) if not preview else tint
        if key == "FOUNDATION_PAD":
            self._make_build_card(root, "foundation_sheet_metal_two_sided", 74.0, 74.0, "sheet_metal", metal, (0.0, 0.0, 1.2), (0.0, -90.0, 0.0), preview)
            border = LineSegs("foundation_snap_border")
            border.setThickness(2.0 if not preview else 1.4)
            border.setColor(*(tint if preview else (0.42, 0.92, 1.0, 0.62)))
            for x, y in [(-37,-37),(37,-37),(37,37),(-37,37),(-37,-37)]:
                if x == -37 and y == -37:
                    border.moveTo(x,y,2.0)
                else:
                    border.drawTo(x,y,2.0)
            np = root.attachNewNode(border.create())
            np.setTransparency(TransparencyAttrib.MAlpha)
            np.setLightOff(1)
        elif key == "SHEET_SHELTER":
            # Foundation strip under the shelter so it snaps visually into the base grid.
            self._make_build_card(root, "shelter_floor_lip", 74.0, 74.0, "sheet_metal", dark_metal, (0.0, 0.0, 1.0), (0.0, -90.0, 0.0), preview)
            # Two-sided sheet-metal roof and windward side panels; robots use this as debris cover.
            self._make_build_card(root, "shelter_roof_two_sided", 76.0, 72.0, "sheet_metal", metal, (0.0, 0.0, 34.0), (0.0, -90.0, 0.0), preview)
            self._make_build_card(root, "shelter_back_panel_two_sided", 76.0, 30.0, "sheet_metal", (0.66,0.78,0.84,1.0) if not preview else tint, (0.0, 36.0, 17.5), (0.0, 0.0, 0.0), preview)
            side_a = self._make_build_card(root, "shelter_side_panel_a_two_sided", 72.0, 24.0, "sheet_metal", (0.60,0.72,0.78,1.0) if not preview else tint, (-38.0, 0.0, 16.0), (90.0, 0.0, 0.0), preview)
            side_b = self._make_build_card(root, "shelter_side_panel_b_two_sided", 72.0, 24.0, "sheet_metal", (0.60,0.72,0.78,1.0) if not preview else tint, (38.0, 0.0, 16.0), (90.0, 0.0, 0.0), preview)
            for x in (-31.0, 31.0):
                for y in (-30.0, 30.0):
                    self._add_build_post(root, x, y, 1.0, 32.0, (0.48,0.68,0.76,1.0) if not preview else tint, preview)
        elif key == "SOLAR_WING":
            self._make_build_card(root, "solar_base_plate", 74.0, 54.0, "sheet_metal", dark_metal, (0.0, 0.0, 1.1), (0.0, -90.0, 0.0), preview)
            # Slight tilt toward the sky; still two-sided so panels do not vanish from the back.
            self._make_build_card(root, "solar_panel_left_two_sided", 54.0, 34.0, "solar_panel", (0.76,0.96,1.0,1.0) if not preview else tint, (-28.0, 0.0, 17.5), (0.0, -58.0, 0.0), preview)
            self._make_build_card(root, "solar_panel_right_two_sided", 54.0, 34.0, "solar_panel", (0.76,0.96,1.0,1.0) if not preview else tint, (28.0, 0.0, 17.5), (180.0, -58.0, 0.0), preview)
            self._add_build_post(root, 0.0, 0.0, 1.0, 18.0, (0.48,0.68,0.76,1.0) if not preview else tint, preview)
        elif key == "CHARGE_DOCK":
            self._make_build_card(root, "charge_dock_pad_two_sided", 74.0, 74.0, "sheet_metal", dark_metal, (0.0, 0.0, 1.15), (0.0, -90.0, 0.0), preview)
            ring = LineSegs("charge_dock_ring")
            ring.setThickness(2.2)
            ring.setColor(*(tint if preview else (0.28, 0.94, 1.0, 0.82)))
            for i in range(65):
                a = i / 64.0 * math.tau
                x = math.cos(a) * 23.0
                y = math.sin(a) * 23.0
                if i == 0:
                    ring.moveTo(x, y, 2.6)
                else:
                    ring.drawTo(x, y, 2.6)
            np = root.attachNewNode(ring.create())
            np.setTransparency(TransparencyAttrib.MAlpha)
            np.setLightOff(1)
            core = self.loader.loadModel("models/misc/sphere")
            core.reparentTo(root)
            core.setScale(8.0, 8.0, 3.0)
            core.setPos(0.0, 0.0, 6.5)
            core.setColorScale(*(tint if preview else (0.18, 0.88, 1.0, 0.78)))
            core.setTransparency(TransparencyAttrib.MAlpha)
            core.setLightOff(1)

    def _clear_base_snap_marker(self) -> None:
        root = getattr(self, "base_snap_marker_root", None)
        if root is not None and not root.isEmpty():
            root.removeNode()
        self.base_snap_marker_root = None

    def _update_base_snap_marker(self, pos: Vec3, valid: bool, state: str, label: str = "MODULE") -> None:
        self._clear_base_snap_marker()
        if not bool(getattr(self, "build_mode", False)) and getattr(self, "grabbed_base_module", None) is None:
            return
        root = self.render.attachNewNode("base_snap_quality_marker")
        root.setPos(pos.x, pos.y, self.world.surface_height(pos.x, pos.y) + 2.0)
        self.base_snap_marker_root = root
        half = BASE_SNAP_EDGE_VISUAL_SIZE * 0.5
        segs = LineSegs("base_snap_quality_lines")
        segs.setThickness(2.8 if valid else 3.4)
        if not valid:
            color = (1.0, 0.34, 0.22, 0.78)
        elif "HOLD" in state:
            color = (0.42, 0.96, 1.0, 0.58)
        elif "EDGE" in state:
            color = (0.50, 1.0, 0.72, 0.68)
        else:
            color = (0.52, 0.82, 1.0, 0.42)
        segs.setColor(*color)
        corners = [(-half, -half, 0.0), (half, -half, 0.0), (half, half, 0.0), (-half, half, 0.0), (-half, -half, 0.0)]
        for i, corner in enumerate(corners):
            if i == 0:
                segs.moveTo(*corner)
            else:
                segs.drawTo(*corner)
        # Short edge ticks make the exact magnetic contact points readable.
        tick = 9.0
        for x1, y1, x2, y2 in ((0, -half, 0, -half + tick), (half, 0, half - tick, 0), (0, half, 0, half - tick), (-half, 0, -half + tick, 0)):
            segs.moveTo(x1, y1, 0.12)
            segs.drawTo(x2, y2, 0.12)
        np = root.attachNewNode(segs.create())
        np.setTransparency(TransparencyAttrib.MAlpha)
        np.setDepthWrite(False)
        np.setLightOff(1)
        self._pin_no_cull(root)

    def _refresh_build_ghost(self, force: bool = False) -> None:
        if not self.build_mode:
            self._remove_build_ghost()
            self._clear_base_snap_marker()
            return
        if not force and getattr(self, "_build_preview_timer", 0.0) > 0.0:
            return
        self._build_preview_timer = 0.12
        pos, valid, reason = self._snap_build_position(self.selected_build_key)
        self._remove_build_ghost()
        ghost = self.render.attachNewNode("build_preview_ghost")
        ghost.setPos(pos)
        ghost.setH(self.build_rotation_index * 90.0)
        self._build_base_module_visual(ghost, self.selected_build_key, preview=True, valid=valid)
        self.build_ghost = ghost
        self.build_preview_valid = valid
        self.build_preview_reason = reason
        self._update_base_snap_marker(pos, valid, reason, BASE_MODULE_DATA.get(self.selected_build_key, {}).get("label", self.selected_build_key))

    def _update_build_preview(self, task: Task) -> int:
        dt = min(globalClock.getDt(), 0.16)
        self._build_preview_timer = max(0.0, float(getattr(self, "_build_preview_timer", 0.0)) - dt)
        if getattr(self, "grabbed_base_module", None) is not None:
            self._update_grabbed_base_module()
        elif self.build_mode:
            self._refresh_build_ghost()
        return Task.cont

    def _place_base_module_at(self, key: str, pos: Vec3, rotation_index: int = 0, free: bool = False) -> bool:
        if key not in BASE_MODULE_DATA:
            return False
        if not free and not self._spend_build_module_cost(key):
            data = BASE_MODULE_DATA[key]
            self.last_status_message = f"NEED MATERIALS FOR {data['label']}: {self._cost_text(dict(data.get('cost', {})))}"
            self.status_flash_timer = 2.2
            self.toast_text.setText("BUILD BLOCKED // REFINE MORE RESOURCES")
            self.toast_text.setFg((1.0, 0.58, 0.30, 1.0))
            return False
        root = self.render.attachNewNode(f"base_module_{key.lower()}_{len(self.base_modules)}")
        root.setPos(pos)
        root.setH(rotation_index * 90.0)
        self._build_base_module_visual(root, key, preview=False, valid=True)
        self._pin_no_cull(root)
        self.base_modules.append({"key": key, "node": root, "pos": Vec3(pos), "rotation_index": rotation_index})
        label = BASE_MODULE_DATA[key]["label"]
        self.last_status_message = f"BUILT: {label} - SNAP GRID MODULE ONLINE"
        self.status_flash_timer = 2.0
        self.toast_text.setText(f"BASE MODULE // {label}")
        self.toast_text.setFg((0.72, 1.0, 0.86, 1.0))
        self._update_upgrade_panel()
        return True

    def _try_place_build_module(self) -> bool:
        if not self.build_mode:
            return False
        pos, valid, reason = self._snap_build_position(self.selected_build_key)
        if not valid:
            self.last_status_message = f"BUILD INVALID: {reason}"
            self.status_flash_timer = 1.6
            self.toast_text.setText(f"SNAP BLOCKED // {reason}")
            self.toast_text.setFg((1.0, 0.44, 0.28, 1.0))
            self._refresh_build_ghost(force=True)
            return True
        self._place_base_module_at(self.selected_build_key, pos, self.build_rotation_index)
        self._refresh_build_ghost(force=True)
        return True

    def _is_under_shelter(self, pos: Vec3 | None = None) -> bool:
        pos = pos or self.camera.getPos(self.render)
        for module in self.base_modules:
            if str(module.get("key")) != "SHEET_SHELTER":
                continue
            mpos = Vec3(module.get("pos", Vec3(0,0,0)))
            rot = math.radians(int(module.get("rotation_index", 0)) * 90.0)
            dx = pos.x - mpos.x
            dy = pos.y - mpos.y
            ca = math.cos(-rot)
            sa = math.sin(-rot)
            lx = dx * ca - dy * sa
            ly = dx * sa + dy * ca
            # Shelter cover is now rectangular and orientation-aware. It protects
            # robots only when they are actually under the sheet-metal roof.
            if abs(lx) <= 37.0 and abs(ly) <= 35.0 and -8.0 <= (pos.z - mpos.z) <= 58.0:
                return True
        return False

    def _nearest_charge_dock_position(self, pos: Vec3 | None = None) -> Vec3 | None:
        pos = pos or self.camera.getPos(self.render)
        best = None
        best_dist = 999999.0
        for module in self.base_modules:
            if str(module.get("key")) != "CHARGE_DOCK":
                continue
            mpos = Vec3(module.get("pos", Vec3(0,0,0)))
            dist = (Vec3(pos.x, pos.y, 0.0) - Vec3(mpos.x, mpos.y, 0.0)).length()
            if dist < 66.0 and dist < best_dist:
                best = mpos
                best_dist = dist
        return best

    def _clear_charge_link_fx(self) -> None:
        root = getattr(self, "charge_link_root", None)
        if root is not None and not root.isEmpty():
            root.removeNode()
        self.charge_link_root = None

    def _update_charge_link_fx(self, dock_pos: Vec3, task_time: float) -> None:
        self._charge_link_timer = max(0.0, float(getattr(self, "_charge_link_timer", 0.0)) - min(globalClock.getDt(), 0.16))
        if self._charge_link_timer > 0.0:
            return
        self._charge_link_timer = 0.12
        self._clear_charge_link_fx()
        player = self.camera.getPos(self.render)
        root = self.render.attachNewNode("charge_dock_robot_link_fx")
        self.charge_link_root = root
        segs = LineSegs("charge_link_lines")
        pulse = 0.5 + 0.5 * math.sin(task_time * 8.0)
        segs.setThickness(2.2 + pulse * 1.4)
        segs.setColor(0.30, 0.96, 1.0, 0.34 + pulse * 0.28)
        start = Vec3(dock_pos.x, dock_pos.y, self.world.surface_height(dock_pos.x, dock_pos.y) + 8.0)
        end = Vec3(player.x, player.y, player.z - 8.0)
        mid = (start + end) * 0.5 + Vec3(0.0, 0.0, 5.0 + pulse * 2.0)
        segs.moveTo(start)
        segs.drawTo(mid)
        segs.drawTo(end)
        np = root.attachNewNode(segs.create())
        np.setTransparency(TransparencyAttrib.MAlpha)
        np.setDepthWrite(False)
        np.setLightOff(1)

    def _near_charge_dock(self, pos: Vec3 | None = None) -> bool:
        return self._nearest_charge_dock_position(pos) is not None

    def _update_base_power_system(self, task: Task) -> int:
        dt = min(globalClock.getDt(), 0.16)
        capacity = self._base_power_capacity()
        generation = self._base_power_generation()
        self.base_power_stored = clamp(float(getattr(self, "base_power_stored", 0.0)) + generation * dt, 0.0, capacity)
        self.robot_charge = clamp(float(getattr(self, "robot_charge", 100.0)) - ROBOT_CHARGE_DRAIN_PER_SEC * dt, 0.0, 100.0)
        dock_pos = self._nearest_charge_dock_position()
        if dock_pos is not None and self.base_power_stored > 0.0 and self.robot_charge < 100.0:
            transfer = min(ROBOT_CHARGE_DOCK_RATE * dt, self.base_power_stored, 100.0 - self.robot_charge)
            self.base_power_stored -= transfer
            self.robot_charge += transfer
            self._update_charge_link_fx(dock_pos, task.time)
            if self.status_flash_timer <= 0.0:
                self.last_status_message = "CHARGE DOCK LINKED - ROBOT BATTERIES TOPPING OFF"
        else:
            self._clear_charge_link_fx()
        return Task.cont

    def _spawn_falling_hazard(self) -> None:
        if len(self.falling_hazards) >= FALLING_HAZARD_MAX_ACTIVE:
            return
        player = self.camera.getPos(self.render)
        use_plume = bool(getattr(self, "active_plumes", [])) and random.random() < 0.62
        if use_plume:
            plume = random.choice(self.active_plumes)
            base_x = float(plume.get("x", player.x))
            base_y = float(plume.get("y", player.y))
            angle = random.random() * math.tau
            dist = 120.0 + random.random() * 520.0
            x = base_x + math.cos(angle) * dist
            y = base_y + math.sin(angle) * dist
        else:
            angle = random.random() * math.tau
            dist = 75.0 + random.random() * 185.0
            x = player.x + math.cos(angle) * dist
            y = player.y + math.sin(angle) * dist
        ground_z = self.world.surface_height(x, y)
        kind = "liquid" if random.random() < FALLING_HAZARD_LIQUID_CHANCE else "debris"
        node = self.render.attachNewNode(f"falling_{kind}_{len(self.falling_hazards)}")
        body = self.loader.loadModel("models/misc/sphere")
        body.reparentTo(node)
        if kind == "liquid":
            body.setScale(2.2, 2.2, 10.0)
            body.setColorScale(0.34, 0.92, 1.0, 0.58)
            body.setTransparency(TransparencyAttrib.MAlpha)
        else:
            body.setScale(5.0, 4.0, 3.0)
            body.setColorScale(0.42, 0.44, 0.42, 1.0)
        body.setLightOff(1)
        node.setPos(x, y, ground_z + 310.0 + random.random() * 190.0)
        warning = self.render.attachNewNode(f"{kind}_impact_warning")
        warning.setPos(x, y, ground_z + 1.3)
        wr = LineSegs("impact_warning_ring")
        wr.setThickness(2.4)
        wr.setColor(*( (0.34, 0.96, 1.0, 0.62) if kind == "liquid" else (1.0, 0.68, 0.36, 0.58) ))
        radius = 18.0 if kind == "liquid" else 14.0
        for i in range(57):
            a = i / 56.0 * math.tau
            px, py = math.cos(a) * radius, math.sin(a) * radius
            if i == 0:
                wr.moveTo(px, py, 0.0)
            else:
                wr.drawTo(px, py, 0.0)
        wnp = warning.attachNewNode(wr.create())
        wnp.setTransparency(TransparencyAttrib.MAlpha)
        wnp.setDepthWrite(False)
        wnp.setLightOff(1)
        self.falling_hazards.append({"node": node, "warning": warning, "kind": kind, "x": x, "y": y, "ground_z": ground_z, "speed": 185.0 + random.random() * 85.0, "warn_time": 0.0})

    def _spawn_hazard_impact_ring(self, x: float, y: float, z: float, kind: str) -> None:
        root = self.render.attachNewNode(f"{kind}_impact_ring")
        root.setPos(x, y, z + 0.8)
        segs = LineSegs("impact_ring_lines")
        segs.setThickness(2.0)
        segs.setColor(*( (0.42, 0.96, 1.0, 0.56) if kind == "liquid" else (0.86, 0.80, 0.68, 0.46) ))
        for i in range(49):
            a = i / 48.0 * math.tau
            r = 12.0 if kind == "liquid" else 9.0
            px, py = math.cos(a) * r, math.sin(a) * r
            if i == 0:
                segs.moveTo(px, py, 0.0)
            else:
                segs.drawTo(px, py, 0.0)
        np = root.attachNewNode(segs.create())
        np.setTransparency(TransparencyAttrib.MAlpha)
        np.setLightOff(1)
        self.taskMgr.doMethodLater(1.4, lambda task, n=root: (n.removeNode(), Task.done)[1], f"remove_{kind}_impact")

    def _animate_falling_hazards(self, task: Task) -> int:
        dt = min(globalClock.getDt(), 0.16)
        self.falling_hazard_timer -= dt
        if self.falling_hazard_timer <= 0.0:
            self._spawn_falling_hazard()
            plume_pressure = 0.72 if getattr(self, "active_plumes", []) else 1.0
            self.falling_hazard_timer = (FALLING_HAZARD_MIN_DELAY + random.random() * (FALLING_HAZARD_MAX_DELAY - FALLING_HAZARD_MIN_DELAY)) * plume_pressure * float(getattr(self, "hazard_delay_multiplier", 1.0))
        player = self.camera.getPos(self.render)
        remaining = []
        for hazard in self.falling_hazards:
            node = hazard.get("node")
            if node is None or not hasattr(node, "isEmpty") or node.isEmpty():
                continue
            speed = float(hazard.get("speed", 220.0))
            node.setZ(node.getZ() - speed * dt)
            node.setH(node.getH() + 82.0 * dt)
            warning = hazard.get("warning")
            hazard["warn_time"] = float(hazard.get("warn_time", 0.0)) + dt
            if hasattr(warning, "setScale"):
                pulse = 1.0 + math.sin(float(hazard.get("warn_time", 0.0)) * 8.0) * 0.10
                warning.setScale(pulse)
                warning.setH(warning.getH() + 36.0 * dt)
            x = float(hazard.get("x", 0.0))
            y = float(hazard.get("y", 0.0))
            kind = str(hazard.get("kind", "debris"))
            warn_distance = (Vec3(player.x, player.y, 0.0) - Vec3(x, y, 0.0)).length()
            if warn_distance < 92.0 and self.status_flash_timer <= 0.0:
                self.last_status_message = f"PLUME {kind.upper()} WARNING - MOVE UNDER SHEET-METAL SHELTER"
                self.status_flash_timer = 0.9
            if node.getZ() <= float(hazard.get("ground_z", 0.0)) + 4.0:
                if hasattr(warning, "removeNode"):
                    warning.removeNode()
                self._spawn_hazard_impact_ring(x, y, float(hazard.get("ground_z", 0.0)), kind)
                hit_distance = (Vec3(player.x, player.y, 0.0) - Vec3(x, y, 0.0)).length()
                if hit_distance < (38.0 if kind == "debris" else 48.0):
                    if self._is_under_shelter(player):
                        self.last_status_message = "SHEET-METAL SHELTER DEFLECTED FALLING PLUME MATERIAL"
                        self.status_flash_timer = 1.8
                    else:
                        damage = 8.0 if kind == "debris" else 5.0
                        self.robot_charge = clamp(float(getattr(self, "robot_charge", 100.0)) - damage, 0.0, 100.0)
                        self.last_status_message = f"{kind.upper()} IMPACT - ROBOT CHARGE LOST. BUILD SHELTER COVER."
                        self.status_flash_timer = 2.2
                node.removeNode()
            else:
                remaining.append(hazard)
        self.falling_hazards = remaining
        return Task.cont

    def _run_runtime_sanity_checks(self, task: Task) -> int:
        """Lightweight QC watchdog for runtime-only systems.

        This pass does not rewrite gameplay. It periodically trims stale FX, clamps
        power/charge values, and repairs small placement drift so performance and
        base-building do not slowly degrade during long demo sessions.
        """
        dt = min(globalClock.getDt(), 0.25)
        self._qc_sanity_elapsed = float(getattr(self, "_qc_sanity_elapsed", 999.0)) + dt
        if self._qc_sanity_elapsed < QC_SANITY_INTERVAL:
            return Task.cont
        self._qc_sanity_elapsed = 0.0
        fixes = 0

        # Keep robot/base power sane for UI, recharge, and demo persistence later.
        old_charge = float(getattr(self, "robot_charge", 0.0))
        old_power = float(getattr(self, "base_power_stored", 0.0))
        capacity = max(float(self._base_power_capacity()), 1.0)
        self.robot_charge = clamp(old_charge, 0.0, 100.0)
        self.base_power_stored = clamp(old_power, 0.0, capacity)
        if abs(self.robot_charge - old_charge) > 0.001 or abs(self.base_power_stored - old_power) > 0.001:
            fixes += 1

        # Remove dead/unknown module entries and gently re-seat modules to the current terrain.
        cleaned_modules: list[dict[str, object]] = []
        seen_cells: set[tuple[int, int, str]] = set()
        for module in list(getattr(self, "base_modules", []))[:QC_BASE_MODULE_LIMIT]:
            key = str(module.get("key", ""))
            node = module.get("node")
            if key not in BASE_MODULE_DATA or node is None or not hasattr(node, "isEmpty") or node.isEmpty():
                fixes += 1
                continue
            pos = Vec3(module.get("pos", node.getPos(self.render)))
            pos.x = clamp(pos.x, -WORLD_HALF + BASE_GRID_SIZE, WORLD_HALF - BASE_GRID_SIZE)
            pos.y = clamp(pos.y, -WORLD_HALF + BASE_GRID_SIZE, WORLD_HALF - BASE_GRID_SIZE)
            target_z = self.world.surface_height(pos.x, pos.y) + 1.0
            cell_key = (int(round(pos.x / BASE_GRID_SIZE)), int(round(pos.y / BASE_GRID_SIZE)), key)
            if cell_key in seen_cells:
                # Same type on the same grid cell is almost always a stale duplicate from a bad grab/release.
                try:
                    node.removeNode()
                except Exception:
                    pass
                fixes += 1
                continue
            seen_cells.add(cell_key)
            if abs(pos.z - target_z) > QC_MODULE_Z_TOLERANCE:
                pos.z = target_z
                node.setPos(pos)
                module["pos"] = Vec3(pos)
                fixes += 1
            cleaned_modules.append(module)
        overflow = len(getattr(self, "base_modules", [])) - len(cleaned_modules)
        if overflow > 0:
            fixes += max(0, overflow - fixes)
        self.base_modules = cleaned_modules

        # Clear orphaned build visuals when build mode/grab state is inactive.
        if not bool(getattr(self, "build_mode", False)) and getattr(self, "grabbed_base_module", None) is None:
            ghost = getattr(self, "build_ghost", None)
            if ghost is not None and hasattr(ghost, "isEmpty") and not ghost.isEmpty():
                self._remove_build_ghost()
                fixes += 1
            marker = getattr(self, "base_snap_marker_root", None)
            if marker is not None and hasattr(marker, "isEmpty") and not marker.isEmpty():
                self._clear_base_snap_marker()
                fixes += 1

        # Trim stale falling hazards/warnings so long-running sessions do not accumulate transparent nodes.
        active_hazards = []
        for hazard in list(getattr(self, "falling_hazards", [])):
            node = hazard.get("node")
            age = float(hazard.get("warn_time", 0.0))
            if node is None or not hasattr(node, "isEmpty") or node.isEmpty() or age > QC_HAZARD_LIFETIME_LIMIT:
                try:
                    if node is not None and hasattr(node, "removeNode"):
                        node.removeNode()
                    warning = hazard.get("warning")
                    if warning is not None and hasattr(warning, "removeNode"):
                        warning.removeNode()
                except Exception:
                    pass
                fixes += 1
                continue
            active_hazards.append(hazard)
        if len(active_hazards) > FALLING_HAZARD_MAX_ACTIVE:
            for hazard in active_hazards[FALLING_HAZARD_MAX_ACTIVE:]:
                node = hazard.get("node")
                warning = hazard.get("warning")
                if node is not None and hasattr(node, "removeNode"):
                    node.removeNode()
                if warning is not None and hasattr(warning, "removeNode"):
                    warning.removeNode()
                fixes += 1
            active_hazards = active_hazards[:FALLING_HAZARD_MAX_ACTIVE]
        self.falling_hazards = active_hazards

        self.qc_last_issue_count = fixes
        if fixes:
            self.qc_total_fixes = int(getattr(self, "qc_total_fixes", 0)) + fixes
            self.qc_last_report = f"QC FIXED {fixes}"
        else:
            self.qc_last_report = "QC OK"
        if getattr(self, "options_visible", False):
            self._update_options_panel()
        return Task.cont

    def _update_robot_operations_panel(self) -> None:
        if not hasattr(self, "robot_text"):
            return
        current_raw = self._first_inventory_item(self.raw_inventory, RAW_RESOURCE_ORDER)
        next_rover_raw = self._first_inventory_item(self.rover_raw_inventory, RAW_RESOURCE_ORDER)
        raw_class = self._resource_tool_class(current_raw) if current_raw else "NONE"
        next_refine = f"{next_rover_raw} -> {self._refined_for_raw(next_rover_raw)}" if next_rover_raw else "NONE"
        transferred = self._inventory_lines(self.resource_inventory, REFINED_RESOURCE_ORDER, limit=4)
        transfer_job = self.rover_transfer_job or {}
        if transfer_job:
            transfer_state = "COMPLETE / DOCKED" if bool(transfer_job.get("complete", False)) else "ACTIVE DOCKING"
            transfer_count = int(transfer_job.get("moved", 0))
        else:
            transfer_state = "IDLE"
            transfer_count = 0
        job = self.rover_refining_job or {}
        if job:
            job_raw = str(job.get("raw", "NONE"))
            job_refined = str(job.get("refined", "NONE"))
            job_state = "COMPLETE / READY" if bool(job.get("complete", False)) else "ACTIVE"
            job_line = f"{job_raw} -> {job_refined}"
        else:
            job_state = "IDLE"
            job_line = "NONE"
        lines = [
            f"SOURCE: {self.robot_panel_source}  |  SAME PANEL FROM DRONE OR ROVER",
            f"MENU INPUT LOCK: {'ACTIVE - CAMERA FROZEN / CURSOR FREE' if self.menu_input_locked else 'OFF'}",
            "",
            "TOOL-SPECIFIC COLLECTION:",
            "  MAGNET -> magnetic metals / upgrade alloys",
            "  GRAPPLE -> hard nonmagnetic minerals / cores / crystals",
            "  SAMPLE TETHER -> plume ice chemistry / brittle deposits",
            "",
            f"PLAYER RAW CARGO: {self._inventory_lines(self.raw_inventory, RAW_RESOURCE_ORDER, limit=4)}",
            f"  Current cargo class: {raw_class}",
            f"ROVER RAW STORAGE: {self._inventory_lines(self.rover_raw_inventory, RAW_RESOURCE_ORDER, limit=4)}",
            f"ROVER REFINED STORAGE: {self._inventory_lines(self.rover_refined_inventory, REFINED_RESOURCE_ORDER, limit=4)}",
            f"DRONE UPGRADE GOODS: {transferred}",
            self._fabrication_goal_text(),
            "",
            f"REFINERY JOB: {job_line}",
            f"REFINERY STATE: {job_state}  {self._rover_refinery_progress_text()}",
            f"NEXT QUEUED BATCH: {next_refine}",
            f"TRANSFER STATE: {transfer_state} x{transfer_count}  {self._transfer_progress_text()}",
            f"ROVER NAV: {getattr(self, 'rover_nav_state', 'OFFLINE')}",
            "BUTTONS: send raw -> refine next -> transfer to drone -> open upgrades",
            "PASS 89 LOOP: scan resources -> drill -> collect -> refine -> transfer -> fabricate relay/upgrades.",
        ]
        self.robot_text.setText("\n".join(lines))

    def toggle_upgrade_panel(self) -> None:
        self.upgrade_visible = not bool(getattr(self, "upgrade_visible", False))
        if self.upgrade_visible:
            if bool(getattr(self, "robot_panel_visible", False)):
                self.robot_panel_visible = False
                if hasattr(self, "robot_frame"):
                    self.robot_frame.hide()
            self._update_upgrade_panel()
            self.upgrade_frame.show()
            self.last_status_message = "UPGRADE PANEL OPEN - CAMERA LOCKED / CURSOR FREE"
        else:
            self.upgrade_frame.hide()
            self.last_status_message = "UPGRADE PANEL CLOSED - CAMERA CONTROLS RESTORED"
        self.status_flash_timer = 1.5
        self._refresh_menu_input_lock("UPGRADE PANEL")

    def _upgrade_level(self, key: str) -> int:
        return int(self.upgrades.get(key, 0))

    def _upgrade_cost_text(self, cost: dict[str, int]) -> str:
        return " + ".join(f"{name}:{amount}" for name, amount in cost.items())

    def _can_afford_upgrade(self, key: str) -> bool:
        data = UPGRADE_DATA.get(key, {})
        cost = dict(data.get("cost", {}))
        return all(int(self.resource_inventory.get(name, 0)) >= int(amount) for name, amount in cost.items())

    def _spend_upgrade_cost(self, key: str) -> bool:
        if self._upgrade_level(key) > 0:
            return False
        if not self._can_afford_upgrade(key):
            return False
        cost = dict(UPGRADE_DATA[key].get("cost", {}))
        for name, amount in cost.items():
            self.resource_inventory[name] = int(self.resource_inventory.get(name, 0)) - int(amount)
        return True

    def _try_purchase_upgrade(self, key: str) -> None:
        if key not in UPGRADE_DATA:
            return
        data = UPGRADE_DATA[key]
        if self._upgrade_level(key) > 0:
            self.last_status_message = f"{data['label']} ALREADY INSTALLED"
            self.status_flash_timer = 1.4
            self._update_upgrade_panel()
            return
        if not self._spend_upgrade_cost(key):
            self.last_status_message = f"NEED REFINED GOODS FOR {data['label']}: {self._upgrade_cost_text(dict(data.get('cost', {})))}"
            self.status_flash_timer = 2.2
            self.toast_text.setText("UPGRADE BLOCKED // REFINE GOODS FIRST")
            self.toast_text.setFg((1.0, 0.58, 0.30, 1.0))
            self._update_upgrade_panel()
            return
        self.upgrades[key] = 1
        if key == "SURFACE_RELAY":
            self._build_surface_relay_pylon()
            self.last_status_message = "FABRICATED: SURFACE RELAY PYLON - SONAR GRID EXPANDED"
            self.toast_text.setText("BUILD COMPLETE // SURFACE RELAY ONLINE")
        else:
            self.last_status_message = f"FABRICATED: {data['label']}"
            self.toast_text.setText(f"UPGRADE INSTALLED // {data['label']}")
        self.status_flash_timer = 2.8
        self.toast_text.setFg((0.78, 1.0, 0.82, 1.0))
        self._update_upgrade_panel()

    def _update_upgrade_panel(self) -> None:
        if not hasattr(self, "upgrade_text"):
            return
        lines = [self._resource_summary_text(all_resources=True), ""]
        for key, data in UPGRADE_DATA.items():
            installed = self._upgrade_level(key) > 0
            afford = self._can_afford_upgrade(key)
            state = "INSTALLED" if installed else ("READY" if afford else "NEED")
            lines.append(f"{data['key']}  {data['label']}  [{state}]")
            lines.append(f"   Cost: {self._upgrade_cost_text(dict(data.get('cost', {})))}")
            lines.append(f"   Effect: {data['desc']}")
        lines.append("")
        lines.append("Use Robot Operations to refine raw cargo, transfer goods to drone, then press 2/3/4/5 here.")
        lines.append("5 builds the Surface Relay. B opens snap build mode; 6/7/8/9 select modules; G grabs/moves modules.")
        lines.append("")
        lines.append("BASE MODULES / SNAP BUILDING")
        for key, data in BASE_MODULE_DATA.items():
            afford = self._can_afford_build_module(key)
            count = self._module_count(key)
            state = "READY" if afford else "NEED"
            lines.append(f"{data['key']}  {data['label']} x{count} [{state}]")
            lines.append(f"   Cost: {self._cost_text(dict(data.get('cost', {})))}")
            lines.append(f"   Role: {data['desc']}")
        self.upgrade_text.setText("\n".join(lines))

    def _max_line_depth(self) -> float:
        return 320.0 + 90.0 * self._upgrade_level("CABLE_SPOOL")

    def _line_depth_speed(self) -> float:
        return 92.0 + 28.0 * self._upgrade_level("CABLE_SPOOL")

    def _hotspot_scan_radius(self) -> float:
        relay_bonus = 160.0 if self._surface_relay_built() else 0.0
        return HOTSPOT_SCAN_RADIUS + 90.0 * self._upgrade_level("SONAR_ARRAY") + relay_bonus

    def _sonar_bearing_radius(self) -> float:
        relay_bonus = 420.0 if self._surface_relay_built() else 0.0
        return SONAR_BEARING_RADIUS + 260.0 * self._upgrade_level("SONAR_ARRAY") + relay_bonus

    def _magnet_signal_bonus(self) -> float:
        return 0.055 * self._upgrade_level("MAGNET_COIL")

    def _auto_hoist_multiplier(self) -> float:
        return 1.0 + 0.22 * self._upgrade_level("MAGNET_COIL")

