    def _build_remote_static_overlay(self) -> None:
        root = self.aspect2d.attachNewNode("remote_signal_static_overlay")
        root.setTransparency(TransparencyAttrib.MAlpha)
        root.setBin("fixed", 9300)
        root.setDepthTest(False)
        root.setDepthWrite(False)
        cm = CardMaker("remote_signal_static_card")
        cm.setFrame(-STARFALL_UI_SAFE_ASPECT, STARFALL_UI_SAFE_ASPECT, -1.0, 1.0)
        card = root.attachNewNode(cm.generate())
        tex_path = self._ensure_remote_static_texture()
        try:
            card.setTexture(self.loader.loadTexture(panda_path(tex_path)))
        except Exception:
            pass
        card.setTransparency(TransparencyAttrib.MAlpha)
        card.setLightOff(1)
        card.setColorScale(0.42, 0.94, 1.0, 0.0)
        card.setBin("fixed", 9301)
        self.remote_static_noise_card = card
        self.remote_static_text = OnscreenText(
            text="",
            parent=root,
            pos=(-1.34, -0.74),
            scale=0.034,
            fg=(0.58, 0.98, 1.0, 0.0),
            align=TextNode.ALeft,
            mayChange=True,
        )
        try:
            self.remote_static_text.setBin("fixed", 9303)
            self.remote_static_text.setDepthTest(False)
            self.remote_static_text.setDepthWrite(False)
        except Exception:
            pass
        root.hide()
        self.remote_static_overlay_root = root

    def _ensure_remote_static_texture(self) -> Path:
        out = ASSET_DIR / "remote_signal_static_noise.png"
        out.parent.mkdir(parents=True, exist_ok=True)
        if out.exists():
            return out
        rng = random.Random(47047)
        img = Image.new("RGBA", (512, 288), (0, 0, 0, 0))
        px = img.load()
        for y in range(288):
            scan_alpha = 16 if y % 5 == 0 else 0
            for x in range(512):
                if rng.random() < 0.11 or scan_alpha:
                    a = scan_alpha + rng.randint(12, 78)
                    px[x, y] = (105 + rng.randint(0, 80), 220 + rng.randint(0, 35), 255, min(a, 125))
        draw = ImageDraw.Draw(img)
        for _ in range(42):
            y = rng.randint(0, 287)
            draw.line((0, y, 512, y + rng.randint(-2, 2)), fill=(90, 230, 255, rng.randint(32, 94)), width=rng.randint(1, 3))
        img = img.filter(ImageFilter.GaussianBlur(radius=0.45))
        img.save(out)
        return out

    def _planet_vision_data(self) -> dict[str, object]:
        key = str(getattr(self, "planet_vision_mode", PLANET_VISION_DEFAULT_MODE))
        return PLANET_VISION_MODES.get(key, PLANET_VISION_MODES[PLANET_VISION_DEFAULT_MODE])

    def _planet_vision_short_label(self) -> str:
        data = self._planet_vision_data()
        return str(data.get("ui", "STD"))

    def _world_saturation_scale(self) -> tuple[float, float, float]:
        scale = ACTIVE_ATMOSPHERIC_FX_PROFILE.get("world_saturation", (0.90, 0.92, 0.94))
        return (float(scale[0]), float(scale[1]), float(scale[2]))

    def _radiation_distortion_multiplier(self) -> float:
        baseline = float(ACTIVE_ATMOSPHERIC_FX_PROFILE.get("radiation_baseline", 1.0))
        try:
            cam = self.camera.getPos(self.render)
            ground_z = self.world.surface_height(float(cam.x), float(cam.y))
            height_exposure = clamp((float(cam.z) - float(ground_z)) / 240.0, 0.0, 1.0)
        except Exception:
            height_exposure = 0.0
        open_sky = 0.78 + height_exposure * 0.50
        return clamp(baseline * open_sky, 0.55, 1.60)

    def _build_planet_vision_overlay(self) -> None:
        root = self.aspect2d.attachNewNode("planet_vision_overlay")
        root.setTransparency(TransparencyAttrib.MAlpha)
        root.setBin("fixed", 9280)
        root.setDepthTest(False)
        root.setDepthWrite(False)
        cm = CardMaker("planet_vision_overlay_card")
        cm.setFrame(-STARFALL_UI_SAFE_ASPECT, STARFALL_UI_SAFE_ASPECT, -1.0, 1.0)
        card = root.attachNewNode(cm.generate())
        card.setTransparency(TransparencyAttrib.MAlpha)
        card.setLightOff(1)
        card.setBin("fixed", 9281)
        grid = root.attachNewNode(cm.generate())
        grid.setTransparency(TransparencyAttrib.MAlpha)
        grid.setLightOff(1)
        grid.setBin("fixed", 9282)
        glitch = root.attachNewNode(cm.generate())
        glitch.setTransparency(TransparencyAttrib.MAlpha)
        glitch.setLightOff(1)
        glitch.setBin("fixed", 9283)
        tex_path = self._ensure_planet_vision_texture()
        glitch_path = self._ensure_planet_vision_glitch_texture()
        try:
            tex = self.loader.loadTexture(panda_path(tex_path))
            card.setTexture(tex)
            grid.setTexture(tex)
        except Exception:
            pass
        try:
            glitch_tex = self.loader.loadTexture(panda_path(glitch_path))
            glitch.setTexture(glitch_tex)
        except Exception:
            pass
        card.setColorScale(0.0, 0.0, 0.0, 0.0)
        grid.setColorScale(0.0, 0.0, 0.0, 0.0)
        glitch.setColorScale(0.0, 0.0, 0.0, 0.0)
        self.planet_vision_overlay_text = OnscreenText(
            text="",
            parent=root,
            pos=(1.31, 0.90),
            scale=0.034,
            fg=(0.88, 0.96, 1.0, 0.0),
            align=TextNode.ARight,
            mayChange=True,
        )
        try:
            self.planet_vision_overlay_text.setBin("fixed", 9284)
            self.planet_vision_overlay_text.setDepthTest(False)
            self.planet_vision_overlay_text.setDepthWrite(False)
        except Exception:
            pass
        root.hide()
        self.planet_vision_overlay_root = root
        self.planet_vision_overlay_card = card
        self.planet_vision_overlay_grid = grid
        self.planet_vision_overlay_glitch = glitch

    def _ensure_planet_vision_texture(self) -> Path:
        out = ASSET_DIR / "planet_vision_overlay.png"
        out.parent.mkdir(parents=True, exist_ok=True)
        if out.exists():
            return out
        width, height = 512, 288
        img = Image.new("RGBA", (width, height), (0, 0, 0, 0))
        px = img.load()
        cx = width * 0.5
        cy = height * 0.5
        for y in range(height):
            scan = 18 if y % 6 == 0 else 0
            for x in range(width):
                dx = (x - cx) / cx
                dy = (y - cy) / cy
                dist = min(1.0, math.sqrt(dx * dx + dy * dy))
                vignette = int(60 * (dist ** 1.8))
                line = scan + (8 if x % 64 == 0 or y % 48 == 0 else 0)
                alpha = max(vignette, line)
                if alpha > 0:
                    px[x, y] = (255, 255, 255, min(alpha, 120))
        draw = ImageDraw.Draw(img)
        draw.rectangle((18, 18, width - 19, height - 19), outline=(255, 255, 255, 72), width=2)
        draw.rectangle((34, 34, width - 35, height - 35), outline=(255, 255, 255, 46), width=1)
        draw.line((0, cy, width, cy), fill=(255, 255, 255, 36), width=1)
        draw.line((cx, 0, cx, height), fill=(255, 255, 255, 36), width=1)
        for r in (56, 92, 126):
            draw.ellipse((cx - r, cy - r, cx + r, cy + r), outline=(255, 255, 255, 20), width=1)
        img = img.filter(ImageFilter.GaussianBlur(radius=0.5))
        img.save(out)
        return out

    def _ensure_planet_vision_glitch_texture(self) -> Path:
        out = ASSET_DIR / "planet_vision_glitch_overlay.png"
        out.parent.mkdir(parents=True, exist_ok=True)
        if out.exists():
            return out
        width, height = 512, 288
        img = Image.new("RGBA", (width, height), (0, 0, 0, 0))
        draw = ImageDraw.Draw(img)
        rng = random.Random(54056)
        # Sparse display-breakup blocks: subtle and transparent, never a solid mask.
        for _ in range(86):
            bw = rng.randint(4, 18)
            bh = rng.randint(3, 12)
            x = rng.randint(0, width - bw - 1)
            y = rng.randint(0, height - bh - 1)
            a = rng.randint(14, 52)
            draw.rectangle((x, y, x + bw, y + bh), fill=(255, 255, 255, a))
            if rng.random() < 0.34:
                draw.rectangle((max(0, x - 1), y, min(width - 1, x + bw + 1), min(height - 1, y + 1)), fill=(255, 255, 255, max(8, a // 2)))
        # A few thin slice-tears to give a broken display read without obscuring play.
        for _ in range(8):
            y = rng.randint(12, height - 12)
            x = rng.randint(0, width - 120)
            w = rng.randint(26, 120)
            draw.rectangle((x, y, x + w, min(height - 1, y + 1)), fill=(255, 255, 255, rng.randint(20, 46)))
        # Light-hit corners / edge sparkle cues.
        for _ in range(14):
            x = rng.choice([rng.randint(0, 96), rng.randint(width - 96, width - 12), rng.randint(0, width - 12)])
            y = rng.choice([rng.randint(0, 42), rng.randint(height - 42, height - 8), rng.randint(0, height - 8)])
            draw.rectangle((x, y, min(width - 1, x + rng.randint(2, 8)), min(height - 1, y + rng.randint(2, 8))), fill=(255, 255, 255, rng.randint(12, 38)))
        img = img.filter(ImageFilter.GaussianBlur(radius=0.22))
        img.save(out)
        return out

    def _cycle_planet_vision_mode(self) -> None:
        self.planet_vision_mode_index = (int(getattr(self, "planet_vision_mode_index", 0)) + 1) % len(PLANET_VISION_MODE_ORDER)
        self.planet_vision_mode = PLANET_VISION_MODE_ORDER[self.planet_vision_mode_index]
        self._apply_planet_vision_mode()
        data = self._planet_vision_data()
        self.last_status_message = f"PLANET VISION // {data['label']}"
        self.status_flash_timer = 1.4

    def _apply_planet_vision_mode(self, initial: bool = False) -> None:
        data = self._planet_vision_data()
        render_scale = data.get("render_scale", (1.0, 1.0, 1.0, 1.0))
        wsx, wsy, wsz = self._world_saturation_scale()
        final_render_scale = (
            float(render_scale[0]) * wsx,
            float(render_scale[1]) * wsy,
            float(render_scale[2]) * wsz,
            float(render_scale[3]),
        )
        try:
            self.render.setColorScale(*final_render_scale)
        except Exception:
            pass
        root = getattr(self, "planet_vision_overlay_root", None)
        if root is None or root.isEmpty():
            return
        if str(getattr(self, "planet_vision_mode", "STANDARD")) == "STANDARD":
            root.hide()
            self.planet_vision_overlay_alpha = 0.0
            if self.planet_vision_overlay_text is not None:
                self.planet_vision_overlay_text.setText("")
                self.planet_vision_overlay_text.setColorScale(1.0, 1.0, 1.0, 0.0)
            return
        root.show()
        if self.planet_vision_overlay_text is not None:
            self.planet_vision_overlay_text.setText(f"VISION {data['label']}")
            color = data.get("text_color", (0.88, 0.96, 1.0, 0.88))
            self.planet_vision_overlay_text.setFg(color)
        if initial:
            self._update_planet_vision_overlay(globalClock.getFrameTime())

    def _update_planet_vision_overlay(self, time_value: float) -> None:
        root = getattr(self, "planet_vision_overlay_root", None)
        card = getattr(self, "planet_vision_overlay_card", None)
        grid = getattr(self, "planet_vision_overlay_grid", None)
        glitch = getattr(self, "planet_vision_overlay_glitch", None)
        text = getattr(self, "planet_vision_overlay_text", None)
        if root is None or root.isEmpty() or card is None or grid is None or glitch is None:
            return
        if getattr(self, "embedded_operation", False):
            root.hide()
            return
        data = self._planet_vision_data()
        mode = str(getattr(self, "planet_vision_mode", "STANDARD"))
        if mode == "STANDARD":
            root.hide()
            self.planet_vision_overlay_alpha = 0.0
            try:
                glitch.setColorScale(0.0, 0.0, 0.0, 0.0)
            except Exception:
                pass
            return
        root.show()
        pulse = 0.5 + 0.5 * math.sin(time_value * float(data.get("pulse_speed", 1.0)) * math.tau * 0.35)
        r, g, b, a = data.get("overlay", (0.2, 0.88, 1.0, 0.16))
        overlay_alpha = clamp(float(a) * (0.84 + pulse * 0.26), 0.0, 0.32)
        self.planet_vision_overlay_alpha = overlay_alpha
        card.setColorScale(float(r), float(g), float(b), overlay_alpha)
        drx, dry = data.get("drift", (0.0, 0.0))
        grid_alpha = clamp(float(data.get("line_alpha", 0.12)) * (0.72 + pulse * 0.48), 0.0, 0.26)
        grid.setColorScale(float(r), float(g), float(b), grid_alpha)
        glitch_alpha_base = clamp(float(data.get("glitch_alpha", 0.0)), 0.0, 0.14)
        glitch_speed = float(data.get("glitch_speed", 1.0))
        gsx, gsy = data.get("glitch_scale", (1.0, 1.0))
        glitch_flicker = 0.30 + 0.70 * max(0.0, math.sin(time_value * math.tau * glitch_speed * 0.42 + 0.8))
        radiation_mult = self._radiation_distortion_multiplier()
        glitch_alpha = clamp(glitch_alpha_base * radiation_mult * (0.56 + pulse * 0.24 + glitch_flicker * 0.45), 0.0, 0.18)
        glitch_tint = (clamp(float(r) * 1.12 + 0.10, 0.0, 1.0), clamp(float(g) * 1.12 + 0.10, 0.0, 1.0), clamp(float(b) * 1.12 + 0.10, 0.0, 1.0))
        glitch.setColorScale(glitch_tint[0], glitch_tint[1], glitch_tint[2], glitch_alpha)
        try:
            card.setTexOffset(TextureStage.getDefault(), math.sin(time_value * (2.6 + abs(drx) * 30.0)) * drx, math.cos(time_value * (3.1 + abs(dry) * 24.0)) * dry)
            grid.setTexOffset(TextureStage.getDefault(), time_value * drx * 0.24, -time_value * dry * 0.22)
            grid.setTexScale(TextureStage.getDefault(), 1.32, 1.10)
            glitch.setTexOffset(TextureStage.getDefault(), math.sin(time_value * 0.92) * 0.006 + time_value * drx * 0.04, math.cos(time_value * 1.18) * 0.004 - time_value * dry * 0.03)
            glitch.setTexScale(TextureStage.getDefault(), float(gsx), float(gsy))
        except Exception:
            pass
        if text is not None:
            tc = data.get("text_color", (0.88, 0.96, 1.0, 0.84))
            text.setColorScale(float(tc[0]), float(tc[1]), float(tc[2]), clamp(float(tc[3]) * (0.88 + pulse * 0.12), 0.0, 0.96))

    def _build_mission_zone_visuals(self) -> None:
        root = getattr(self, "mission_zone_visual_root", None)
        if root is None or root.isEmpty():
            root = self.render.attachNewNode("mission_zone_signal_rings")
            root.setTransparency(TransparencyAttrib.MAlpha)
            root.setLightOff(1)
            self.mission_zone_visual_root = root
        self._update_mission_zone_visuals(0.0)

    def _update_mission_zone_visuals(self, time_value: float) -> None:
        root = getattr(self, "mission_zone_visual_root", None)
        if root is None or root.isEmpty():
            return
        for child in root.getChildren():
            child.removeNode()
        center = getattr(self, "mission_zone_center", Vec3(0.0, 0.0, 0.0))
        for radius, alpha, label in (
            (MISSION_ZONE_WARNING_RADIUS, 0.26, "warning"),
            (MISSION_ZONE_HARD_RADIUS, 0.18, "hard"),
        ):
            segs = LineSegs(f"mission_zone_{label}_ring")
            segs.setThickness(2.1 if label == "warning" else 2.7)
            pulse = 0.82 + 0.18 * math.sin(time_value * (1.8 if label == "warning" else 2.7))
            if label == "warning":
                segs.setColor(0.36, 0.90, 1.0, alpha * pulse)
            else:
                segs.setColor(1.0, 0.40, 0.24, alpha * pulse)
            for i in range(MISSION_ZONE_VISUAL_RING_SEGMENTS + 1):
                a = i / MISSION_ZONE_VISUAL_RING_SEGMENTS * math.tau
                x = center.x + math.cos(a) * radius
                y = center.y + math.sin(a) * radius
                z = self.world.surface_height(x, y) + (8.0 if label == "warning" else 13.0)
                if i == 0:
                    segs.moveTo(x, y, z)
                else:
                    segs.drawTo(x, y, z)
            np = root.attachNewNode(segs.create())
            np.setTransparency(TransparencyAttrib.MAlpha)
            np.setLightOff(1)
            np.setBin("transparent", 76)

    def _signal_quality_from_strength(self, strength: float) -> float:
        return 1.0 - clamp(strength, 0.0, 1.0) * MISSION_SIGNAL_DEGRADE_MAX

    def _liquid_signal_at(self, x: float, y: float) -> float:
        if IS_TITAN_LEVEL and hasattr(self.world, "titan_liquid_signal"):
            return float(self.world.titan_liquid_signal(float(x), float(y)))
        return 0.0

    def _liquid_contact_forbidden(self, x: float, y: float, z: float | None = None, *, clearance: float = TITAN_LIQUID_SURFACE_CLEARANCE) -> bool:
        if not IS_TITAN_LEVEL:
            return False
        signal = self._liquid_signal_at(x, y)
        if signal < TITAN_LIQUID_CONTACT_SIGNAL:
            return False
        terrain_z = self.world.surface_height(float(x), float(y))
        if terrain_z > WATER_Z + 9.0 and signal < 0.50:
            # Raised dry bank inside the broad wet shelf remains traversable.
            return False
        if z is None:
            return True
        return float(z) <= WATER_Z + clearance

    def _terrain_contact_safe_height(self, x: float, y: float, minimum_clearance: float) -> float:
        ground = self.world.surface_height(float(x), float(y))
        if IS_TITAN_LEVEL and self._liquid_signal_at(x, y) >= TITAN_LIQUID_CONTACT_SIGNAL:
            return max(ground, WATER_Z) + minimum_clearance
        return ground + minimum_clearance

    def _nearest_liquid_bank_point(self, from_pos: Vec3, target_x: float, target_y: float) -> tuple[float, float, bool]:
        if not IS_TITAN_LEVEL:
            return float(target_x), float(target_y), False
        tx, ty = float(target_x), float(target_y)
        if not self._liquid_contact_forbidden(tx, ty):
            return tx, ty, False
        fx, fy = float(from_pos.x), float(from_pos.y)
        # Search from the liquid target back toward the current rover/drone.
        direction = Vec2(fx - tx, fy - ty)
        if direction.lengthSquared() <= 1e-4:
            direction = Vec2(1.0, 0.0)
        direction.normalize()
        best: tuple[float, float] | None = None
        for step in range(1, TITAN_LIQUID_BANK_SEARCH_STEPS + 1):
            d = step * TITAN_LIQUID_BANK_SEARCH_STEP
            cx = clamp(tx + direction.x * d, -WORLD_HALF + 80.0, WORLD_HALF - 80.0)
            cy = clamp(ty + direction.y * d, -WORLD_HALF + 80.0, WORLD_HALF - 80.0)
            signal = self._liquid_signal_at(cx, cy)
            if signal <= TITAN_LIQUID_SAFE_SIGNAL_MAX and self.world.surface_height(cx, cy) >= WATER_Z - 2.0:
                return cx, cy, True
            if signal < TITAN_LIQUID_CONTACT_SIGNAL and best is None:
                best = (cx, cy)
        if best is not None:
            return best[0], best[1], True
        # Last fallback: move radially away from the target and keep units dry.
        cx = clamp(tx + direction.x * TITAN_LIQUID_SAFE_SAMPLE_RANGE, -WORLD_HALF + 80.0, WORLD_HALF - 80.0)
        cy = clamp(ty + direction.y * TITAN_LIQUID_SAFE_SAMPLE_RANGE, -WORLD_HALF + 80.0, WORLD_HALF - 80.0)
        return cx, cy, True

    def _liquid_sample_fact_line(self) -> str:
        return REAL_WORLD_FACTS.get(MOON_LEVEL_ID, "FACT: Survey targets use real Saturn-system geology where available.")

    def _rover_docking_position_for_drone(self, drone_key: str) -> Vec3 | None:
        rover = getattr(self, "support_rover", None)
        if rover is None or rover.isEmpty():
            return None
        base = rover.getPos(self.render)
        h = math.radians(rover.getH(self.render) if hasattr(rover, "getH") else getattr(self, "heading", 0.0))
        right = Vec3(math.cos(h), math.sin(h), 0.0)
        back = Vec3(math.sin(h), -math.cos(h), 0.0)
        slot = -1.0 if drone_key == "DRONE_A" else 1.0
        dock = base + right * (26.0 * slot) + back * 18.0
        dock.z = self.world.surface_height(dock.x, dock.y) + FLIGHT_DRONE_DOCK_ALTITUDE
        return dock

    def _flight_drone_task_state(self, drone_key: str) -> str:
        drone = self.remote_drones.get(drone_key, {})
        if str(drone.get("state", "ACTIVE")) == "DISABLED":
            return "DISABLED"
        if str(getattr(self, "active_control_mode", "DRONE_A")).upper() == drone_key:
            return "REMOTE PILOT"
        if self.remote_rescue_pull and str(self.remote_rescue_pull.get("drone_key", "")) == drone_key:
            return "RESCUE PULL"
        if drone_key == "DRONE_A":
            dispatch = getattr(self, "drone_dispatch", None)
            if dispatch and bool(dispatch.get("active", False)):
                return "DRILL ROUTE"
            if 0 <= int(getattr(self, "active_rig_index", -1)) < len(getattr(self, "rigs", [])):
                return "SURFACE TASK"
        return "IDLE"

    def _flight_drone_altitude_limit(self, drone_key: str) -> float:
        drone = self.remote_drones.get(drone_key, {})
        return float(drone.get("max_altitude", FLIGHT_DRONE_A_MAX_ALTITUDE if drone_key == "DRONE_A" else FLIGHT_DRONE_B_MAX_ALTITUDE))

    def _flight_drone_relative_altitude(self, drone_key: str) -> float:
        drone = self.remote_drones.get(drone_key, {})
        node = drone.get("node")
        if not hasattr(node, "getPos"):
            return 0.0
        pos = node.getPos(self.render)
        return max(0.0, pos.z - self.world.surface_height(pos.x, pos.y))

    def _draw_flight_drone_dock_links(self, time_value: float) -> None:
        root = getattr(self, "flight_drone_dock_links_root", None)
        if root is None or root.isEmpty():
            root = self.render.attachNewNode("flight_drone_auto_charge_links")
            root.setTransparency(TransparencyAttrib.MAlpha)
            root.setLightOff(1)
            self.flight_drone_dock_links_root = root
        for child in root.getChildren():
            child.removeNode()
        rover = getattr(self, "support_rover", None)
        if rover is None or rover.isEmpty():
            return
        rover_pos = rover.getPos(self.render) + Vec3(0.0, 0.0, 14.0)
        for key, drone in self.remote_drones.items():
            if not bool(drone.get("docked", False)):
                continue
            node = drone.get("node")
            if not hasattr(node, "getPos") or node.isEmpty():
                continue
            drone_pos = node.getPos(self.render)
            segs = LineSegs(f"{key.lower()}_charge_dock_link")
            segs.setThickness(2.4)
            pulse = 0.68 + 0.32 * math.sin(time_value * 7.0 + (0.0 if key == "DRONE_A" else 1.6))
            segs.setColor(0.34, 1.0, 0.78, 0.28 + 0.30 * pulse)
            mid = (rover_pos + drone_pos) * 0.5 + Vec3(0.0, 0.0, 5.0 + pulse * 2.5)
            segs.moveTo(rover_pos)
            segs.drawTo(mid)
            segs.drawTo(drone_pos)
            np = root.attachNewNode(segs.create())
            np.setTransparency(TransparencyAttrib.MAlpha)
            np.setLightOff(1)

    def _update_flight_drone_power_and_docking(self, dt: float, time_value: float) -> None:
        if not self.remote_drones:
            return
        render_root = getattr(self, "render", None)
        if render_root is None or not hasattr(render_root, "isEmpty") or render_root.isEmpty():
            return
        rover = getattr(self, "support_rover", None)
        for key, drone in list(self.remote_drones.items()):
            node = drone.get("node")
            if not hasattr(node, "isEmpty") or node.isEmpty():
                continue
            state = str(drone.get("state", "ACTIVE"))
            task_state = self._flight_drone_task_state(key)
            drone["task_state"] = task_state
            power = clamp(float(drone.get("power", FLIGHT_DRONE_POWER_MAX)), 0.0, FLIGHT_DRONE_POWER_MAX)
            if state == "DISABLED":
                drone["power"] = power
                continue
            try:
                pos = node.getPos(render_root)
            except (AssertionError, TypeError):
                # Embedded operation teardown can invalidate the relative scene root
                # before a late frame reaches this updater. Treat that drone handle
                # as stale instead of letting Panda3D assert inside NodePath.getPos().
                drone["node"] = None
                drone["docked"] = False
                continue
            terrain_z = self.world.surface_height(pos.x, pos.y)
            altitude_limit = self._flight_drone_altitude_limit(key)
            if pos.z > terrain_z + altitude_limit:
                pos.z = terrain_z + altitude_limit
                node.setPos(pos)
                vel = self.remote_drone_velocity.setdefault(key, Vec3(0.0, 0.0, 0.0))
                if vel.z > 0.0:
                    vel.z *= 0.18
                if self.active_control_mode == key and self.status_flash_timer <= 0.0:
                    self.last_status_message = f"{key.replace('_', ' ')} HEIGHT LIMIT {int(altitude_limit)}m"
                    self.status_flash_timer = 0.8
            dock = self._rover_docking_position_for_drone(key)
            if task_state in {"REMOTE PILOT", "SURFACE TASK", "DRILL ROUTE", "RESCUE PULL"}:
                drone["docked"] = False
            should_auto_dock = task_state == "IDLE" and dock is not None
            if should_auto_dock:
                delta = dock - pos
                dist = delta.length()
                if dist > FLIGHT_DRONE_DOCK_DISTANCE:
                    drone["docked"] = False
                    speed = FLIGHT_DRONE_AUTO_DOCK_SPEED * (0.65 + clamp(power / FLIGHT_DRONE_POWER_MAX, 0.0, 1.0) * 0.35)
                    step = min(dist, speed * dt)
                    if dist > 0.001:
                        delta.normalize()
                        node.setPos(pos + delta * step)
                        node.setH(math.degrees(math.atan2(-delta.x, delta.y)))
                    drone["task_state"] = "AUTO-DOCK"
                else:
                    node.setPos(dock)
                    drone["docked"] = True
                    drone["task_state"] = "DOCKED CHARGE"
            if bool(drone.get("docked", False)) and dock is not None:
                power = min(FLIGHT_DRONE_POWER_MAX, power + FLIGHT_DRONE_RECHARGE_PER_SEC * dt)
                drone["power"] = power
            else:
                if task_state == "REMOTE PILOT":
                    drain = FLIGHT_DRONE_REMOTE_DRAIN_PER_SEC
                elif task_state in {"SURFACE TASK", "DRILL ROUTE", "RESCUE PULL"}:
                    drain = FLIGHT_DRONE_TASK_DRAIN_PER_SEC
                else:
                    drain = FLIGHT_DRONE_IDLE_DRAIN_PER_SEC
                drone["power"] = max(0.0, power - drain * dt)
            if float(drone.get("power", 0.0)) <= FLIGHT_DRONE_CRITICAL_POWER and state != "DISABLED":
                self._disable_remote_drone(key, "POWER DEPLETED")
            elif float(drone.get("power", 0.0)) <= FLIGHT_DRONE_LOW_POWER and task_state == "REMOTE PILOT" and self.status_flash_timer <= 0.0:
                self.last_status_message = f"{key.replace('_', ' ')} LOW POWER // RETURN TO ROVER DOCK"
                self.status_flash_timer = 1.1
        self._draw_flight_drone_dock_links(time_value)

    def _flight_drone_stats_lines(self) -> list[str]:
        lines = []
        for key in self.remote_drone_order:
            drone = self.remote_drones.get(key, {})
            if not drone:
                continue
            power = clamp(float(drone.get("power", FLIGHT_DRONE_POWER_MAX)), 0.0, FLIGHT_DRONE_POWER_MAX)
            alt = self._flight_drone_relative_altitude(key)
            limit = self._flight_drone_altitude_limit(key)
            state = str(drone.get("task_state", drone.get("state", "ACTIVE"))).replace("_", " ")
            if str(drone.get("state", "ACTIVE")) == "DISABLED":
                state = "DISABLED"
            dock = "DOCK" if bool(drone.get("docked", False)) else "AIR"
            label = "A" if key == "DRONE_A" else "B"
            lines.append(f"F-{label} PWR {power:03.0f}% ALT {alt:03.0f}/{limit:03.0f}m {dock} {state}")
        return lines

    def _flight_drone_stats_text(self) -> str:
        lines = self._flight_drone_stats_lines()
        mode = str(getattr(self, "active_control_mode", "DRONE_A")).upper()
        mount = str(getattr(self, "remote_camera_mount_label", "HOVER BELLY CAM"))
        rover_speed = int(float(getattr(self, "rover_velocity", Vec3(0.0, 0.0, 0.0)).length()))
        rover_line = f"SUPPORT ROVER DOCK  SPD {rover_speed:03d}  LINK {int(self.remote_signal_quality*100):03d}%"
        if not mode.startswith("DRONE"):
            mode = "DRONE_A"
        active_line = f"ACTIVE {mode.replace('_', ' ')}  {mount}  PITCH {int(self.pitch):+03d}°"
        if not lines:
            return "REMOTE UNITS\n" + active_line + "\n" + rover_line
        rover_power = f"ROVER STORAGE/CHARGE {self.base_power_stored:04.1f}/{self._base_power_capacity():04.0f}"
        vision = f"VISION {self._planet_vision_data().get('label', 'STANDARD VIEW')}"
        fact = self._liquid_sample_fact_line()
        return "REMOTE UNITS\n" + active_line + "\n" + rover_line + "\n" + "\n".join(lines[:2]) + f"\n{rover_power}\n{vision}\n{fact}"

    def _rescue_line_of_sight_clear(self, start: Vec3, end: Vec3) -> bool:
        delta = end - start
        distance = delta.length()
        if distance <= DRONE_RESCUE_LINE_OF_SIGHT_STEP:
            return True
        samples = max(2, min(32, int(distance / DRONE_RESCUE_LINE_OF_SIGHT_STEP)))
        for i in range(1, samples):
            t = i / samples
            p = start + delta * t
            terrain_z = self.world.surface_height(p.x, p.y)
            clearance = p.z - terrain_z
            if clearance < DRONE_RESCUE_LINE_OF_SIGHT_CLEARANCE:
                return False
        return True

    def _disabled_drone_pick_score(self, node: NodePath | None) -> float | None:
        if node is None or not hasattr(node, "isEmpty") or node.isEmpty():
            return None
        try:
            world_pos = node.getPos(self.render)
            if (world_pos - self.camera.getPos(self.render)).length() > 2900.0:
                return None
            cam_pos = self.cam.getRelativePoint(self.render, world_pos)
            if cam_pos.y <= 0.0:
                return None
            projected = Point2()
            if not self.camLens.project(cam_pos, projected):
                return None
            score = math.hypot(float(projected.x), float(projected.y))
            return score if score <= 0.42 else None
        except Exception:
            return None

    def _update_disabled_drone_beacons(self, time_value: float) -> None:
        root = getattr(self, "remote_rescue_beacon_root", None)
        if root is None or root.isEmpty():
            root = self.render.attachNewNode("remote_disabled_drone_beacons")
            root.setTransparency(TransparencyAttrib.MAlpha)
            root.setLightOff(1)
            self.remote_rescue_beacon_root = root
        for child in root.getChildren():
            child.removeNode()
        for key, drone in self.remote_drones.items():
            if str(drone.get("state", "ACTIVE")) != "DISABLED":
                continue
            node = drone.get("node")
            if not hasattr(node, "isEmpty") or node.isEmpty():
                continue
            pos = node.getPos(self.render)
            z = pos.z + DRONE_RESCUE_BEACON_HEIGHT
            pulse = 0.70 + 0.30 * math.sin(time_value * 5.6)
            segs = LineSegs(f"{key.lower()}_disabled_rescue_beacon")
            segs.setThickness(3.1)
            segs.setColor(1.0, 0.32, 0.18, 0.82 * pulse)
            r = DRONE_RESCUE_BEACON_RADIUS * (0.82 + 0.16 * pulse)
            # beacon mast and diamond/cross marker
            segs.moveTo(pos.x, pos.y, pos.z + 10.0)
            segs.drawTo(pos.x, pos.y, z + 8.0)
            points = [(0, r), (r, 0), (0, -r), (-r, 0), (0, r)]
            for i, (ox, oy) in enumerate(points):
                if i == 0:
                    segs.moveTo(pos.x + ox, pos.y + oy, z)
                else:
                    segs.drawTo(pos.x + ox, pos.y + oy, z)
            segs.moveTo(pos.x - r * 0.68, pos.y, z)
            segs.drawTo(pos.x + r * 0.68, pos.y, z)
            segs.moveTo(pos.x, pos.y - r * 0.68, z)
            segs.drawTo(pos.x, pos.y + r * 0.68, z)
            np = root.attachNewNode(segs.create())
            np.setTransparency(TransparencyAttrib.MAlpha)
            np.setLightOff(1)
            np.setBin("transparent", 91)

    def _control_node_for_mode(self, mode: str | None = None) -> NodePath | None:
        mode = str(mode or getattr(self, "active_control_mode", "DRONE_A")).upper()
        if mode == "ROVER":
            mode = "DRONE_A"
        drone = self.remote_drones.get(mode, {})
        node = drone.get("node")
        if hasattr(node, "isEmpty") and not node.isEmpty():
            return node
        # Rover is a storage/charging support target now, not a camera/control POV.
        if mode.startswith("DRONE"):
            for key in self.remote_drone_order:
                fallback = self.remote_drones.get(key, {})
                fallback_node = fallback.get("node")
                if str(fallback.get("state", "ACTIVE")) != "DISABLED" and hasattr(fallback_node, "isEmpty") and not fallback_node.isEmpty():
                    return fallback_node
        return None

    def _select_control_mode(self, mode: str) -> None:
        # Pass74: the player camera is always attached to a drone.  The rover remains
        # a visible storage/charge base, but never owns the view/camera anymore.
        requested = str(mode or "DRONE_A").upper()
        if requested == "ROVER":
            requested = "DRONE_A"
        if not requested.startswith("DRONE"):
            requested = "DRONE_A"
        drone = self.remote_drones.get(requested)
        if not drone or str(drone.get("state", "ACTIVE")) == "DISABLED":
            self.last_status_message = f"{requested} UNAVAILABLE // USING PRIMARY DRONE CAMERA"
            self.status_flash_timer = 1.4
            requested = self._fallback_control_mode(exclude=requested)
        self.active_control_mode = requested
        self.remote_view_label = requested.replace("_", " ")
        self.velocity = Vec3(0.0, 0.0, 0.0)
        self.rover_controlled = False
        self.drone_control_heading = self.heading
        self.drone_control_pitch = clamp(self.pitch, DRONE_CAMERA_MIN_PITCH, DRONE_CAMERA_MAX_PITCH)
        self.pitch = self.drone_control_pitch
        self.remote_camera_mount_label = "HOVER BELLY CAM" if requested == "DRONE_A" else "REMOTE DRONE CAM"
        self.last_status_message = f"{self.remote_view_label} POV // DRONE CAMERA ONLY // ROVER DOCKS/STORES"
        self.status_flash_timer = 1.8

    def _toggle_or_select_remote_drone(self, drone_key: str) -> None:
        # View toggling is intentionally removed. Keep the method as a safe no-op
        # for old bindings/tests, but do not switch back to rover camera.
        self._select_control_mode("DRONE_A")

    def _fallback_control_mode(self, exclude: str | None = None) -> str:
        exclude = str(exclude or "").upper()
        preferred = ["DRONE_A", "DRONE_B"]
        for key in preferred:
            if key == exclude:
                continue
            drone = self.remote_drones.get(key, {})
            node = drone.get("node")
            if str(drone.get("state", "ACTIVE")) != "DISABLED" and hasattr(node, "isEmpty") and not node.isEmpty():
                return key
        return "DRONE_A"

    def _remote_anchor_position(self) -> Vec3:
        node = self._control_node_for_mode()
        if node is not None:
            pos = node.getPos(self.render)
            return Vec3(pos.x, pos.y, pos.z)
        return self.camera.getPos(self.render)

    def _signal_distance_from_zone(self, pos: Vec3 | None = None) -> float:
        pos = pos or self._remote_anchor_position()
        center = getattr(self, "mission_zone_center", Vec3(0.0, 0.0, 0.0))
        return math.hypot(pos.x - center.x, pos.y - center.y)

    def _signal_static_strength(self, pos: Vec3 | None = None) -> float:
        dist = self._signal_distance_from_zone(pos)
        start = self.mission_zone_radius * MISSION_ZONE_STATIC_START
        stop = max(self.mission_zone_radius, MISSION_ZONE_DRONE_DISABLE_RADIUS)
        return clamp((dist - start) / max(stop - start, 1.0), 0.0, 1.0)

    def _apply_remote_static_overlay(self, strength: float, time_value: float) -> None:
        root = getattr(self, "remote_static_overlay_root", None)
        card = getattr(self, "remote_static_noise_card", None)
        text = getattr(self, "remote_static_text", None)
        strength = clamp(strength, 0.0, 1.0)
        self.remote_static_alpha = strength
        if root is None or root.isEmpty() or card is None:
            return
        if strength <= 0.015:
            root.hide()
            if text is not None:
                text.setText("")
                text.setColorScale(1.0, 1.0, 1.0, 0.0)
            return
        root.show()
        flicker = 0.78 + 0.22 * math.sin(time_value * 24.0 + strength * 7.0)
        alpha = clamp(0.05 + strength * 0.28 * flicker, 0.0, 0.36)
        card.setColorScale(0.35, 0.86, 1.0, alpha)
        try:
            card.setTexOffset(TextureStage.getDefault(), math.sin(time_value * 8.0) * 0.018 * strength, math.cos(time_value * 11.0) * 0.024 * strength)
        except Exception:
            pass
        mode = str(getattr(self, "active_control_mode", "DRONE_A")).upper()
        if mode == "ROVER":
            card.setColorScale(1.0, 0.62, 0.22, alpha * 0.82)
        elif mode == "DRONE_B":
            card.setColorScale(1.0, 0.74, 0.28, alpha)
        else:
            card.setColorScale(0.35, 0.86, 1.0, alpha)
        if text is not None:
            dist = int(self._signal_distance_from_zone())
            quality = int(self._signal_quality_from_strength(strength) * 100)
            link_name = "LAND ROVER LINK" if mode == "ROVER" else ("RESCUE DRONE LINK" if mode == "DRONE_B" else "HOVER DRONE LINK")
            text.setText(f"{link_name} // {quality:03d}% // {dist}m FROM ZONE")
            text.setColorScale(1.0, 0.86 if mode == "ROVER" else 1.0, 0.48 if mode == "ROVER" else 1.0, clamp(strength * 1.25, 0.0, 0.86))

    def _apply_rover_camera(self, initial: bool = False) -> None:
        rover = getattr(self, "support_rover", None)
        if rover is None or rover.isEmpty():
            return
        rover_pos = rover.getPos(self.render)
        h = math.radians(self.heading)
        forward = Vec3(-math.sin(h), math.cos(h), 0.0)
        cam_pos = rover_pos + forward * ROVER_CAMERA_FORWARD + Vec3(0.0, 0.0, ROVER_CAMERA_UP)
        if initial:
            self.camera.setPos(cam_pos)
        else:
            current = self.camera.getPos(self.render)
            self.camera.setPos(current + (cam_pos - current) * 0.48)
        self.pitch = clamp(self.pitch, ROVER_CAMERA_MIN_PITCH, ROVER_CAMERA_MAX_PITCH)
        self.remote_camera_mount_label = "LAND ROVER TOP CAM"
        self.camera.setHpr(self.heading, self.pitch, 0.0)

    def _apply_drone_camera(self, drone_key: str) -> None:
        node = self._control_node_for_mode(drone_key)
        if node is None:
            self._select_control_mode(self._fallback_control_mode(exclude=drone_key))
            return
        self.drone_control_pitch = clamp(self.drone_control_pitch, DRONE_CAMERA_MIN_PITCH, DRONE_CAMERA_MAX_PITCH)
        heading_rad = math.radians(self.drone_control_heading)
        forward = Vec3(-math.sin(heading_rad), math.cos(heading_rad), 0.0)
        # Belly-mounted camera: below and just forward of the hover body, so a
        # direct-down tilt sees terrain/hotspots and not the drone shell itself.
        pos = node.getPos(self.render) + forward * DRONE_CAMERA_FORWARD + Vec3(0.0, 0.0, DRONE_CAMERA_UP)
        # The drone center can be safely above terrain while its forward/belly
        # camera offset crosses a steep rim or canyon face. Clamp the camera at
        # its own XY sample so entry and movement can never put the lens in ground.
        terrain_clear_z = self.world.surface_height(pos.x, pos.y) + DRONE_CAMERA_TERRAIN_CLEARANCE
        pos.z = max(pos.z, terrain_clear_z)
        self.camera.setPos(pos)
        self.camera.setHpr(self.drone_control_heading, self.drone_control_pitch, 0.0)
        self.heading = self.drone_control_heading
        self.pitch = self.drone_control_pitch
        self.remote_camera_mount_label = "HOVER BELLY CAM" if str(drone_key).upper() == "DRONE_A" else "REMOTE DRONE CAM"

    def _drive_rover_from_inputs(self, dt: float, wish: Vec3, sliding: bool, jump_pressed: bool) -> None:
        rover = getattr(self, "support_rover", None)
        if rover is None or rover.isEmpty():
            return
        pos = rover.getPos(self.render)
        current_ground = self.world.surface_height(pos.x, pos.y)
        signal_strength = self._signal_static_strength(pos)
        signal_quality = self._signal_quality_from_strength(signal_strength)
        self.rover_control_degrade = 1.0 - signal_quality
        accel = ROVER_ACCEL * (1.10 if sliding else 1.0) * signal_quality
        max_speed = ROVER_MAX_SPEED * (ROVER_SPRINT_SPEED_MULT if sliding else 1.0) * max(0.48, signal_quality)
        self.rover_velocity += wish * accel * dt
        self.rover_velocity.setZ(0.0)
        drag = ROVER_DRAG ** (dt * 60.0)
        self.rover_velocity.x *= drag
        self.rover_velocity.y *= drag
        if self.rover_velocity.length() > max_speed:
            self.rover_velocity.normalize()
            self.rover_velocity *= max_speed
        if jump_pressed and self.rover_grounded and self._jump_armed:
            self.rover_vertical_velocity = PLAYER_EFFECTIVE_JUMP_IMPULSE * 0.62
            self.rover_grounded = False
            self._jump_armed = False
            self.last_status_message = "TRITON MICRO-G ROVER HOP // LONG FLOAT ARC" if IS_TRITON_LEVEL else ("EUROPA LOW-G ROVER HOP // CLIMBING JAGGED GROUND" if IS_EUROPA_LEVEL else "ROVER SUSPENSION HOP // CLIMBING JAGGED GROUND")
            self.status_flash_timer = 0.9
        new_pos = pos + self.rover_velocity * dt
        new_pos.x = clamp(new_pos.x, -WORLD_HALF + 58.0, WORLD_HALF - 58.0)
        new_pos.y = clamp(new_pos.y, -WORLD_HALF + 58.0, WORLD_HALF - 58.0)
        terrain_z = self.world.surface_height(new_pos.x, new_pos.y)
        climb = terrain_z - current_ground
        if wish.lengthSquared() > 0.0 and climb > PLAYER_CLIMB_STEP_SOFT and self.rover_grounded:
            severity = clamp((climb - PLAYER_CLIMB_STEP_SOFT) / max(PLAYER_CLIMB_STEP_HARD - PLAYER_CLIMB_STEP_SOFT, 1.0), 0.0, 1.0)
            factor = 1.0 - severity * 0.42
            if jump_pressed:
                factor = max(factor, 0.84)
            new_pos = pos + (new_pos - pos) * factor
            terrain_z = self.world.surface_height(new_pos.x, new_pos.y)
            self.rover_velocity *= max(0.72, factor)
        if IS_TITAN_LEVEL:
            if self._liquid_contact_forbidden(new_pos.x, new_pos.y, new_pos.z):
                bx, by, adjusted = self._nearest_liquid_bank_point(pos, new_pos.x, new_pos.y)
                if adjusted and not self._liquid_contact_forbidden(bx, by):
                    new_pos.x, new_pos.y = bx, by
                    terrain_z = self.world.surface_height(new_pos.x, new_pos.y)
                    self.rover_velocity *= 0.36
                else:
                    new_pos = pos
                    terrain_z = current_ground
                    self.rover_velocity *= 0.12
                if self.status_flash_timer <= 0.0:
                    self.last_status_message = "LIQUID CONTACT LOCKOUT // ROVER STAYS DRY, USE TETHER SAMPLE"
                    self.status_flash_timer = 1.4
        if not self.rover_grounded:
            self.rover_vertical_velocity -= PLAYER_EFFECTIVE_GRAVITY * dt
            self.rover_vertical_offset += self.rover_vertical_velocity * dt
            self.rover_vertical_offset = min(self.rover_vertical_offset, PLAYER_EFFECTIVE_MAX_JUMP_OFFSET * 0.65)
            if self.rover_vertical_offset <= PLAYER_GROUND_SNAP_DISTANCE and self.rover_vertical_velocity <= 0.0:
                self.rover_vertical_offset = 0.0
                self.rover_vertical_velocity = 0.0
                self.rover_grounded = True
        else:
            self.rover_vertical_offset = max(0.0, self.rover_vertical_offset - PLAYER_EFFECTIVE_GRAVITY * dt * 0.35)
        new_pos.z = terrain_z + 7.2 + self.rover_vertical_offset
        rover.setPos(new_pos)
        if self.rover_velocity.length() > 0.8:
            rover.setH(math.degrees(math.atan2(-self.rover_velocity.x, self.rover_velocity.y)))
        if self.rover_control_degrade > 0.05:
            self.rover_nav_state = f"MANUAL ROVER // LINK {int(signal_quality * 100):03d}% // {int(self.rover_velocity.length()):03d} m/s"
        else:
            self.rover_nav_state = f"MANUAL ROVER // {int(self.rover_velocity.length()):03d} m/s"
        self._update_support_rover_visual(globalClock.getFrameTime(), self.rover_velocity.length())
        self._apply_rover_camera()

    def _drive_drone_from_inputs(self, dt: float, drone_key: str, wish: Vec3, vertical: float) -> None:
        drone = self.remote_drones.get(drone_key, {})
        if str(drone.get("state", "ACTIVE")) == "DISABLED":
            self._select_control_mode(self._fallback_control_mode(exclude=drone_key))
            return
        node = drone.get("node")
        if not hasattr(node, "isEmpty") or node.isEmpty():
            self._select_control_mode(self._fallback_control_mode(exclude=drone_key))
            return
        power = clamp(float(drone.get("power", FLIGHT_DRONE_POWER_MAX)), 0.0, FLIGHT_DRONE_POWER_MAX)
        if power <= FLIGHT_DRONE_CRITICAL_POWER:
            self._disable_remote_drone(drone_key, "POWER DEPLETED")
            return
        drone["docked"] = False
        vel = self.remote_drone_velocity.setdefault(drone_key, Vec3(0.0, 0.0, 0.0))
        current_pos = node.getPos(self.render)
        signal_strength = self._signal_static_strength(current_pos)
        signal_quality = self._signal_quality_from_strength(signal_strength)
        power_factor = clamp(0.46 + power / FLIGHT_DRONE_POWER_MAX * 0.54, 0.42, 1.0)
        effective_accel = DRONE_ACCEL * signal_quality * power_factor
        effective_max_speed = DRONE_MAX_SPEED * max(0.42, signal_quality) * power_factor
        vel += wish * effective_accel * dt
        vel.z += vertical * effective_accel * 0.58 * dt
        vel *= DRONE_DRAG ** (dt * 60.0)
        if vel.length() > effective_max_speed:
            vel.normalize()
            vel *= effective_max_speed
        pos = current_pos + vel * dt
        pos.x = clamp(pos.x, -WORLD_HALF + 42.0, WORLD_HALF - 42.0)
        pos.y = clamp(pos.y, -WORLD_HALF + 42.0, WORLD_HALF - 42.0)
        terrain_z = self.world.surface_height(pos.x, pos.y)
        if IS_TITAN_LEVEL and self._liquid_contact_forbidden(pos.x, pos.y, pos.z):
            bx, by, adjusted = self._nearest_liquid_bank_point(current_pos, pos.x, pos.y)
            if adjusted and not self._liquid_contact_forbidden(bx, by):
                pos.x, pos.y = bx, by
                terrain_z = self.world.surface_height(pos.x, pos.y)
                vel *= 0.30
                self.last_status_message = f"{drone_key.replace('_', ' ')} LIQUID AVOID // SAMPLE FROM BANK"
                self.status_flash_timer = max(float(getattr(self, "status_flash_timer", 0.0)), 0.9)
            else:
                pos = current_pos
                terrain_z = self.world.surface_height(pos.x, pos.y)
                vel *= 0.0
        altitude_limit = self._flight_drone_altitude_limit(drone_key)
        min_clearance = max(24.0, TITAN_LIQUID_SURFACE_CLEARANCE if IS_TITAN_LEVEL and self._liquid_signal_at(pos.x, pos.y) >= TITAN_LIQUID_SAMPLE_SIGNAL_MIN else 24.0)
        min_z = self._terrain_contact_safe_height(pos.x, pos.y, min_clearance)
        pos.z = clamp(pos.z, min_z, max(min_z, terrain_z + altitude_limit))
        node.setPos(pos)
        node.setH(self.drone_control_heading)
        node.setP(clamp(self.drone_control_pitch * 0.30, -22.0, 22.0))
        drone["last_distance"] = self._signal_distance_from_zone(pos)
        self.remote_view_label = drone_key.replace("_", " ")
        self._apply_drone_camera(drone_key)
        if drone_key == "DRONE_A":
            self._update_persistent_drill_drone_visual(globalClock.getFrameTime(), min(vel.length() / DRONE_MAX_SPEED, 1.0))
        else:
            self._update_remote_drone_b_visual(globalClock.getFrameTime(), drone_key)

    def _update_remote_drone_b_visual(self, time_value: float, drone_key: str = "DRONE_B") -> None:
        drone = self.remote_drones.get(drone_key, {})
        node = drone.get("node")
        ring_root = drone.get("ring_root")
        if not hasattr(node, "isEmpty") or node.isEmpty() or not hasattr(ring_root, "getChildren"):
            return
        for child in ring_root.getChildren():
            child.removeNode()
        disabled = str(drone.get("state", "ACTIVE")) == "DISABLED"
        ring = LineSegs("remote_drone_b_ring_lines")
        ring.setThickness(2.0)
        ring.setColor(1.0 if disabled else 0.95, 0.34 if disabled else 0.78, 0.24 if disabled else 0.32, 0.76 if disabled else 0.52)
        radius = 10.8 + math.sin(time_value * 4.4) * 0.45
        for i in range(37):
            a = i / 36.0 * math.tau + time_value * 1.15
            x = math.cos(a) * radius
            y = math.sin(a) * radius
            z = -3.5 + math.sin(a * 2.0 + time_value) * 0.12
            if i == 0:
                ring.moveTo(x, y, z)
            else:
                ring.drawTo(x, y, z)
        np = ring_root.attachNewNode(ring.create())
        np.setTransparency(TransparencyAttrib.MAlpha)
        np.setLightOff(1)
        if disabled:
            node.setR(math.sin(time_value * 2.0) * 10.0)

    def _disable_remote_drone(self, drone_key: str, reason: str = "SIGNAL LOST") -> None:
        drone = self.remote_drones.get(drone_key)
        if not drone or str(drone.get("state", "ACTIVE")) == "DISABLED":
            return
        drone["state"] = "DISABLED"
        drone["disabled_reason"] = reason
        drone["disabled_since"] = globalClock.getFrameTime()
        vel = self.remote_drone_velocity.setdefault(drone_key, Vec3(0.0, 0.0, 0.0))
        vel *= 0.0
        node = drone.get("node")
        if hasattr(node, "setColorScale"):
            node.setColorScale(1.0, 0.32, 0.22, 0.78)
        self._play_sfx("drone_disabled", 1.0)
        if self.active_control_mode == drone_key:
            fallback = self._fallback_control_mode(exclude=drone_key)
            self._select_control_mode(fallback)
        self.last_status_message = f"{drone_key.replace('_', ' ')} DISABLED // CLICK IT TO PULL RESCUE CABLE"
        self.status_flash_timer = 2.4

    def _try_rescue_disabled_drone_from_crosshair(self) -> bool:
        best_key = None
        best_score = None
        for key, drone in self.remote_drones.items():
            if str(drone.get("state", "ACTIVE")) != "DISABLED":
                continue
            node = drone.get("node")
            score = self._disabled_drone_pick_score(node)
            if score is None:
                continue
            if best_score is None or score < best_score:
                best_key = key
                best_score = score
        if best_key is None:
            return False
        drone = self.remote_drones.get(best_key, {})
        node = drone.get("node")
        target_node = self._control_node_for_mode()
        if not hasattr(node, "getPos") or target_node is None:
            return False
        if not self._rescue_line_of_sight_clear(target_node.getPos(self.render) + Vec3(0.0, 0.0, 12.0), node.getPos(self.render)):
            self.last_status_message = f"RESCUE LINE BLOCKED // MOVE ROVER OR ACTIVE DRONE INTO VIEW"
            self.status_flash_timer = 1.6
            return True
        self.remote_rescue_pull = {"drone_key": best_key, "progress": 0.0, "line_of_sight": True}
        self._play_sfx("rescue_pull", 1.0)
        self.last_status_message = f"RESCUE CABLE LOCKED // PULLING {best_key.replace('_', ' ')}"
        self.status_flash_timer = 1.8
        return True

    def _update_remote_signal_and_rescue(self, task: Task) -> int:
        dt = min(globalClock.getDt(), 0.12)
        self._update_mission_zone_visuals(task.time)
        self._update_flight_drone_power_and_docking(dt, task.time)
        # Disable only remotely piloted drones that truly leave the mission zone.
        for key, drone in self.remote_drones.items():
            node = drone.get("node")
            if not hasattr(node, "isEmpty") or node.isEmpty():
                continue
            pos = node.getPos(self.render)
            distance = self._signal_distance_from_zone(pos)
            drone["last_distance"] = distance
            if str(drone.get("state", "ACTIVE")) != "DISABLED" and distance > MISSION_ZONE_DRONE_DISABLE_RADIUS:
                self._disable_remote_drone(key, "MISSION ZONE SIGNAL LOST")
        pull = self.remote_rescue_pull
        if pull:
            key = str(pull.get("drone_key", ""))
            drone = self.remote_drones.get(key, {})
            node = drone.get("node")
            target_node = self._control_node_for_mode()
            if not hasattr(node, "isEmpty") or node.isEmpty() or target_node is None:
                self.remote_rescue_pull = None
            else:
                pos = node.getPos(self.render)
                target = target_node.getPos(self.render)
                target.z = self.world.surface_height(target.x, target.y) + 38.0
                delta = target - pos
                dist = delta.length()
                los_clear = self._rescue_line_of_sight_clear(target + Vec3(0.0, 0.0, 10.0), pos)
                if dist <= 58.0:
                    drone["state"] = "ACTIVE"
                    drone["disabled_reason"] = ""
                    if hasattr(node, "clearColorScale"):
                        node.clearColorScale()
                    self.remote_rescue_pull = None
                    self._play_sfx("rescue_complete", 1.0)
                    self.last_status_message = f"{key.replace('_', ' ')} RESCUED // ALT POV RESTORED"
                    self.status_flash_timer = 2.0
                elif not los_clear:
                    self._draw_rescue_cable(target_node, node, task.time, blocked=True)
                    self.last_status_message = "RESCUE CABLE OBSTRUCTED // REPOSITION FOR LINE OF SIGHT"
                    self.status_flash_timer = max(self.status_flash_timer, 0.25)
                else:
                    signal_quality = self._signal_quality_from_strength(self._signal_static_strength(target))
                    distance_factor = clamp(1.0 - dist / max(MISSION_ZONE_HARD_RADIUS * 1.35, 1.0), 0.35, 1.0)
                    step_rate = DRONE_RESCUE_PULL_RATE * signal_quality * distance_factor
                    step = min(dist, step_rate * dt)
                    pull["progress"] = clamp(float(pull.get("progress", 0.0)) + dt * (0.18 + distance_factor * 0.42), 0.0, 1.0)
                    if dist > 0.001:
                        delta.normalize()
                        node.setPos(pos + delta * step)
                    self._draw_rescue_cable(target_node, node, task.time, blocked=False)
        self._update_disabled_drone_beacons(task.time)
        strength = self._signal_static_strength(self._remote_anchor_position())
        self.remote_signal_quality = self._signal_quality_from_strength(strength)
        self.remote_signal_crackle_timer = max(0.0, float(getattr(self, "remote_signal_crackle_timer", 0.0)) - dt)
        if strength > 0.20 and self.remote_signal_crackle_timer <= 0.0:
            self._play_sfx("signal_static", clamp(0.45 + strength * 1.05, 0.45, 1.35))
            self.remote_signal_crackle_timer = MISSION_SIGNAL_CRACKLE_INTERVAL * (1.15 - min(strength, 0.85))
        self._apply_remote_static_overlay(strength, task.time)
        self._update_planet_vision_overlay(task.time)
        return Task.cont

    def _draw_rescue_cable(self, from_node: NodePath, to_node: NodePath, time_value: float, blocked: bool = False) -> None:
        root = getattr(self, "remote_rescue_cable_root", None)
        if root is None or root.isEmpty():
            root = self.render.attachNewNode("remote_drone_rescue_cable")
            root.setTransparency(TransparencyAttrib.MAlpha)
            root.setLightOff(1)
            self.remote_rescue_cable_root = root
        for child in root.getChildren():
            child.removeNode()
        a = from_node.getPos(self.render) + Vec3(0.0, 0.0, 10.0)
        b = to_node.getPos(self.render)
        mid = (a + b) * 0.5 + Vec3(0.0, 0.0, 6.0 + math.sin(time_value * 6.0) * 1.8)
        segs = LineSegs("remote_rescue_cable_lines")
        segs.setThickness(3.4)
        if blocked:
            segs.setColor(1.0, 0.30, 0.18, 0.62)
        else:
            segs.setColor(0.45, 0.96, 1.0, 0.70)
        segs.moveTo(a)
        segs.drawTo(mid)
        segs.drawTo(b)
        np = root.attachNewNode(segs.create())
        np.setTransparency(TransparencyAttrib.MAlpha)
        np.setLightOff(1)

    def _active_rig_for_relocation(self) -> tuple[int, dict[str, object]] | None:
        if 0 <= self.active_rig_index < len(self.rigs):
            rig = self.rigs[self.active_rig_index]
            node = rig.get("node")
            if hasattr(node, "isEmpty") and not node.isEmpty():
                return self.active_rig_index, rig
        return None

    def _begin_drone_travel_to(self, x: float, y: float, start_pos: Vec3 | None = None) -> None:
        drone = self.persistent_drill_drone
        if drone is None or drone.isEmpty():
            self._start_drilling_hole(x, y)
            return
        drone.show()
        if start_pos is None:
            start_pos = drone.getPos(self.render)
        if IS_TITAN_LEVEL and self._liquid_contact_forbidden(x, y):
            sx, sy, adjusted = self._nearest_liquid_bank_point(start_pos, x, y)
            if adjusted:
                x, y = sx, sy
        target_z = self._terrain_contact_safe_height(x, y, 36.0)
        target_pos = Vec3(x, y, target_z)
        distance = max((target_pos - start_pos).length(), 1.0)
        duration = clamp(distance / 240.0, 0.85, 3.25)
        self.drone_dispatch = {
            "active": True,
            "phase": "travel",
            "x": x,
            "y": y,
            "start": Vec3(start_pos),
            "target": target_pos,
            "duration": duration,
            "time": 0.0,
            "progress": 0.0,
        }
        self.last_status_message = "DRONE ROUTING TO DRILL SITE"
        self.status_flash_timer = duration

    def _begin_active_rig_relocation(self, rig_index: int, rig: dict[str, object], x: float, y: float) -> None:
        node = rig.get("node")
        if not hasattr(node, "getPos"):
            self._begin_drone_travel_to(x, y)
            return
        rig["retracting"] = True
        rig["retract_progress"] = 0.0
        rig["retract_start_stabilize"] = clamp(float(rig.get("stabilize_progress", 1.0)), 0.0, 1.0)
        rig["retract_start_line_depth"] = float(rig.get("line_depth", 54.0))
        self.drone_dispatch = {
            "active": True,
            "phase": "retract",
            "rig_index": rig_index,
            "x": x,
            "y": y,
            "time": 0.0,
            "duration": 1.15,
            "progress": 0.0,
        }
        self.last_status_message = "DRONE RETRACTING TRIPOD AND LINE"
        self.status_flash_timer = 1.15

    def _release_retracted_rig_to_travel(self, rig_index: int, x: float, y: float) -> None:
        if not (0 <= rig_index < len(self.rigs)):
            self.drone_dispatch = None
            self._begin_drone_travel_to(x, y)
            return
        rig = self.rigs[rig_index]
        node = rig.get("node")
        if hasattr(node, "getPos"):
            start_pos = node.getPos(self.render)
            start_pos.z = self.world.surface_height(start_pos.x, start_pos.y) + 38.0
        else:
            start_pos = None
        if hasattr(node, "removeNode"):
            node.removeNode()
        self.rigs.pop(rig_index)
        if self.rigs:
            self.active_rig_index = min(max(rig_index - 1, 0), len(self.rigs) - 1)
        else:
            self.active_rig_index = -1
        drone = self.persistent_drill_drone
        if drone is not None and not drone.isEmpty() and start_pos is not None:
            drone.show()
            drone.setPos(start_pos)
            drone.setH(float(rig.get("phase", 0.0)) * 30.0)
        self._begin_drone_travel_to(x, y, start_pos)

    def _request_drone_drill_at(self, x: float, y: float) -> None:
        dispatch = self.drone_dispatch
        if dispatch and bool(dispatch.get("active", False)):
            phase = str(dispatch.get("phase", "travel"))
            if phase == "retract":
                self.last_status_message = "DRONE IS RETRACTING BEFORE RELOCATION"
            else:
                self.last_status_message = "DRONE ALREADY ROUTING TO DRILL SITE"
            self.status_flash_timer = 1.4
            return
        if any(not bool(effect.get("preview_only", False)) for effect in self.drill_effects):
            self.last_status_message = "DRILL SEQUENCE ALREADY ACTIVE"
            self.status_flash_timer = 1.4
            return
        hotspot = self._scan_hotspots_near(x, y)
        if hotspot is None or not bool(hotspot.get("ready", False)):
            self.pending_drill_hotspot = None
            if hotspot is None:
                self.last_status_message = "NO SONAR HOTSPOT UNDER CROSSHAIR"
            else:
                self.last_status_message = "SONAR TRACE WEAK - POINT INSIDE HOTSPOT"
            self.status_flash_timer = 1.6
            return
        self.pending_drill_hotspot = hotspot
        # Drill/sample at the actual ground point under the crosshair when dry.
        # Liquid targets are tested remotely from a safe bank point; no rover or
        # drone body is allowed to touch the liquid surface.
        sample_target_x = float(hotspot.get("sample_x", hotspot.get("x", x)))
        sample_target_y = float(hotspot.get("sample_y", hotspot.get("y", y)))
        if IS_TITAN_LEVEL and (self._liquid_contact_forbidden(x, y) or bool(hotspot.get("liquid_sample", False))):
            anchor = self._remote_anchor_position()
            bank_x, bank_y, adjusted = self._nearest_liquid_bank_point(anchor, sample_target_x, sample_target_y)
            x, y = bank_x, bank_y
            hotspot["liquid_sample"] = True
            hotspot["sample_x"] = sample_target_x
            hotspot["sample_y"] = sample_target_y
            hotspot["sample_from_bank"] = True
            if adjusted:
                self.last_status_message = "TITAN LIQUID SAMPLE // DRONE HOLDS BANK, TETHER TESTS METHANE"
                self.status_flash_timer = 1.8
        hotspot["drill_x"] = x
        hotspot["drill_y"] = y
        if not self._can_place_hole(x, y):
            self.last_status_message = "UNSAFE LIQUID EDGE OR TOO CLOSE TO ANOTHER HOLE"
            self.status_flash_timer = 1.5
            return
        active = self._active_rig_for_relocation()
        if active is not None:
            rig_index, rig = active
            self._begin_active_rig_relocation(rig_index, rig, x, y)
            return
        self._begin_drone_travel_to(x, y)

    def _animate_drone_dispatch(self, task: Task) -> int:
        drone = self.persistent_drill_drone
        if drone is None or drone.isEmpty():
            return Task.cont
        dt = min(globalClock.getDt(), 0.08)
        dispatch = self.drone_dispatch
        if dispatch and bool(dispatch.get("active", False)):
            phase = str(dispatch.get("phase", "travel"))
            dispatch["time"] = float(dispatch.get("time", 0.0)) + dt
            duration = max(float(dispatch.get("duration", 1.0)), 0.1)
            raw = clamp(float(dispatch["time"]) / duration, 0.0, 1.0)
            eased = raw * raw * (3.0 - 2.0 * raw)
            dispatch["progress"] = raw

            if phase == "retract":
                rig_index = int(dispatch.get("rig_index", -1))
                if not (0 <= rig_index < len(self.rigs)):
                    x = float(dispatch.get("x", 0.0))
                    y = float(dispatch.get("y", 0.0))
                    self.drone_dispatch = None
                    self._begin_drone_travel_to(x, y)
                    return Task.cont
                rig = self.rigs[rig_index]
                rig["retract_progress"] = raw
                rig["stabilize_progress"] = clamp(float(rig.get("retract_start_stabilize", 1.0)) * (1.0 - eased), 0.0, 1.0)
                rig["line_retract_progress"] = eased
                node = rig.get("node")
                if hasattr(node, "setZ"):
                    base_z = float(rig.get("base_z", node.getZ()))
                    node.setZ(base_z + eased * 9.0 + math.sin(task.time * 5.0) * 0.35)
                self.last_status_message = f"DRONE RETRACTING TRIPOD {int(raw * 100):02d}%"
                if raw >= 1.0:
                    x = float(dispatch.get("x", 0.0))
                    y = float(dispatch.get("y", 0.0))
                    self.drone_dispatch = None
                    self._release_retracted_rig_to_travel(rig_index, x, y)
                return Task.cont

            start = dispatch.get("start", Vec3(0.0, 0.0, 0.0))
            target = dispatch.get("target", Vec3(0.0, 0.0, 0.0))
            pos = start + (target - start) * eased
            terrain_z = self.world.surface_height(pos.x, pos.y)
            hop = math.sin(raw * math.pi) * 24.0
            bob = math.sin(task.time * 7.0) * 1.0
            pos.z = terrain_z + 36.0 + hop + bob
            drone.setPos(pos)
            dx = float(dispatch.get("x", pos.x)) - pos.x
            dy = float(dispatch.get("y", pos.y)) - pos.y
            if abs(dx) + abs(dy) > 0.01:
                drone.setH(math.degrees(math.atan2(-dx, dy)))
            self._update_persistent_drill_drone_visual(task.time, 0.65 + 0.35 * math.sin(raw * math.pi))
            self.last_status_message = f"DRONE APPROACHING DRILL SITE {int(raw * 100):02d}%"
            if raw >= 1.0:
                x = float(dispatch.get("x", pos.x))
                y = float(dispatch.get("y", pos.y))
                final_pos = Vec3(x, y, self.world.surface_height(x, y) + 34.0)
                drone.setPos(final_pos)
                drone.hide()
                self.drone_dispatch = None
                self._start_drilling_hole(x, y)
            return Task.cont
        if str(getattr(self, "active_control_mode", "")).upper() == "DRONE_A":
            self._update_persistent_drill_drone_visual(task.time, 0.20)
            return Task.cont
        if not drone.isHidden():
            pos = drone.getPos(self.render)
            pos.z = self.world.surface_height(pos.x, pos.y) + 40.0 + math.sin(task.time * 2.2) * 1.2
            drone.setPos(pos)
            self._update_persistent_drill_drone_visual(task.time, 0.0)
        return Task.cont

    def _start_drilling_hole(self, x: float, y: float, *, preview_progress: float | None = None) -> None:
        if not self._can_place_hole(x, y):
            self.last_status_message = "TOO CLOSE TO ANOTHER HOLE"
            self.status_flash_timer = 1.5
            return
        surface_z = self.world.surface_height(x, y)
        root = self.hole_root.attachNewNode(f"drill_sequence_{len(self.drill_effects)}")
        root.setPos(x, y, surface_z)

        guide = MeshFactory.make_disc("drill_guide_ring", HOLE_RADIUS * 1.10, segments=48)
        guide.reparentTo(root)
        guide.setZ(0.38)
        guide.setColorScale(0.22, 0.72, 1.0, 0.22)
        guide.setTwoSided(True)
        guide.setTransparency(TransparencyAttrib.MAlpha)
        guide.setBin("transparent", 38)
        guide.setLightOff(1)

        body = self.loader.loadModel("models/misc/sphere")
        body.reparentTo(root)
        body.setScale(8.0, 8.0, 2.6)
        body.setPos(0.0, 0.0, 30.0)
        body.setColorScale(0.16, 0.20, 0.24, 1.0)
        body.setLightOff(1)

        motor = self.loader.loadModel("models/misc/sphere")
        motor.reparentTo(root)
        motor.setScale(5.0, 5.0, 4.6)
        motor.setPos(0.0, 0.0, 22.0)
        motor.setColorScale(0.70, 0.90, 1.0, 1.0)
        motor.setLightOff(1)

        bit = self.loader.loadModel("models/misc/sphere")
        bit.reparentTo(root)
        bit.setScale(2.2, 2.2, 14.0)
        bit.setPos(0.0, 0.0, 10.0)
        bit.setColorScale(0.84, 0.94, 1.0, 1.0)
        bit.setLightOff(1)

        progress_disc = MeshFactory.make_disc("drill_scored_ice", HOLE_RADIUS * 0.18, segments=48)
        progress_disc.reparentTo(root)
        progress_disc.setZ(0.48)
        progress_disc.setColorScale(0.84, 0.96, 1.0, 0.28)
        progress_disc.setTwoSided(True)
        progress_disc.setTransparency(TransparencyAttrib.MAlpha)
        progress_disc.setBin("transparent", 39)
        progress_disc.setLightOff(1)

        blade_lines = root.attachNewNode("drill_blades")
        dust_lines = root.attachNewNode("drill_dust")
        chips: list[NodePath] = []
        for i in range(14):
            chip = self.loader.loadModel("models/misc/sphere")
            chip.reparentTo(root)
            chip.setScale(0.85 + (i % 5) * 0.22)
            chip.setColorScale(0.78, 0.94, 1.0, 0.54)
            chip.setTransparency(TransparencyAttrib.MAlpha)
            chip.setLightOff(1)
            chips.append(chip)

        effect = {
            "x": x,
            "y": y,
            "duration": 2.20,
            "time": 0.0,
            "root": root,
            "body": body,
            "motor": motor,
            "bit": bit,
            "guide": guide,
            "progress_disc": progress_disc,
            "blade_lines": blade_lines,
            "dust_lines": dust_lines,
            "chips": chips,
            "seed": len(self.holes) * 97 + len(self.drill_effects) * 31,
            "preview_only": preview_progress is not None,
        }
        self.drill_effects.append(effect)
        if preview_progress is None:
            self._play_sfx("drill_start")
            self._set_drill_loop(True)
        self.last_status_message = "DRILLING DARK REGOLITH LAYER..." if IS_IAPETUS_LEVEL else ("DRILLING THICK SNOW-ICE LAYER..." if IS_MIMAS_LEVEL else "DRILLING THICK ICE...")
        self.status_flash_timer = 2.2
        if preview_progress is not None:
            effect["time"] = float(effect["duration"]) * clamp(preview_progress, 0.0, 0.96)
            self._update_drill_effect(effect, float(effect["time"]))

    def _update_drill_effect(self, effect: dict[str, object], time_value: float) -> float:
        duration = max(float(effect.get("duration", 2.2)), 0.1)
        progress = clamp(float(effect.get("time", 0.0)) / duration, 0.0, 1.0)
        root = effect["root"]
        bit = effect["bit"]
        motor = effect["motor"]
        guide = effect["guide"]
        progress_disc = effect["progress_disc"]
        blade_lines = effect["blade_lines"]
        dust_lines = effect["dust_lines"]
        if not hasattr(root, "isEmpty") or root.isEmpty():
            return progress

        spin = time_value * 980.0
        root.setH(math.sin(time_value * 18.0) * (0.35 + progress * 0.75))
        motor.setH(spin % 360.0)
        bit.setH((-spin * 1.4) % 360.0)
        bit.setZ(12.0 - progress * 15.0)
        motor.setZ(22.0 - progress * 4.0)
        guide.setScale(1.0 + progress * 0.025)
        guide.setColorScale(0.22, 0.76, 1.0, 0.20 + progress * 0.10)
        progress_disc.setScale(0.20 + progress * 5.30)
        progress_disc.setColorScale(0.78, 0.92, 1.0, 0.16 + progress * 0.34)

        for child in blade_lines.getChildren():
            child.removeNode()
        blades = LineSegs("animated_drill_blades")
        blades.setThickness(3.0)
        blades.setColor(0.80, 0.94, 1.0, 0.86)
        for arm in range(4):
            ang = math.radians(spin + arm * 90.0)
            blades.moveTo(math.cos(ang) * 2.0, math.sin(ang) * 2.0, 11.0 - progress * 11.0)
            blades.drawTo(math.cos(ang) * 10.0, math.sin(ang) * 10.0, 7.0 - progress * 9.0)
        turns = 5
        points = 64
        for i in range(points):
            t = i / max(points - 1, 1)
            ang = math.radians(spin * 0.45) + t * math.tau * turns
            r = 3.1 + math.sin(t * math.tau * 3.0) * 0.35
            z = 19.0 - t * 23.0 - progress * 2.0
            if i == 0:
                blades.moveTo(math.cos(ang) * r, math.sin(ang) * r, z)
            else:
                blades.drawTo(math.cos(ang) * r, math.sin(ang) * r, z)
        blade_np = blade_lines.attachNewNode(blades.create())
        blade_np.setTransparency(TransparencyAttrib.MAlpha)
        blade_np.setLightOff(1)

        for child in dust_lines.getChildren():
            child.removeNode()
        dust = LineSegs("drill_dust_rings")
        dust.setThickness(2.2)
        dust.setColor(0.86, 0.96, 1.0, 0.40 + progress * 0.36)
        ring_segments = 48
        for ring_index in range(3):
            radius = HOLE_RADIUS * (0.28 + progress * 0.88 + ring_index * 0.18)
            phase = time_value * (2.4 + ring_index * 0.4)
            for i in range(ring_segments + 1):
                a = (i / ring_segments) * math.tau
                wobble = 1.0 + math.sin(a * 5.0 + phase) * (0.025 + progress * 0.030)
                x = math.cos(a) * radius * wobble
                y = math.sin(a) * radius * wobble
                z = 0.64 + ring_index * 0.24 + math.sin(a * 4.0 + phase) * 0.10
                if i == 0:
                    dust.moveTo(x, y, z)
                else:
                    dust.drawTo(x, y, z)
        dust_np = dust_lines.attachNewNode(dust.create())
        dust_np.setTransparency(TransparencyAttrib.MAlpha)
        dust_np.setDepthWrite(False)
        dust_np.setLightOff(1)

        chips = effect.get("chips", [])
        seed = int(effect.get("seed", 0))
        for i, chip in enumerate(chips):
            angle = (i / max(len(chips), 1)) * math.tau + time_value * (2.8 + (i % 4) * 0.35) + seed * 0.013
            push = HOLE_RADIUS * (0.30 + progress * (0.58 + (i % 5) * 0.045))
            bob = math.sin(time_value * 6.0 + i) * (0.20 + progress * 0.35)
            chip.setPos(math.cos(angle) * push, math.sin(angle) * push, 0.95 + bob)
            chip.setColorScale(0.78, 0.94, 1.0, max(0.10, 0.58 - progress * 0.18))
        return progress

    def _finish_drilling_effect(self, effect: dict[str, object]) -> None:
        root = effect.get("root")
        x = float(effect.get("x", 0.0))
        y = float(effect.get("y", 0.0))
        if hasattr(root, "removeNode"):
            root.removeNode()
        if not bool(effect.get("preview_only", False)):
            self._spawn_hole(x, y)

    def _spawn_hole(self, x: float, y: float) -> None:
        if len(self.holes) >= MAX_HOLES:
            return
        for hole in self.holes:
            if (hole.x - x) ** 2 + (hole.y - y) ** 2 < (hole.radius + HOLE_RADIUS * 0.9) ** 2:
                return
        hole = Hole(x, y, HOLE_RADIUS)
        self.holes.append(hole)
        # Stable local-hole method: keep the original pretty terrain intact and let
        # the drilled opening own its fitted rim/aperture/shaft geometry. This avoids
        # sorting fights between a live transparent heightfield and the hole walls.
        self._spawn_local_hole_patch(hole)
        self._spawn_hole_shaft(hole)
        self._spawn_hole_cracks(hole)
        if IS_MIMAS_LEVEL:
            self._rebuild_mimas_crater_ice_pools()
        self._spawn_floating_rig(hole)

    def _spawn_local_hole_patch(self, hole: Hole) -> None:
        surface_z = self.world.surface_height(hole.x, hole.y)
        patch = MeshFactory.make_local_hole_patch(
            f"stable_local_hole_patch_{len(self.holes)}",
            hole.x,
            hole.y,
            hole.radius * 0.72,
            hole.radius * 1.12,
            self.world.surface_height,
            self._rig_hash01,
            segments=72,
            rings=6,
        )
        patch.reparentTo(self.hole_root)
        patch.setTexture(self.ice_base_stage, self._load_texture(self.texture_paths["ice_base"], repeat=True))
        patch.setTexture(self.ice_detail_stage, self._load_texture(self.texture_paths["ice_detail"], repeat=True))
        patch.setTexScale(self.ice_base_stage, 0.28, 0.28)
        patch.setTexScale(self.ice_detail_stage, 0.92, 0.92)
        patch.setColorScale(0.50, 0.66, 0.82, 1.0)
        patch.setTwoSided(False)
        patch.setDepthWrite(True)
        patch.setDepthTest(True)
        patch.setBin("opaque", 0)
        mat = Material()
        mat.setBaseColor((0.58, 0.76, 0.90, 1.0))
        mat.setEmission((0.002, 0.004, 0.008, 1.0))
        mat.setShininess(28.0)
        patch.setMaterial(mat, 1)

        aperture = MeshFactory.make_disc(f"stable_hole_dark_aperture_{len(self.holes)}", hole.radius * 0.74, segments=56)
        aperture.reparentTo(self.hole_root)
        aperture.setPos(hole.x, hole.y, surface_z + 0.16)
        aperture.setColorScale(0.006, 0.018, 0.030, 1.0)
        aperture.setTwoSided(True)
        aperture.setDepthWrite(True)
        aperture.setDepthTest(True)
        aperture.setBin("opaque", 0)
        aperture.setLightOff(1)

        # A few solid chips around the edge make the drilled rim read as broken ice,
        # but they stay small so the result does not become another artificial mound.
        for i in range(10):
            a = (i / 10.0) * math.tau + self._rig_hash01(int(hole.x // 19), int(hole.y // 19), 880 + i) * 0.35
            dist = hole.radius * (0.78 + self._rig_hash01(int(hole.x // 13), int(hole.y // 13), 910 + i) * 0.25)
            chip = self.loader.loadModel("models/misc/sphere")
            chip.reparentTo(self.hole_root)
            chip.setScale(2.8 + (i % 3) * 0.8, 1.0 + (i % 2) * 0.5, 0.32)
            chip.setPos(hole.x + math.cos(a) * dist, hole.y + math.sin(a) * dist, self.world.surface_height(hole.x + math.cos(a) * dist, hole.y + math.sin(a) * dist) + 0.28)
            chip.setH(math.degrees(a) + i * 17.0)
            chip.setColorScale(0.42, 0.58, 0.72, 1.0)
            chip.setDepthWrite(True)
            chip.setDepthTest(True)
            chip.setBin("opaque", 0)
            chip.setLightOff(1)

    def _spawn_hole_shaft(self, hole: Hole) -> None:
        surface_z = self.world.surface_height(hole.x, hole.y)
        # Render a believable local ice thickness instead of exposing a giant visual tube
        # all the way to the global water plane through the transparent ice sheet.
        shaft_bottom_z = surface_z - 52.0
        shaft_bottom = lambda _x, _y: shaft_bottom_z
        water_z = shaft_bottom_z
        shaft = MeshFactory.make_hole_shaft(
            f"hole_shaft_{len(self.holes)}",
            hole.x,
            hole.y,
            hole.radius * 0.74,
            self.world.surface_height,
            shaft_bottom,
            segments=56,
        )
        shaft.reparentTo(self.hole_wall_root)
        shaft.setTexture(self._load_texture(self.texture_paths["hole_wall"], repeat=True))
        shaft.setTexScale(TextureStage.getDefault(), 1.0, max((surface_z - water_z) / 40.0, 1.0))
        shaft.setColorScale(0.08, 0.18, 0.28, 1.0)
        shaft.setTwoSided(True)
        shaft.setDepthWrite(True)
        shaft.setDepthTest(True)
        shaft.setBin("opaque", 0)
        wall_mat = Material()
        wall_mat.setBaseColor((0.10, 0.20, 0.30, 1.0))
        wall_mat.setEmission((0.0, 0.001, 0.003, 1.0))
        wall_mat.setShininess(8.0)
        shaft.setMaterial(wall_mat, 1)

        water_disc = MeshFactory.make_disc(f"hole_water_{len(self.holes)}", hole.radius * 0.70, segments=40)
        water_disc.reparentTo(self.hole_wall_root)
        water_disc.setPos(hole.x, hole.y, water_z + 0.05)
        water_disc.setTexture(self._load_texture(self.texture_paths["water"], repeat=True))
        water_disc.setColorScale(0.20, 0.38, 0.54, 1.0)
        water_disc.setTwoSided(True)
        water_disc.setDepthWrite(True)
        water_disc.setDepthTest(True)
        water_disc.setBin("opaque", 0)
        water_disc.setTexScale(TextureStage.getDefault(), 0.12, 0.12)
        water_disc.setTexOffset(TextureStage.getDefault(), (hole.x % 120.0) / 120.0, (hole.y % 120.0) / 120.0)
        water_mat = Material()
        water_mat.setBaseColor((0.06, 0.16, 0.22, 1.0))
        water_mat.setEmission((0.0, 0.02, 0.03, 1.0))
        water_mat.setShininess(26.0)
        water_disc.setMaterial(water_mat, 1)

    def _spawn_hole_ring(self, hole: Hole) -> None:
        cm = CardMaker(f"hole_ring_{len(self.holes)}")
        cm.setFrame(-1.0, 1.0, -1.0, 1.0)
        ring = self.hole_root.attachNewNode(cm.generate())
        ring.setP(-90)
        ring.setPos(hole.x, hole.y, self.world.surface_height(hole.x, hole.y) + 0.18)
        ring.setScale(hole.radius * 1.08)
        ring.setTexture(self._load_texture(self.texture_paths["hole_ring"], repeat=False, clamp=True))
        ring.setColorScale(0.90, 0.96, 1.0, 0.62)
        ring.setTransparency(TransparencyAttrib.MAlpha)
        ring.setDepthWrite(False)
        ring.setBin("transparent", 40)
        ring.setLightOff(1)

    def _spawn_floating_rig(self, hole: Hole) -> None:
        rig = self.rig_root.attachNewNode(f"rig_{len(self.rigs)}")
        surface_z = self.world.surface_height(hole.x, hole.y)
        base_z = surface_z + 22.0
        rig.setPos(hole.x, hole.y, base_z)

        body = self.loader.loadModel("models/misc/sphere")
        body.reparentTo(rig)
        body.setScale(16.0, 16.0, 2.6)
        self._apply_holoverse_surface(body, tint=(0.72, 0.96, 1.0), alpha=1.0, emission=(0.140, 0.240, 0.300), shininess=40.0, tex_scale=(2.6, 1.15), transparent=False)
        self._attach_holoverse_trim_rings(body, "rig_body_trim", 0.90, [0.12, -0.08], color=(0.36, 0.96, 1.0, 0.48), thickness=1.1, y_scale=0.84)

        cap = self.loader.loadModel("models/misc/sphere")
        cap.reparentTo(rig)
        cap.setScale(7.4, 7.4, 5.2)
        cap.setZ(4.8)
        self._apply_holoverse_surface(cap, tint=(0.46, 0.78, 0.90), alpha=1.0, emission=(0.018, 0.042, 0.058), shininess=26.0, tex_scale=(1.5, 1.25), transparent=False)

        for ox, oy in ((8.5, 8.5), (-8.5, 8.5), (8.5, -8.5), (-8.5, -8.5)):
            thruster = self.loader.loadModel("models/misc/sphere")
            thruster.reparentTo(rig)
            thruster.setScale(2.2, 2.2, 1.4)
            thruster.setPos(ox, oy, -1.4)
            self._apply_holoverse_surface(thruster, tint=(0.48, 0.98, 1.0), alpha=1.0, emission=(0.160, 0.280, 0.340), shininess=36.0, tex_scale=(1.0, 1.0), transparent=False)

        # Stabilizer tripod: stowed inside the robot during drilling, then extends
        # after the hole opens.  The legs are kept as world-stable/braced geometry
        # relative to the rig so the drone reads as anchored for heavy pulls.
        stabilizer_root = rig.attachNewNode("stabilizer_tripod")
        stabilizer_lines = stabilizer_root.attachNewNode("tripod_leg_lines")
        stabilizer_feet: list[NodePath] = []
        stabilizer_spikes: list[NodePath] = []
        stabilizer_mounts: list[NodePath] = []
        for i in range(3):
            mount = self.loader.loadModel("models/misc/sphere")
            mount.reparentTo(stabilizer_root)
            mount.setScale(1.7, 1.7, 1.0)
            self._apply_holoverse_surface(mount, tint=(0.40, 0.72, 0.82), alpha=1.0, emission=(0.012, 0.028, 0.040), shininess=22.0, tex_scale=(1.0, 1.0), transparent=False)
            stabilizer_mounts.append(mount)

            foot = self.loader.loadModel("models/misc/sphere")
            foot.reparentTo(stabilizer_root)
            foot.setScale(3.6, 2.2, 0.55)
            self._apply_holoverse_surface(foot, tint=(0.60, 0.86, 0.94), alpha=1.0, emission=(0.018, 0.040, 0.055), shininess=22.0, tex_scale=(1.4, 0.8), transparent=False)
            stabilizer_feet.append(foot)

            spike = self.loader.loadModel("models/misc/sphere")
            spike.reparentTo(stabilizer_root)
            spike.setScale(1.0, 1.0, 1.8)
            self._apply_holoverse_surface(spike, tint=(0.44, 0.76, 0.88), alpha=1.0, emission=(0.014, 0.032, 0.046), shininess=20.0, tex_scale=(1.0, 1.6), transparent=False)
            stabilizer_spikes.append(spike)

        cable = rig.attachNewNode("cable")
        hook = self.loader.loadModel("models/misc/sphere")
        hook.reparentTo(rig)
        hook.setScale(2.2)
        self._apply_holoverse_surface(hook, tint=(0.90, 0.62, 0.38), alpha=1.0, emission=(0.050, 0.040, 0.028), shininess=18.0, tex_scale=(0.8, 1.6), transparent=False)

        cargo = self.loader.loadModel("models/misc/sphere")
        cargo.reparentTo(rig)
        cargo.setScale(5.2, 4.1, 2.2)
        self._apply_holoverse_surface(cargo, tint=(0.70, 0.84, 0.92), alpha=1.0, emission=(0.080, 0.150, 0.190), shininess=24.0, tex_scale=(1.1, 1.0), transparent=False)
        cargo.hide()

        glow = self.loader.loadModel("models/misc/sphere")
        glow.reparentTo(rig)
        glow.setScale(3.8, 3.8, 0.65)
        glow.setPos(0.0, 0.0, -1.4)
        self._apply_holoverse_surface(glow, tint=(0.34, 0.98, 1.0), alpha=0.62, emission=(0.120, 0.220, 0.290), shininess=18.0, tex_scale=(1.0, 1.0), transparent=True)

        for node in (body, cap, hook, cargo):
            node.setLightOff(1)

        cell_x = int((hole.x + WORLD_HALF) // 260)
        cell_y = int((hole.y + WORLD_HALF) // 260)
        hotspot = self.pending_drill_hotspot
        if hotspot is None or math.hypot(float(hotspot.get("x", hole.x)) - hole.x, float(hotspot.get("y", hole.y)) - hole.y) > HOTSPOT_DRILL_RADIUS * 1.35:
            hotspot = self._scan_hotspots_near(hole.x, hole.y)
        if hotspot is not None and bool(hotspot.get("ready", False)):
            entity_present = True
            entity_depth = float(hotspot.get("depth", 120.0))
            fish_name = str(hotspot.get("fish_name", self._fish_name_for_cell(cell_x, cell_y)))
            profile = dict(hotspot.get("target_profile", self._target_profile_by_name(fish_name)))
            hotspot_strength = float(hotspot.get("signal", hotspot.get("strength", 0.8)))
        else:
            entity_roll = self._rig_hash01(cell_x, cell_y, 233)
            entity_present = entity_roll > 0.66
            entity_depth = 84.0 + self._rig_hash01(cell_x, cell_y, 241) * 210.0
            profile = self._target_profile_for_cell(cell_x, cell_y)
            fish_name = str(profile.get("name", "Enceladus Sample"))
            hotspot_strength = 0.45
        required_tool = self._target_profile_tool(profile)
        target_kind = self._target_profile_class(profile)
        resource_name = str(profile.get("resource", "FERROUS SALVAGE"))
        upgrade_use = str(profile.get("upgrade_use", "future building upgrade"))
        self.pending_drill_hotspot = None
        line_depth = 54.0

        rig_data = {
            "node": rig,
            # Keep the rig's resting animation height separate from the raw
            # ice surface height.  The prior pass stored an undefined surface_z
            # here, which crashed as soon as drilling completed and the robot
            # tried to spawn its braced tripod rig.
            "base_z": base_z,
            "surface_z": surface_z,
            "phase": len(self.rigs) * 0.73,
            "cable": cable,
            "hook": hook,
            "cargo": cargo,
            "glow": glow,
            "stabilizer_root": stabilizer_root,
            "stabilizer_lines": stabilizer_lines,
            "stabilizer_feet": stabilizer_feet,
            "stabilizer_spikes": stabilizer_spikes,
            "stabilizer_mounts": stabilizer_mounts,
            "stabilize_progress": 0.0,
            "pull_load": 0.0,
            "hotspot_strength": hotspot_strength,
            "hotspot_key": str(hotspot.get("key", "")) if hotspot is not None else "",
            "reeling": False,
            "reel_locked": False,
            "reel_progress": 0.0,
            "reel_tension": 0.0,
            "auto_hoist": False,
            "attached_object": False,
            "collection_ready": False,
            "attach_hook_z": None,
            "signal_lock_time": 0.0,
            "hole": hole,
            "line_depth": line_depth,
            "entity_present": entity_present,
            "entity_depth": entity_depth,
            "signal": 0.0,
            "fish_name": fish_name,
            "target_kind": target_kind,
            "target_class": target_kind,
            "tool_hint": self._tool_hint_for_profile(profile),
            "required_tool": required_tool,
            "resource_name": resource_name,
            "upgrade_use": upgrade_use,
            "target_profile": profile,
            "line_tool": self.selected_line_tool,
            "caught": False,
            "anchor_sfx_played": False,
            "braced_sfx_played": False,
            "depth_lock_sfx_played": False,
        }
        self.rigs.append(rig_data)
        self.active_rig_index = len(self.rigs) - 1
        self._apply_line_tool_visual(rig_data, 0.0)
        self._play_sfx("robot_activate")

    def _update_stabilizer_tripod(self, rig: dict[str, object], time_value: float) -> None:
        node = rig.get("node")
        hole = rig.get("hole")
        lines_root = rig.get("stabilizer_lines")
        feet = rig.get("stabilizer_feet", [])
        spikes = rig.get("stabilizer_spikes", [])
        mounts = rig.get("stabilizer_mounts", [])
        if not hasattr(node, "getZ") or hole is None or not hasattr(lines_root, "getChildren"):
            return
        progress = clamp(float(rig.get("stabilize_progress", 0.0)), 0.0, 1.0)
        eased = progress * progress * (3.0 - 2.0 * progress)
        hx = float(getattr(hole, "x", 0.0))
        hy = float(getattr(hole, "y", 0.0))
        base_z = float(rig.get("base_z", node.getZ()))
        current_z = node.getZ()
        deploy_radius = HOLE_RADIUS * (1.06 + 0.32 * eased)
        mount_radius = 9.5
        for child in lines_root.getChildren():
            child.removeNode()
        segs = LineSegs("tripod_stabilizer_lines")
        segs.setThickness(4.4)
        if eased >= 0.98:
            segs.setColor(0.76, 0.94, 1.0, 0.96)
        else:
            segs.setColor(0.42, 0.86, 1.0, 0.64 + eased * 0.22)

        for i in range(3):
            angle = (i / 3.0) * math.tau + math.radians(30.0)
            mount = Vec3(math.cos(angle) * mount_radius, math.sin(angle) * mount_radius, 1.2)
            hinge_radius = mount_radius + (deploy_radius - mount_radius) * (0.42 + eased * 0.36)
            hinge = Vec3(math.cos(angle) * hinge_radius, math.sin(angle) * hinge_radius, -5.0 - eased * 6.0)
            foot_radius = mount_radius + (deploy_radius - mount_radius) * eased
            wx = hx + math.cos(angle) * foot_radius
            wy = hy + math.sin(angle) * foot_radius
            terrain_z = self.world.surface_height(wx, wy) + 0.55
            foot = Vec3(math.cos(angle) * foot_radius, math.sin(angle) * foot_radius, terrain_z - current_z)
            if eased < 1.0:
                stowed = Vec3(math.cos(angle) * (mount_radius + 1.5), math.sin(angle) * (mount_radius + 1.5), -2.8)
                foot = stowed + (foot - stowed) * eased
                hinge = mount + (hinge - mount) * max(0.18, eased)

            segs.moveTo(mount)
            segs.drawTo(hinge)
            segs.drawTo(foot)
            # Cross brace gives the legs a load-bearing/pulling-machine read.
            brace = Vec3(math.cos(angle) * (mount_radius * 0.68 + foot_radius * 0.32), math.sin(angle) * (mount_radius * 0.68 + foot_radius * 0.32), -1.6 - eased * 2.8)
            segs.moveTo(Vec3(0.0, 0.0, -0.8))
            segs.drawTo(brace)

            if i < len(feet):
                feet[i].setPos(foot)
                feet[i].setH(math.degrees(angle))
                feet[i].setScale(1.6 + eased * 2.4, 0.8 + eased * 1.4, 0.16 + eased * 0.42)
                feet[i].setColorScale(0.30 + eased * 0.24, 0.52 + eased * 0.20, 0.66 + eased * 0.20, 1.0)
                if eased <= 0.03:
                    feet[i].hide()
                else:
                    feet[i].show()
            if i < len(spikes):
                spikes[i].setPos(foot.x, foot.y, foot.z - 1.0 - eased * 1.2)
                spikes[i].setH(math.degrees(angle))
                spikes[i].setScale(0.5 + eased * 0.7, 0.5 + eased * 0.7, 0.8 + eased * 1.2)
                if eased < 0.25:
                    spikes[i].hide()
                else:
                    spikes[i].show()
            if i < len(mounts):
                mounts[i].setPos(mount)
                mounts[i].setH(math.degrees(angle))
        line_np = lines_root.attachNewNode(segs.create())
        line_np.setDepthWrite(True)
        line_np.setDepthTest(True)
        line_np.setLightOff(1)

    def _hole_at(self, x: float, y: float) -> Hole | None:
        for hole in self.holes:
            if (hole.x - x) ** 2 + (hole.y - y) ** 2 <= (hole.radius - 2.0) ** 2:
                return hole
        return None

    def _set_underwater_state(self, state: bool) -> None:
        if self._underwater == state:
            return
        self._underwater = state
        overlay = getattr(self, "titan_underwater_overlay_root", None)
        if state:
            self.render.setFog(self.fog_water)
            if IS_TITAN_LEVEL:
                self.setBackgroundColor(0.030, 0.050, 0.035, 1.0)
                if overlay is not None and not overlay.isEmpty():
                    overlay.show()
                    overlay.setColorScale(0.28, 0.82, 0.92, 0.26)
            else:
                self.setBackgroundColor(0.0, 0.03, 0.05, 1.0)
        else:
            self.render.setFog(self.fog_surface)
            self.setBackgroundColor((0.006, 0.016, 0.048, 1.0) if IS_TRITON_LEVEL else ((0.042, 0.022, 0.010, 1.0) if IS_TITAN_LEVEL else ((0.00045, 0.00055, 0.0018, 1.0) if IS_PLUTO_LEVEL else (0.004, 0.005, 0.014, 1.0))))
            if overlay is not None and not overlay.isEmpty():
                overlay.hide()
                overlay.setColorScale(0.28, 0.82, 0.92, 0.0)

    def _update_camera(self, task: Task) -> int:
        dt = min(globalClock.getDt(), 0.2)
        if getattr(self, "starfall_vessel_active", False):
            return self._update_starfall_vessel(task)
        if self.menu_input_locked or self._is_any_hud_panel_open():
            self.velocity = Vec3(0.0, 0.0, 0.0)
            self.keys["reel"] = False
            return Task.cont
        control_mode_for_pitch = str(getattr(self, "active_control_mode", "DRONE_A")).upper()
        if control_mode_for_pitch == "ROVER":
            self._select_control_mode("DRONE_A")
            control_mode_for_pitch = "DRONE_A"
        if not self.is_offscreen and self.win.getProperties().getForeground():
            dx, dy = self._mouse_delta()
            self.heading -= dx * self.mouse_sensitivity
            raw_pitch = self.pitch - dy * self.mouse_sensitivity * 0.80
            if control_mode_for_pitch.startswith("DRONE"):
                self.pitch = clamp(raw_pitch, DRONE_CAMERA_MIN_PITCH, DRONE_CAMERA_MAX_PITCH)
            elif control_mode_for_pitch == "ROVER":
                self.pitch = clamp(raw_pitch, ROVER_CAMERA_MIN_PITCH, ROVER_CAMERA_MAX_PITCH)
            else:
                self.pitch = clamp(raw_pitch, -85.0, 85.0)
            self.camera.setHpr(self.heading, self.pitch, 0.0)

        heading_rad = math.radians(self.heading)
        forward = Vec3(-math.sin(heading_rad), math.cos(heading_rad), 0)
        right = Vec3(math.cos(heading_rad), math.sin(heading_rad), 0)
        wish = Vec3(0, 0, 0)
        if self.keys["forward"]:
            wish += forward
        if self.keys["back"]:
            wish -= forward
        if self.keys["left"]:
            wish -= right
        if self.keys["right"]:
            wish += right
        if wish.lengthSquared() > 0.0:
            wish.normalize()

        sliding = bool(self.keys.get("slide", False) and wish.lengthSquared() > 0.0)
        control_mode = str(getattr(self, "active_control_mode", "DRONE_A")).upper()
        if control_mode == "ROVER":
            self._select_control_mode("DRONE_A")
            control_mode = "DRONE_A"
        jump_pressed = bool(self.keys.get("up", False))
        if not jump_pressed:
            self._jump_armed = True
        if control_mode == "ROVER":
            self._drive_rover_from_inputs(dt, wish, sliding, jump_pressed)
            self._set_underwater_state(False)
            return Task.cont
        if control_mode.startswith("DRONE"):
            self.drone_control_heading = self.heading
            self.drone_control_pitch = clamp(self.pitch, DRONE_CAMERA_MIN_PITCH, DRONE_CAMERA_MAX_PITCH)
            dispatch = getattr(self, "drone_dispatch", None)
            if control_mode == "DRONE_A" and dispatch and bool(dispatch.get("active", False)):
                # Hover-drone click-to-hotspot autopilot owns movement while the
                # belly camera remains attached to the existing Drone A body.
                self._apply_drone_camera("DRONE_A")
            else:
                vertical = (1.0 if self.keys.get("up", False) else 0.0) - (1.0 if self.keys.get("slide", False) else 0.0)
                self._drive_drone_from_inputs(dt, control_mode, wish, vertical)
            self._set_underwater_state(False)
            return Task.cont
        if sliding:
            # Pass 95: robot feet switch to low-friction runners while Shift is held.
            # The same wish vector is used for forward/back/strafe, so diagonal and
            # pure side-slides are fast without needing separate movement code.
            accel = 820.0
            max_speed = 590.0
            drag_base = 0.987
        else:
            accel = 430.0
            max_speed = 270.0
            drag_base = 0.940
        self.velocity += wish * accel * dt
        self.velocity.setZ(0.0)
        drag = drag_base ** (dt * 60.0)
        self.velocity.x *= drag
        self.velocity.y *= drag
        planar = Vec2(self.velocity.x, self.velocity.y)
        speed = planar.length()
        if speed > max_speed:
            planar.normalize()
            planar *= max_speed
            self.velocity.x, self.velocity.y = planar.x, planar.y
            speed = max_speed
        self.ice_slide_active = bool(sliding and speed > 230.0)
        self.ice_slide_speed = float(speed)

        current_pos = self.camera.getPos()
        current_ground = self.world.surface_height(current_pos.x, current_pos.y)
        was_grounded = bool(getattr(self, "player_grounded", True))
        current_vertical_offset = max(0.0, float(getattr(self, "player_vertical_offset", 0.0)))
        jump_pressed = bool(self.keys.get("up", False))
        if not jump_pressed:
            self._jump_armed = True
        if jump_pressed and self._jump_armed and was_grounded:
            self.player_vertical_velocity = PLAYER_EFFECTIVE_JUMP_IMPULSE
            self.player_grounded = False
            self._jump_armed = False
            was_grounded = False
            self.last_status_message = "TRITON MICRO-G // FLOAT TIME EXTENDED" if IS_TRITON_LEVEL else ("EUROPA LOW-G // FLOAT TIME EXTENDED" if IS_EUROPA_LEVEL else "LOW-G CLIMB JUMP")
            self.status_flash_timer = max(float(getattr(self, "status_flash_timer", 0.0)), 0.55)

        pos = current_pos + self.velocity * dt
        pos.x = clamp(pos.x, -WORLD_HALF + 40.0, WORLD_HALF - 40.0)
        pos.y = clamp(pos.y, -WORLD_HALF + 40.0, WORLD_HALF - 40.0)
        terrain_z = self.world.surface_height(pos.x, pos.y)
        climb_delta = terrain_z - current_ground
        self._last_climb_delta = float(climb_delta)
        if wish.lengthSquared() > 0.0 and climb_delta > PLAYER_CLIMB_STEP_SOFT and was_grounded:
            # Do not hard-stop on rough procedural slopes.  Instead, bleed speed
            # proportionally and let the ground snap/vertical jump arc carry the
            # player up the face.  This makes mountains climbable while still
            # making steep grades feel heavier.
            severity = clamp((climb_delta - PLAYER_CLIMB_STEP_SOFT) / max(PLAYER_CLIMB_STEP_HARD - PLAYER_CLIMB_STEP_SOFT, 1.0), 0.0, 1.0)
            climb_speed = 1.0 - severity * (1.0 - PLAYER_CLIMB_SPEED_FLOOR)
            if jump_pressed:
                climb_speed = max(climb_speed, 0.84)
            pos = current_pos + (pos - current_pos) * climb_speed
            pos.x = clamp(pos.x, -WORLD_HALF + 40.0, WORLD_HALF - 40.0)
            pos.y = clamp(pos.y, -WORLD_HALF + 40.0, WORLD_HALF - 40.0)
            terrain_z = self.world.surface_height(pos.x, pos.y)
            self.velocity.x *= 0.96 - severity * 0.18
            self.velocity.y *= 0.96 - severity * 0.18

        if IS_TITAN_LEVEL:
            liquid_signal = self.world.titan_liquid_signal(pos.x, pos.y)
            if self._liquid_contact_forbidden(pos.x, pos.y, pos.z):
                bx, by, adjusted = self._nearest_liquid_bank_point(current_pos, pos.x, pos.y)
                if adjusted and not self._liquid_contact_forbidden(bx, by):
                    pos.x, pos.y = bx, by
                    terrain_z = self.world.surface_height(pos.x, pos.y)
                    self.velocity.x *= 0.36
                    self.velocity.y *= 0.36
                else:
                    pos = current_pos
                    terrain_z = current_ground
                    self.velocity.x *= 0.10
                    self.velocity.y *= 0.10
                if self.status_flash_timer <= 0.0:
                    self.last_status_message = "LIQUID CONTACT LOCKOUT // SAMPLE FROM BANK"
                    self.status_flash_timer = 1.4
            elif liquid_signal >= TITAN_LIQUID_SAMPLE_SIGNAL_MIN and self.status_flash_timer <= 0.0:
                self.last_status_message = "TITAN SHORELINE // TEST METHANE/ETHANE WITH SAMPLE TETHER"
                self.status_flash_timer = 0.9
        if IS_IAPETUS_LEVEL:
            # Iapetus is a mountain-ascent operation.  Pass36 keeps the scale and
            # danger, but removes the sticky uphill clamp that made the ridge feel
            # like the controls were failing.
            radial = math.hypot(pos.x, pos.y)
            if radial > IAPETUS_PLAY_RADIUS:
                if radial > 0.001:
                    scale = IAPETUS_PLAY_RADIUS / radial
                    pos.x *= scale
                    pos.y *= scale
                terrain_z = self.world.surface_height(pos.x, pos.y)
                self.velocity.x *= 0.16
                self.velocity.y *= 0.16
                if self.status_flash_timer <= 0.0:
                    self.last_status_message = IAPETUS_EDGE_MESSAGE
                    self.status_flash_timer = 1.8
            elif radial >= IAPETUS_BOUNDARY_WARN_RADIUS and self.status_flash_timer <= 0.0:
                self.last_status_message = "APPROACHING DARK HORIZON LIMIT // RETURN TOWARD RIDGE CORRIDOR"
                self.status_flash_timer = 1.2
            climb = max(0.0, terrain_z - current_ground)
            ridge_factor = self.world._iapetus_ridge_factor_at(pos.x, pos.y)
            climb_penalty = clamp((climb / 48.0) * (0.18 + ridge_factor * 0.42), 0.0, 0.34)
            if climb_penalty > 0.01 and was_grounded:
                if jump_pressed:
                    climb_penalty *= 0.38
                pos = current_pos + (pos - current_pos) * (1.0 - climb_penalty)
                pos.x = clamp(pos.x, -WORLD_HALF + 40.0, WORLD_HALF - 40.0)
                pos.y = clamp(pos.y, -WORLD_HALF + 40.0, WORLD_HALF - 40.0)
                edge_r = math.hypot(pos.x, pos.y)
                if edge_r > IAPETUS_PLAY_RADIUS:
                    scale = IAPETUS_PLAY_RADIUS / max(edge_r, 1e-6)
                    pos.x *= scale
                    pos.y *= scale
                terrain_z = self.world.surface_height(pos.x, pos.y)
                self.velocity.x *= 1.0 - climb_penalty * 0.30
                self.velocity.y *= 1.0 - climb_penalty * 0.30
                if ridge_factor > 0.36 and self.status_flash_timer <= 0.0:
                    self.last_status_message = "RIDGE CLIMB ASSIST // SPACE HOPS OVER JAGGED STEPS"

        if not bool(getattr(self, "player_grounded", True)):
            self.player_vertical_velocity -= PLAYER_EFFECTIVE_GRAVITY * dt
            current_vertical_offset += self.player_vertical_velocity * dt
            current_vertical_offset = min(current_vertical_offset, PLAYER_EFFECTIVE_MAX_JUMP_OFFSET)
            if current_vertical_offset <= PLAYER_GROUND_SNAP_DISTANCE and self.player_vertical_velocity <= 0.0:
                current_vertical_offset = 0.0
                self.player_vertical_velocity = 0.0
                self.player_grounded = True
        else:
            self.player_vertical_velocity = 0.0
            current_vertical_offset = max(0.0, current_vertical_offset - PLAYER_EFFECTIVE_GRAVITY * dt * 0.45)
        self.player_vertical_offset = max(0.0, current_vertical_offset)
        pos.z = terrain_z + PLAYER_EYE_HEIGHT + self.player_vertical_offset
        self._set_underwater_state(False)

        self.camera.setPos(pos)
        return Task.cont

    def _sync_celestial_anchor_positions(self) -> None:
        camera_pos = self.camera.getPos(self.render)
        self.sky_anchor.setPos(camera_pos)
        anchor = getattr(self, "jupiter_celestial_anchor", None)
        if IS_EUROPA_LEVEL and anchor is not None and not anchor.isEmpty():
            follow = 1.0 - JUPITER_CELESTIAL_PARALLAX
            anchor.setPos(camera_pos.x * follow, camera_pos.y * follow, camera_pos.z * follow)

    def _update_sky(self, task: Task) -> int:
        self._sync_celestial_anchor_positions()
        dt = min(globalClock.getDt(), 0.16)
        self._sky_moon_update_elapsed = float(getattr(self, "_sky_moon_update_elapsed", 999.0)) + dt
        if hasattr(self, "neptune_planet") and self.neptune_planet is not None and not self.neptune_planet.isEmpty():
            self.neptune_planet.setH(task.time * 0.055)
        if hasattr(self, "neptune_cloud_shell") and self.neptune_cloud_shell is not None and not self.neptune_cloud_shell.isEmpty():
            self.neptune_cloud_shell.setH(task.time * 0.105)
            self.neptune_cloud_shell.setP(math.sin(task.time * 0.08) * 0.45)
        if hasattr(self, "jupiter_planet") and self.jupiter_planet is not None and not self.jupiter_planet.isEmpty():
            # Pass95: subtle globe rotation supplies a real surface-motion depth cue.
            # Complete wrapped frames stay on the same sphere, so storm/lightning still
            # travel with the globe rather than sliding as screen-space decals.
            self.jupiter_planet.setH(task.time * (JUPITER_ROTATION_DEG_PER_SEC if IS_EUROPA_LEVEL else 0.18))
        if hasattr(self, "jupiter_cloud_shell") and self.jupiter_cloud_shell is not None and not self.jupiter_cloud_shell.isEmpty():
            self.jupiter_cloud_shell.setH(task.time * (0.245 if IS_EUROPA_LEVEL else 0.132))
            if IS_EUROPA_LEVEL:
                self.jupiter_cloud_shell.setP(math.sin(task.time * 0.13) * 0.9)
                self.jupiter_cloud_shell.setR(math.sin(task.time * 0.19 + 0.6) * 0.7)
        if hasattr(self, "jupiter_rings") and self.jupiter_rings is not None and not self.jupiter_rings.isEmpty():
            self.jupiter_rings.setR(math.sin(task.time * 0.025) * 1.2)
        if IS_EUROPA_LEVEL:
            wrapped_frames = getattr(self, "jupiter_wrapped_textures", [])
            if wrapped_frames and self.jupiter_planet is not None and not self.jupiter_planet.isEmpty():
                frame_index = int(task.time * 7.5) % len(wrapped_frames)
                if frame_index != int(getattr(self, "jupiter_storm_frame_index", -1)):
                    self.jupiter_planet.setTexture(wrapped_frames[frame_index], 1)
                    self.jupiter_storm_frame_index = frame_index
        if self._sky_moon_update_elapsed < float(getattr(self, "sky_moon_update_interval", 0.20)):
            return Task.cont
        self._sky_moon_update_elapsed = 0.0
        if hasattr(self, "mimas") and self.mimas is not None and not self.mimas.isEmpty():
            if IS_TITAN_LEVEL or IS_MARS_LEVEL or IS_PLUTO_LEVEL or IS_EUROPA_LEVEL or IS_TRITON_LEVEL:
                self.mimas.hide()
            mimas_orbit = getattr(self, "mimas_orbit", None)
            if (not IS_TITAN_LEVEL) and (not IS_MARS_LEVEL) and (not IS_PLUTO_LEVEL) and (not IS_EUROPA_LEVEL) and (not IS_TRITON_LEVEL) and mimas_orbit is not None:
                phase = mimas_orbit["phase"] + task.time * mimas_orbit["speed"]
                self.mimas.setPos(
                    Vec3(
                        self.jupiter_center.x + math.cos(phase) * mimas_orbit["radius_x"],
                        self.jupiter_center.y + math.sin(phase) * mimas_orbit["radius_y"],
                        self.jupiter_center.z + math.sin(phase * 0.75) * 90.0 + mimas_orbit["z_amp"],
                    )
                )
        if IS_PLUTO_LEVEL and getattr(self, "charon", None) is not None and not self.charon.isEmpty():
            orbit = self.charon_orbit
            phase = orbit["phase"] + task.time * orbit["speed"]
            self.charon.setPos(Vec3(math.cos(phase) * orbit["radius_x"], 15400.0 + math.sin(phase) * orbit["radius_y"], 3600.0 + math.sin(phase * 0.6) * orbit["z_amp"]))
        for moon in getattr(self, "mars_moons", []):
            phase = moon["phase"] + task.time * moon["speed"]
            center = moon["center"]
            moon["node"].setPos(Vec3(center.x + math.cos(phase) * moon["radius_x"], center.y + math.sin(phase) * moon["radius_y"], center.z + math.sin(phase * 0.7) * moon["z_amp"]))
        for moon in self.jupiter_moons:
            radius = moon["radius"]
            tilt = moon["tilt"]
            phase = moon["phase"] + task.time * moon["speed"]
            pos = Vec3(
                self.jupiter_center.x + math.cos(phase) * radius,
                self.jupiter_center.y + math.sin(phase) * radius * tilt,
                self.jupiter_center.z + math.sin(phase * 0.7) * moon["z_amp"],
            )
            moon["node"].setPos(pos)
        for layer in getattr(self, "sky_mist_layers", []):
            node = layer["node"]
            base = layer["pos"]
            drift = layer["drift"]
            phase = layer["phase"]
            wobble_x = math.sin(task.time * 0.018 + phase) * 340.0
            wobble_y = math.cos(task.time * 0.014 + phase * 0.7) * 180.0
            wobble_z = math.sin(task.time * 0.021 + phase * 1.4) * 90.0
            node.setPos(base.x + drift.x * task.time + wobble_x, base.y + drift.y * task.time + wobble_y, base.z + wobble_z)
            base_color = layer["color"]
            pulse = 0.68 + 0.32 * (0.5 + 0.5 * math.sin(task.time * 0.09 + phase))
            node.setColorScale(base_color[0], base_color[1], base_color[2], base_color[3] * pulse)
        for layer in getattr(self, "titan_gas_volume_layers", []):
            node = layer["node"]
            base = layer["pos"]
            drift = layer["drift"]
            phase = layer["phase"]
            wobble_x = math.sin(task.time * 0.007 + phase) * 540.0
            wobble_y = math.cos(task.time * 0.005 + phase * 0.8) * 220.0
            wobble_z = math.sin(task.time * 0.009 + phase * 1.4) * 180.0
            node.setPos(base.x + drift.x * task.time + wobble_x, base.y + drift.y * task.time + wobble_y, base.z + wobble_z)
            base_color = layer["color"]
            pulse = 0.76 + 0.24 * (0.5 + 0.5 * math.sin(task.time * 0.035 + phase))
            node.setColorScale(base_color[0], base_color[1], base_color[2], base_color[3] * pulse)
        for layer in getattr(self, "sun_horizon_glow_layers", []):
            node = layer["node"]
            base = layer["pos"]
            drift = layer["drift"]
            phase = layer["phase"]
            wobble_x = math.sin(task.time * 0.010 + phase) * 260.0
            wobble_y = math.cos(task.time * 0.008 + phase * 0.6) * 120.0
            wobble_z = math.sin(task.time * 0.012 + phase) * 55.0
            node.setPos(base.x + drift.x * task.time + wobble_x, base.y + drift.y * task.time + wobble_y, base.z + wobble_z)
            base_color = layer["color"]
            pulse = 0.78 + 0.22 * (0.5 + 0.5 * math.sin(task.time * 0.05 + phase))
            node.setColorScale(base_color[0], base_color[1], base_color[2], base_color[3] * pulse)
        for layer in getattr(self, "atmospheric_fx_layers", []):
            node = layer["node"]
            base = layer["pos"]
            drift = layer["drift"]
            phase = layer["phase"]
            wobble = layer.get("wobble", (240.0, 80.0, 40.0))
            wobble_x = math.sin(task.time * 0.010 + phase) * float(wobble[0])
            wobble_y = math.cos(task.time * 0.008 + phase * 0.6) * float(wobble[1])
            wobble_z = math.sin(task.time * 0.012 + phase * 1.2) * float(wobble[2])
            node.setPos(base.x + drift.x * task.time + wobble_x, base.y + drift.y * task.time + wobble_y, base.z + wobble_z)
            base_color = layer["color"]
            pulse = 0.72 + 0.28 * (0.5 + 0.5 * math.sin(task.time * 0.045 + phase))
            node.setColorScale(base_color[0], base_color[1], base_color[2], base_color[3] * pulse)
        return Task.cont

    def _animate_surface(self, task: Task) -> int:
        t = task.time
        self.water_stage.setMode(TextureStage.MModulate)
        self.water.setTexOffset(self.water_stage, t * 0.006, -t * 0.004)
        self.water.setTexScale(self.water_stage, 1.28, 1.28)
        if IS_TITAN_LEVEL:
            overlay = getattr(self, "titan_underwater_overlay_root", None)
            if overlay is not None and not overlay.isEmpty() and not overlay.isHidden():
                overlay.setTexOffset(TextureStage.getDefault(), math.sin(t * 0.03) * 0.015, math.cos(t * 0.025) * 0.012)
                overlay.setColorScale(0.24, 0.78, 0.90, 0.22 + 0.06 * (0.5 + 0.5 * math.sin(t * 0.42)))
            for layer in getattr(self, "titan_sea_glint_layers", []):
                node = layer["node"]
                base = layer["base"]
                phase = layer["phase"]
                alpha = layer["alpha"]
                shimmer = 0.62 + 0.38 * (0.5 + 0.5 * math.sin(t * 0.75 + phase))
                node.setPos(base.x + math.sin(t * 0.10 + phase) * 26.0, base.y + math.cos(t * 0.08 + phase) * 18.0, base.z)
                node.setColorScale(1.0, 0.62 + shimmer * 0.16, 0.22 + shimmer * 0.10, alpha * shimmer)
            for layer in getattr(self, "titan_underwater_blur_layers", []):
                node = layer["node"]
                base = layer["base"]
                color = layer["color"]
                phase = layer["phase"]
                drift = math.sin(t * 0.055 + phase) * 42.0
                bob = math.cos(t * 0.047 + phase * 0.7) * 8.0
                node.setPos(base.x + drift, base.y + math.cos(t * 0.033 + phase) * 24.0, base.z + bob)
                node.setColorScale(color[0], color[1], color[2], color[3] * (0.78 + 0.22 * (0.5 + 0.5 * math.sin(t * 0.18 + phase))))
            for part in getattr(self, "titan_underwater_fox_parts", []):
                node = part["node"]
                base = part["base"]
                color = part["color"]
                phase = part["phase"]
                swim = math.sin(t * 0.15 + phase) * 74.0
                depth = math.cos(t * 0.11 + phase * 0.8) * 11.0
                node.setPos(base.x + swim, base.y + math.cos(t * 0.12 + phase) * 18.0, base.z + depth)
                node.setR(math.sin(t * 0.20 + phase) * 2.5)
                node.setColorScale(color[0], color[1], color[2], color[3] * (0.70 + 0.30 * (0.5 + 0.5 * math.sin(t * 0.21 + phase))))
            for layer in getattr(self, "titan_silhouette_layers", []):
                node = layer["node"]
                base = layer["base"]
                color = layer["color"]
                phase = layer["phase"]
                breath = 0.80 + 0.20 * (0.5 + 0.5 * math.sin(t * 0.045 + phase))
                node.setPos(base.x + math.sin(t * 0.012 + phase) * 120.0, base.y, base.z + math.sin(t * 0.009 + phase) * 18.0)
                node.setColorScale(color[0], color[1], color[2], color[3] * breath)
        if self.ice is not None:
            self.ice.setTexOffset(self.ice_detail_stage, -t * 0.0007, t * 0.0004)
        return Task.cont

    def _update_reel_state(self, rig: dict[str, object], dt: float) -> None:
        if rig.get("caught", False) or bool(rig.get("collection_ready", False)):
            rig["reeling"] = False
            rig["reel_tension"] = max(float(rig.get("reel_tension", 0.0)) - dt * REEL_TENSION_RELIEF, 0.0)
            return
        if not bool(rig.get("entity_present", False)) and not bool(rig.get("attached_object", False)):
            rig["reeling"] = False
            rig["reel_tension"] = max(float(rig.get("reel_tension", 0.0)) - dt * REEL_TENSION_RELIEF, 0.0)
            return
        if not bool(rig.get("auto_hoist", False)) and not bool(rig.get("reeling", False)):
            rig["reel_tension"] = max(float(rig.get("reel_tension", 0.0)) - dt * REEL_TENSION_RELIEF, 0.0)
            return
        if not self._line_tool_matches_target(rig):
            rig["reeling"] = False
            rig["reel_locked"] = False
            rig["auto_hoist"] = False
            rig["attached_object"] = False
            status, toast = self._tool_mismatch_status(rig)
            self.last_status_message = f"ATTACHMENT LOST - {status}"
            self.toast_text.setText(toast)
            self.toast_text.setFg((1.0, 0.48, 0.34, 1.0))
            self.status_flash_timer = 1.8
            return

        signal = max(float(rig.get("signal", 0.0)), SIGNAL_CATCH_THRESHOLD)
        progress = float(rig.get("reel_progress", 0.0))
        tension = float(rig.get("reel_tension", 0.0))
        if bool(rig.get("auto_hoist", False)):
            difficulty = self._dark_side_tension_multiplier_for_rig(rig)
            progress += dt * AUTO_HOIST_RATE * self._auto_hoist_multiplier() * (0.86 + signal * 0.22) / (1.0 + (difficulty - 1.0) * 0.72)
            tension = clamp(tension + dt * 0.10 * difficulty, 0.0, 0.68 + (difficulty - 1.0) * 0.10)
            if difficulty > 1.08:
                self.last_status_message = f"DARK-SIDE AUTO-HOIST {int(clamp(progress, 0.0, 1.0) * 100):02d}%"
            else:
                self.last_status_message = f"AUTO-HOISTING CARGO {int(clamp(progress, 0.0, 1.0) * 100):02d}%"
        elif self.keys.get("reel", False):
            difficulty = self._dark_side_tension_multiplier_for_rig(rig)
            progress += dt * REEL_PROGRESS_RATE * (0.74 + signal * 0.46) / difficulty
            tension += dt * (REEL_TENSION_RISE + progress * 0.18) * difficulty
            if difficulty > 1.08:
                self.last_status_message = f"DARK-SIDE REEL {int(progress * 100):02d}% - TENSION HIGH"
            else:
                self.last_status_message = f"REELING CARGO {int(progress * 100):02d}%"
        else:
            tension -= dt * REEL_TENSION_RELIEF
            self.last_status_message = "REEL PAUSED - TENSION DROPPING"

        tension = clamp(tension, 0.0, REEL_TENSION_LIMIT + 0.2)
        progress = clamp(progress, 0.0, 1.1)
        rig["reel_progress"] = progress
        rig["reel_tension"] = tension
        if not bool(rig.get("auto_hoist", False)) and tension >= REEL_TENSION_LIMIT:
            self._fail_reel_tension(rig)
        elif progress >= 1.0:
            self._stage_held_resource_for_collection(rig)

    def _animate_rigs(self, task: Task) -> int:
        dt = min(globalClock.getDt(), 0.2)
        for index, rig in enumerate(self.rigs):
            node = rig["node"]
            base_z = rig["base_z"]
            phase = rig["phase"]
            retracting = bool(rig.get("retracting", False))
            if retracting:
                stabilize = clamp(float(rig.get("stabilize_progress", 0.0)), 0.0, 1.0)
            else:
                rig["stabilize_progress"] = clamp(float(rig.get("stabilize_progress", 0.0)) + dt / 1.45, 0.0, 1.0)
                stabilize = float(rig.get("stabilize_progress", 0.0))
            eased = stabilize * stabilize * (3.0 - 2.0 * stabilize)
            retract_progress = clamp(float(rig.get("line_retract_progress", 0.0)), 0.0, 1.0) if retracting else 0.0
            bob = math.sin(task.time * 2.3 + phase) * 1.6 * (1.0 - eased)
            if not retracting:
                node.setZ(base_z + bob - eased * 4.0)
            if stabilize < 0.98:
                node.setH((task.time * 18.0 + phase * 30.0) % 360.0)
            else:
                node.setH(phase * 30.0)
            self._update_stabilizer_tripod(rig, task.time)
            if not retracting and stabilize >= 0.48 and not bool(rig.get("anchor_sfx_played", False)):
                rig["anchor_sfx_played"] = True
                self._play_sfx("robot_anchor")
            if not retracting and stabilize >= 0.98 and not bool(rig.get("braced_sfx_played", False)):
                rig["braced_sfx_played"] = True
                self._play_sfx("robot_braced")

            if index == self.active_rig_index and not retracting and not bool(rig.get("reeling", False)):
                depth_delta = 0.0
                if self.keys["rig_down"]:
                    depth_delta += self._line_depth_speed() * dt
                if self.keys["rig_up"]:
                    depth_delta -= self._line_depth_speed() * dt
                rig["line_depth"] = clamp(float(rig["line_depth"]) + depth_delta, 24.0, self._max_line_depth())

            if index == self.active_rig_index and not retracting:
                self._update_reel_state(rig, dt)

            line_depth = float(rig["line_depth"])
            reel_progress = clamp(float(rig.get("reel_progress", 0.0)), 0.0, 1.0)
            normal_hook_z = WATER_Z - (node.getZ() + line_depth)
            if bool(rig.get("auto_hoist", False)) or bool(rig.get("attached_object", False)) or bool(rig.get("collection_ready", False)):
                attach_hook_z = rig.get("attach_hook_z")
                if attach_hook_z is None:
                    attach_hook_z = normal_hook_z
                    rig["attach_hook_z"] = float(attach_hook_z)
                held_z = HELD_OBJECT_Z
                hook_z = float(attach_hook_z) + (held_z - float(attach_hook_z)) * reel_progress
                if bool(rig.get("collection_ready", False)):
                    hook_z = held_z
            else:
                hook_z = normal_hook_z
            hook_z = hook_z + (-1.2 - hook_z) * retract_progress
            cable = rig["cable"]
            for child in cable.getChildren():
                child.removeNode()
            segs = LineSegs("rig_cable")
            segs.setThickness(2.4)
            tool_color = self._line_tool_data(str(rig.get("line_tool", self.selected_line_tool))).get("color", (0.82, 0.94, 1.0, 0.95))
            if str(rig.get("line_tool", self.selected_line_tool)) == "magnet" and bool(rig.get("entity_present", False)):
                mag_pulse = 0.10 * (math.sin(task.time * 5.5 + phase) * 0.5 + 0.5)
            else:
                mag_pulse = 0.0
            segs.setColor(
                clamp(float(tool_color[0]) + mag_pulse, 0.0, 1.0),
                clamp(float(tool_color[1]) + mag_pulse * 0.25, 0.0, 1.0),
                clamp(float(tool_color[2]) + mag_pulse * 0.10, 0.0, 1.0),
                0.95,
            )
            segs.moveTo(0.0, 0.0, -1.2)
            segs.drawTo(0.0, 0.0, hook_z)
            cable_np = cable.attachNewNode(segs.create())
            cable_np.setTransparency(TransparencyAttrib.MAlpha)
            cable_np.setLightOff(1)

            hook = rig["hook"]
            hook.setPos(0.0, 0.0, hook_z)
            cargo = rig.get("cargo")
            if hasattr(cargo, "setPos"):
                cargo.setPos(0.0, 0.0, hook_z - 2.3)
                if bool(rig.get("attached_object", False)) or bool(rig.get("collection_ready", False)):
                    cargo.show()
                    cargo_pulse = 0.08 * (math.sin(task.time * 5.0 + phase) * 0.5 + 0.5)
                    cargo.setH((task.time * 26.0 + phase * 90.0) % 360.0)
                    cargo.setColorScale(0.62 + cargo_pulse, 0.70 + cargo_pulse * 0.55, 0.74 + cargo_pulse * 0.34, 1.0)
                else:
                    cargo.hide()
            glow = rig["glow"]
            if retracting:
                signal = 0.01
            elif rig.get("caught", False):
                signal = 0.02
            elif rig["entity_present"]:
                depth_error = abs(line_depth - float(rig["entity_depth"]))
                base_signal = clamp(1.0 - depth_error / 140.0, 0.0, 1.0)
                pulse = 0.04 * (math.sin(task.time * 3.2 + phase) * 0.5 + 0.5)
                signal = clamp(base_signal + pulse * base_signal + self._magnet_signal_bonus(), 0.0, 1.0)
                if signal >= SIGNAL_CATCH_THRESHOLD:
                    rig["signal_lock_time"] = min(float(rig.get("signal_lock_time", 0.0)) + dt, 9.0)
                    if not bool(rig.get("depth_lock_sfx_played", False)) and stabilize >= 0.98:
                        rig["depth_lock_sfx_played"] = True
                        self._play_sfx("sonar_lock", 0.72)
                    if (
                        stabilize >= 0.98
                        and depth_error <= MAGNET_ATTACH_TOLERANCE
                        and self._line_tool_matches_target(rig)
                        and not bool(rig.get("auto_hoist", False))
                        and not bool(rig.get("collection_ready", False))
                    ):
                        self._begin_auto_hoist(rig, hook_z)
                else:
                    rig["signal_lock_time"] = max(float(rig.get("signal_lock_time", 0.0)) - dt * 1.5, 0.0)
                    if signal < SONAR_LOCK_RESET_SIGNAL:
                        rig["depth_lock_sfx_played"] = False
            else:
                signal = 0.04 + (math.sin(task.time * 0.9 + phase) * 0.5 + 0.5) * 0.03
                rig["signal_lock_time"] = 0.0
            if bool(rig.get("reeling", False)):
                signal = max(signal, SIGNAL_CATCH_THRESHOLD + 0.06)
            rig["signal"] = signal
            self._apply_line_tool_visual(rig, signal)
            glow.setScale(3.2 + signal * 2.6, 3.2 + signal * 2.6, 0.60 + signal * 0.22)
        return Task.cont

    def _animate_drilling(self, task: Task) -> int:
        dt = min(globalClock.getDt(), 0.08)
        finished: list[dict[str, object]] = []
        for effect in list(self.drill_effects):
            if bool(effect.get("preview_only", False)):
                self._update_drill_effect(effect, task.time)
                continue
            effect["time"] = float(effect.get("time", 0.0)) + dt
            progress = self._update_drill_effect(effect, task.time)
            shaft_word = "REGOLITH" if IS_IAPETUS_LEVEL else ("SNOW-ICE" if IS_MIMAS_LEVEL else "ICE")
            self.last_status_message = f"DRILLING {shaft_word} SHAFT {int(progress * 100):02d}%"
            if progress >= 1.0:
                finished.append(effect)
        for effect in finished:
            if effect in self.drill_effects:
                self.drill_effects.remove(effect)
            self._finish_drilling_effect(effect)
            self._play_sfx("drill_breakthrough")
            self.last_status_message = "HOLE OPEN - DRONE DEPLOYED"
            self.status_flash_timer = 2.0
        self._set_drill_loop(any(not bool(effect.get("preview_only", False)) for effect in self.drill_effects))
        return Task.cont

    def _animate_cracks(self, task: Task) -> int:
        for effect in self.crack_effects:
            effect["grow"] = clamp(float(effect["grow"]) + globalClock.getDt() * 1.8, 0.0, 1.0)
            self._rebuild_crack_effect(effect)
        return Task.cont


    def _update_survey_hotspot_marker(self, hotspot: dict[str, object] | None, time_value: float) -> None:
        marker = getattr(self, "survey_marker_root", None)
        if marker is None or marker.isEmpty():
            return
        for child in marker.getChildren():
            child.removeNode()
        if hotspot is None or float(hotspot.get("signal", 0.0)) <= 0.08:
            marker.hide()
            return
        hx = float(hotspot.get("x", 0.0))
        hy = float(hotspot.get("y", 0.0))
        signal = clamp(float(hotspot.get("signal", 0.0)), 0.0, 1.0)
        sound = clamp(float(hotspot.get("sound_signal", signal)), 0.0, 1.0)
        movement = clamp(float(hotspot.get("movement_signal", signal)), 0.0, 1.0)
        ready = bool(hotspot.get("ready", False))
        radius = float(hotspot.get("drill_radius", HOTSPOT_DRILL_RADIUS))
        z = self.world.surface_height(hx, hy) + 1.05
        marker.show()
        marker.setPos(0.0, 0.0, 0.0)

        # Draw the hidden drillable surface zone only after sonar has actually
        # detected it. Cyan reads as sound ping; orange reads as movement/thermal.
        rings = LineSegs("survey_hotspot_surface_zone")
        rings.setThickness(2.2 if ready else 1.35)
        alpha = 0.24 + signal * (0.46 if ready else 0.28)
        rings.setColor(0.25 + sound * 0.26, 0.82 + sound * 0.16, 1.0, alpha)
        for ring_index, ring_radius in enumerate((radius, radius * (1.0 + signal * 0.16))):
            phase = time_value * (1.6 + ring_index * 0.55)
            segments = 72
            for i in range(segments + 1):
                a = (i / segments) * math.tau
                wobble = 1.0 + math.sin(a * 4.0 + phase) * (0.018 + signal * 0.018)
                x = hx + math.cos(a) * ring_radius * wobble
                y = hy + math.sin(a) * ring_radius * wobble
                pz = self.world.surface_height(x, y) + 1.08 + ring_index * 0.03
                if i == 0:
                    rings.moveTo(x, y, pz)
                else:
                    rings.drawTo(x, y, pz)
        ring_np = marker.attachNewNode(rings.create())
        ring_np.setTransparency(TransparencyAttrib.MAlpha)
        ring_np.setDepthWrite(False)
        ring_np.setDepthTest(True)
        ring_np.setLightOff(1)

        if movement > 0.12:
            plume = LineSegs("survey_hotspot_movement_ticks")
            plume.setThickness(2.0)
            plume.setColor(1.0, 0.48 + movement * 0.22, 0.12, 0.22 + movement * 0.34)
            tick_count = 7
            for i in range(tick_count):
                a = (i / tick_count) * math.tau + time_value * 0.28
                inner = radius * (0.30 + 0.07 * math.sin(time_value * 2.0 + i))
                outer = radius * (0.72 + 0.10 * movement)
                x0 = hx + math.cos(a) * inner
                y0 = hy + math.sin(a) * inner
                x1 = hx + math.cos(a) * outer
                y1 = hy + math.sin(a) * outer
                plume.moveTo(x0, y0, self.world.surface_height(x0, y0) + 1.35)
                plume.drawTo(x1, y1, self.world.surface_height(x1, y1) + 1.35)
            plume_np = marker.attachNewNode(plume.create())
            plume_np.setTransparency(TransparencyAttrib.MAlpha)
            plume_np.setDepthWrite(False)
            plume_np.setDepthTest(True)
            plume_np.setLightOff(1)

    def _update_scanner_pip(self, task: Task) -> int:
        dt = min(globalClock.getDt(), 0.2)
        self._scanner_update_elapsed = float(getattr(self, "_scanner_update_elapsed", 999.0)) + dt
        if self._scanner_update_elapsed < float(getattr(self, "scanner_draw_interval", 0.050)):
            self._update_sonar_sfx(
                dt,
                ready=bool(self.current_sonar.get("ready", False)),
                signal=float(self.current_sonar.get("signal", 0.0)),
                bearing_signal=float(self.current_sonar.get("bearing_signal", 0.0)),
            )
            self._update_universal_sonar_meter(task.time)
            return Task.cont
        self._scanner_update_elapsed = 0.0
        surface_survey_mode = (
            self.active_rig_index < 0
            or self.active_rig_index >= len(self.rigs)
            or bool(self.rigs[self.active_rig_index].get("caught", False))
        )
        if surface_survey_mode:
            point = self._mouse_to_terrain_point()
            bearing = self._scan_hotspot_bearing_near_player()
            bearing_signal = float(bearing.get("bearing_signal", 0.0)) if bearing is not None else 0.0
            bearing_angle = float(bearing.get("bearing_angle", 0.0)) if bearing is not None else None
            if point is None:
                self.current_sonar = {
                    "signal": 0.0,
                    "sound": 0.0,
                    "movement": 0.0,
                    "ready": False,
                    "detected": False,
                    "bearing_signal": bearing_signal,
                    "bearing_angle": bearing_angle if bearing_angle is not None else 0.0,
                }
                self._update_survey_hotspot_marker(None, task.time)
                self.pip_root.show()
                if bearing_signal > 0.035:
                    self._rebuild_scanner_graphics(0.04 + bearing_signal * 0.22, False, task.time, 0.02 + bearing_signal * 0.10, bearing_angle, bearing_signal, False)
                    self._update_sonar_sfx(dt, ready=False, signal=0.0, bearing_signal=bearing_signal)
                else:
                    self._rebuild_scanner_graphics(0.03, False, task.time, 0.02, None, 0.0, False)
                    self._update_sonar_sfx(dt, ready=False, signal=0.0, bearing_signal=0.0)
                self._update_universal_sonar_meter(task.time)
                return Task.cont
            hotspot = self._scan_hotspots_near(point.x, point.y)
            if hotspot is None:
                self.current_sonar = {
                    "signal": 0.0,
                    "sound": 0.0,
                    "movement": 0.0,
                    "ready": False,
                    "detected": False,
                    "bearing_signal": bearing_signal,
                    "bearing_angle": bearing_angle if bearing_angle is not None else 0.0,
                }
                self._update_survey_hotspot_marker(None, task.time)
                self.pip_root.show()
                self._rebuild_scanner_graphics(0.04 + bearing_signal * 0.18, False, task.time, 0.02 + bearing_signal * 0.10, bearing_angle, bearing_signal, False)
                self._update_sonar_sfx(dt, ready=False, signal=0.0, bearing_signal=bearing_signal)
            else:
                signal = float(hotspot.get("signal", 0.0))
                ready = bool(hotspot.get("ready", False))
                self.current_sonar = {
                    "signal": signal,
                    "sound": float(hotspot.get("sound_signal", 0.0)),
                    "movement": float(hotspot.get("movement_signal", 0.0)),
                    "ready": ready,
                    "distance": float(hotspot.get("distance", 999.0)),
                    "fish_name": str(hotspot.get("fish_name", "UNKNOWN")),
                    "x": float(hotspot.get("x", point.x)),
                    "y": float(hotspot.get("y", point.y)),
                    "drill_radius": float(hotspot.get("drill_radius", HOTSPOT_DRILL_RADIUS)),
                    "detected": bool(hotspot.get("detected", True)),
                    "bearing_signal": max(bearing_signal, signal),
                    "bearing_angle": bearing_angle if bearing_angle is not None else 0.0,
                }
                self.pip_root.show()
                self._update_survey_hotspot_marker(hotspot, task.time)
                self._rebuild_scanner_graphics(
                    float(hotspot.get("sound_signal", 0.0)),
                    signal > 0.08,
                    task.time,
                    float(hotspot.get("movement_signal", 0.0)),
                    bearing_angle,
                    max(bearing_signal, signal * 0.55),
                    ready,
                )
                self._update_sonar_sfx(dt, ready=ready, signal=signal, bearing_signal=bearing_signal)
            self._update_universal_sonar_meter(task.time)
            return Task.cont
        self._update_survey_hotspot_marker(None, task.time)
        rig = self.rigs[self.active_rig_index]
        signal = float(rig.get("signal", 0.0))
        has_target = bool(rig.get("entity_present", False))
        self.current_sonar = {
            "signal": signal,
            "sound": signal,
            "movement": signal,
            "ready": signal >= SIGNAL_CATCH_THRESHOLD,
            "detected": has_target,
            "bearing_signal": 0.0,
        }
        self.pip_root.show()
        self._rebuild_scanner_graphics(signal, has_target, task.time, signal, None, 0.0, signal >= SIGNAL_CATCH_THRESHOLD)
        self._update_universal_sonar_meter(task.time)
        return Task.cont

    def _world_action_profile(self) -> dict[str, object]:
        return dict(WORLD_ACTION_PROFILES.get(MOON_LEVEL_ID, WORLD_ACTION_PROFILES["enceladus"]))

    def _set_standard_action_state(self, state: str, hint: str, progress: int | float = 0) -> dict[str, object]:
        state = str(state if state in STANDARD_ACTION_SEQUENCE else "SURVEY")
        profile = self._world_action_profile()
        payload = {
            "version": ACTION_CONSISTENCY_VERSION,
            "world": MOON_LEVEL_ID,
            "state": state,
            "hint": str(hint),
            "progress": int(clamp(float(progress), 0.0, 100.0)),
            "binding": STANDARD_ACTION_BINDINGS.get(state, "context action"),
            "profile": profile,
        }
        self.standard_action_state = state
        self.standard_action_hint = str(hint)
        self.standard_action_progress = int(payload["progress"])
        return payload

    def _standard_action_payload(self) -> dict[str, object]:
        target = max(int(getattr(self, "loop_goal_catches", 3)), 1)
        caught = int(getattr(self, "catch_count", 0))
        cycle_progress = int(clamp((caught / max(target, 1)) * 100.0, 0.0, 100.0))
        if getattr(self, "embedded_operation", False) and caught >= target:
            return self._set_standard_action_state("RETURN_RESULT", "TAB returns completed run result to StarFall", 100)
        if getattr(self, "grabbed_base_module", None) is not None:
            return self._set_standard_action_state("COLLECT", "LMB/G releases moved module; build placement uses same snap rules", cycle_progress)
        if getattr(self, "build_mode", False):
            return self._set_standard_action_state("COLLECT", "LMB places/adjusts module; Q/E rotates; B exits build mode", cycle_progress)
        if self.drone_dispatch and bool(self.drone_dispatch.get("active", False)):
            progress = int(clamp(float(self.drone_dispatch.get("progress", 0.0)) * 100.0, 0.0, 100.0))
            return self._set_standard_action_state("DRILL_DEPLOY", f"drone traveling to locked {MOON_THEME['display_name']} site", progress)
        if self.drill_effects and not (0 <= self.active_rig_index < len(self.rigs)):
            effect = self.drill_effects[-1]
            duration = max(float(effect.get("duration", 2.2)), 0.1)
            progress = int(clamp(float(effect.get("time", 0.0)) / duration * 100.0, 0.0, 100.0))
            return self._set_standard_action_state("DRILL_DEPLOY", "cutting shaft and preparing tripod drone", progress)
        if not (0 <= self.active_rig_index < len(self.rigs)):
            sonar = getattr(self, "current_sonar", {})
            if bool(sonar.get("ready", False)):
                return self._set_standard_action_state("DRILL_DEPLOY", "hotspot locked; LMB from hover drone or press 1 to deploy drill", 100)
            if float(sonar.get("bearing_signal", 0.0)) > 0.06 or float(sonar.get("signal", 0.0)) > 0.08:
                strength = max(float(sonar.get("bearing_signal", 0.0)), float(sonar.get("signal", 0.0)))
                return self._set_standard_action_state("SURVEY", "sonar return nearby; sweep crosshair over terrain", int(clamp(strength * 100.0, 0.0, 99.0)))
            profile = self._world_action_profile()
            return self._set_standard_action_state("SURVEY", f"survey {profile['terrain']} to {profile['survey_objective']}", 0)
        rig = self.rigs[self.active_rig_index]
        if bool(rig.get("collection_ready", False)):
            return self._set_standard_action_state("COLLECT", "LMB held cargo below drone to store raw resources", 100)
        if bool(rig.get("caught", False)):
            return self._set_standard_action_state("SURVEY", "cargo stored; sweep for the next return", cycle_progress)
        stabilize = float(rig.get("stabilize_progress", 0.0))
        if stabilize < 0.98:
            return self._set_standard_action_state("ANCHOR", "wait for tripod feet and anchors to brace", int(clamp(stabilize * 100.0, 0.0, 99.0)))
        if bool(rig.get("auto_hoist", False)):
            return self._set_standard_action_state("REEL_ATTACH", "auto-hoist active; wait for cargo to reach drone", int(clamp(float(rig.get("reel_progress", 0.0)) * 100.0, 0.0, 99.0)))
        if bool(rig.get("reeling", False)):
            return self._set_standard_action_state("REEL_ATTACH", "RMB/R reel active; manage tension until cargo attaches", int(clamp(float(rig.get("reel_progress", 0.0)) * 100.0, 0.0, 99.0)))
        required = str(rig.get("required_tool", "hook"))
        current = str(rig.get("line_tool", self.selected_line_tool))
        signal = float(rig.get("signal", 0.0))
        if current != required and signal >= SIGNAL_CATCH_THRESHOLD:
            return self._set_standard_action_state("MATCH_TOOL", f"LMB drone/line to switch to {self._line_tool_data(required)['short']}", int(clamp(signal * 100.0, 0.0, 99.0)))
        if signal >= SIGNAL_CATCH_THRESHOLD:
            return self._set_standard_action_state("REEL_ATTACH", "hot signal; RMB/R to attach cargo", int(clamp(signal * 100.0, 0.0, 99.0)))
        return self._set_standard_action_state("LOWER_LINE", "UP/DOWN arrows adjust depth until sonar signal turns hot", int(clamp(signal * 100.0, 0.0, 95.0)))

    def _standard_action_line(self) -> str:
        payload = self._standard_action_payload()
        state = str(payload.get("state", "SURVEY"))
        binding = str(payload.get("binding", "context action"))
        progress = int(payload.get("progress", 0))
        hint = str(payload.get("hint", ""))
        return f"ACTION {state} {progress:03d}% // {binding} // {hint}"

    def _loop_phase_text(self) -> str:
        grabbed = getattr(self, "grabbed_base_module", None)
        if grabbed is not None:
            label = self._base_module_label(grabbed)
            state = str(getattr(self, "grab_preview_snap_state", "FREE PULL")) if bool(getattr(self, "grab_preview_valid", True)) else str(getattr(self, "grab_preview_reason", "BLOCKED"))
            action = self._standard_action_payload()
            return f"MOVING: {label} // MAGNET {state} // {action['state']}"
        if getattr(self, "build_mode", False):
            data = BASE_MODULE_DATA.get(self.selected_build_key, {})
            label = data.get("label", self.selected_build_key)
            pos, valid, reason = self._snap_build_position(self.selected_build_key)
            state = "VALID" if valid else reason
            action = self._standard_action_payload()
            return f"BUILD MODE: {label} // SNAP {state} // {action['state']}"
        target = max(int(getattr(self, "loop_goal_catches", 3)), 1)
        cycle = min(self.catch_count + 1, target)
        if (not self._surface_relay_built()) and self._can_afford_upgrade("SURFACE_RELAY"):
            phase = "BUILD RELAY - PRESS 5"
        elif self.drone_dispatch and bool(self.drone_dispatch.get("active", False)):
            phase = "RELOCATE DRONE"
        elif self.drill_effects and not (0 <= self.active_rig_index < len(self.rigs)):
            phase = "DRILL SHAFT"
        elif not (0 <= self.active_rig_index < len(self.rigs)):
            if bool(self.current_sonar.get("ready", False)):
                phase = "LOCKED - PRESS 1"
            elif float(self.current_sonar.get("bearing_signal", 0.0)) > 0.06:
                phase = "SWEEP TO PING"
            else:
                phase = "FIND HOTSPOT"
        else:
            rig = self.rigs[self.active_rig_index]
            if (not self._surface_relay_built()) and self._can_afford_upgrade("SURFACE_RELAY"):
                phase = "BUILD RELAY - PRESS 5"
            elif bool(rig.get("collection_ready", False)):
                phase = "COLLECT CARGO"
            elif bool(rig.get("caught", False)):
                phase = "REFINE OR FIND NEXT"
            elif bool(rig.get("auto_hoist", False)):
                phase = "AUTO-HOIST"
            elif float(rig.get("stabilize_progress", 0.0)) < 0.98:
                phase = "ANCHOR TRIPOD"
            else:
                phase = "LOWER LINE"
        action = self._standard_action_payload()
        return f"LOOP {cycle}/{target}: {phase} // {action['state']}"

    def _update_status_panel(self, task: Task) -> int:
        if getattr(self, "embedded_operation", False):
            self._hide_embedded_moon_hud()
            return Task.cont
        dt = min(globalClock.getDt(), 0.16)
        if self.status_flash_timer > 0.0:
            self.status_flash_timer = max(0.0, self.status_flash_timer - dt)
        self._status_update_elapsed = float(getattr(self, "_status_update_elapsed", 999.0)) + dt
        active_motion_ui = (
            bool(getattr(self, "build_mode", False))
            or getattr(self, "grabbed_base_module", None) is not None
            or bool(getattr(self, "robot_panel_visible", False))
            or bool(getattr(self, "upgrade_visible", False))
            or bool(getattr(self, "options_visible", False))
            or bool(getattr(self, "ice_slide_active", False))
            or bool(getattr(self, "drill_effects", []))
            or bool(getattr(self, "drone_dispatch", None) and getattr(self, "drone_dispatch", {}).get("active", False))
            or bool(0 <= getattr(self, "active_rig_index", -1) < len(getattr(self, "rigs", [])))
        )
        interval = 0.0 if active_motion_ui else float(getattr(self, "status_draw_interval", 0.050))
        if self._status_update_elapsed < interval:
            return Task.cont
        self._status_update_elapsed = 0.0
        rig_line = "NO DRONE"
        signal_line = "SIGNAL --"
        dispatch = getattr(self, "drone_dispatch", None)
        if dispatch and bool(dispatch.get("active", False)):
            progress = clamp(float(dispatch.get("progress", 0.0)), 0.0, 1.0)
            phase = str(dispatch.get("phase", "travel"))
            if phase == "retract":
                rig_line = f"RETRACT {progress*100:03.0f}%"
                signal_line = "TRIPOD + LINE STOWING"
            else:
                rig_line = f"DRONE {progress*100:03.0f}%"
                signal_line = "EN ROUTE"
        elif self.drill_effects and not (0 <= self.active_rig_index < len(self.rigs)):
            effect = self.drill_effects[-1]
            progress = clamp(float(effect.get("time", 0.0)) / max(float(effect.get("duration", 2.2)), 0.0), 0.0, 1.0) if float(effect.get("duration", 2.2)) > 0 else 0.0
            rig_line = f"DRILL {progress*100:03.0f}%"
            signal_line = "CUTTING SHAFT"
        elif not (0 <= self.active_rig_index < len(self.rigs)):
            sonar = self.current_sonar
            sig = float(sonar.get("signal", 0.0))
            sound = float(sonar.get("sound", 0.0))
            movement = float(sonar.get("movement", 0.0))
            ready = bool(sonar.get("ready", False))
            bearing_signal = float(sonar.get("bearing_signal", 0.0))
            if ready:
                rig_line = "HOTSPOT LOCK"
                signal_line = f"SOUND {sound*100:03.0f}%  MOVE {movement*100:03.0f}%"
                if self.status_flash_timer <= 0.0:
                    self.last_status_message = "HOVER DRONE LOCK: LMB AUTOPILOT DRILL OR PRESS 1"
            elif sig > 0.08:
                rig_line = f"SONAR {sig*100:03.0f}%"
                signal_line = f"SOUND {sound*100:03.0f}%  MOVE {movement*100:03.0f}%"
                if self.status_flash_timer <= 0.0:
                    self.last_status_message = "SONAR DETECTED - POINT CROSSHAIR INTO HOTSPOT"
            elif bearing_signal > 0.06:
                rig_line = f"WIDE PING {bearing_signal*100:03.0f}%"
                signal_line = "BEARING CUE - SWEEP CROSSHAIR"
                if self.status_flash_timer <= 0.0:
                    self.last_status_message = "SONAR RETURN NEARBY - SWEEP GROUND FOR HOTSPOT"
            else:
                rig_line = "SURVEY MODE"
                signal_line = "SOUND --  MOVE --"
                if self.status_flash_timer <= 0.0:
                    self.last_status_message = str(MOON_THEME["scan_prompt"])
        elif 0 <= self.active_rig_index < len(self.rigs):
            rig = self.rigs[self.active_rig_index]
            line_depth = float(rig.get("line_depth", 0.0))
            signal = float(rig.get("signal", 0.0))
            self.best_signal = max(self.best_signal, signal)
            stabilize = float(rig.get("stabilize_progress", 0.0))
            if rig.get("caught", False):
                sonar = self.current_sonar
                sig = float(sonar.get("signal", 0.0))
                sound = float(sonar.get("sound", 0.0))
                movement = float(sonar.get("movement", 0.0))
                ready = bool(sonar.get("ready", False))
                bearing_signal = float(sonar.get("bearing_signal", 0.0))
                if ready:
                    rig_line = "NEXT HOTSPOT LOCK"
                    signal_line = f"SOUND {sound*100:03.0f}%  MOVE {movement*100:03.0f}%"
                    if self.status_flash_timer <= 0.0:
                        self.last_status_message = "HOVER DRONE LOCK: LMB RELOCATE/DRILL OR PRESS 1"
                elif sig > 0.08:
                    rig_line = f"NEXT SONAR {sig*100:03.0f}%"
                    signal_line = f"SOUND {sound*100:03.0f}%  MOVE {movement*100:03.0f}%"
                    if self.status_flash_timer <= 0.0:
                        self.last_status_message = "POINT CROSSHAIR INSIDE NEXT HOTSPOT"
                elif bearing_signal > 0.06:
                    rig_line = f"NEXT WIDE PING {bearing_signal*100:03.0f}%"
                    signal_line = "BEARING CUE - SWEEP FOR NEXT SITE"
                    if self.status_flash_timer <= 0.0:
                        self.last_status_message = "DRONE CLEAR - SWEEP SONAR FOR NEXT RETURN"
                else:
                    rig_line = "DRONE CLEAR"
                    signal_line = "NEXT RETURN HIDDEN"
                    if self.status_flash_timer <= 0.0:
                        self.last_status_message = "CATCH COMPLETE - SWEEP SONAR FOR NEXT HOTSPOT"
            elif bool(rig.get("collection_ready", False)):
                resource = str(rig.get("resource_name", "METAL"))
                amount = int(rig.get("resource_amount", 1))
                rig_line = "CARGO HELD BELOW DRONE"
                signal_line = f"AIM LMB AT OBJECT TO COLLECT {resource} x{amount}"
            elif stabilize < 0.98:
                rig_line = f"ANCHOR {stabilize*100:03.0f}%"
                signal_line = "TRIPOD DEPLOYING"
            elif bool(rig.get("auto_hoist", False)):
                progress = clamp(float(rig.get("reel_progress", 0.0)), 0.0, 1.0)
                tool = self._line_tool_data(str(rig.get("line_tool", self.selected_line_tool)))
                rig_line = f"{tool['short']} AUTO-HOIST {progress*100:03.0f}%"
                signal_line = "DRONE WINCHING CARGO BELOW BODY"
            elif bool(rig.get("reeling", False)):
                progress = clamp(float(rig.get("reel_progress", 0.0)), 0.0, 1.0)
                tension = clamp(float(rig.get("reel_tension", 0.0)), 0.0, 1.0)
                tool = self._line_tool_data(str(rig.get("line_tool", self.selected_line_tool)))
                rig_line = f"{tool['short']} REEL {progress*100:03.0f}%  TENSION {tension*100:03.0f}%"
                signal_line = "MANUAL REEL NUDGE ACTIVE"
            else:
                tool = self._line_tool_data(str(rig.get("line_tool", self.selected_line_tool)))
                required = self._line_tool_data(str(rig.get("required_tool", "hook")))
                match = self._line_tool_matches_target(rig)
                rig_line = f"{tool['short']} DEPTH {line_depth:05.1f} m  SONAR ONLY"
                state = "HOT" if signal >= SIGNAL_CATCH_THRESHOLD else ("TRACK" if signal > 0.34 else "SEARCH")
                target_class = str(rig.get("target_class", rig.get("target_kind", "TARGET")))
                if signal >= SIGNAL_CATCH_THRESHOLD and not match:
                    signal_line = f"NEED {required['short']} // {target_class}"
                else:
                    signal_line = f"SIGNAL {signal*100:03.0f}% {state}  {required['short']} TARGET: {str(rig.get('resource_name', 'RESOURCE'))}"
        crosshair = getattr(self, "crosshair_text", None)
        if crosshair is not None:
            sonar = getattr(self, "current_sonar", {})
            if bool(sonar.get("ready", False)):
                crosshair.setText("+")
                crosshair.setFg((1.0, 0.86, 0.36, 0.92))
            elif float(sonar.get("signal", 0.0)) > 0.08 and (not (0 <= self.active_rig_index < len(self.rigs)) or bool(self.rigs[self.active_rig_index].get("caught", False))):
                crosshair.setText("+")
                crosshair.setFg((0.46, 0.90, 1.0, 0.78))
            else:
                crosshair.setText("+")
                crosshair.setFg((0.72, 0.96, 1.0, 0.50))
        loop_line = self._loop_phase_text()
        action_line = self._standard_action_line()
        tool_label = self._line_tool_data(self.selected_line_tool).get("label", "MAGNET")
        installed = sum(1 for value in self.upgrades.values() if int(value) > 0)
        dark_factor = getattr(self, "current_dark_side_factor", 0.0)
        sonar_dark = bool(getattr(self, "current_sonar", {}).get("dark_side", False))
        pending_dark = bool(getattr(self, "pending_drill_hotspot", {}) and getattr(self, "pending_drill_hotspot", {}).get("dark_side", False))
        if dark_factor > 0.58 or sonar_dark or pending_dark:
            zone_text = "DARK SIDE"
        elif dark_factor > 0.18:
            zone_text = "TERMINATOR"
        else:
            zone_text = "SUNLIT REGOLITH" if IS_IAPETUS_LEVEL else ("SUNLIT HAZE" if IS_TITAN_LEVEL else ("SUNLIT SNOW" if IS_MIMAS_LEVEL else "SUNLIT ICE"))
        relay_state = "RELAY ONLINE" if self._surface_relay_built() else "BUILD RELAY: 5"
        charge_state = f"CHARGE {self.robot_charge:03.0f}%"
        control_state = f"VIEW {str(getattr(self, 'remote_view_label', 'ROVER')).replace('_', ' ')}"
        static_state = f"STATIC {int(float(getattr(self, 'remote_static_alpha', 0.0)) * 100):02d}%"
        vision_state = f"VISION {self._planet_vision_short_label()}"
        power_state = f"PWR {self.base_power_stored:04.1f}/{self._base_power_capacity():04.0f}"
        shelter_state = "SHELTERED" if self._is_under_shelter() else ("OPEN REGOLITH" if IS_IAPETUS_LEVEL else ("OPEN HAZE" if IS_TITAN_LEVEL else ("OPEN SNOW" if IS_MIMAS_LEVEL else "OPEN ICE")))
        slide_label = "RIDGE SLIDE" if IS_IAPETUS_LEVEL else ("DUNE WALK" if IS_TITAN_LEVEL else ("SNOW SLIDE" if IS_MIMAS_LEVEL else "ICE SLIDE"))
        slide_state = f"{slide_label} {float(getattr(self, 'ice_slide_speed', 0.0)):03.0f}" if bool(getattr(self, "ice_slide_active", False)) else "WALK"
        qc_state = getattr(self, "qc_last_report", "QC READY")
        style = getattr(self, "hud_style", "MINIMAL")
        drone_stats = self._flight_drone_stats_text()
        if getattr(self, "flight_drone_stats_text", None) is not None:
            self.flight_drone_stats_text.setText("" if style == "HIDDEN" else drone_stats)
        if style == "MINIMAL":
            self.status_text.setText(f"{loop_line}\n{action_line}")
            self.depth_text.setText(f"{control_state}  |  {zone_text}  |  {slide_state}  |  {vision_state}  |  {static_state}")
            self.catch_text.setText("")
        elif style == "COMPACT":
            self.status_text.setText(f"{loop_line}\n{action_line}\n{rig_line} // {signal_line}")
            self.depth_text.setText(f"{control_state}  |  LINE {tool_label}  |  {zone_text}  |  {slide_state}  |  {vision_state}  |  {charge_state}  |  {static_state}")
            self.catch_text.setText(f"RUN {self.catch_count}/{self.loop_goal_catches}  |  MODULES {len(self.base_modules)}  |  {relay_state}")
        else:
            self.status_text.setText(f"{loop_line}\n{action_line}\n{self.last_status_message}\n{rig_line}\n{signal_line}")
            self.depth_text.setText(f"{control_state}  |  LINE {tool_label}  |  {zone_text}  |  {slide_state}  |  {vision_state}  |  {charge_state}  |  {power_state}  |  {shelter_state}  |  B BUILD")
            self.catch_text.setText(f"{self._resource_summary_text()}  |  MODULES {len(self.base_modules)}  |  RESOURCE RUN {self.catch_count}/{self.loop_goal_catches}  |  {relay_state}  |  {qc_state}")
        if self.status_flash_timer <= 0.0 and self.toast_text.getText():
            self.toast_text.setFg((1.0, 0.86, 0.42, 0.0))
        if getattr(self, "upgrade_visible", False):
            self._update_upgrade_panel()
        return Task.cont

    def _run_drone_camera_runtime_test(self, task: Task) -> int:
        report_dir = ROOT / "verification" / "reports"
        report_dir.mkdir(parents=True, exist_ok=True)
        hx = -620.0
        hy = -480.0
        profile = self._target_profile_by_name("Cryo-Ferrite Sheet")
        hotspot = {
            "key": "pass51:runtime_hover_click",
            "x": hx,
            "y": hy,
            "ready": True,
            "signal": 0.94,
            "strength": 0.94,
            "sound": 0.88,
            "movement": 0.10,
            "sound_signal": 0.88,
            "movement_signal": 0.10,
            "drill_radius": HOTSPOT_DRILL_RADIUS,
            "depth": 126.0,
            "fish_name": str(profile.get("name", "Cryo-Ferrite Sheet")),
            "target_profile": profile,
        }
        self.loop_hotspots.append(dict(hotspot))
        self.current_sonar = dict(hotspot, detected=True, bearing_signal=0.70, distance=0.0)
        drone = self.remote_drones.get("DRONE_A", {}).get("node")
        if hasattr(drone, "isEmpty") and not drone.isEmpty():
            drone.show()
            drone.setPos(hx - 88.0, hy - 76.0, self.world.surface_height(hx - 88.0, hy - 76.0) + 92.0)
            self._update_persistent_drill_drone_visual(task.time, 0.25)
        self.active_control_mode = "DRONE_A"
        self.remote_view_label = "DRONE A"
        self.heading = 28.0
        self.pitch = -88.0
        self.drone_control_heading = self.heading
        self.drone_control_pitch = self.pitch
        before_pos = drone.getPos(self.render) if hasattr(drone, "getPos") else Vec3(0, 0, 0)
        click_result = self._try_drone_camera_context_action()
        dispatch = getattr(self, "drone_dispatch", None)
        checks = {
            "click_consumed": bool(click_result),
            "dispatch_started": bool(dispatch and dispatch.get("active")),
            "dispatch_phase_travel": bool(dispatch and str(dispatch.get("phase")) == "travel"),
            "dispatch_target_matches_hotspot": bool(dispatch and abs(float(dispatch.get("x", 0.0)) - hx) < HOTSPOT_DRILL_RADIUS and abs(float(dispatch.get("y", 0.0)) - hy) < HOTSPOT_DRILL_RADIUS),
            "active_mode_remains_drone_a": str(getattr(self, "active_control_mode", "")) == "DRONE_A",
            "rover_not_controlled": not bool(getattr(self, "rover_controlled", True)),
            "camera_mount_belly": str(getattr(self, "remote_camera_mount_label", "")) == "HOVER BELLY CAM" or "HOVER" in str(getattr(self, "last_status_message", "")),
        }
        payload = {
            "status": "PASS" if all(checks.values()) else "FAIL",
            "level": MOON_LEVEL_ID,
            "checks": checks,
            "before_drone_pos": [round(before_pos.x, 3), round(before_pos.y, 3), round(before_pos.z, 3)],
            "dispatch": {k: (round(v, 3) if isinstance(v, float) else str(v) if isinstance(v, Vec3) else v) for k, v in (dispatch or {}).items() if k in {"active", "phase", "x", "y", "duration", "progress"}},
            "rule": "LMB from hover-drone belly camera on a locked hotspot routes existing Drone A into the drilling dispatch without spawning a replacement entity.",
        }
        out = report_dir / "drone_camera_runtime_test.json"
        out.write_text(json.dumps(payload, indent=2, sort_keys=True), encoding="utf-8")
        print(("DRONE_CAMERA_RUNTIME_TEST PASS " if payload["status"] == "PASS" else "DRONE_CAMERA_RUNTIME_TEST FAIL ") + json.dumps(payload, sort_keys=True), flush=True)
        os._exit(0 if payload["status"] == "PASS" else 1)

    def _run_jupiter_spatial_runtime_test(self, task: Task) -> int:
        report_dir = ROOT / "verification" / "reports"
        report_dir.mkdir(parents=True, exist_ok=True)
        checks: dict[str, bool] = {"is_europa": IS_EUROPA_LEVEL}
        metrics: dict[str, float | str | list[float]] = {}
        root = getattr(self, "saturn_system", None)
        planet = getattr(self, "jupiter_planet", None)
        glow = getattr(self, "jupiter_glow", None)
        anchor = getattr(self, "jupiter_celestial_anchor", None)
        checks["dedicated_celestial_anchor"] = bool(anchor is not None and not anchor.isEmpty())
        checks["jupiter_parent_is_celestial_anchor"] = bool(root is not None and not root.isEmpty() and root.getParent() == anchor)
        checks["camera_facing_glow_hidden"] = bool(glow is not None and glow.isHidden())
        if planet is not None and not planet.isEmpty():
            scale = planet.getScale()
            metrics["planet_scale"] = [float(scale.x), float(scale.y), float(scale.z)]
            checks["oblate_not_one_axis_stretched"] = bool(abs(scale.x - scale.y) < 0.002 and scale.x > scale.z + 0.05)
        else:
            checks["oblate_not_one_axis_stretched"] = False

        cam_a = Vec3(-720.0, -1320.0, self.world.surface_height(-720.0, -1320.0) + 118.0)
        cam_b = cam_a + Vec3(3200.0, 0.0, 0.0)
        self.camera.setPos(cam_a)
        self._sync_celestial_anchor_positions()
        world_a = root.getPos(self.render) if root is not None and not root.isEmpty() else Vec3(0.0)
        vec_a = world_a - cam_a
        vec_a.normalize()
        self.camera.setPos(cam_b)
        self._sync_celestial_anchor_positions()
        world_b = root.getPos(self.render) if root is not None and not root.isEmpty() else Vec3(0.0)
        vec_b = world_b - cam_b
        vec_b.normalize()
        dot = max(-1.0, min(1.0, float(vec_a.dot(vec_b))))
        parallax_angle = math.degrees(math.acos(dot))
        metrics["translation_parallax_degrees"] = parallax_angle
        checks["translation_changes_sky_direction"] = bool(parallax_angle >= 1.0)

        self.camera.setPos(cam_a)
        self._sync_celestial_anchor_positions()
        world_before_turn = root.getPos(self.render) if root is not None and not root.isEmpty() else Vec3(0.0)
        self.camera.lookAt(world_before_turn)
        centered_h = float(self.camera.getH(self.render))
        self.camera.setH(self.render, centered_h + 58.0)
        self._sync_celestial_anchor_positions()
        world_after_turn = root.getPos(self.render) if root is not None and not root.isEmpty() else Vec3(0.0)
        rotation_world_shift = float((world_after_turn - world_before_turn).length())
        metrics["world_shift_after_camera_rotation"] = rotation_world_shift
        checks["camera_rotation_does_not_move_jupiter"] = bool(rotation_world_shift <= 0.001)

        ok = all(checks.values())
        payload = {
            "status": "PASS" if ok else "FAIL",
            "level": MOON_LEVEL_ID,
            "contract": JUPITER_SPATIAL_AUTHORITY_VERSION,
            "checks": checks,
            "metrics": metrics,
            "rule": "Europa Jupiter uses a dedicated partially translating celestial anchor, has no active camera-facing halo, uses oblate globe proportions, gains visible translation parallax, and never changes world position merely because the camera rotates.",
        }
        out = report_dir / "jupiter_spatial_runtime_test.json"
        out.write_text(json.dumps(payload, indent=2, sort_keys=True), encoding="utf-8")
        print(("JUPITER_SPATIAL_RUNTIME_TEST PASS " if ok else "JUPITER_SPATIAL_RUNTIME_TEST FAIL ") + json.dumps(payload, sort_keys=True), flush=True)
        os._exit(0 if ok else 1)

