    def _smoke_exit(self, task: Task) -> int:
        print("Smoke test initialized cleanly; exiting.", flush=True)
        # QC harness safety: exit the smoke process directly so high-detail
        # offscreen/Xvfb runs cannot linger after the initialization check passes.
        os._exit(0)

    def _run_drill_regression_test(self, task: Task) -> int:
        """Regression guard for the drone-drilling crash path.

        This drives the same runtime path that failed for players:
        persistent drone travel -> drilling sequence -> hole spawn -> braced rig spawn.
        """
        if IS_MIMAS_LEVEL:
            pool_spec = MIMAS_CRATER_ICE_POOLS[0]
            hx, hy = float(pool_spec["x"]), float(pool_spec["y"])
            cam_x, cam_y = hx - 175.0, hy + 245.0
            cam_z = self.world.surface_height(cam_x, cam_y) + 115.0
            self.camera.setPos(cam_x, cam_y, cam_z)
            self.heading = math.degrees(math.atan2(-(hx - cam_x), hy - cam_y))
            self.pitch = -34.0
            self.camera.setHpr(self.heading, self.pitch, 0.0)
        elif IS_IAPETUS_LEVEL:
            hx = 0.0
            hy = self.world._iapetus_ridge_axis_offset(hx)
            cam_x, cam_y = -4600.0, -21200.0
            cam_z = self.world.surface_height(cam_x, cam_y) + 920.0
            self.camera.setPos(cam_x, cam_y, cam_z)
            self.camera.lookAt(Point3(hx + 900.0, hy + 1600.0, self.world.surface_height(hx, hy) + 1850.0))
            self.heading = self.camera.getH()
            self.pitch = self.camera.getP()
        else:
            hx, hy = DARK_SIDE_CENTER_X + 180.0, DARK_SIDE_CENTER_Y - 120.0
        if "--terrain-horizon-shot" in sys.argv:
            # Pass104 failure-revealing composition: stand just inside the real
            # movement boundary and look outward.  Before the horizon authority
            # fix this view exposed the hard square end of the heightfield.
            hx, hy = WORLD_HALF - max(220.0, WORLD_HALF * 0.025), 0.0
            cam_x = hx - max(520.0, WORLD_HALF * 0.045)
            cam_y = -max(620.0, WORLD_HALF * 0.055)
            cam_z = self.world.surface_height(cam_x, cam_y) + (720.0 if IS_IAPETUS_LEVEL else 420.0)
            look_x = WORLD_HALF * 0.90 if IS_IAPETUS_LEVEL else WORLD_HALF + TERRAIN_HORIZON_MARGIN * 0.64
            look_y = 0.0
            look_z = self.world.surface_height(look_x, look_y) + (140.0 if IS_IAPETUS_LEVEL else 36.0)
            self.camera.setPos(cam_x, cam_y, cam_z)
            self.camera.lookAt(Point3(look_x, look_y, look_z))
            self.heading = self.camera.getH()
            self.pitch = self.camera.getP()
            self.last_status_message = f"TERRAIN HORIZON QC // {MOON_THEME['display_name']}"
            self.status_flash_timer = 0.0
        self.selected_line_tool = "hook" if (IS_TITAN_LEVEL or IS_TRITON_LEVEL) else ("grapple" if (IS_IAPETUS_LEVEL or IS_MARS_LEVEL) else "magnet")
        regression_profile = self._target_profile_by_name("Tholin Ridge Shard") if IS_IAPETUS_LEVEL else self._target_profile_by_name("Cryo-Ferrite Sheet")
        self.pending_drill_hotspot = {
            "key": "regression:drill_runtime",
            "x": hx,
            "y": hy,
            "ready": True,
            "signal": 0.91,
            "strength": 0.91,
            "sound": 0.87,
            "movement": 0.08,
            "sound_signal": 0.87,
            "movement_signal": 0.08,
            "drill_radius": HOTSPOT_DRILL_RADIUS,
            "depth": 126.0,
            "fish_name": str(regression_profile.get("name", "Cryo-Ferrite Sheet")),
            "target_profile": regression_profile,
            "dark_side": True,
        }
        self._drill_regression_poll_count = 0
        self._begin_drone_travel_to(hx, hy)
        self.taskMgr.doMethodLater(5.80, self._finish_drill_regression_test, "finish_drill_regression_test")
        return Task.done

    def _finish_drill_regression_test(self, task: Task) -> int:
        ok = (
            len(self.holes) >= 1
            and len(self.rigs) >= 1
            and self.active_rig_index >= 0
            and not bool(getattr(self, "drill_effects", []))
            and not bool(getattr(self, "drone_dispatch", None))
        )
        rig_ok = False
        if self.rigs:
            rig = self.rigs[self.active_rig_index]
            node = rig.get("node")
            rig_ok = hasattr(node, "isEmpty") and not node.isEmpty() and "base_z" in rig and "surface_z" in rig
            hole = rig.get("hole")
            if hole is not None:
                surface_z = self.world.surface_height(float(getattr(hole, "x", 0.0)), float(getattr(hole, "y", 0.0)))
                self.camera.setPos(float(getattr(hole, "x", 0.0)) - 136.0, float(getattr(hole, "y", 0.0)) - 180.0, surface_z + 116.0)
                self.camera.lookAt(Point3(float(getattr(hole, "x", 0.0)), float(getattr(hole, "y", 0.0)), surface_z + 20.0))
        ok = ok and rig_ok
        if not ok and (bool(getattr(self, "drone_dispatch", None)) or bool(getattr(self, "drill_effects", [])) or len(self.holes) < 1):
            self._drill_regression_poll_count = int(getattr(self, "_drill_regression_poll_count", 0)) + 1
            if self._drill_regression_poll_count < 56:
                self.taskMgr.doMethodLater(0.25, self._finish_drill_regression_test, "finish_drill_regression_test")
                return Task.done
        if "--drill-test-shot" in sys.argv:
            try:
                idx = sys.argv.index("--drill-test-shot")
                out_path = sys.argv[idx + 1] if idx + 1 < len(sys.argv) else str(ROOT / "verification" / "drill_regression.png")
                self.graphicsEngine.renderFrame()
                self.graphicsEngine.renderFrame()
                self.win.saveScreenshot(panda_path(Path(out_path)))
                print(f"DRILL_REGRESSION_SCREENSHOT {out_path}", flush=True)
            except Exception as exc:
                print(f"DRILL_REGRESSION_SCREENSHOT_FAIL {exc}", flush=True)
                ok = False
        print(
            f"DRILL_REGRESSION_TEST {'PASS' if ok else 'FAIL'} holes={len(self.holes)} rigs={len(self.rigs)} active={self.active_rig_index} dispatch={bool(getattr(self, 'drone_dispatch', None))} effects={len(getattr(self, 'drill_effects', []))}",
            flush=True,
        )
        os._exit(0 if ok else 1)

    def _run_test_shot(self, task: Task) -> int:
        # Verification shots must show the real loaded world, not the boot/loading
        # art.  Titan especially uses a loading illustration with Saturn/sea haze,
        # which hid the actual shoreline during earlier validation screenshots.
        try:
            self._remove_boot_loading_screen(None)
        except Exception:
            pass
        # Verification composition for Pass 39: hard distant solar lighting, visible
        # terminator field, dynamic plumes, and a reachable dark-side drill context.
        if IS_MIMAS_LEVEL:
            pool_spec = MIMAS_CRATER_ICE_POOLS[0]
