                try:
                    shot_mode_index = sys.argv.index("--jupiter-spatial-shot")
                    shot_mode = sys.argv[shot_mode_index + 1].strip().lower() if shot_mode_index + 1 < len(sys.argv) else "centered"
                except (ValueError, IndexError):
                    shot_mode = "centered"
                jupiter_world = self.saturn_system.getPos(self.render)
                self.camera.lookAt(jupiter_world)
                centered_hpr = self.camera.getHpr(self.render)
                if shot_mode == "turned":
                    self.camera.setH(self.render, self.camera.getH(self.render) + 48.0)
                elif shot_mode in {"parallax", "moved"}:
                    # Keep the exact same camera orientation while translating the
                    # observer.  Jupiter should drift in screen space because its
                    # celestial direction is no longer locked to the camera origin.
                    self.camera.setPos(cam_x + 3200.0, cam_y, cam_z)
                    self.camera.setHpr(self.render, centered_hpr)
                    self._sync_celestial_anchor_positions()
                self.heading = self.camera.getH(self.render)
