            search_half = min(WORLD_HALF - 900.0, 7600.0)
            step = 520
            for ix in range(int(-search_half), int(search_half) + 1, step):
                for iy in range(int(-search_half), int(search_half) + 1, step):
                    x = float(ix)
                    y = float(iy)
                    if IS_TITAN_LEVEL and self.world.titan_liquid_signal(x, y) >= 0.42:
                        continue
                    jag = self.world._jagged_mountain_patches(x, y, strength=1.0)
                    if jag > best_jag:
                        best_x, best_y, best_jag = x, y, jag
            spire_positions = list(getattr(self, "jagged_rock_spire_positions", []))
            if spire_positions:
                height, sx, sy, ground_z, radius = max(spire_positions, key=lambda item: item[0])
                look_x, look_y = sx, sy
                look_z = ground_z + height * 0.56
                cam_distance = max(420.0, height * 1.70)
                cam_x, cam_y = look_x - cam_distance * 0.78, look_y - cam_distance
                cam_z = self.world.surface_height(cam_x, cam_y) + max(160.0, height * 0.52)
