            self.resource_inventory["CLATHRATE INSULATOR"] = max(self.resource_inventory.get("CLATHRATE INSULATOR", 0), 1)
            if not self.base_modules:
                base0 = Vec3(robot_x, robot_y, robot_z + 1.0)
                base1 = Vec3(robot_x + BASE_GRID_SIZE, robot_y, self.world.surface_height(robot_x + BASE_GRID_SIZE, robot_y) + 1.0)
