def _iapetus_expanded_ridge_contract_test() -> int:
    world = WorldGenerator()
    sample_xs = [-22400.0, -16800.0, -11200.0, -5600.0, 0.0, 5600.0, 11200.0, 16800.0, 22400.0]
    crest_samples: list[dict[str, float]] = []
    finite = True
    for x in sample_xs:
        axis_y = world._iapetus_ridge_axis_offset(x)
        z = world.surface_height(x, axis_y)
        finite = finite and math.isfinite(z)
        crest_samples.append({"x": round(x, 1), "axis_y": round(axis_y, 3), "z": round(z, 3)})
    axis0 = world._iapetus_ridge_axis_offset(0.0)
    spread_offsets = [-16000.0, -12800.0, -9800.0, -6200.0, -3200.0, 0.0, 3200.0, 6200.0, 9800.0, 12800.0, 16000.0]
    spread_samples = []
    for off in spread_offsets:
        y = axis0 + off
        spread_samples.append({
            "offset": round(off, 1),
            "factor": round(world._iapetus_ridge_factor_at(0.0, y), 4),
            "z": round(world.surface_height(0.0, y), 3),
            "dark_factor": round(world._iapetus_cassini_dark_factor(0.0, y), 4),
        })
    min_crest = min(s["z"] for s in crest_samples)
    max_crest = max(s["z"] for s in crest_samples)
    outer_factor = world._iapetus_ridge_factor_at(0.0, axis0 - 12800.0)
    mid_factor = world._iapetus_ridge_factor_at(0.0, axis0 - 6200.0)
    outer_z = world.surface_height(0.0, axis0 - 12800.0)
    mid_z = world.surface_height(0.0, axis0 - 6200.0)
    inner_z = world.surface_height(0.0, axis0 - 3200.0)
    crest_z = world.surface_height(0.0, axis0)
    approach_gain = mid_z - outer_z
    inner_wall_gain = crest_z - inner_z
    total_gain = crest_z - outer_z
    dark_values = [world._iapetus_cassini_dark_factor(x, world._iapetus_ridge_axis_offset(x) + 1600.0) for x in sample_xs]
    dark_range = max(dark_values) - min(dark_values)
    void_center = world._iapetus_void_factor_at(0.0, 0.0)
    void_outer = world._iapetus_void_factor_at(IAPETUS_HORIZON_FADE_END, 0.0)
    ok = bool(
        IS_IAPETUS_LEVEL
        and WORLD_HALF >= 25000.0
        and WORLD_RESOLUTION >= 300
        and finite
        and min_crest >= 6200.0
        and max_crest >= 8200.0
        and outer_factor <= 0.02
        and mid_factor >= 0.45
        and approach_gain >= 1100.0
        and inner_wall_gain >= 2600.0
        and total_gain >= 6200.0
        and dark_range >= 0.18
        and IAPETUS_PLAY_RADIUS < WORLD_HALF
        and IAPETUS_HORIZON_FADE_START < IAPETUS_PLAY_RADIUS
        and void_center <= 0.01
        and void_outer >= 0.98
    )
    payload = {
        "level": MOON_LEVEL_ID,
        "status": "PASS" if ok else "FAIL",
        "world_half": WORLD_HALF,
        "world_diameter": WORLD_HALF * 2.0,
        "world_resolution": WORLD_RESOLUTION,
        "default_resolution_target": 304,
        "high_detail_resolution_target": 384,
        "min_crest_z": round(min_crest, 3),
        "max_crest_z": round(max_crest, 3),
        "ridge_factor_at_12800m_offset": round(outer_factor, 4),
        "ridge_factor_at_6200m_offset": round(mid_factor, 4),
        "approach_gain_outer_to_mid": round(approach_gain, 3),
        "inner_wall_gain": round(inner_wall_gain, 3),
        "total_gain_outer_to_crest": round(total_gain, 3),
        "cassini_dark_factor_range": round(dark_range, 4),
        "play_radius": round(IAPETUS_PLAY_RADIUS, 3),
        "horizon_fade_start": round(IAPETUS_HORIZON_FADE_START, 3),
        "horizon_fade_end": round(IAPETUS_HORIZON_FADE_END, 3),
        "void_factor_center": round(void_center, 4),
        "void_factor_outer": round(void_outer, 4),
        "crest_samples": crest_samples,
        "spread_samples": spread_samples,
        "rule": "Iapetus must read as a wraparound Cassini Regio equatorial ridge with dark horizon fade, hidden world edges, and a no-further-travel boundary before any texture seam can be seen.",
        "source_target": "NASA/JPL describe Iapetus as having an equatorial ridge up to about 20 km high and over 1300 km long; the game scales this into a playable heightfield identity.",
    }
    out = ROOT / "verification" / "reports" / "iapetus_cassini_regio_ridge_report.json"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(json.dumps(payload, indent=2), encoding="utf-8")
    print(("IAPETUS_CASSINI_REGIO_RIDGE_TEST PASS " if ok else "IAPETUS_CASSINI_REGIO_RIDGE_TEST FAIL ") + json.dumps(payload, sort_keys=True), flush=True)
    return 0 if ok else 1


def _mimas_crater_pool_contract_test() -> int:
    world = WorldGenerator()
    pool_results: list[dict[str, object]] = []
    ok = bool(IS_MIMAS_LEVEL and len(MIMAS_CRATER_ICE_POOLS) >= 5)
    spawn_x, spawn_y = 220.0, 1860.0
    for spec in MIMAS_CRATER_ICE_POOLS:
        cx = float(spec["x"])
        cy = float(spec["y"])
        radius = float(spec["radius"])
        center = world.surface_height(cx, cy)
        crater_radius = radius * float(spec.get("crater_scale", 2.05 + (len(pool_results) % 2) * 0.22))
        rim_samples = []
        for a in (0.0, math.pi * 0.5, math.pi, math.pi * 1.5):
            rim_samples.append(world.surface_height(cx + math.cos(a) * crater_radius, cy + math.sin(a) * crater_radius))
        rim_avg = sum(rim_samples) / max(len(rim_samples), 1)
        basin_depth = rim_avg - center
        spawn_distance = math.hypot(cx - spawn_x, cy - spawn_y)
        pool_ok = math.isfinite(center) and math.isfinite(rim_avg) and radius >= 280.0 and crater_radius >= 900.0 and basin_depth >= 8.0
        if str(spec.get("key", "")).startswith("starter_"):
            pool_ok = pool_ok and spawn_distance <= 950.0
        ok = ok and pool_ok
        pool_results.append({
            "key": str(spec.get("key", "pool")),
            "x": round(cx, 2),
            "y": round(cy, 2),
            "pool_radius": round(radius, 2),
            "crater_radius": round(crater_radius, 2),
            "center_z": round(center, 3),
            "rim_avg_z": round(rim_avg, 3),
            "rim_minus_center": round(basin_depth, 3),
            "profile": str(spec.get("profile", "")),
            "spawn_distance": round(spawn_distance, 2),
            "drillable_hotspot": True,
            "pass": pool_ok,
        })
    payload = {
        "level": MOON_LEVEL_ID,
        "status": "PASS" if ok else "FAIL",
        "pool_count": len(MIMAS_CRATER_ICE_POOLS),
        "pools": pool_results,
        "crater_pool_rule": "visible large frozen crater-floor ice lenses with real sonar/drill hotspots and starter basin near spawn",
    }
    out = ROOT / "verification" / "reports" / "mimas_crater_pool_report.json"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(json.dumps(payload, indent=2), encoding="utf-8")
    print(("MIMAS_CRATER_POOL_TEST PASS " if ok else "MIMAS_CRATER_POOL_TEST FAIL ") + json.dumps(payload, sort_keys=True), flush=True)
    return 0 if ok else 1

