def _movement_accessibility_contract_test() -> int:
    source = Path(__file__).read_text(encoding="utf-8")
    checks = {
        "jump_constants_present": all(name in source for name in ("PLAYER_JUMP_IMPULSE", "PLAYER_GRAVITY", "PLAYER_MAX_JUMP_OFFSET")),
        "space_bound_to_surface_jump": '"space": ("up", True)' in source and "LOW-G CLIMB JUMP" in source,
        "shoreline_axis_slide_present": "axis-wise shoreline sliding" in source,
        "iapetus_penalty_reduced": "climb / 48.0" in source and "0.34" in source,
        "climb_assist_present": "PLAYER_CLIMB_STEP_SOFT" in source and "PLAYER_CLIMB_SPEED_FLOOR" in source,
    }
    # Exercise deterministic terrain deltas to ensure the new climb thresholds are
    # sized for real terrain samples and remain finite.
    world = WorldGenerator()
    path = [
        (0.0, 0.0),
        (240.0, 240.0),
        (820.0, 620.0),
        (-1180.0, 1420.0),
        (-3800.0, -3400.0),
    ]
    deltas = []
    for (x0, y0), (x1, y1) in zip(path, path[1:]):
        deltas.append(world.surface_height(x1, y1) - world.surface_height(x0, y0))
    finite_deltas = all(math.isfinite(d) for d in deltas)
    checks["finite_surface_deltas"] = finite_deltas
    ok = all(checks.values())
    payload = {
        "status": "PASS" if ok else "FAIL",
        "level": MOON_LEVEL_ID,
        "checks": checks,
        "sample_climb_deltas": [round(d, 3) for d in deltas],
        "jump_impulse": PLAYER_JUMP_IMPULSE,
        "climb_soft_step": PLAYER_CLIMB_STEP_SOFT,
        "climb_hard_step": PLAYER_CLIMB_STEP_HARD,
        "rule": "Surface controls must support jump arcs, slope forgiveness, and shoreline sliding so rough terrain does not trap the player.",
    }
    out = ROOT / "verification" / "reports" / "movement_accessibility_contract.json"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(json.dumps(payload, indent=2, sort_keys=True), encoding="utf-8")
    print(("MOVEMENT_ACCESSIBILITY_TEST PASS " if ok else "MOVEMENT_ACCESSIBILITY_TEST FAIL ") + json.dumps(payload, sort_keys=True), flush=True)
    return 0 if ok else 1



