def _all_world_progress_contract_test() -> int:
    from level_contract import LabProfile, standard_all_world_results, validate_level_result, write_level_result, preview_apply_result
    results = standard_all_world_results()
    profile = LabProfile()
    world_payload = {}
    issues: list[str] = []
    for world_key, result in results.items():
        ok, sub_issues = validate_level_result(result)
        if not ok:
            issues.extend([f"{world_key}:{issue}" for issue in sub_issues])
            continue
        entry = profile.apply_result(result)
        world_payload[world_key] = {
            "level_id": result.level_id,
            "level_name": result.level_name,
            "objective_name": result.objective_name,
            "completed": result.completed,
            "progress_percent": result.progress_percent,
            "score": result.score,
            "lab_points_awarded": result.lab_points_awarded,
            "profile_completed": bool(entry.get("completed")),
            "profile_runs": int(entry.get("runs", 0) or 0),
        }
        if result.progress_percent != 100 or result.lab_points_awarded <= 0 or not result.return_to_lab:
            issues.append(f"{world_key}:bad_completion_values")
    report_dir = ROOT / "verification" / "reports"
    report_dir.mkdir(parents=True, exist_ok=True)
    # Write active-world output paths used by the Prototype Lab handoff layer.
    active_result = results.get(MOON_LEVEL_ID) or next(iter(results.values()))
    write_level_result(active_result, LEVEL_RESULT_PATH)
    preview_apply_result(active_result, LAB_PROFILE_PREVIEW_PATH)
    all_world_profile_path = report_dir / "all_world_lab_profile_preview.json"
    all_world_profile_path.write_text(json.dumps(profile.data, indent=2, sort_keys=True), encoding="utf-8")
    expected = set(STARFALL_CANONICAL_WORLDS)
    checks = {
        "all_worlds_present": set(results.keys()) == expected,
        "all_results_validate": not issues,
        "all_complete": all(bool(v.get("completed")) for v in world_payload.values()),
        "all_100_progress": all(int(v.get("progress_percent", 0)) == 100 for v in world_payload.values()),
        "profile_has_all_levels": expected <= {str(v.get("world_key", "")) for v in profile.data.get("levels", {}).values()},
        "active_result_written": LEVEL_RESULT_PATH.exists(),
        "active_profile_preview_written": LAB_PROFILE_PREVIEW_PATH.exists(),
    }
    payload = {
        "status": "PASS" if all(checks.values()) else "FAIL",
        "contract": "operation_starfall_progress_result_contract_v0.1",
        "active_world": MOON_LEVEL_ID,
        "checks": checks,
        "issues": issues,
        "worlds": world_payload,
        "total_profile_points_preview": int(profile.data.get("total_lab_points", 0) or 0),
        "rule": "Every active moon world must produce a validated result packet with objective, progress, score, Lab points, completion state, and return_to_lab=true.",
    }
    out = report_dir / "all_world_progress_contract.json"
    out.write_text(json.dumps(payload, indent=2, sort_keys=True), encoding="utf-8")
    print(("ALL_WORLD_PROGRESS_CONTRACT_TEST PASS " if payload["status"] == "PASS" else "ALL_WORLD_PROGRESS_CONTRACT_TEST FAIL ") + json.dumps(payload, sort_keys=True), flush=True)
    return 0 if payload["status"] == "PASS" else 1

