def _generation_authority_contract_test() -> int:
    source = Path(__file__).read_text(encoding="utf-8")
    world = WorldGenerator()
    profile = ACTIVE_GENERATION_PROFILE
    sample_points = [
        (0.0, 0.0),
        (-1080.0, -820.0),
        (1550.0, 870.0),
        (-3800.0, -3400.0),
        (640.0, -1260.0),
    ]
    heights = [world.surface_height(x, y) for x, y in sample_points]
    slopes = []
    for x, y in sample_points:
        step = 42.0
        dx = abs(world.surface_height(x + step, y) - world.surface_height(x - step, y)) / (step * 2.0)
        dy = abs(world.surface_height(x, y + step) - world.surface_height(x, y - step)) / (step * 2.0)
        slopes.append(math.sqrt(dx * dx + dy * dy))
    jagged_samples = []
    dry_spire_candidates = 0
    for x in range(-6400, 6401, 800):
        for y in range(-6400, 6401, 800):
            x_f = float(x)
            y_f = float(y)
            if abs(x_f) > WORLD_HALF or abs(y_f) > WORLD_HALF:
                continue
            jag = world._jagged_mountain_patches(x_f, y_f, strength=1.0)
            jagged_samples.append(jag)
            if jag > 32.0:
                if profile.get("liquid_avoid_threshold") is not None:
                    if world.titan_liquid_signal(x_f, y_f) >= float(profile["liquid_avoid_threshold"]):
                        continue
                dry_spire_candidates += 1
    checks = {
        "authority_version": STARFALL_GENERATION_AUTHORITY_VERSION == "operation_starfall_generation_terrain_v0.2",
        "active_world_profile": MOON_LEVEL_ID in STARFALL_GENERATION_PROFILES,
        "all_world_profiles": set(STARFALL_GENERATION_PROFILES) == set(STARFALL_CANONICAL_WORLDS),
        "finite_surface_samples": all(math.isfinite(h) for h in heights),
        "finite_slope_samples": all(math.isfinite(v) for v in slopes),
        "finite_jagged_samples": all(math.isfinite(v) for v in jagged_samples),
        "jagged_peak_available": bool(jagged_samples and max(jagged_samples) >= 70.0),
        "spire_target_from_profile": ROCK_MAX_ACTIVE_SPIRES == int(profile.get("rock_spire_target_count", 0)),
        "crest_target_present": int(profile.get("crest_line_target_count", 0)) >= 8,
        "base_intersects_terrain": ROCK_BASE_INTERSECT_RATIO >= 0.045,
        "visual_only_collision_rule": str(profile.get("collision_rule", "")).startswith("visual_only"),
        "snap_rule_declared": "terrain" in str(profile.get("snap_rule", "")).lower(),
        "mesh_spire_builder_uses_tags": "setTag(\"generation_authority\"" in source and "setTag(\"collision_rule\"" in source,
        "world_heightfield_functions_preserved": all(name in source for name in ("surface_height", "subsurface_terrain_height", "_jagged_mountain_patches")),
        "dry_spire_candidates_exist": dry_spire_candidates >= 1,
        "terrain_horizon_version": TERRAIN_HORIZON_VERSION == "operation_starfall_terrain_horizon_v0.1",
        "terrain_horizon_world_coverage": set(TERRAIN_HORIZON_WORLDS) == (set(STARFALL_CANONICAL_WORLDS) - {"iapetus"}),
        "terrain_horizon_extends_beyond_play_bounds": TERRAIN_HORIZON_OUTER_HALF >= WORLD_HALF + 5000.0,
        "terrain_horizon_keeps_gameplay_bounds_frozen": "inner_half=WORLD_HALF" in source and "visual_only_outside_playable_bounds" in source,
        "terrain_horizon_uses_surface_authority": "height_func=self.world.surface_height" in source,
        "titan_horizon_continues_liquid_mask": "titan_methane_horizon_continuation" in source and "titan_liquid_alpha" in source,
        "iapetus_keeps_existing_horizon_authority": "_iapetus_void_factor_at" in source and "iapetus" not in TERRAIN_HORIZON_WORLDS,
    }
    # Titan-specific authority must keep hard props out of deep methane surfaces.
    if IS_TITAN_LEVEL:
        checks["titan_liquid_avoidance"] = profile.get("liquid_avoid_threshold") == 0.48 and "titan_liquid_signal" in source
    payload = {
        "status": "PASS" if all(checks.values()) else "FAIL",
        "contract": STARFALL_GENERATION_AUTHORITY_VERSION,
        "active_world": MOON_LEVEL_ID,
        "profile": dict(profile),
        "checks": checks,
        "surface_samples": [round(h, 3) for h in heights],
        "slope_samples": [round(v, 4) for v in slopes],
        "jagged_peak_height": round(max(jagged_samples) if jagged_samples else 0.0, 3),
        "jagged_active_samples": sum(1 for v in jagged_samples if v > 18.0),
        "dry_spire_candidate_count": dry_spire_candidates,
        "rock_base_intersect_ratio": ROCK_BASE_INTERSECT_RATIO,
        "rock_spire_target_count": ROCK_MAX_ACTIVE_SPIRES,
        "rule": "Every active StarFall world uses deterministic heightfields and profile-owned terrain/rock rules. Props snap to sampled surface height, sink into terrain, stay visual-only, and respect moon identity/liquid masks. Finite square play bounds are visually continued beyond WORLD_HALF so terrain never terminates at the movement boundary; Iapetus retains its dedicated circular fade authority.",
    }
    out = ROOT / "verification" / "reports" / "generation_authority_contract.json"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(json.dumps(payload, indent=2, sort_keys=True), encoding="utf-8")
    print(("GENERATION_AUTHORITY_TEST PASS " if payload["status"] == "PASS" else "GENERATION_AUTHORITY_TEST FAIL ") + json.dumps(payload, sort_keys=True), flush=True)
    return 0 if payload["status"] == "PASS" else 1

