def _liquid_contact_sampling_contract_test() -> int:
    source = Path(__file__).read_text(encoding="utf-8")
    world = WorldGenerator()
    liquid_samples: list[dict[str, float]] = []
    max_above = -9999.0
    for x in range(-7600, 7601, 400):
        for y in range(-7600, 7601, 400):
            alpha = world.titan_liquid_alpha(float(x), float(y)) if hasattr(world, "titan_liquid_alpha") else 0.0
            if alpha >= TITAN_LIQUID_TERRAIN_CUT_ALPHA:
                h = world.surface_height(float(x), float(y))
                above = h - (WATER_Z - 3.0)
                max_above = max(max_above, above)
                if len(liquid_samples) < 8:
                    liquid_samples.append({"x": float(x), "y": float(y), "alpha": round(alpha, 4), "surface_z": round(h, 2)})
    checks = {
        "version_declared": LIQUID_CONTACT_VERSION == "operation_starfall_liquid_contact_sampling_v0.1",
        "terrain_cut_constants": TITAN_LIQUID_TERRAIN_CUT_ALPHA <= 0.03 and TITAN_LIQUID_CONTACT_SIGNAL >= 0.40,
        "liquid_samples_found": len(liquid_samples) >= 4,
        "liquid_terrain_below_surface": max_above <= 0.0,
        "rover_no_contact_guard": "LIQUID CONTACT LOCKOUT // ROVER STAYS DRY" in source and "_drive_rover_from_inputs" in source,
        "drone_no_contact_guard": "DRONE_A LIQUID AVOID" in source or "LIQUID AVOID // SAMPLE FROM BANK" in source,
        "hole_no_liquid_guard": "_liquid_contact_forbidden(float(x), float(y))" in source,
        "bank_sampling_route": "sample_from_bank" in source and "TITAN LIQUID SAMPLE" in source,
        "real_fact_lines": "methane/ethane lakes and seas" in source and "subsurface saltwater ocean" in source and "equatorial ridge about 10 km high" in source,
    }
    ok = all(checks.values())
    payload = {
        "status": "PASS" if ok else "FAIL",
        "level": MOON_LEVEL_ID,
        "checks": checks,
        "max_terrain_above_liquid_cut": round(max_above, 3),
        "sample_count": len(liquid_samples),
        "samples": liquid_samples,
        "rule": "Titan liquids cut neighboring terrain below the liquid plane; rover/drone bodies cannot touch liquids and must sample from safe bank points using a tether. Info text uses real Saturn-system facts.",
    }
    out = ROOT / "verification" / "reports" / "liquid_contact_sampling_contract.json"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(json.dumps(payload, indent=2, sort_keys=True), encoding="utf-8")
    print(("LIQUID_CONTACT_SAMPLING_CONTRACT_TEST PASS " if ok else "LIQUID_CONTACT_SAMPLING_CONTRACT_TEST FAIL ") + json.dumps(payload, sort_keys=True), flush=True)
    return 0 if ok else 1

