def _jupiter_full_wrap_fx_contract_test() -> int:
    source = Path(__file__).read_text(encoding="utf-8")
    generated = ROOT / "assets" / "generated"
    raw_frame_paths = [generated / f"europa_jupiter_storm_frame_{idx:02d}.png" for idx in range(8)]
    wrapped_frame_paths = [generated / f"europa_jupiter_wrapped_frame_{idx:02d}.png" for idx in range(8)]
    shadow_path = generated / "europa_jupiter_shadow_mask.png"
    base_path = generated / "europa_jupiter_generated.png"

    dimensions: dict[str, list[int] | None] = {}
    for label, path in [
        ("base", base_path),
        ("shadow", shadow_path),
        *[(f"storm_{idx}", path) for idx, path in enumerate(raw_frame_paths)],
        *[(f"wrapped_{idx}", path) for idx, path in enumerate(wrapped_frame_paths)],
    ]:
        if path.exists():
            with Image.open(path) as image:
                dimensions[label] = list(image.size)
        else:
            dimensions[label] = None

    wrapped_opaque = True
    for path in wrapped_frame_paths:
        if not path.exists():
            wrapped_opaque = False
            break
        with Image.open(path) as image:
            alpha_extrema = image.convert("RGBA").getchannel("A").getextrema()
            if alpha_extrema != (255, 255):
                wrapped_opaque = False
                break

    build_start = source.index("    def _build_jupiter_system(self) -> NodePath:")
    build_end = source.index("    def _make_billboard(", build_start)
    build_source = source[build_start:build_end]

    checks = {
        "is_europa": IS_EUROPA_LEVEL,
        "base_wrap_2_to_1": dimensions.get("base") is not None and dimensions["base"][0] == dimensions["base"][1] * 2,
        "shadow_source_2_to_1": dimensions.get("shadow") is not None and dimensions["shadow"][0] == dimensions["shadow"][1] * 2,
        "storm_sources_2_to_1": all(dimensions.get(f"storm_{idx}") is not None and dimensions[f"storm_{idx}"][0] == dimensions[f"storm_{idx}"][1] * 2 for idx in range(8)),
        "wrapped_frames_2_to_1": all(dimensions.get(f"wrapped_{idx}") is not None and dimensions[f"wrapped_{idx}"][0] == dimensions[f"wrapped_{idx}"][1] * 2 for idx in range(8)),
        "wrapped_frames_opaque": wrapped_opaque,
        "compositor_exists": "_make_jupiter_wrapped_fx_frames" in source and "frame.alpha_composite(storm)" in source and "frame.alpha_composite(shadow)" in source,
        "planet_uses_wrapped_frame": 'planet.setTexture(self.jupiter_wrapped_textures[0], 1)' in source,
        "runtime_swaps_complete_wrap": "self.jupiter_planet.setTexture(wrapped_frames[frame_index], 1)" in source,
        "legacy_storm_billboards_disabled": "self.jupiter_storm_glow = None" in source and "self.jupiter_storm_core = None" in source and "self.jupiter_storm_arcs = []" in source,
        "legacy_shadow_billboard_disabled": "self.jupiter_shadow_card = None" in build_source and 'planet_radius * 3.0' not in build_source,
        "no_extra_fx_sphere_geometry": '"jupiter_storm_uv_shell"' not in build_source and '"jupiter_terminator_uv_shell"' not in build_source,
        "no_jupiter_multitexture_stage": 'TextureStage("jupiter_storm_wrap_stage")' not in build_source and 'TextureStage("jupiter_shadow_wrap_stage")' not in build_source,
        "wrapped_lightning_source": "Tiny lightning filaments are baked" in source and "lightning *= flash_strength" in source,
        "europa_duplicate_cloud_hidden": "cloud.hide()" in source,
    }
    ok = all(bool(value) for value in checks.values())
    payload = {
        "status": "PASS" if ok else "FAIL",
        "level": MOON_LEVEL_ID,
        "checks": checks,
        "dimensions": dimensions,
        "rule": "Europa Jupiter animation swaps complete opaque 2:1 equirectangular wraps on the original Jupiter sphere. Storm, tiny lightning, and terminator are composited into the wrap; no cards, extra FX spheres, or multitexture stages own the presentation.",
    }
    out = ROOT / "verification" / "reports" / "jupiter_full_wrap_fx_contract.json"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(json.dumps(payload, indent=2, sort_keys=True), encoding="utf-8")
    print(("JUPITER_FULL_WRAP_FX_TEST PASS " if ok else "JUPITER_FULL_WRAP_FX_TEST FAIL ") + json.dumps(payload, sort_keys=True), flush=True)
    return 0 if ok else 1


def _handle_standardization_cli() -> int | None:
    if "--jupiter-spatial-authority-test" in sys.argv:
        return _jupiter_spatial_authority_contract_test()
    if "--jupiter-full-wrap-fx-test" in sys.argv:
        return _jupiter_full_wrap_fx_contract_test()
    if "--planet-vision-contract-test" in sys.argv:
        return _planet_vision_contract_test()
    if "--atmospheric-fx-contract-test" in sys.argv:
        return _atmospheric_fx_contract_test()
    if "--liquid-contact-sampling-test" in sys.argv:
        return _liquid_contact_sampling_contract_test()
    if "--drone-camera-hotspot-test" in sys.argv:
        return _drone_camera_hotspot_contract_test()
    if "--flight-drone-power-contract-test" in sys.argv:
        return _flight_drone_power_contract_test()
    if "--mission-signal-rescue-contract-test" in sys.argv:
        return _mission_signal_rescue_contract_test()
    if "--remote-rover-drone-contract-test" in sys.argv:
        return _remote_rover_drone_contract_test()
    if "--windows-optimization-contract-test" in sys.argv:
        return _windows_optimization_contract_test()
    if "--generation-authority-test" in sys.argv:
        return _generation_authority_contract_test()
    if "--world-action-contract-test" in sys.argv:
        return _world_action_contract_test()
    if "--all-world-progress-contract-test" in sys.argv:
        return _all_world_progress_contract_test()
    if "--audio-fx-contract-test" in sys.argv:
        return _audio_fx_contract_test()
    if "--asset-preflight" in sys.argv:
        return _standardization_asset_preflight()
    if "--terrain-authority-test" in sys.argv:
        return _terrain_authority_test()
    if "--placement-authority-test" in sys.argv:
        return _placement_authority_test()
    if "--level-contract-test" in sys.argv:
        return _level_contract_test()
    if "--lab-profile-test" in sys.argv:
        return _lab_profile_test()
    if "--level-result-test" in sys.argv:
        return _level_result_test(write_outputs=True)
    if "--complete-level-test" in sys.argv:
        return _complete_level_test()
    if "--transport-link-test" in sys.argv:
        info = transport_link_self_test(__file__)
        ok = bool(info.get("enceladus_exists") and info.get("mimas_exists") and info.get("iapetus_exists") and info.get("titan_exists") and info.get("pluto_exists") and info.get("starfall_exists") and info.get("display_contract", {}).get("same_screen_default") and info.get("launch_mode") == "linked_handoff")
        print(("TRANSPORT_LINK_TEST PASS " if ok else "TRANSPORT_LINK_TEST FAIL ") + json.dumps(info, sort_keys=True), flush=True)
        return 0 if ok else 1
    if "--screen-layout-contract-test" in sys.argv:
        return _screen_layout_contract_test()
    if "--all-world-screen-contract-test" in sys.argv:
        return _all_world_screen_contract_test()
    if "--display-contract-test" in sys.argv:
        info = display_contract_self_test(ROOT)
        checks = dict(info.get("checks", {}))
        ok = bool(info.get("starfall_main_exists") and info.get("default_mode") == "reference_1080p_window" and info.get("design_canvas_size") == "1920x1080" and info.get("minimum_supported_size") == "1280x720" and all(checks.values()))
        print(("DISPLAY_CONTRACT_TEST PASS " if ok else "DISPLAY_CONTRACT_TEST FAIL ") + json.dumps(info, sort_keys=True), flush=True)
        return 0 if ok else 1
    if "--iapetus-expanded-ridge-test" in sys.argv or "--iapetus-cassini-ridge-test" in sys.argv:
        return _iapetus_expanded_ridge_contract_test()
    if "--enceladus-tlc-test" in sys.argv:
        return _enceladus_tlc_contract_test()
    if "--mimas-surface-contract-test" in sys.argv:
        return _mimas_surface_contract_test()
    if "--mimas-crater-pool-test" in sys.argv:
        return _mimas_crater_pool_contract_test()
    if "--universal-sonar-meter-test" in sys.argv:
        return _universal_sonar_meter_contract_test()
    if "--titan-foundation-test" in sys.argv:
        return _titan_foundation_contract_test()
    if "--titan-shoreline-smoothing-test" in sys.argv:
        return _titan_shoreline_smoothing_contract_test()
    if "--titan-atmosphere-depth-test" in sys.argv:
        return _titan_atmosphere_depth_contract_test()
    if "--movement-accessibility-test" in sys.argv:
        return _movement_accessibility_contract_test()
    if "--jagged-mountain-test" in sys.argv:
        return _jagged_mountain_contract_test()
    if "--pass37-rocks-underwater-test" in sys.argv:
        return _pass37_rocks_underwater_contract_test()
    if "--operation-return-controls-test" in sys.argv:
        return _operation_return_controls_contract_test()
    if "--starfall-integrated-vessel-test" in sys.argv:
        return _starfall_integrated_vessel_contract_test()
    if "--testrun-scenario-contract-test" in sys.argv:
        return _testrun_scenario_contract_test()
    if "--testrun-scenario" in sys.argv:
        idx = sys.argv.index("--testrun-scenario")
        name = sys.argv[idx + 1] if idx + 1 < len(sys.argv) else ""
        variant = "default"
        if "--testrun-variant" in sys.argv:
            vidx = sys.argv.index("--testrun-variant")
            if vidx + 1 < len(sys.argv):
                variant = sys.argv[vidx + 1]
        result = _run_named_testrun_scenario(name, variant)
        _write_testrun_scenario_report([result])
        print(f"TESTRUN_SCENARIO_SINGLE {name}/{variant} {result['status']}", flush=True)
        return 0 if result.get("status") == "PASS" else 1
    if "--testrun-all" in sys.argv:
        return _testrun_all()
    return None



def _titan_atmosphere_depth_contract_test() -> int:
    source = Path(__file__).read_text(encoding="utf-8")
    checks = {
        "is_titan": IS_TITAN_LEVEL,
        "gas_volume_count_constant": TITAN_SKY_GAS_VOLUME_COUNT >= 4,
        "sea_glint_count_constant": TITAN_SEA_GLINT_COUNT >= 6,
        "silhouette_count_constant": TITAN_DISTANT_SILHOUETTE_COUNT >= 5,
        "gas_layer_builder_exists": "titan_gas_volume_layers" in source,
        "sea_glint_builder_exists": "_build_titan_sea_glints" in source,
        "distant_silhouette_builder_exists": "_build_titan_distant_silhouettes" in source,
        "alpha_methane_plane": "titan_methane_sea_alpha_reflection" in source,
        "alpha_shoreline_plane": "titan_wet_shoreline_alpha_sheen" in source,
        "no_terrain_resolution_increase": WORLD_RESOLUTION_DEFAULT <= 236 and WORLD_RESOLUTION_HIGH <= 300,
    }
    ok = all(checks.values())
    payload = {
        "status": "PASS" if ok else "FAIL",
        "level": MOON_LEVEL_ID,
        "checks": checks,
        "terrain_resolution_default": WORLD_RESOLUTION_DEFAULT,
        "terrain_resolution_high": WORLD_RESOLUTION_HIGH,
        "rule": "Titan atmosphere polish must add depth and reflections with low-cost layers only, without increasing terrain resolution or loading cost.",
    }
    out = ROOT / "verification" / "reports" / "titan_atmosphere_depth_contract.json"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(json.dumps(payload, indent=2, sort_keys=True), encoding="utf-8")
    print(("TITAN_ATMOSPHERE_DEPTH_TEST PASS " if ok else "TITAN_ATMOSPHERE_DEPTH_TEST FAIL ") + json.dumps(payload, sort_keys=True), flush=True)
    return 0 if ok else 1

if __name__ == "__main__":
    cli_result = _handle_standardization_cli()
    if cli_result is not None:
        raise SystemExit(cli_result)
    app = EnceladusIce()
    app.run()
